src/model/MintInfo.ts.source:
import { type Logger, NULL_LOGGER } from '../logger';
import { isRecord, nullIfUndefined } from '../utils/core';
import {
  ABSOLUTE_MAX_ARRAY_LENGTH,
  ABSOLUTE_MAX_BATCH_SIZE,
  ABSOLUTE_MAX_PER_MINT,
  DEFAULT_MAX_ARRAY_LENGTH,
  MAX_METHOD_LENGTH,
  MAX_MINT_INFO_DEPTH,
  MAX_MINT_INFO_LIST,
} from '../utils/limits';
import { normalizeSafeIntegerMetadata } from '../utils/normalizeNumbers';

import { Amount } from './Amount';
import { CTSError } from './Errors';
import {
  type GetInfoResponse,
  type MPPMethod,
  type Nut29Info,
  type SwapMethod,
  type WebSocketSupport,
  type Nut19Policy,
} from './types';

type Method = 'GET' | 'POST';
type Endpoint = { method: Method; path: string };

/**
 * Per NUT-04/05, when `method_name` is null or omitted, wallets derive a human-readable name.
 * Returns null for a missing/empty/non-string/over-long method so malformed (or hostile) entries
 * stay null. The length cap avoids a potential memory-exhaustion DoS vector.
 */
function deriveMethodName(method: unknown): string | null {
  if (typeof method !== 'string' || method.length > MAX_METHOD_LENGTH) return null;
  const words = method.split(/[-_]/).filter((w) => w !== '');
  if (words.length === 0) return null;
  return words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

type ProtectedIndex = {
  exact: Record<Method, Set<string>>;
  prefix: Record<Method, string[]>;
};

/**
 * Wraps a mint's `/v1/info` response with capability helpers.
 *
 * Constructable from any `GetInfoResponse`, including one persisted from an earlier session; no
 * live connection is needed. Persist `cache` and rehydrate with `new MintInfo(stored)`. Accessors
 * return snapshots, never internal references.
 */
export class MintInfo {
  // Full mint info response
  private readonly _mintInfo: GetInfoResponse;
  // NUT-22, Blind-auth protected endpoints
  private readonly _protected22?: ProtectedIndex;
  // NUT-21, Clear-auth protected endpoints
  private readonly _protected21?: ProtectedIndex;
  // NUT-06, resolved request array cap
  private readonly _maxArrayLength: number;

  constructor(info: GetInfoResponse, logger?: Logger) {
    const log = logger ?? NULL_LOGGER;
    this._mintInfo = MintInfo.normalizeInfo(info, log);
    this._maxArrayLength = MintInfo.resolveMaxArrayLength(info.max_array_length, log);

    const pe22 = this.toEndpoints(this._mintInfo?.nuts?.[22]?.protected_endpoints, log);
    this._protected22 = this.buildIndex(pe22);

    const pe21 = this.toEndpoints(this._mintInfo?.nuts?.[21]?.protected_endpoints, log);
    this._protected21 = this.buildIndex(pe21);
  }

  static normalizeInfo(info: GetInfoResponse, logger: Logger = NULL_LOGGER): GetInfoResponse {
    // The response is untrusted JSON: check the shape before any spread copies it.
    if (!isRecord(info) || !isRecord(info.nuts)) {
      logger.error('MintInfo: malformed info response', { op: 'normalizeInfo' });
      throw new CTSError('Invalid response from mint');
    }
    return {
      ...info,
      ...(Array.isArray(info.contact)
        ? { contact: MintInfo.capList(info.contact, 'contact', logger) }
        : {}),
      ...(Array.isArray(info.urls) ? { urls: MintInfo.capList(info.urls, 'urls', logger) } : {}),
      nuts: {
        ...info.nuts,
        ...(info.nuts['4']
          ? { '4': MintInfo.normalizeSwapSection(info.nuts['4'], 'nuts.4', logger) }
          : {}),
        ...(info.nuts['5']
          ? { '5': MintInfo.normalizeSwapSection(info.nuts['5'], 'nuts.5', logger) }
          : {}),
        ...(info.nuts['15'] ? { '15': MintInfo.normalizeNut15(info.nuts['15'], logger) } : {}),
        ...(info.nuts['17'] ? { '17': MintInfo.normalizeNut17(info.nuts['17'], logger) } : {}),
        ...(info.nuts['19'] ? { '19': MintInfo.normalizeNut19(info.nuts['19'], logger) } : {}),
        ...(info.nuts['21'] ? { '21': MintInfo.normalizeNut21(info.nuts['21'], logger) } : {}),
        ...(info.nuts['22'] ? { '22': MintInfo.normalizeNut22(info.nuts['22'], logger) } : {}),
        ...(info.nuts['29'] ? { '29': MintInfo.normalizeNut29(info.nuts['29'], logger) } : {}),
      },
    };
  }

  /**
   * Warns that a malformed optional section was dropped. Sections arrive as untrusted JSON, so one
   * that is not a record is omitted rather than spread.
   */
  private static dropSection(label: string, logger: Logger): undefined {
    logger.warn(`MintInfo: ${label} is malformed and was omitted`);
    return undefined;
  }

  /**
   * NUT-04/05 are mandatory sections, so a malformed one fails the whole response rather than
   * leaving the wallet to guess what the mint supports.
   */
  private static normalizeSwapSection(
    section: GetInfoResponse['nuts']['4'],
    label: string,
    logger: Logger,
  ): GetInfoResponse['nuts']['4'] {
    if (!isRecord(section)) {
      logger.error('MintInfo: malformed info response', { op: label });
      throw new CTSError('Invalid response from mint');
    }
    return { ...section, methods: MintInfo.normalizeSwapMethods(section.methods, logger) };
  }

  // Per NUT-04/05/25/XX, `min_amount` and `max_amount` are `<x|null>`. Mints that omit them entirely
  // (older Nutshell, etc.) leave the field as `undefined`; coerce to null so the normalized response
  // is spec-valid and matches the declared types. `method_name` is `<str|null>` but per NUT-04/05 a
  // null/omitted name is derived deterministically from `method`, so we populate it here instead.
  private static normalizeSwapMethods(methods: SwapMethod[], logger: Logger): SwapMethod[] {
    if (!Array.isArray(methods)) {
      logger.warn('MintInfo: nuts.4/5.methods is malformed and was omitted');
      return [];
    }
    // Entries are untrusted JSON; drop any that is not a record before spreading it.
    const bounded = MintInfo.capList(methods, 'nuts.4/5.methods', logger).filter((m) =>
      isRecord(m),
    );
    return bounded.map((m) => {
      const next = { ...m } as Record<string, unknown>;
      nullIfUndefined(next, 'min_amount', 'max_amount');
      if (next.method_name == null) {
        next.method_name = deriveMethodName(next.method);
      }
      return next as SwapMethod;
    });
  }

  /**
   * NUT-06: `max_array_length` bounds every array the wallet puts in a request, so it always
   * resolves to a usable number. Missing or malformed falls back to the library default; an
   * advertised value is clamped into `[1, ABSOLUTE_MAX_ARRAY_LENGTH]`. The response itself keeps
   * whatever the mint sent, so `cache` never reports a limit the mint did not advertise.
   */
  private static resolveMaxArrayLength(value: number | undefined, logger: Logger): number {
    if (value == null) return DEFAULT_MAX_ARRAY_LENGTH;

    let max: number;
    try {
      max = normalizeSafeIntegerMetadata(value, 'max_array_length');
    } catch {
      logger.warn('MintInfo: max_array_length is malformed, defaulting to internal default', {
        value,
      });
      return DEFAULT_MAX_ARRAY_LENGTH;
    }

    if (max < 1 || max > ABSOLUTE_MAX_ARRAY_LENGTH) {
      const clamped = Math.min(Math.max(max, 1), ABSOLUTE_MAX_ARRAY_LENGTH);
      logger.warn('MintInfo: max_array_length is out of range and was clamped', {
        advertised: max,
        clampedTo: clamped,
      });
      return clamped;
    }
    return max;
  }

  private static normalizeNut15(
    nut15: GetInfoResponse['nuts']['15'],
    logger: Logger,
  ): GetInfoResponse['nuts']['15'] {
    if (!isRecord(nut15)) return MintInfo.dropSection('nuts.15', logger);
    if (!Array.isArray(nut15.methods)) return nut15;

    return { ...nut15, methods: MintInfo.capList(nut15.methods, 'nuts.15.methods', logger) };
  }

  private static normalizeNut17(
    nut17: GetInfoResponse['nuts']['17'],
    logger: Logger,
  ): GetInfoResponse['nuts']['17'] {
    if (!isRecord(nut17)) return MintInfo.dropSection('nuts.17', logger);
    if (!Array.isArray(nut17.supported)) return nut17;

    return { ...nut17, supported: MintInfo.capList(nut17.supported, 'nuts.17.supported', logger) };
  }

  private static normalizeNut19(
    nut19: GetInfoResponse['nuts']['19'],
    logger: Logger,
  ): GetInfoResponse['nuts']['19'] {
    if (!isRecord(nut19)) return MintInfo.dropSection('nuts.19', logger);

    return {
      ...nut19,
      ...(Array.isArray(nut19.cached_endpoints)
        ? {
            cached_endpoints: MintInfo.capList(
              nut19.cached_endpoints,
              'nuts.19.cached_endpoints',
              logger,
            ),
          }
        : {}),
      ttl: normalizeSafeIntegerMetadata(nut19.ttl, 'nuts.19.ttl', null),
    };
  }

  private static normalizeNut21(
    nut21: GetInfoResponse['nuts']['21'],
    logger: Logger,
  ): GetInfoResponse['nuts']['21'] {
    if (!isRecord(nut21)) return MintInfo.dropSection('nuts.21', logger);
    if (!Array.isArray(nut21.protected_endpoints)) return nut21;

    return {
      ...nut21,
      protected_endpoints: MintInfo.capList(
        nut21.protected_endpoints,
        'nuts.21.protected_endpoints',
        logger,
      ),
    };
  }

  private static normalizeNut22(
    nut22: GetInfoResponse['nuts']['22'],
    logger: Logger,
  ): GetInfoResponse['nuts']['22'] {
    if (!isRecord(nut22)) return MintInfo.dropSection('nuts.22', logger);

    let bat_max_mint = ABSOLUTE_MAX_PER_MINT;
    try {
      bat_max_mint = normalizeSafeIntegerMetadata(
        nut22.bat_max_mint,
        'nuts.22.bat_max_mint',
        ABSOLUTE_MAX_PER_MINT,
      );
    } catch {
      logger.warn('MintInfo: nuts.22.bat_max_mint is malformed, defaulting to internal cap', {
        value: nut22.bat_max_mint,
      });
      // bat_max_mint stays at ABSOLUTE_MAX_PER_MINT — initialized above
    }

    if (bat_max_mint > ABSOLUTE_MAX_PER_MINT) {
      logger.warn('MintInfo: nuts.22.bat_max_mint exceeds internal cap and was clamped', {
        advertised: bat_max_mint,
        clampedTo: ABSOLUTE_MAX_PER_MINT,
      });
      bat_max_mint = ABSOLUTE_MAX_PER_MINT;
    }

    return {
      ...nut22,
      ...(Array.isArray(nut22.protected_endpoints)
        ? {
            protected_endpoints: MintInfo.capList(
              nut22.protected_endpoints,
              'nuts.22.protected_endpoints',
              logger,
            ),
          }
        : {}),
      bat_max_mint,
    };
  }

  private static normalizeNut29(
    nut29: GetInfoResponse['nuts']['29'],
    logger: Logger,
  ): GetInfoResponse['nuts']['29'] {
    if (!isRecord(nut29)) return MintInfo.dropSection('nuts.29', logger);

    let max_batch_size = ABSOLUTE_MAX_BATCH_SIZE;
    try {
      max_batch_size = normalizeSafeIntegerMetadata(
        nut29.max_batch_size,
        'nuts.29.max_batch_size',
        ABSOLUTE_MAX_BATCH_SIZE,
      );
    } catch {
      logger.warn('MintInfo: nuts.29.max_batch_size is malformed, defaulting to internal cap', {
        value: nut29.max_batch_size,
      });
      // max_batch_size stays at ABSOLUTE_MAX_BATCH_SIZE — initialized above
    }

    if (max_batch_size > ABSOLUTE_MAX_BATCH_SIZE) {
      logger.warn('MintInfo: nuts.29.max_batch_size exceeds internal cap and was clamped', {
        advertised: max_batch_size,
        clampedTo: ABSOLUTE_MAX_BATCH_SIZE,
      });
      max_batch_size = ABSOLUTE_MAX_BATCH_SIZE;
    }

    // Explicit reconstruction — do not spread ...nut29 here.
    // A spread would reintroduce a malformed max_batch_size from the original object.
    return {
      methods: Array.isArray(nut29.methods)
        ? MintInfo.capList(nut29.methods, 'nuts.29.methods', logger)
        : nut29.methods,
      max_batch_size,
    };
  }

  isSupported(num: 4 | 5): { disabled: boolean; params: SwapMethod[] };
  isSupported(num: 7 | 8 | 9 | 10 | 11 | 12 | 14 | 20): { supported: boolean };
  isSupported(num: 17): { supported: boolean; params?: WebSocketSupport[] };
  isSupported(num: 15): { supported: boolean; params?: MPPMethod[] };
  isSupported(num: 19): { supported: boolean; params?: Nut19Policy };
  isSupported(num: 29): { supported: boolean; params?: Nut29Info };
  isSupported(num: number) {
    switch (num) {
      case 4:
      case 5: {
        return this.checkMintMelt(num);
      }
      case 7:
      case 8:
      case 9:
      case 10:
      case 11:
      case 12:
      case 14:
      case 20: {
        return this.checkGenericNut(num);
      }
      case 17: {
        return this.checkNut17();
      }
      case 15: {
        return this.checkNut15();
      }
      case 19: {
        return this.checkNut19();
      }
      case 29: {
        return this.checkNut29();
      }
      default: {
        throw new CTSError('nut is not supported by cashu-ts');
      }
    }
  }

  requiresBlindAuthToken(method: 'GET' | 'POST', path: string): boolean {
    return this.matchesProtected(this._protected22, method, path);
  }

  requiresClearAuthToken(method: 'GET' | 'POST', path: string): boolean {
    return this.matchesProtected(this._protected21, method, path);
  }

  private matchesProtected(idx: ProtectedIndex | undefined, method: Method, path: string): boolean {
    if (!idx) return false;

    // Runtime guard for method
    const exact = idx.exact[method];
    const prefix = idx.prefix[method];
    if (!exact || !prefix) return false;

    // Exact match first
    if (idx.exact[method].has(path)) return true;

    // Prefix match fallback
    for (const p of idx.prefix[method]) {
      if (path.startsWith(p)) return true;
    }

    return false;
  }

  private checkGenericNut(num: 7 | 8 | 9 | 10 | 11 | 12 | 14 | 20) {
    return { supported: this._mintInfo.nuts[num]?.supported === true };
  }

  private checkMintMelt(num: 4 | 5) {
    const mintMeltInfo = this._mintInfo.nuts[num];
    if (mintMeltInfo && mintMeltInfo.methods.length > 0 && !mintMeltInfo.disabled) {
      return { disabled: false, params: MintInfo.snapshot(mintMeltInfo.methods) };
    }
    return { disabled: true, params: MintInfo.snapshot(mintMeltInfo?.methods ?? []) };
  }

  private checkNut17() {
    if (this._mintInfo.nuts[17] && this._mintInfo.nuts[17].supported.length > 0) {
      return { supported: true, params: MintInfo.snapshot(this._mintInfo.nuts[17].supported) };
    }
    return { supported: false };
  }

  private checkNut15() {
    if (this._mintInfo.nuts[15] && this._mintInfo.nuts[15].methods.length > 0) {
      return { supported: true, params: MintInfo.snapshot(this._mintInfo.nuts[15].methods) };
    }
    return { supported: false };
  }

  private checkNut19() {
    const rawPolicy = this._mintInfo.nuts?.[19];
    if (rawPolicy && (rawPolicy?.cached_endpoints?.length || 0) > 0) {
      const ttlSeconds = normalizeSafeIntegerMetadata(rawPolicy.ttl, 'nuts.19.ttl', null);
      return {
        supported: true,
        params: {
          // map null to infinity, if not null map seconds to milliseconds.
          // this way ttl is always a number
          ttl: ttlSeconds === null ? Infinity : Math.max(ttlSeconds, 0) * 1000,
          cached_endpoints: MintInfo.snapshot(rawPolicy.cached_endpoints),
        },
      };
    }
    return { supported: false };
  }

  private checkNut29() {
    const nut29 = this._mintInfo.nuts?.[29];
    if (nut29) {
      return { supported: true, params: MintInfo.snapshot(nut29) };
    }
    return { supported: false };
  }

  // ---------- private helpers ----------

  /**
   * Bounds a mint-advertised list to `MAX_MINT_INFO_LIST` before any per-entry work, warning once
   * when it truncates. Guards against memory amplification from a hostile `/v1/info`.
   */
  private static capList<T>(list: T[], label: string, logger: Logger): T[] {
    if (list.length <= MAX_MINT_INFO_LIST) return list;
    logger.warn(`MintInfo: ${label} exceeds internal cap and was truncated`, {
      advertised: list.length,
      cap: MAX_MINT_INFO_LIST,
    });
    return list.slice(0, MAX_MINT_INFO_LIST);
  }

  private toEndpoints(maybe: unknown, logger: Logger): Endpoint[] {
    if (!Array.isArray(maybe)) return [];
    const bounded = MintInfo.capList(maybe, 'nuts.21/22.protected_endpoints', logger);
    const out: Endpoint[] = [];
    for (const e of bounded) {
      if (e && typeof e === 'object') {
        const rec = e as Record<string, unknown>;
        const mm = rec.method;
        const pp = rec.path;
        if (typeof mm === 'string' && typeof pp === 'string') {
          const method = mm.toUpperCase();
          if (method === 'GET' || method === 'POST') {
            out.push({ method, path: pp });
          }
        }
      }
    }
    return out;
  }

  private buildIndex(endpoints?: Endpoint[]): ProtectedIndex | undefined {
    if (!endpoints?.length) return undefined;

    const exact: ProtectedIndex['exact'] = { GET: new Set(), POST: new Set() };
    const prefix: ProtectedIndex['prefix'] = { GET: [], POST: [] };

    for (const e of endpoints) {
      let p = e.path;

      // Handle deprecated regex formatting (backwards compat)
      // TODO: remove once mints support revised glob wildcard
      // See: https://github.com/cashubtc/nuts/pull/334
      if (p.startsWith('^')) p = p.slice(1);
      if (p.endsWith('$')) p = p.slice(0, -1);

      // Deprecated regex prefix formatting (backwards compat)
      if (p.endsWith('.*')) {
        prefix[e.method].push(p.slice(0, -2));
        continue;
      }

      // Glob style prefix match
      if (p.endsWith('*')) {
        prefix[e.method].push(p.slice(0, -1));
        continue;
      }

      // Exact match
      exact[e.method].add(p);
    }

    // Optional: longer prefixes first for faster early exits
    prefix.GET.sort((a, b) => b.length - a.length);
    prefix.POST.sort((a, b) => b.length - a.length);

    return { exact, prefix };
  }

  // ---------- getters ----------

  /**
   * Deep-copies a plain data value so accessors return snapshots, never internal references.
   * Preserves bigints (AmountLike fields may hold them; JSON round-trips would not) and Amount
   * instances (which AmountLike also admits): Amount is frozen and immutable, so sharing the
   * reference is safe and structural copying would strip its prototype into a bare `{value}`.
   * Nesting past MAX_MINT_INFO_DEPTH throws rather than running the stack out.
   */
  private static snapshot<T>(value: T, depth = 0): T {
    if (value === null || typeof value !== 'object') return value;
    if (value instanceof Amount) return value;
    if (depth > MAX_MINT_INFO_DEPTH) {
      throw new CTSError(`Mint info nesting exceeds ${MAX_MINT_INFO_DEPTH} levels`);
    }
    if (Array.isArray(value)) {
      return (value as unknown[]).map((v) => MintInfo.snapshot(v, depth + 1)) as T;
    }
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = MintInfo.snapshot(v, depth + 1);
    }
    return out as T;
  }

  /**
   * Snapshot of the full mint info response, safe to mutate or persist.
   */
  get cache(): GetInfoResponse {
    return MintInfo.snapshot(this._mintInfo);
  }
  get contact() {
    return MintInfo.snapshot(this._mintInfo.contact);
  }
  get description() {
    return this._mintInfo.description;
  }
  get description_long() {
    return this._mintInfo.description_long;
  }
  get name() {
    return this._mintInfo.name;
  }
  get pubkey() {
    return this._mintInfo.pubkey;
  }
  get nuts() {
    return MintInfo.snapshot(this._mintInfo.nuts);
  }
  get version() {
    return this._mintInfo.version;
  }
  get motd() {
    return this._mintInfo.motd;
  }
  get icon_url() {
    return this._mintInfo.icon_url;
  }
  /**
   * Endpoint URLs the mint advertises for itself. Informational only: whether to trust or switch to
   * any of them is the consumer's decision.
   */
  get urls() {
    return MintInfo.snapshot(this._mintInfo.urls);
  }
  /**
   * Current server time as a Unix timestamp in seconds.
   */
  get time() {
    return this._mintInfo.time;
  }
  get tos_url() {
    return this._mintInfo.tos_url;
  }
  /**
   * NUT-06: max length the mint accepts for any array in a request (`inputs`, `outputs`, `Ys`).
   * Always a usable number: the library default when the mint advertises none.
   */
  get maxArrayLength(): number {
    return this._maxArrayLength;
  }

  /**
   * Checks if the mint supports creating invoices/offers with a description for the specified
   * payment method.
   *
   * @param method - The payment method to check ('bolt11' or 'bolt12')
   * @returns True if the mint supports description for the method, false otherwise.
   */
  supportsNut04Description(method: 'bolt11' | 'bolt12', unit?: string): boolean {
    return this._mintInfo.nuts[4]?.methods.some(
      (met) =>
        met.method === method &&
        (unit ? met.unit === unit : true) &&
        (met.options?.description === true || met.description === true),
    );
  }

  /**
   * Lists the method-unit settings the mint advertises for an operation (`'mint'` → NUT-4, `'melt'`
   * → NUT-5), or `[]` when that operation is disabled. Use this to discover what a consumer can
   * mint or melt with; to test a single pair use `supportsMintMeltMethod`, or `getMintMeltMethod`
   * to read its settings.
   */
  supportedMethods(op: 'mint' | 'melt'): SwapMethod[] {
    const { disabled, params } = this.isSupported(op === 'mint' ? 4 : 5);
    return disabled ? [] : params;
  }

  /**
   * Returns the mint's advertised settings for a (method, unit) pair for the given operation
   * (`'mint'` → NUT-4, `'melt'` → NUT-5), or `undefined` when the pair is unsupported or the
   * operation is disabled. The result carries the `min_amount`/`max_amount` limits and `options`.
   */
  getMintMeltMethod(op: 'mint' | 'melt', method: string, unit: string): SwapMethod | undefined {
    return this.supportedMethods(op).find((m) => m.method === method && m.unit === unit);
  }

  /**
   * Checks if the mint advertises the given (method, unit) pair for the given operation (`'mint'` →
   * NUT-4, `'melt'` → NUT-5).
   */
  supportsMintMeltMethod(op: 'mint' | 'melt', method: string, unit: string): boolean {
    return this.getMintMeltMethod(op, method, unit) !== undefined;
  }

  supportsAmountless(method: string = 'bolt11', unit: string = 'sat'): boolean {
    const meltMethods = this._mintInfo?.nuts?.[5]?.methods ?? [];

    if (!Array.isArray(meltMethods)) return false;

    return meltMethods.some(
      (met) => met.method === method && met.unit === unit && met.options?.amountless === true,
    );
  }
}

