import { type WeierstrassPoint } from '@noble/curves/abstract/weierstrass.js';
import { bytesToNumberBE } from '@noble/curves/utils.js';
import { bytesToHex, hexToBytes, randomBytes } from '@noble/hashes/utils.js';

import {
  asBlsG1Point,
  assertV3PointSecret,
  asSecpPoint,
  blindMessage,
  blindMessageBls,
  buildP2PKTags,
  constructUnblindedSignatureBls,
  createSecretAndBlindingFactorDeriver,
  constructUnblindedSignature,
  createRandomSecretKey,
  deriveP2BKBlindedPubkeys,
  deriveSecretAndBlindingFactor,
  getPubKeyFromPrivKey,
  isBlsKeyset,
  normalizeP2PKOptions,
  normalizeSecpPubkey,
  pointFromHex,
  pointFromHexAuto,
  pointFromHexG1,
  pointFromHexG2,
  pointToHex,
  verifyDLEQProof,
  verifyUnblindedSignatureBls,
  type CurvePoint,
  type ProofDLEQ,
  type BlindSignature,
  type G1Point,
  type G2Point,
  type P2PKOptions,
  type DerivedSecretAndBlindingFactor,
} from '../crypto';
import { deriveReceiverKeyedSecret, type ParsedNutrootOption } from '../crypto/nutroot';
import { numberToHexPadded64, splitAmount } from '../utils';
import { decodeUtf8Field } from '../utils/bytes';
import { MAX_SECRET_LENGTH } from '../utils/limits';

import { Amount, type AmountLike } from './Amount';
import { BlindedMessage } from './BlindedMessage';
import { CTSError } from './Errors';
import {
  type HasKeysetKeys,
  type Proof,
  type SerializedBlindedMessage,
  type SerializedBlindedSignature,
  type SpendInfo,
} from './types';

const RECOVERY_HINT =
  'Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.';

/**
 * Minimum interface for an output data object. OutputData helpers only require keyset `id` and
 * `keys`. Custom implementations must satisfy this interface to be used with wallet operations.
 */
export interface OutputDataLike {
  blindedMessage: SerializedBlindedMessage;
  blindingFactor: bigint;
  secret: Uint8Array;
  ephemeralE?: string;
  spendInfo?: SpendInfo;

  toProof: (signature: SerializedBlindedSignature, keyset: HasKeysetKeys) => Proof;
}

/**
 * Factory function that produces an {@link OutputDataLike} for a given amount and keyset. Implement
 * this to customise blinded-message construction (e.g. deterministic secrets, P2PK).
 */
export type OutputDataFactory = (amount: AmountLike, keys: HasKeysetKeys) => OutputDataLike;

/**
 * JSON-safe representation of an {@link OutputData} entry.
 */
export type SerializedOutputData = {
  /**
   * Storage shape: `amount` is a decimal string, not an {@link Amount} instance like the wire-shape
   * {@link SerializedBlindedMessage}.
   */
  blindedMessage: {
    amount: string;
    B_: string;
    id: string;
  };
  /**
   * Decimal-encoded bigint.
   */
  blindingFactor: string;
  secret: string;
  ephemeralE?: string;
  spendInfo?: SpendInfo;
};

export function isOutputDataFactory(
  value: OutputData[] | OutputDataFactory,
): value is OutputDataFactory {
  return typeof value === 'function';
}

export class OutputData implements OutputDataLike {
  blindedMessage: SerializedBlindedMessage;
  blindingFactor: bigint;
  secret: Uint8Array;
  ephemeralE?: string;
  /**
   * Key behind a v3 point secret.
   *
   * @remarks
   * Set on v3 keysets by random and deterministic creation alike: the secret is a pubkey and its
   * key signs the spend witness. The key travels to the proof as `spendInfo.k` (mirrored by the
   * wallet when a custom factory sets only this field).
   */
  secretKey?: Uint8Array;
  /**
   * Spend info to travel with the resulting proof (NUT-10).
   *
   * @remarks
   * Set for receiver-keyed nutroot outputs, where the ephemeral `E` and the disclosed tree are the
   * only way the receiver can derive its key. Lost spend info means a proof nobody can spend.
   */
  spendInfo?: SpendInfo;

  constructor(
    blindedMessage: SerializedBlindedMessage,
    blindingFactor: bigint,
    secret: Uint8Array,
    ephemeralE?: string,
    secretKey?: Uint8Array,
    spendInfo?: SpendInfo,
  ) {
    // Cheap JS runtime guards, as this runs per output on the send and receive path
    // c.f: `deserialize` re-blinds the secret and compares when hydrating stored data.
    if (typeof blindingFactor !== 'bigint' || blindingFactor <= 0n) {
      throw new CTSError('OutputData: blindingFactor must be a positive bigint');
    }
    if (!(secret instanceof Uint8Array) || secret.length === 0) {
      throw new CTSError('OutputData: secret must be a non-empty Uint8Array');
    }
    if (blindedMessage == undefined) {
      throw new CTSError('OutputData: blindedMessage is required');
    }
    this.secret = secret;
    this.blindingFactor = blindingFactor;
    this.blindedMessage = blindedMessage;
    this.ephemeralE = ephemeralE;
    this.secretKey = secretKey;
    this.spendInfo = spendInfo;
  }

  toProof(sig: SerializedBlindedSignature, keyset: HasKeysetKeys) {
    if (sig == undefined) {
      throw new CTSError(
        `Mint response is missing a signature for one of the outputs. ${RECOVERY_HINT}`,
      );
    }
    // The keys must be the keyset the mint signed under: DLEQ/pairing verify against them, and
    // unblinding with any other keyset yields an unspendable proof.
    if (sig.id !== keyset.id) {
      throw new CTSError(`Mint signature keyset id ${sig.id} does not match keys for ${keyset.id}`);
    }

    // Blanks (amount=0, e.g. NUT-08 fee change, NUT-09 restore) declare neither amount nor
    // keyset up front; the mint's choice is authoritative for both, including one rotated in
    // meanwhile. Any other output must come back on the keyset and at the amount it asked for:
    // a malicious mint can otherwise sign a smaller denomination and return it as `sig.amount`,
    // which verifies under K2/A of the downgraded amount, or move the output to a worse keyset.
    const requested = this.blindedMessage.amount;
    if (!requested.isZero() && sig.id !== this.blindedMessage.id) {
      throw new CTSError(
        `Mint signature keyset id ${sig.id} does not match output ${this.blindedMessage.id}`,
      );
    }
    if (!requested.isZero() && !sig.amount.equals(requested)) {
      throw new CTSError(
        `Mint signature amount ${sig.amount.toString()} does not match requested amount ${requested.toString()}. ${RECOVERY_HINT}`,
      );
    }

    // v3 (BLS12-381) path: multiplicative unblinding, then pairing equality
    // `e(C, G2_gen) == e(Y, K2)` to confirm the mint actually signed this output. v3 carries no
    // DLEQ — the pairing is the only check that the returned `C_` is a real signature, so it
    // MUST run here. Without it, a malicious mint can return garbage `C_`, the wallet stores an
    // invalid `C`, marks inputs spent, and the user loses funds. Mirrors the secp DLEQ check below.
    if (isBlsKeyset(sig.id)) {
      let C_: G1Point;
      let K2: G2Point;
      try {
        const K2Hex = keyset.keys[sig.amount.toString()];
        if (!K2Hex) {
          throw new CTSError(`Amount ${sig.amount.toString()} not in keyset`);
        }
        C_ = pointFromHexG1(sig.C_);
        K2 = pointFromHexG2(K2Hex);
      } catch (e) {
        throw new CTSError(`Mint returned invalid signature or amount. ${RECOVERY_HINT}`, {
          cause: e,
        });
      }
      const blindSig: BlindSignature = { id: sig.id, C_ };
      const unblinded = constructUnblindedSignatureBls(blindSig, this.blindingFactor, this.secret);
      if (!verifyUnblindedSignatureBls(K2, unblinded.C, unblinded.secret)) {
        throw new CTSError('BLS pairing verification failed on mint response');
      }
      const proof: Proof = {
        id: sig.id,
        amount: sig.amount,
        C: unblinded.C.toHex(true),
        secret: decodeUtf8Field(unblinded.secret),
      };
      if (this.ephemeralE) proof.p2pk_e = this.ephemeralE;
      if (this.spendInfo) proof.spend_info = this.spendInfo;
      return proof;
    }

    let A: WeierstrassPoint<bigint>;
    let C_: WeierstrassPoint<bigint>;
    try {
      const AHex = keyset.keys[sig.amount.toString()];
      if (!AHex) {
        throw new CTSError(`Amount ${sig.amount.toString()} not in keyset`);
      }
      A = pointFromHex(AHex);
      C_ = pointFromHex(sig.C_);
    } catch (e) {
      throw new CTSError(`Mint returned invalid signature or amount. ${RECOVERY_HINT}`, {
        cause: e,
      });
    }

    // NUT-12: the mint issues `{e, s}`, the wallet completes it with the `r` it blinded with.
    let dleq: ProofDLEQ | undefined;
    if (sig.dleq) {
      dleq = {
        s: hexToBytes(sig.dleq.s),
        e: hexToBytes(sig.dleq.e),
        r: this.blindingFactor,
      };
    }

    // NUT-12: Verify DLEQ proof if present. Only secp keysets carry DLEQ.
    if (dleq) {
      const bAuto = pointFromHexAuto(this.blindedMessage.B_);
      if (bAuto.kind === 'secp') {
        if (!verifyDLEQProof(dleq, bAuto.pt, C_, A)) {
          throw new CTSError('DLEQ verification failed on mint response');
        }
      }
    }

    const blindSig: BlindSignature = { id: sig.id, C_ };
    const unblinded = constructUnblindedSignature(blindSig, this.blindingFactor, this.secret, A);
    const proof: Proof = {
      id: sig.id,
      amount: sig.amount,
      C: unblinded.C.toHex(true),
      secret: decodeUtf8Field(unblinded.secret),
      ...(dleq && {
        dleq: {
          s: bytesToHex(dleq.s),
          e: bytesToHex(dleq.e),
          r: numberToHexPadded64(dleq.r),
        },
      }),
    };

    // Add P2BK (Pay to Blinded Key) blinding factors if needed
    if (this.ephemeralE) proof.p2pk_e = this.ephemeralE;
    if (this.spendInfo) proof.spend_info = this.spendInfo;

    return proof;
  }

  static createP2PKData(
    p2pk: P2PKOptions,
    amount: AmountLike,
    keyset: HasKeysetKeys,
    customSplit?: AmountLike[],
  ): OutputData[] {
    const amounts = splitAmount(amount, keyset.keys, customSplit);
    // NUT-28: a SIG_ALL batch shares one ephemeral key so every secret carries the
    // identical data/tags that NUT-11 requires; SIG_INPUTS keeps per-output keys.
    const eBytes =
      p2pk.blindKeys && p2pk.sigFlag === 'SIG_ALL' ? createRandomSecretKey() : undefined;
    return amounts.map((a) => this.createSingleP2PKData(p2pk, a, keyset.id, eBytes));
  }

  /**
   * @param eBytes Optional fixed P2BK ephemeral key; batch callers pass one shared key for SIG_ALL.
   *   Omit for a fresh random key.
   */
  static createSingleP2PKData(
    p2pk: P2PKOptions,
    amount: AmountLike,
    keysetId: string,
    eBytes?: Uint8Array,
  ): OutputData {
    const amountValue = Amount.from(amount);
    const normalized = normalizeP2PKOptions(p2pk);
    const isHTLC = normalized.kind === 'HTLC';
    const refundKeys = normalized.refundKeys ?? [];
    const reqLock = normalized.requiredSignatures ?? 1;
    const reqRefund = normalized.requiredRefundSignatures ?? 1;

    // Canonical layout: `data` is the NUT-10 data slot (a pubkey for P2PK, a hashlock
    // for HTLC); `pubkeys` is the optional `pubkeys` tag content.
    let data = normalized.data;
    let pubkeys = normalized.pubkeys ?? [];
    let refund = refundKeys;

    // Optional key blinding (P2BK). Only signing keys are blinded: for P2PK the data
    // key signs and is blinded too; for HTLC the data is a hash, so it stays in clear.
    let Ehex: string | undefined;
    if (normalized.blindKeys) {
      const lockKeys = isHTLC ? pubkeys : [data, ...pubkeys];
      const ordered = [...lockKeys, ...refundKeys];
      // For HTLC the hashlock occupies slot 0, so key slots start at 1 (NUT-28)
      const { blinded, Ehex: _E } = deriveP2BKBlindedPubkeys(ordered, eBytes, !isHTLC);
      if (isHTLC) {
        // hashlock is in data, all locking keys into pubkeys
        pubkeys = blinded.slice(0, lockKeys.length);
      } else {
        // first locking key in data, rest into pubkeys
        data = blinded[0];
        pubkeys = blinded.slice(1, lockKeys.length);
      }
      refund = blinded.slice(lockKeys.length);
      Ehex = _E;
    }

    // build P2PK Tags (NUT-11), from the post-blinding key layout
    const tags = buildP2PKTags({
      locktime: normalized.locktime,
      pubkeys,
      refundKeys: refund,
      requiredSignatures: reqLock,
      requiredRefundSignatures: reqRefund,
      sigFlag: normalized.sigFlag,
      additionalTags: normalized.additionalTags,
    });

    // Construct secret
    const kind = isHTLC ? 'HTLC' : 'P2PK';
    const newSecret: [string, { nonce: string; data: string; tags: string[][] }] = [
      kind,
      {
        nonce: bytesToHex(randomBytes(32)),
        data,
        tags,
      },
    ];
    const parsed = JSON.stringify(newSecret);

    // Check secret length, counting Unicode code points
    // Same semantics as Nutshell python: len(str)
    const charCount = [...parsed].length;
    if (charCount > MAX_SECRET_LENGTH) {
      throw new CTSError(
        `Secret too long (${charCount} characters), maximum is ${MAX_SECRET_LENGTH}`,
      );
    }

    // blind the message
    const secretBytes = new TextEncoder().encode(parsed);
    const { r, B_ } = blindMessageForKeyset(secretBytes, keysetId);

    // create OutputData
    return new OutputData(
      new BlindedMessage(amountValue, B_, keysetId).getSerializedBlindedMessage(),
      r,
      secretBytes,
      Ehex,
    );
  }

  static createRandomData(amount: AmountLike, keyset: HasKeysetKeys, customSplit?: AmountLike[]) {
    const amounts = splitAmount(amount, keyset.keys, customSplit);
    return amounts.map((a) => this.createSingleRandomData(a, keyset.id));
  }

  static createSingleRandomData(amount: AmountLike, keysetId: string): OutputData {
    if (isBlsKeyset(keysetId)) {
      // v3 secrets are points, so a random secret is a random keypair: the key
      // rides on the OutputData because it signs the spend witness later.
      const amountValue = Amount.from(amount);
      const privKey = createRandomSecretKey();
      const secretBytes = new TextEncoder().encode(bytesToHex(getPubKeyFromPrivKey(privKey)));
      const { r, B_ } = blindMessageForKeyset(secretBytes, keysetId);
      const data = new OutputData(
        new BlindedMessage(amountValue, B_, keysetId).getSerializedBlindedMessage(),
        r,
        secretBytes,
        undefined,
        privKey,
      );
      data.spendInfo = { k: bytesToHex(privKey) };
      return data;
    }
    const amountValue = Amount.from(amount);
    const randomHex = bytesToHex(randomBytes(32));
    const secretBytes = new TextEncoder().encode(randomHex);
    const { r, B_ } = blindMessageForKeyset(secretBytes, keysetId);
    return new OutputData(
      new BlindedMessage(amountValue, B_, keysetId).getSerializedBlindedMessage(),
      r,
      secretBytes,
    );
  }

  /**
   * Output data for a nutroot (v3) secret chosen by the caller: a bare `K` or a tweaked `P`.
   *
   * @remarks
   * Pair with `buildNutrootSecret` for locked outputs; the caller keeps the tree (spend_info) and
   * any keys. The secret travels as its 66-char hex; hashing uses the raw 33 bytes.
   */
  static createSingleNutrootData(
    secretHex: string,
    amount: AmountLike,
    keysetId: string,
  ): OutputData {
    if (!isBlsKeyset(keysetId)) {
      throw new CTSError('Nutroot outputs require a v3 keyset');
    }
    assertV3PointSecret(secretHex);
    const amountValue = Amount.from(amount);
    const secretBytes = new TextEncoder().encode(secretHex);
    const { r, B_ } = blindMessageForKeyset(secretBytes, keysetId);
    return new OutputData(
      new BlindedMessage(amountValue, B_, keysetId).getSerializedBlindedMessage(),
      r,
      secretBytes,
    );
  }

  /**
   * Output data for a receiver-keyed nutroot send (NUT-28): one output per denomination, each
   * derived to the payee's static key under its own fresh ephemeral.
   *
   * @remarks
   * Fresh `e` per output is the rule, not an optimisation: a shared ephemeral would reproduce `K`,
   * hence the secret, hence the colliding `C` of 2.4. Each output carries its own spend info so the
   * payee can derive its key; `leaves` build a tree over the internal key, and `blindKeys` are the
   * leaf keys their owner tagged blind-me. A NUMS output with no blind-me keys blinds nothing and
   * carries no ephemeral at all (NUT-18).
   * @throws If the keyset is not v3: point secrets are keyset-gated, and a pre-v3 mint would read
   *   this as a plain text secret.
   */
  static createNutrootData(
    options: ParsedNutrootOption,
    amount: AmountLike,
    keyset: HasKeysetKeys,
    customSplit?: AmountLike[],
  ): OutputData[] {
    if (!isBlsKeyset(keyset.id)) {
      throw new CTSError('Nutroot outputs require a v3 keyset');
    }
    return splitAmount(amount, keyset.keys, customSplit).map((a) => {
      const { secret, E, tree, K, u } = deriveReceiverKeyedSecret(options.receiverKey, {
        leaves: options.leaves,
        blindKeys: options.blindKeys,
      });
      const data = OutputData.createSingleNutrootData(secret, a, keyset.id);
      data.spendInfo = { ...(E && { E }), ...(tree && { tree, K }), ...(u && { u }) };
      return data;
    });
  }

  static createDeterministicData(
    amount: AmountLike,
    seed: Uint8Array,
    counter: number,
    keyset: HasKeysetKeys,
    customSplit?: AmountLike[],
  ): OutputData[] {
    const amounts = splitAmount(amount, keyset.keys, customSplit);
    // Create a "deriver" up front for this batch of outputs
    // This ensures the HDKey is only created once for legacy BIP-32 keysets
    const derive = createSecretAndBlindingFactorDeriver(seed, keyset.id);
    return amounts.map((a, i) =>
      createSingleDeterministicDataFromBytes(a, keyset.id, derive(counter + i)),
    );
  }

  /**
   * @throws May throw if blinding factor is out of range. Caller should catch, increment counter,
   *   and retry per BIP32-style derivation.
   */
  static createSingleDeterministicData(
    amount: AmountLike,
    seed: Uint8Array,
    counter: number,
    keysetId: string,
  ): OutputData {
    return createSingleDeterministicDataFromBytes(
      amount,
      keysetId,
      deriveSecretAndBlindingFactor(seed, keysetId, counter),
    );
  }

  /**
   * Calculates the sum of amounts in an array of OutputDataLike objects.
   *
   * @param outputs Array of OutputDataLike objects.
   * @returns The total sum of amounts.
   */
  static sumOutputAmounts(outputs: OutputDataLike[]): Amount {
    return Amount.sum(outputs.map((output) => output.blindedMessage.amount));
  }

  /**
   * Converts output data to a JSON-safe representation.
   *
   * @remarks
   * Pair with {@link OutputData.deserialize} to persist prepared melt change outputs (e.g. across a
   * NUT-06 async melt's pending window) and reconstruct spendable change proofs via
   * `wallet.createMeltChangeProofs` once the quote is paid.
   * @example
   *
   * ```ts
   * // Save while async melt is pending:
   * const preview = await wallet.prepareMelt('bolt11', meltQuote, proofs);
   * const stored = JSON.stringify(preview.outputData.map((o) => OutputData.serialize(o)));
   * await wallet.completeMelt(preview, undefined, { preferAsync: true });
   *
   * // ... time passes, quote pays ...
   * const restored = (JSON.parse(stored) as SerializedOutputData[]).map((s) =>
   *   OutputData.deserialize(s),
   * );
   * // zero-value entries carry no ecash (NUT-08); Amount.from also covers a quote rehydrated from JSON
   * const sigs = (paidQuote.change ?? []).filter((s) => !Amount.from(s.amount).isZero());
   * await wallet.ensureOperableKeysets(sigs.map((s) => s.id)); // change may be on a rotated-in keyset
   * const change = wallet.createMeltChangeProofs(restored, sigs);
   * ```
   */
  static serialize(output: OutputDataLike): SerializedOutputData {
    return {
      blindedMessage: {
        amount: output.blindedMessage.amount.toString(),
        B_: output.blindedMessage.B_,
        id: output.blindedMessage.id,
      },
      blindingFactor: output.blindingFactor.toString(),
      secret: bytesToHex(output.secret),
      ...(output.ephemeralE && { ephemeralE: output.ephemeralE }),
      ...(output.spendInfo && { spendInfo: output.spendInfo }),
    };
  }

  /**
   * Reconstructs concrete {@link OutputData} from its JSON-safe representation.
   *
   * @throws {@link CTSError} If any field fails validation: non-canonical or zero blindingFactor,
   *   malformed hex secret/ephemeralE, a secret that is not valid UTF-8 (or not a point secret on a
   *   v3 keyset), a B_ that does not match the secret and blindingFactor, or an Amount that cannot
   *   be parsed.
   * @see {@link OutputData.serialize} for the persist/restore lifecycle example.
   */
  static deserialize(serialized: SerializedOutputData): OutputData {
    try {
      if (!/^(0|[1-9]\d*)$/.test(serialized.blindingFactor)) {
        throw new CTSError('blindingFactor must be a canonical decimal integer');
      }
      // Validate
      const secret = hexToBytes(serialized.secret);
      decodeUtf8Field(secret); // asserts round trip
      const blindingFactor = BigInt(serialized.blindingFactor);
      const { B_ } = blindMessageForKeyset(secret, serialized.blindedMessage.id, blindingFactor); // asserts valid `r`
      if (pointToHex(B_) !== serialized.blindedMessage.B_.toLowerCase()) {
        throw new CTSError(`stored output does not match its secret. ${RECOVERY_HINT}`);
      }
      return new OutputData(
        {
          amount: Amount.from(serialized.blindedMessage.amount),
          B_: serialized.blindedMessage.B_,
          id: serialized.blindedMessage.id,
        },
        blindingFactor,
        secret,
        serialized.ephemeralE ? normalizeSecpPubkey(serialized.ephemeralE) : undefined,
        undefined,
        serialized.spendInfo,
      );
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      throw new CTSError(`Invalid SerializedOutputData: ${message}`, { cause: e });
    }
  }
}

/**
 * Derives OutputData from specified derived bytes.
 */
function createSingleDeterministicDataFromBytes(
  amount: AmountLike,
  keysetId: string,
  derived: DerivedSecretAndBlindingFactor,
): OutputData {
  const amountValue = Amount.from(amount);
  const secretBytesAsHex = bytesToHex(derived.secret);
  const utf8SecretBytes = new TextEncoder().encode(secretBytesAsHex);
  // Note: bytesToNumberBE is used here so invalid values bubble up as throws
  // for BIP32-style retry logic (caller increments counter and retries).
  const deterministicR = bytesToNumberBE(derived.blindingFactor);
  const { r, B_ } = blindMessageForKeyset(utf8SecretBytes, keysetId, deterministicR);
  // A v3 secret is a pubkey; its key travels with the proof so a spend can sign (NUT-10).
  const secretKey = derived.secretKey;
  return new OutputData(
    new BlindedMessage(amountValue, B_, keysetId).getSerializedBlindedMessage(),
    r,
    utf8SecretBytes,
    undefined,
    secretKey,
    secretKey && { k: bytesToHex(secretKey) },
  );
}

/**
 * Curve dispatch for output blinding: v3 (`02…`) keysets use multiplicative BLS12-381 G1;
 * everything else uses secp256k1 additive blinding.
 */
function blindMessageForKeyset(
  secret: Uint8Array,
  keysetId: string,
  r?: bigint,
): { r: bigint; B_: CurvePoint } {
  if (isBlsKeyset(keysetId)) {
    assertV3PointSecret(secret);
    const out = blindMessageBls(secret, r);
    return { r: out.r, B_: asBlsG1Point(out.B_) };
  }
  const out = blindMessage(secret, r);
  return { r: out.r, B_: asSecpPoint(out.B_) };
}

