import { equalBytes } from '@noble/curves/utils.js';

import { normalizeSecpPubkey } from '../crypto/curve_secp';
import { getTag, getTagInt, getTagScalar } from '../crypto/NUT10';
import type { P2PKOptions, P2PKTag } from '../crypto/NUT11';
import { isP2PKKnownTagKey, p2pkOptionsToPRNut10, parseP2PKSecret } from '../crypto/NUT11';
import {
  isConditionLeaf,
  parseNutrootLeaf,
  serializeNutrootLeaf,
  serializeNutrootLeafHex,
  NUTROOT_MAX_TREE_LEAVES,
  NUTROOT_NUMS_KEY,
  type ParsedNutrootOption,
} from '../crypto/nutroot';
import {
  decodeBase64ToUint8Legacy,
  decodeBase64UrlToUint8,
  decodeCBOR,
  hexToBytes,
  encodeCBOR,
  encodeUint8ToBase64UrlPadded,
  normalizeMintUrl,
} from '../utils';
import { decodeBech32m, encodeBech32m } from '../utils/bech32m';
import { JSONInt } from '../utils/JSONInt';
import { MAX_P2PK_PUBKEYS } from '../utils/limits';
import { decodeTLV, encodeTLV } from '../utils/tlv';
import type { DecodedTLVPaymentRequest } from '../utils/tlv';
import { lockToNutrootOptions, lockToP2PKOptions, type LockOptions } from '../wallet/lock';
import type { LockBuilder } from '../wallet/LockBuilder';
import { PaymentRequestTransportType } from '../wallet/types';
import type {
  RawPaymentRequest,
  RawTransport,
  NUT10Option,
  PaymentRequestPayload,
  PaymentRequestTransport,
  SupportedMethod,
  NutrootOption,
} from '../wallet/types';

import { Amount, type AmountLike } from './Amount';
import { CTSError } from './Errors';
import type { Proof } from './types/proof';

/**
 * Normalizes a wire boolean flag, admitting true/false, the numeric 0/1 form, and null.
 *
 * @remarks
 * `null` is treated the same as an absent key: some encoders (eg cdk) serialize an unset optional
 * field as CBOR null rather than omitting it.
 * @throws If `value` is present, non-null, and not one of those four values.
 */
function normalizePaymentRequestFlag(value: unknown, field: 's' | 'mp'): boolean | undefined {
  if (value === undefined || value === null) return undefined;
  if (value === true || value === 1) return true;
  if (value === false || value === 0) return false;
  throw new CTSError(`invalid payment request: ${field} must be a boolean (or 0/1)`);
}

/**
 * Constructor options for {@link PaymentRequest}. Keys mirror the class properties; `amount` and
 * method `fee` values accept flexible input and are normalized on construction.
 */
export type PaymentRequestOptions = {
  id?: string;
  amount?: AmountLike;
  unit?: string;
  mints?: string[];
  description?: string;
  transport?: PaymentRequestTransport[];
  singleUse?: boolean;
  nut10?: NUT10Option;
  mintsPreferred?: boolean;
  supportedMethods?: Array<{ method: string; fee?: AmountLike }>;
  nutroot?: NutrootOption;
};

export class PaymentRequest {
  public id?: string;
  public amount?: Amount;
  public unit?: string;
  public mints?: string[];
  public description?: string;
  public transport?: PaymentRequestTransport[];
  public singleUse?: boolean;
  public nut10?: NUT10Option;
  public mintsPreferred?: boolean;
  public supportedMethods?: SupportedMethod[];
  public nutroot?: NutrootOption;

  constructor(options: PaymentRequestOptions = {}) {
    this.id = options.id;
    this.nutroot = options.nutroot;
    this.unit = options.unit;
    this.mints = options.mints;
    this.description = options.description;
    this.transport = options.transport;
    this.nut10 = options.nut10;
    this.amount = options.amount !== undefined ? Amount.from(options.amount) : undefined;
    this.supportedMethods = options.supportedMethods?.map((m) => ({
      method: m.method,
      fee: m.fee !== undefined ? Amount.from(m.fee) : undefined,
    }));
    this.singleUse = normalizePaymentRequestFlag(options.singleUse, 's');
    this.mintsPreferred = normalizePaymentRequestFlag(options.mintsPreferred, 'mp');
  }

  /**
   * Resolves the NUT-18 mint list strictness per spec.
   *
   * - `undefined` if no mint list is set (`mp` SHOULD be ignored)
   * - `true` if the list is strict (`mp` absent or `false`)
   * - `false` if the list is preferred/advisory (`mp === true`)
   */
  get isMintListStrict(): boolean | undefined {
    if (!this.mints?.length) {
      return undefined;
    }
    return this.mintsPreferred !== true;
  }

  /**
   * NUT-18: `u` MUST be set if `a` or `sm` is set: `mf` and the melt-method check are denominated
   * in the request unit. Enforced when encoding or pricing; parsing stays lenient so foreign
   * requests can still be inspected.
   */
  private assertUnitRule(): void {
    if (!this.unit && (this.amount !== undefined || this.supportedMethods?.length)) {
      throw new CTSError(
        'invalid payment request: unit (u) is required when an amount (a) or supported methods (sm) are set',
      );
    }
  }

  /**
   * The per-method fee (`mf`) the payer must add when paying from `mint`: `0` if `mint` is in the
   * mint list, otherwise the lowest fee among the `sm` methods that `meltMethods` says the mint
   * supports (NUT-18).
   *
   * Use this for amountless requests (where the payer chooses the amount): add the result to the
   * chosen amount. This prices only the fee that applies; it does NOT validate admissibility (e.g.
   * a strict mint list, or a mint supporting none of `sm`) — callers that must reject disallowed
   * mints/methods check that separately.
   *
   * @param mint - The mint URL the payer will send from.
   * @param meltMethods - The methods the mint can melt the request unit via (its NUT-05 melt
   *   methods, matched against `sm`); omit if unknown (prices as `0`).
   * @throws If the request sets `a` or `sm` without `u` (invalid per NUT-18; `mf` is denominated in
   *   the request unit).
   */
  feesFor(mint: string, meltMethods?: string[]): Amount {
    this.assertUnitRule();
    // Fees compensate the payee for melting out: payments from a listed mint carry none.
    if (!this.supportedMethods?.length || this.includesMint(mint)) {
      return Amount.zero();
    }
    const applicable = this.supportedMethods
      .filter((m) => meltMethods?.includes(m.method))
      .map((m) => m.fee ?? Amount.zero());
    if (!applicable.length) {
      return Amount.zero();
    }
    return applicable.reduce((min, fee) => Amount.min(min, fee));
  }

  /**
   * The total amount to send from `mint`: the requested amount plus
   * {@link PaymentRequest.feesFor | feesFor}.
   *
   * @param mint - The mint URL the payer will send from.
   * @param meltMethods - The methods the mint can melt the request unit via (its NUT-05 melt
   *   methods, matched against `sm`); omit if unknown.
   * @throws If the request has no amount (amountless requests have no base to add fees to; use
   *   {@link PaymentRequest.feesFor | feesFor} and add it to the amount the payer chooses), or no
   *   unit (invalid per NUT-18).
   */
  amountToSend(mint: string, meltMethods?: string[]): Amount {
    if (!this.amount) {
      throw new CTSError(
        'cannot compute amount to send: request has no amount; use feesFor() and add the payer-chosen amount',
      );
    }
    return this.amount.add(this.feesFor(mint, meltMethods));
  }

  /**
   * Whether `mintUrl` is in the request's mint list, compared after URL normalization.
   *
   * @remarks
   * Foreign requests may carry non-normalized or unparsable entries; those fall back to a raw
   * string comparison. `false` when the request has no mint list.
   */
  includesMint(mintUrl: string): boolean {
    const norm = (u: string) => {
      try {
        return normalizeMintUrl(u);
      } catch {
        return u;
      }
    };
    const target = norm(mintUrl);
    return this.mints?.some((m) => norm(m) === target) ?? false;
  }

  /**
   * Serializes the default NUT-18 payment payload for this request.
   *
   * @remarks
   * Plain `JSON.stringify` can't serialize the bigint proof amounts, so use this. Proofs must come
   * from `mint` and net the request after fees: `wallet.ops.sendToRequest` produces both, this only
   * packages. Send it as the POST body or Nostr DM content.
   * @param mint - The mint the proofs are from.
   * @param proofs - The proofs to send (eg the `send` half of a send flow).
   * @param opts.memo - Optional memo for the payee.
   * @param opts.unit - Unit when the request has none (default 'sat').
   * @throws If the request has a strict mint list and `mint` is not in it.
   */
  encodePayload(mint: string, proofs: Proof[], opts?: { memo?: string; unit?: string }): string {
    if (this.isMintListStrict && !this.includesMint(mint)) {
      throw new CTSError("mint is not in the request's strict mint list");
    }
    const payload: PaymentRequestPayload = {
      ...(this.id !== undefined && { id: this.id }),
      ...(opts?.memo !== undefined && { memo: opts.memo }),
      unit: this.unit ?? opts?.unit ?? 'sat',
      mint,
      proofs,
    };
    return JSONInt.stringify(payload)!;
  }

  /**
   * Parses a default NUT-18 payment payload received from a payer.
   *
   * @remarks
   * Validates payload shape only. To confirm the payment settles the request, pass the result to
   * {@link Wallet.isPaymentRequestSatisfied}. Imposes no size limit of its own: cap the raw text at
   * the transport (POST body, DM) before decoding.
   * @param json - Raw payload text (POST body or Nostr DM content).
   * @throws {@link CTSError} If the text is not valid JSON or not payload-shaped.
   */
  static decodePayload(json: string): PaymentRequestPayload {
    let raw: unknown;
    try {
      raw = JSONInt.parse(json, undefined, { strict: true });
    } catch (e) {
      throw new CTSError('invalid payment payload: not valid JSON', { cause: e });
    }
    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
      throw new CTSError('invalid payment payload: expected a JSON object');
    }
    const { id, memo, unit, mint, proofs } = raw as Record<string, unknown>;
    if (typeof mint !== 'string' || !mint) {
      throw new CTSError('invalid payment payload: missing mint');
    }
    if (typeof unit !== 'string' || !unit) {
      throw new CTSError('invalid payment payload: missing unit');
    }
    if (id !== undefined && typeof id !== 'string') {
      throw new CTSError('invalid payment payload: id must be a string');
    }
    if (memo !== undefined && typeof memo !== 'string') {
      throw new CTSError('invalid payment payload: memo must be a string');
    }
    if (!Array.isArray(proofs) || proofs.length === 0) {
      throw new CTSError('invalid payment payload: missing proofs');
    }
    const normalized = proofs.map((p: unknown, i: number) => {
      if (
        typeof p !== 'object' ||
        p === null ||
        Array.isArray(p) ||
        typeof (p as Record<string, unknown>).id !== 'string' ||
        typeof (p as Record<string, unknown>).secret !== 'string' ||
        typeof (p as Record<string, unknown>).C !== 'string'
      ) {
        throw new CTSError(`invalid payment payload: malformed proof at index ${i}`);
      }
      const amount = (p as Record<string, unknown>).amount;
      if (typeof amount === 'string') {
        // A quoted amount is the tell-tale of plain JSON.stringify over bigint proofs (or an
        // Amount VO via toJSON). NUT-18 amounts are JSON numbers: point the payer at the encoder.
        throw new CTSError(
          `invalid payment payload: proof amount at index ${i} is a string; amounts must be JSON numbers (serialize with encodePayload() or JSONInt.stringify, not JSON.stringify)`,
        );
      }
      if (typeof amount !== 'number' && typeof amount !== 'bigint') {
        throw new CTSError(`invalid payment payload: malformed proof amount at index ${i}`);
      }
      return { ...(p as Omit<Proof, 'amount'>), amount: Amount.from(amount) };
    });
    return {
      ...(id !== undefined && { id }),
      ...(memo !== undefined && { memo }),
      unit,
      mint,
      proofs: normalized,
    };
  }

  toRawRequest() {
    this.assertUnitRule();
    const rawRequest: RawPaymentRequest = {};
    if (this.transport) {
      rawRequest.t = this.transport.map((t: PaymentRequestTransport) => ({
        t: t.type,
        a: t.target,
        g: t.tags,
      }));
    }
    if (this.id) {
      rawRequest.i = this.id;
    }
    if (this.amount) {
      rawRequest.a = this.amount.toBigInt();
    }
    if (this.unit) {
      rawRequest.u = this.unit;
    }
    if (this.mints) {
      rawRequest.m = this.mints;
    }
    if (this.mintsPreferred !== undefined) {
      rawRequest.mp = this.mintsPreferred;
    }
    if (this.supportedMethods && this.supportedMethods.length > 0) {
      rawRequest.sm = this.supportedMethods.map((m) =>
        m.fee !== undefined ? { mn: m.method, mf: m.fee.toBigInt() } : { mn: m.method },
      );
    }
    if (this.description) {
      rawRequest.d = this.description;
    }
    if (this.singleUse !== undefined) {
      rawRequest.s = this.singleUse;
    }
    if (this.nut10) {
      rawRequest.nut10 = {
        k: this.nut10.kind,
        d: this.nut10.data,
        t: this.nut10.tags,
      };
    }
    if (this.nutroot) {
      rawRequest.nutroot = {
        k: this.nutroot.receiverKey,
        ...(this.nutroot.leaves?.length && { l: this.nutroot.leaves }),
        ...(this.nutroot.blindKeys?.length && { b: this.nutroot.blindKeys }),
      };
    }
    return rawRequest;
  }

  toEncodedRequest(): string {
    const rawRequest: RawPaymentRequest = this.toRawRequest();
    const data = encodeCBOR(rawRequest);
    const encodedData = encodeUint8ToBase64UrlPadded(data);
    return 'creq' + 'A' + encodedData;
  }

  /**
   * Encodes the payment request to creqA format (CBOR).
   *
   * @returns A base64 encoded payment request string with 'creqA' prefix.
   */
  toEncodedCreqA(): string {
    return this.toEncodedRequest();
  }

  /**
   * Encodes the payment request to creqB format (TLV + bech32m).
   *
   * @returns A bech32m encoded payment request string with 'CREQB' prefix.
   * @experimental
   */
  toEncodedCreqB(): string {
    this.assertUnitRule();
    const tlvRequest: DecodedTLVPaymentRequest = {
      id: this.id,
      amount: this.amount !== undefined ? this.amount.toBigInt() : undefined,
      unit: this.unit,
      singleUse: this.singleUse,
      mints: this.mints,
      mintsPreferred: this.mintsPreferred,
      supportedMethods: this.supportedMethods?.map((m) => ({
        method: m.method,
        fee: m.fee !== undefined ? m.fee.toBigInt() : undefined,
      })),
      description: this.description,
      transports: this.transport,
      nut10: this.nut10
        ? {
            kind: this.nut10.kind,
            data: this.nut10.data,
            tags: this.nut10.tags,
          }
        : undefined,
      nutroot: this.nutroot,
    };

    const tlvBytes = encodeTLV(tlvRequest);
    return encodeBech32m('creqb', tlvBytes).toUpperCase();
  }

  getTransport(type: PaymentRequestTransportType) {
    return this.transport?.find((t: PaymentRequestTransport) => t.type === type);
  }

  /**
   * A fresh {@link PaymentRequestBuilder}.
   */
  static builder(): PaymentRequestBuilder {
    return new PaymentRequestBuilder();
  }

  /**
   * Converts this request's `nut10` locking option into a wire {@link P2PKOptions}; decode with
   * `p2pkToLockOptions()` for `.asLocked()`, so a payer locks proofs to exactly the requested
   * condition.
   *
   * @remarks
   * Supports `P2PK` (NUT-11) and `HTLC` (NUT-14) only; returns `undefined` for no `nut10` or an
   * unbuildable kind.
   * @throws If the option is missing its `data` field, carries malformed NUT-10 tags, or holds a
   *   non-compliant pubkey (x-only or off-curve). Paying this request creates new outputs under the
   *   lock, so invalid lock semantics must not be silently dropped or repaired.
   */
  toP2PKOptions(): P2PKOptions | undefined {
    return nut10ToP2PKOptions(this.nut10);
  }

  /**
   * Converts this request's `nutroot` option into the arguments for a receiver-keyed nutroot send
   * (NUT-28), so a payer can derive outputs to the payee's static key under the tree they asked
   * for, honouring their blind-me tags.
   *
   * @remarks
   * `undefined` when the request carries no nutroot option. Leaves must round-trip byte for byte: a
   * payer that cannot reproduce the payee's exact leaf bytes would build a different tree, hence a
   * different secret, so it refuses rather than paying to something the payee did not ask for.
   * @throws If the receiver key is not a valid point, or a requested leaf is unparsable or would
   *   not re-serialize to the bytes the payee sent.
   */
  toNutrootOptions(): ParsedNutrootOption | undefined {
    const nutroot = this.nutroot;
    if (!nutroot) return undefined;
    if (!nutroot.receiverKey) {
      throw new CTSError('nutroot option is missing its receiver key');
    }
    const receiverKey = normalizeSecpPubkey(nutroot.receiverKey);
    // NUT-10: the payer offsets the NUMS base per output, so uniqueness no longer depends on
    // the tree and the requested leaves are reproduced unchanged. Leaves are still required:
    // nothing else could spend a proof with no key path.
    if (receiverKey === NUTROOT_NUMS_KEY && !nutroot.leaves?.length) {
      throw new CTSError('malformed request: a NUMS receiver key requires leaves');
    }
    if (!nutroot.leaves?.length) {
      if (nutroot.blindKeys?.length) {
        throw new CTSError('malformed request: blind-me keys require a tree');
      }
      return { receiverKey };
    }
    if (nutroot.leaves.length > NUTROOT_MAX_TREE_LEAVES) {
      throw new CTSError(`nutroot tree exceeds ${NUTROOT_MAX_TREE_LEAVES} leaves`);
    }
    const leaves = nutroot.leaves.map((hex, i) => {
      const bytes = hexToBytes(hex);
      const leaf = parseNutrootLeaf(bytes);
      /* v8 ignore next 3 -- backstop: parseNutrootLeaf admits only canonical bytes today */
      if (!equalBytes(serializeNutrootLeaf(leaf), bytes)) {
        throw new CTSError(`requested leaf ${i} does not round-trip: cannot reproduce its bytes`);
      }
      return leaf;
    });
    // Every blind-me key must be a leaf key, so the tree's own key count (at most
    // NUTROOT_MAX_SLOTS) bounds the list before any EC decompression.
    const treeKeys = new Set(leaves.filter(isConditionLeaf).flatMap((leaf) => leaf.keys));
    const requestedBlindKeys = nutroot.blindKeys ?? [];
    if (requestedBlindKeys.length > treeKeys.size) {
      throw new CTSError(`Too many blind-me keys: ${requestedBlindKeys.length}`);
    }
    const blindKeys = requestedBlindKeys.map((key) => normalizeSecpPubkey(key));
    for (const key of blindKeys) {
      if (!treeKeys.has(key)) {
        throw new CTSError(`blind-me key is not in the requested tree: ${key}`);
      }
    }
    return {
      receiverKey,
      leaves,
      ...(blindKeys.length && { blindKeys }),
    };
  }

  /**
   * Creates a PaymentRequest from a raw payment request. Supports both creqA and creqB versions.
   *
   * @param rawPaymentRequest - The raw payment request string to create a PaymentRequest from.
   * @returns A PaymentRequest object.
   * @throws An error if the raw payment request is not supported.
   */
  static fromRawRequest(rawPaymentRequest: RawPaymentRequest): PaymentRequest {
    const transports = rawPaymentRequest.t
      ? rawPaymentRequest.t.map((t: RawTransport) => ({
          type: t.t,
          target: t.a,
          tags: t.g,
        }))
      : undefined;
    const nut10 = rawPaymentRequest.nut10
      ? {
          kind: rawPaymentRequest.nut10.k,
          data: rawPaymentRequest.nut10.d,
          tags: rawPaymentRequest.nut10.t,
        }
      : undefined;
    const supportedMethods = rawPaymentRequest.sm?.map((m) => ({ method: m.mn, fee: m.mf }));
    const nutroot = rawPaymentRequest.nutroot
      ? {
          receiverKey: rawPaymentRequest.nutroot.k,
          leaves: rawPaymentRequest.nutroot.l,
          blindKeys: rawPaymentRequest.nutroot.b,
        }
      : undefined;
    return new PaymentRequest({
      nutroot,
      transport: transports,
      id: rawPaymentRequest.i,
      amount: rawPaymentRequest.a,
      unit: rawPaymentRequest.u,
      mints: rawPaymentRequest.m,
      description: rawPaymentRequest.d,
      singleUse: rawPaymentRequest.s,
      nut10,
      mintsPreferred: rawPaymentRequest.mp,
      supportedMethods,
    });
  }

  static fromEncodedRequest(encodedRequest: string): PaymentRequest {
    const lowerRequest = encodedRequest.toLowerCase();

    // Version B: bech32m + TLV encoding (creqb...)
    if (lowerRequest.startsWith('creqb')) {
      // The HRP must be exactly `creqb` (NUT-26); a longer HRP shares the prefix but is not it.
      const { hrp, data } = decodeBech32m(lowerRequest);
      if (hrp !== 'creqb') {
        throw new CTSError('unsupported pr: invalid prefix');
      }
      const decoded = decodeTLV(data);
      const nut10 = decoded.nut10
        ? {
            kind: decoded.nut10.kind,
            data: decoded.nut10.data,
            tags: decoded.nut10.tags ?? [],
          }
        : undefined;
      return new PaymentRequest({
        transport: decoded.transports,
        id: decoded.id,
        amount: decoded.amount,
        unit: decoded.unit,
        mints: decoded.mints,
        description: decoded.description,
        singleUse: decoded.singleUse,
        nut10,
        mintsPreferred: decoded.mintsPreferred,
        supportedMethods: decoded.supportedMethods,
        nutroot: decoded.nutroot,
      });
    }

    // Version A: CBOR encoding (creqA...). The prefix check is case-insensitive (NUT-26);
    // the base64 payload keeps its case.
    if (!lowerRequest.startsWith('creq')) {
      throw new CTSError('unsupported pr: invalid prefix');
    }
    const version = lowerRequest[4];
    if (version !== 'a') {
      throw new CTSError('unsupported pr version');
    }
    const encodedData = encodedRequest.slice(5);
    // NUT-18 mandates base64url, but requests this library emitted before it encoded that way
    // are standard base64 and still in circulation. CDK falls back the same way, and only here.
    let data: Uint8Array;
    try {
      data = decodeBase64UrlToUint8(encodedData);
    } catch (urlSafeError) {
      try {
        data = decodeBase64ToUint8Legacy(encodedData);
      } catch {
        throw urlSafeError;
      }
    }
    const decoded = decodeCBOR(data) as RawPaymentRequest;
    return this.fromRawRequest(decoded);
  }
}

/**
 * Fluent builder for authoring a {@link PaymentRequest} (NUT-18).
 *
 * @remarks
 * Setters collect state in any order and never throw on cross-field state; `build()` is the single
 * validation point. The {@link PaymentRequest} class itself stays lenient because it is also the
 * decode type for foreign requests.
 */
export class PaymentRequestBuilder {
  private _id?: string;
  private _amount?: AmountLike;
  private _unit?: string;
  private _description?: string;
  private _mints: string[] = [];
  private _mintsPreferred?: boolean;
  private _singleUse?: boolean;
  private _transports: PaymentRequestTransport[] = [];
  private _nut10?: NUT10Option;
  private _nutroot?: NutrootOption;
  private _omitted: { nut10?: string; nutroot?: string } = {};

  /**
   * Why the last `lock()` left an encoding out, per encoding; empty when nothing was dropped.
   *
   * @remarks
   * Lets a caller tell a deliberate omission (eg no `nut10` for blinded keys or disclosure) from a
   * bug, and show the reason. Reset by the next `lock()`.
   */
  get omitted(): Readonly<{ nut10?: string; nutroot?: string }> {
    return { ...this._omitted };
  }
  private _methods: Array<{ method: string; fee?: AmountLike }> = [];

  /**
   * Sets the optional payment ID reference.
   */
  id(id: string): this {
    this._id = id;
    return this;
  }

  /**
   * Sets the requested amount and its unit together (NUT-18: `u` MUST be set when `a` is set).
   *
   * @throws If the unit is empty.
   */
  amount(amount: AmountLike, unit: string): this {
    if (!unit) {
      throw new CTSError('amount requires a unit (NUT-18: `u` MUST be set when `a` is set)');
    }
    this._amount = amount;
    this._unit = unit;
    return this;
  }

  /**
   * Sets the unit for an amountless request. The last write here or via `amount()` wins.
   *
   * @throws If the unit is empty.
   */
  unit(unit: string): this {
    if (!unit) {
      throw new CTSError('unit must be a non-empty string');
    }
    this._unit = unit;
    return this;
  }

  /**
   * A human readable description for the payment request.
   */
  description(description: string): this {
    this._description = description;
    return this;
  }

  /**
   * Appends to the mint list; URLs are normalized (as `Mint` does) and deduplicated, first-seen
   * order preserved.
   *
   * @throws If a URL is not a valid mint URL.
   */
  addMint(mint: string | string[]): this {
    const arr = Array.isArray(mint) ? mint : [mint];
    for (const m of arr) {
      const normalized = normalizeMintUrl(m);
      if (!this._mints.includes(normalized)) this._mints.push(normalized);
    }
    return this;
  }

  /**
   * Marks the mint list advisory (`mp`) rather than strict; requires mints at `build()`.
   */
  mintsPreferred(preferred = true): this {
    this._mintsPreferred = preferred;
    return this;
  }

  singleUse(single = true): this {
    this._singleUse = single;
    return this;
  }

  /**
   * Appends a transport; order is preference order (NUT-18).
   */
  addTransport(transport: PaymentRequestTransport): this {
    this._transports.push(transport);
    return this;
  }

  /**
   * Appends a nostr transport for the given NIPs (default NIP-17 direct messages).
   *
   * @throws If the target is not an nprofile, or `nips` is empty (the `n` tag MUST carry at least
   *   one value).
   */
  addNostrTransport(nprofile: string, nips: string[] = ['17']): this {
    if (!nprofile.startsWith('nprofile1')) {
      throw new CTSError('nostr transport target must be an nprofile');
    }
    if (nips.length === 0) {
      throw new CTSError('nostr transport requires at least one NIP (`n` tag value)');
    }
    return this.addTransport({
      type: PaymentRequestTransportType.NOSTR,
      target: nprofile,
      tags: [['n', ...nips.map(String)]],
    });
  }

  /**
   * Appends an HTTP POST transport; the payer POSTs the payment payload to `url`.
   */
  addHttpPostTransport(url: string): this {
    return this.addTransport({ type: PaymentRequestTransportType.POST, target: url });
  }

  /**
   * Appends a NUT-05 melting method the payee accepts (`sm`), with an optional per-method fee.
   *
   * @throws If the method name is empty.
   */
  addSupportedMethod(method: string, fee?: AmountLike): this {
    if (!method) {
      throw new CTSError('supported method name must be a non-empty string');
    }
    this._methods.push({ method, fee });
    return this;
  }

  /**
   * Sets the locking condition from semantic {@link LockOptions}, a {@link LockBuilder}, or wire
   * {@link P2PKOptions}. Replaces any condition set earlier.
   *
   * @remarks
   * Semantic input is encoded as `nutroot` (the current spec) and, while `legacy` is not `false`,
   * also as `nut10` so payers that predate v3 can pay: a NUT-18 transition measure. Wire
   * `P2PKOptions` target `nut10` alone; `requestNutroot()` makes a deliberately v3-only request.
   * @throws If no permitted encoding can express the lock, or a wire lock is invalid.
   */
  lock(lock: LockOptions | LockBuilder | P2PKOptions, opts?: { legacy?: boolean }): this {
    const semantic = asLockOptions(lock);
    this._omitted = {};
    if (!semantic) {
      this._nut10 = p2pkOptionsToPRNut10(lock as P2PKOptions);
      this._nutroot = undefined;
      return this;
    }
    const omitted: { nut10?: string; nutroot?: string } = {};
    const tryEncode = <T>(key: keyof typeof omitted, encode: () => T): T | undefined => {
      try {
        return encode();
      } catch (e) {
        omitted[key] = e instanceof Error ? e.message : String(e);
        return undefined;
      }
    };
    const nut10 =
      opts?.legacy === false
        ? undefined
        : tryEncode('nut10', () => p2pkOptionsToPRNut10(lockToP2PKOptions(semantic)));
    const nutroot = tryEncode('nutroot', () => encodeNutrootRequest(semantic));
    if (!nut10 && !nutroot) {
      throw new CTSError(
        `lock fits no permitted request encoding: ${Object.values(omitted).join('; ')}`,
      );
    }
    this._omitted = omitted;
    this._nut10 = nut10;
    this._nutroot = undefined;
    if (nutroot) this.requestNutroot(nutroot);
    return this;
  }

  /**
   * Sets the `nut10` locking condition verbatim, for kinds `lock()` cannot express.
   */
  nut10(option: NUT10Option): this {
    this._nut10 = option;
    return this;
  }

  /**
   * Requests nutroot (v3 keyset) outputs derived to `receiverKey`, optionally under a tree.
   *
   * @remarks
   * NUT-28: the receiver key is blinded at slot 0 by the payer, so one request can be reused
   * without linking payments. The payer assigns slots in transmitted leaf order; the receiver
   * derives every occupied slot and matches keys by value. `blindKeys` names the leaf keys to
   * blind.
   * @throws If the receiver key is not a valid point, a leaf is unparsable, or a blind-me key is
   *   not one of the leaves' keys.
   */
  requestNutroot(lock: NutrootOption | LockOptions | LockBuilder): this {
    const semantic = asLockOptions(lock);
    const option: NutrootOption = semantic
      ? encodeNutrootRequest(semantic)
      : (lock as NutrootOption);
    const nutroot: NutrootOption = {
      receiverKey: normalizeSecpPubkey(option.receiverKey),
      ...(option.leaves?.length && { leaves: [...option.leaves] }),
      ...(option.blindKeys?.length && {
        blindKeys: option.blindKeys.map((k) => normalizeSecpPubkey(k)),
      }),
    };
    if ((nutroot.leaves?.length ?? 0) > NUTROOT_MAX_TREE_LEAVES) {
      throw new CTSError(`nutroot tree exceeds ${NUTROOT_MAX_TREE_LEAVES} leaves`);
    }
    // Validate here rather than at build(): a request nobody can pay is worth catching at the
    // point the payee wrote it, not at the payer.
    const treeKeys = new Set(
      (nutroot.leaves ?? [])
        .map((hex) => parseNutrootLeaf(hexToBytes(hex)))
        .filter(isConditionLeaf)
        .flatMap((leaf) => leaf.keys),
    );
    for (const key of nutroot.blindKeys ?? []) {
      if (!treeKeys.has(key)) {
        throw new CTSError(`blind-me key is not in the requested tree: ${key}`);
      }
    }
    if (nutroot.receiverKey === NUTROOT_NUMS_KEY && !nutroot.leaves?.length) {
      throw new CTSError('A NUMS receiver key requires leaves');
    }
    this._nutroot = nutroot;
    return this;
  }

  /**
   * Validates cross-field state and constructs the {@link PaymentRequest}.
   *
   * @throws If `mintsPreferred` is set without mints (NUT-18 ignores `mp` without `m`), a supported
   *   method is listed twice, or supported methods are set without a unit (NUT-18: `u` MUST be set
   *   when `sm` is set).
   */
  build(): PaymentRequest {
    if (this._mintsPreferred !== undefined && this._mints.length === 0) {
      throw new CTSError('mintsPreferred (mp) requires a mint list; add mints or drop the flag');
    }
    if (this._methods.length > 0 && !this._unit) {
      throw new CTSError(
        'supported methods (sm) require a unit; set it via amount(value, unit) or unit()',
      );
    }
    const seen = new Set<string>();
    for (const m of this._methods) {
      if (seen.has(m.method)) {
        throw new CTSError(`duplicate supported method "${m.method}"`);
      }
      seen.add(m.method);
    }
    // Copy the collected arrays so reusing the builder cannot mutate the built request.
    return new PaymentRequest({
      id: this._id,
      amount: this._amount,
      unit: this._unit,
      mints: this._mints.length ? [...this._mints] : undefined,
      description: this._description,
      transport: this._transports.length ? [...this._transports] : undefined,
      singleUse: this._singleUse,
      nut10: this._nut10,
      mintsPreferred: this._mintsPreferred,
      supportedMethods: this._methods.length ? this._methods : undefined,
      nutroot: this._nutroot,
    });
  }
}

/**
 * Reads semantic lock input; undefined for a wire shape (`P2PKOptions` carries `kind`, a
 * `NutrootOption` carries `receiverKey`).
 */
function asLockOptions(
  lock: LockOptions | LockBuilder | P2PKOptions | NutrootOption,
): LockOptions | undefined {
  if (typeof (lock as LockBuilder).toOptions === 'function') {
    return (lock as LockBuilder).toOptions();
  }
  if ('kind' in lock || 'receiverKey' in lock) return undefined;
  return lock as LockOptions;
}

/**
 * Encodes semantic lock options as a wire nutroot request.
 */
function encodeNutrootRequest(lock: LockOptions): NutrootOption {
  const { receiverKey, leaves, blindKeys } = lockToNutrootOptions(lock);
  return {
    receiverKey,
    ...(leaves?.length && { leaves: leaves.map((leaf) => serializeNutrootLeafHex(leaf)) }),
    ...(blindKeys?.length && { blindKeys }),
  };
}

/**
 * A NUT-10 locking option as wire {@link P2PKOptions}, canonicalising kind, data and tags.
 *
 * @remarks
 * Shared by the payer (build the lock) and the payee (check a proof carries it). Supports `P2PK`
 * (NUT-11) and `HTLC` (NUT-14) only; returns `undefined` for no option or an unbuildable kind.
 * @throws If the option is missing `data`, carries malformed tags, or holds a non-compliant pubkey.
 */
export function nut10ToP2PKOptions(nut10: NUT10Option | undefined): P2PKOptions | undefined {
  const isHTLC = nut10?.kind === 'HTLC';
  if (!nut10 || (nut10.kind !== 'P2PK' && !isHTLC)) {
    return undefined;
  }
  if (!nut10.data) {
    throw new CTSError(`NUT-10 ${nut10.kind} option is missing its data field`);
  }

  // Use parseP2PKSecret (the parser the verifier uses): it rejects malformed
  // tags, duplicate tag keys and bad sigflags — all of which NUT-11 says make a
  // proof unspendable — so a bad lock fails loudly instead of silently first-winning.
  const secret = parseP2PKSecret([
    nut10.kind,
    { nonce: '', data: nut10.data, tags: nut10.tags ?? [] },
  ]);
  // Bound EC decompression before mapping over the request's keys; the exact NUT-28 slot
  // rule is enforced by the builder.
  const pubkeys = getTag(secret, 'pubkeys') ?? [];
  if (pubkeys.length > MAX_P2PK_PUBKEYS) {
    throw new CTSError(`Too many pubkeys: ${pubkeys.length}`);
  }
  const refundKeys = getTag(secret, 'refund') ?? [];
  if (refundKeys.length > MAX_P2PK_PUBKEYS) {
    throw new CTSError(`Too many refund pubkeys: ${refundKeys.length}`);
  }
  // `data` is the NUT-10 data slot (hashlock for HTLC, primary pubkey for P2PK);
  // the `pubkeys` tag carries the optional additional / receiver keys for either kind.
  const taggedPubkeys = pubkeys.map(normalizeSecpPubkey);
  const options: P2PKOptions = {
    kind: isHTLC ? 'HTLC' : 'P2PK',
    data: isHTLC ? nut10.data : normalizeSecpPubkey(nut10.data),
    ...(taggedPubkeys.length ? { pubkeys: taggedPubkeys } : {}),
  };

  // Optional fields pass straight through: the accessors return undefined when absent
  // and throw when malformed, and the builder ignores undefined options.
  options.locktime = getTagInt(secret, 'locktime');
  // `getTag` yields undefined, never [], so a key-only tag reads as absent.
  options.refundKeys = refundKeys.length ? refundKeys.map(normalizeSecpPubkey) : undefined;
  options.requiredSignatures = getTagInt(secret, 'n_sigs');
  options.requiredRefundSignatures = getTagInt(secret, 'n_sigs_refund');
  if (getTagScalar(secret, 'sigflag') === 'SIG_ALL') {
    options.sigFlag = 'SIG_ALL';
  }

  // Forward any non-standard tags verbatim.
  const additionalTags = (nut10.tags ?? []).filter(
    (t) => t.length > 0 && !isP2PKKnownTagKey(t[0]),
  ) as P2PKTag[];
  if (additionalTags.length > 0) {
    options.additionalTags = additionalTags;
  }

  return options;
}

src/model/ScriptPath.ts.source:
import { equalBytes } from '@noble/curves/utils.js';
import { utf8ToBytes } from '@noble/hashes/utils.js';

import { schnorrSignDigest } from '../crypto/core';
import { hashToCurveBls } from '../crypto/curve_bls';
import { getPubKeyFromPrivKey } from '../crypto/curve_secp';
import { hashToCurveHex, isBlsKeyset } from '../crypto/curves';
import {
  buildScriptPathWitness,
  enumerateLeafKeySlots,
  parseNutrootLeaf,
  selectRequiredLeafSignatures,
  slotKeysByBlindedPubkey,
  nutrootLeafHash,
  nutrootMerklePath,
  type NutrootConditionLeaf,
  type NutrootLeaf,
  verifyNutrootCommitment,
} from '../crypto/nutroot';
import {
  digestForPayload,
  inputsForPayload,
  meltOutputAmount,
  type PayloadProofInput,
} from '../crypto/transcript';
import {
  bytesToHex,
  bytesToUtf8,
  decodeBase64UrlToUint8,
  hexToBytes,
  isValidHex,
  JSONInt,
  encodeUint8ToBase64Url,
} from '../utils';
import { NUTROOT_MAX_SLOTS } from '../utils/limits';
import { orderOutputsForPayload } from '../wallet/_internal';
import type { MeltPreview, ScriptPathPlan, SwapPreview } from '../wallet/types';

import { Amount } from './Amount';
import { CTSError } from './Errors';
import type { MeltQuoteBaseResponse, Proof, SerializedBlindedMessage } from './types';

/**
 * Transport prefix for a serialized script path signing package.
 */
const SCRIPT_PATH_PREFIX = 'nutspA';

/**
 * One input's script path spend, awaiting signatures.
 */
export type ScriptPathSpendRequest = {
  /**
   * The input being spent, by its 33-byte point secret hex.
   */
  secret: string;
  /**
   * The serialized leaf being exercised, hex.
   */
  leaf: string;
  /**
   * Control block for the witness: internal key and merkle path.
   */
  control: { K: string; path: string[] };
  /**
   * Ephemeral `E` when the proof is receiver-keyed, so a signer holding a blinded slot key can
   * derive it. Absent for bearer and script-only proofs, whose leaf keys are verbatim.
   */
  E?: string;
  /**
   * Absolute blinding slot of each leaf key, aligned with the leaf's `keys` (NUT-28). A hint only:
   * the signer derives these first and falls back to the full slot scan if none match.
   */
  slots?: number[];
  /**
   * Signatures collected so far, hex. Grows as signers add theirs.
   */
  signatures: string[];
};

/**
 * Everything a signer needs to satisfy one or more script path spends, and nothing else.
 *
 * @remarks
 * Carries no secrets, no preimages and no blinding factors: inputs are named by `Y`, as in the
 * transcript, and a hashlock preimage stays with the coordinator until merge. Serialize it, send it
 * wherever the keys are, sign, and merge the result back into the preview it came from. Unlike a
 * co-signer hook, the transaction is not in flight meanwhile, so a ceremony can outlive the process
 * that started it, which is the normal case on a phone.
 */
export type ScriptPathSigningPackage = {
  version: 'nutspA';
  type: 'swap' | 'melt';
  /**
   * Melt quote id; melt packages only.
   */
  quote?: string;
  /**
   * Every transaction input, named by `Y` rather than by secret (NUT-10).
   */
  inputs: Array<Pick<Proof, 'amount' | 'id' | 'C'> & { Y: string }>;
  outputs: SerializedBlindedMessage[];
  /**
   * The melt output's amount, quote amount plus the selected fee reserve (NUT-10); needed to
   * reproduce the digest. Melt packages only.
   */
  quoteAmount?: bigint;
  spends: ScriptPathSpendRequest[];
};

function digestOf(
  inputs: PayloadProofInput[],
  outputs: SerializedBlindedMessage[],
  meltQuote?: { quoteId: string; amount: bigint },
): Uint8Array {
  return digestForPayload({ inputs, outputs, ...(meltQuote && { meltQuote }) });
}

/**
 * The digest a package's signatures cover, always rebuilt from its inputs and outputs: the package
 * carries no digest field, so there is nothing to sign but what it shows.
 */
function packageDigest(pkg: ScriptPathSigningPackage): Uint8Array {
  return digestOf(
    pkg.inputs,
    pkg.outputs,
    pkg.type === 'melt'
      ? { quoteId: pkg.quote!, amount: Amount.from(pkg.quoteAmount!).toBigInt() }
      : undefined,
  );
}

/**
 * Each spend's input digest by its secret, rebuilt the same way (NUT-10: inputs sign per input).
 *
 * @remarks
 * Package inputs are named by `Y`, so a spend finds its input by hashing its own secret: one hash
 * per spend, on the BLS curve every v3 keyset uses.
 */
function packageInputDigests(pkg: ScriptPathSigningPackage): Map<string, Uint8Array> {
  const meltQuote =
    pkg.type === 'melt'
      ? { quoteId: pkg.quote!, amount: Amount.from(pkg.quoteAmount!).toBigInt() }
      : undefined;
  const { proofs } = inputsForPayload({
    inputs: pkg.inputs,
    outputs: pkg.outputs,
    ...(meltQuote && { meltQuote }),
  });
  return new Map(
    pkg.spends.map((spend) => {
      const Y = spendY(spend);
      const proof = pkg.inputs.find((input) => input.Y === Y && isBlsKeyset(input.id));
      if (!proof) throw new CTSError('Signing package spend must name a v3 transaction input');
      return [spend.secret, proofs.get(Y)!.digest];
    }),
  );
}

/**
 * The `Y` of a spend's v3 point secret, hashed as every BLS keyset does.
 */
function spendY(spend: Pick<ScriptPathSpendRequest, 'secret'>): string {
  return hashToCurveBls(utf8ToBytes(spend.secret)).toHex(true);
}

function buildPackage(
  type: 'swap' | 'melt',
  inputs: Proof[],
  outputs: SerializedBlindedMessage[],
  plans: ScriptPathPlan[],
  meltQuote?: { quoteId: string; amount: bigint },
): ScriptPathSigningPackage {
  if (plans.length === 0) {
    throw new CTSError('A script path package needs at least one plan');
  }
  const spends = plans.map((plan) => {
    const proof = inputs.find((p) => p.secret === plan.secret && isBlsKeyset(p.id));
    if (!proof) {
      throw new CTSError('Script path plan names a secret not in this transaction');
    }
    const tree = proof.spend_info?.tree;
    if (!tree || plan.leafIndex < 0 || plan.leafIndex >= tree.length) {
      throw new CTSError(`Script path plan names leaf ${plan.leafIndex}, which is not disclosed`);
    }
    const info = proof.spend_info;
    let K = info?.K;
    if (info?.k) {
      try {
        K = bytesToHex(getPubKeyFromPrivKey(hexToBytes(info.k)));
      } catch {
        throw new CTSError('Script path package bearer key is not a valid private key');
      }
    }
    if (!K) {
      // NUT-10: K travels with a disclosed tree precisely so a signer who is not the receiver
      // can build a control block.
      throw new CTSError('Script path package needs the internal key from the proof spend info');
    }
    const leafHashes = tree.map((leaf) => nutrootLeafHash(hexToBytes(leaf)));
    const E = proof.spend_info?.E;
    // The package carries one leaf, so only the builder, holding the whole tree, knows the slots.
    const slots = E
      ? enumerateLeafKeySlots(tree.map((leaf) => parseNutrootLeaf(hexToBytes(leaf))))
          .filter((s) => s.leafIndex === plan.leafIndex)
          .map((s) => s.slot)
      : undefined;
    return {
      secret: plan.secret,
      leaf: tree[plan.leafIndex],
      control: {
        K,
        path: nutrootMerklePath(leafHashes, plan.leafIndex).map((h) => bytesToHex(h)),
      },
      ...(E && { E, slots }),
      signatures: [],
    };
  });
  return {
    version: SCRIPT_PATH_PREFIX,
    type,
    ...(meltQuote && { quote: meltQuote.quoteId, quoteAmount: meltQuote.amount }),
    inputs: inputs.map((p) => ({
      amount: p.amount,
      id: p.id,
      Y: hashToCurveHex(p.secret, p.id),
      C: p.C,
    })),
    outputs,
    spends,
  };
}

/**
 * Outputs in the order the payload will carry them, so a package's digest matches what is sent.
 */
function orderedOutputs(preview: SwapPreview): SerializedBlindedMessage[] {
  return orderOutputsForPayload(
    preview.keepOutputs ?? [],
    preview.sendOutputs ?? [],
  ).outputData.map((d) => d.blindedMessage);
}

function extractSwapPackage(
  preview: SwapPreview,
  plans: ScriptPathPlan[],
): ScriptPathSigningPackage {
  return buildPackage('swap', preview.inputs, orderedOutputs(preview), plans);
}

function extractMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote' | 'amount'>>(
  preview: MeltPreview<TQuote>,
  plans: ScriptPathPlan[],
  feeIndex?: number,
): ScriptPathSigningPackage {
  return buildPackage(
    'melt',
    preview.inputs,
    preview.outputData.map((d) => d.blindedMessage),
    plans,
    { quoteId: preview.quote.quote, amount: meltOutputAmount(preview.quote, feeIndex).toBigInt() },
  );
}

function serializePackage(pkg: ScriptPathSigningPackage): string {
  const json = JSONInt.stringify(pkg) ?? '{}';
  return `${SCRIPT_PATH_PREFIX}${encodeUint8ToBase64Url(utf8ToBytes(json))}`;
}

function deserializePackage(input: string): ScriptPathSigningPackage {
  if (!input.startsWith(SCRIPT_PATH_PREFIX)) {
    throw new CTSError(`Invalid signing package: must start with "${SCRIPT_PATH_PREFIX}"`);
  }
  let data: unknown;
  try {
    data = JSONInt.parse(
      bytesToUtf8(decodeBase64UrlToUint8(input.slice(SCRIPT_PATH_PREFIX.length))),
      undefined,
      { strict: true },
    );
  } catch (e) {
    throw new CTSError('Failed to parse signing package', { cause: e });
  }
  const pkg = data as ScriptPathSigningPackage;
  assertValidPackage(pkg);
  return pkg;
}

function assertValidPackage(pkg: ScriptPathSigningPackage): NutrootConditionLeaf[] {
  if (!pkg || typeof pkg !== 'object' || pkg.version !== SCRIPT_PATH_PREFIX) {
    throw new CTSError('Invalid signing package version');
  }
  if (pkg.type !== 'swap' && pkg.type !== 'melt') {
    throw new CTSError('Invalid signing package type');
  }
  if (!Array.isArray(pkg.inputs) || !Array.isArray(pkg.outputs) || !Array.isArray(pkg.spends)) {
    throw new CTSError('Malformed signing package');
  }
  // JSONInt flattens Amount to bare integers, so a decoded package must be rehydrated
  // before consumers touch it; digestOf normalizing internally would otherwise mask this.
  for (const [i, input] of pkg.inputs.entries()) {
    if (
      !input ||
      typeof input !== 'object' ||
      typeof input.Y !== 'string' ||
      typeof input.id !== 'string' ||
      typeof input.C !== 'string'
    ) {
      throw new CTSError(`Signing package input ${i} is malformed`);
    }
    try {
      input.amount = Amount.from(input.amount);
    } catch (e) {
      throw new CTSError(`Signing package input ${i} amount is invalid`, { cause: e });
    }
  }
  for (const [i, output] of pkg.outputs.entries()) {
    if (
      !output ||
      typeof output !== 'object' ||
      typeof output.B_ !== 'string' ||
      typeof output.id !== 'string'
    ) {
      throw new CTSError(`Signing package output ${i} is malformed`);
    }
    try {
      output.amount = Amount.from(output.amount);
    } catch (e) {
      throw new CTSError(`Signing package output ${i} amount is invalid`, { cause: e });
    }
  }
  if (
    pkg.type === 'melt' &&
    (typeof pkg.quote !== 'string' || pkg.quote.length === 0 || pkg.quoteAmount === undefined)
  ) {
    throw new CTSError('Melt signing package needs a quote and amount');
  }
  if (pkg.quoteAmount !== undefined) {
    try {
      pkg.quoteAmount = Amount.from(pkg.quoteAmount).toBigInt();
    } catch (e) {
      throw new CTSError('Signing package quote amount is invalid', { cause: e });
    }
  }
  const inputYs = new Set(pkg.inputs.filter((input) => isBlsKeyset(input.id)).map((i) => i.Y));
  const spent = new Set<string>();
  const leaves: NutrootConditionLeaf[] = [];
  for (const spend of pkg.spends) {
    if (
      typeof spend?.secret !== 'string' ||
      !isValidHex(spend.secret) ||
      spend.secret.length !== 66 ||
      !inputYs.has(spendY(spend)) ||
      spent.has(spend.secret)
    ) {
      throw new CTSError('Signing package spend must name one unique transaction input');
    }
    spent.add(spend.secret);
    let leaf;
    try {
      leaf = parseNutrootLeaf(hexToBytes(spend.leaf));
      if (
        !spend.control ||
        !Array.isArray(spend.control.path) ||
        !verifyNutrootCommitment(
          hexToBytes(spend.secret),
          hexToBytes(spend.control.K),
          hexToBytes(spend.leaf),
          spend.control.path.map((hash) => hexToBytes(hash)),
        )
      ) {
        throw new CTSError('commitment mismatch');
      }
    } catch (e) {
      throw new CTSError('Signing package leaf does not commit to its input secret', { cause: e });
    }
    if (leaf.type === 'commit') {
      throw new CTSError('Signing package names a commit leaf, which is not a spend path');
    }
    if (!Array.isArray(spend.signatures)) {
      throw new CTSError('Signing package signatures must be an array');
    }
    if (spend.slots !== undefined) {
      const isSlot = (s: unknown) =>
        Number.isInteger(s) && (s as number) >= 1 && (s as number) < NUTROOT_MAX_SLOTS;
      const oneSlotPerKey =
        Array.isArray(spend.slots) &&
        spend.slots.length === leaf.keys.length &&
        spend.slots.every(isSlot);
      if (!oneSlotPerKey) {
        throw new CTSError('Signing package slot hints must name one valid slot per leaf key');
      }
    }
    leaves.push(leaf);
  }
  return leaves;
}

function signPackage(pkg: ScriptPathSigningPackage, privkey: string): ScriptPathSigningPackage {
  const leaves = assertValidPackage(pkg);
  const digests = packageInputDigests(pkg);
  const pub = bytesToHex(getPubKeyFromPrivKey(hexToBytes(privkey)));
  const spends = pkg.spends.map((spend, i) => {
    const leaf = leaves[i];
    const keys: string[] = [];
    if (leaf.keys.some((key) => key.slice(-64) === pub.slice(-64))) {
      keys.push(privkey.toLowerCase());
    }
    if (spend.E !== undefined) {
      // The slot hint is trust-free: a wrong slot simply fails to match, and the fallback matches
      // by value over the whole slot space, which no leaf order or tree shape can defeat.
      const matches = (slots: number | number[]) => {
        const blinded = slotKeysByBlindedPubkey(spend.E!, privkey, slots);
        return leaf.keys.flatMap((key) => blinded.get(key)?.secretKey ?? []);
      };
      const hinted = spend.slots ? matches(spend.slots) : [];
      keys.push(...(hinted.length > 0 ? hinted : matches(NUTROOT_MAX_SLOTS - 1)));
    }
    if (keys.length === 0) return spend;
    const digest = digests.get(spend.secret);
    if (!digest) return spend; // assertValidPackage already rejected an unmatched spend
    const added = keys.map((k) => schnorrSignDigest(digest, k));
    return { ...spend, signatures: [...new Set([...spend.signatures, ...added])] };
  });
  return { ...pkg, spends };
}

function mergeSwapPackage(
  pkg: ScriptPathSigningPackage,
  preview: SwapPreview,
  plans?: ScriptPathPlan[],
): SwapPreview {
  if (pkg.type !== 'swap') throw new CTSError('Cannot merge a melt package into a swap');
  assertValidPackage(pkg);
  assertMatches(pkg, digestOf(preview.inputs, orderedOutputs(preview)));
  return { ...preview, inputs: applyWitnesses(pkg, preview.inputs, plans) };
}

function mergeMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote' | 'amount'>>(
  pkg: ScriptPathSigningPackage,
  preview: MeltPreview<TQuote>,
  plans?: ScriptPathPlan[],
): MeltPreview<TQuote> {
  if (pkg.type !== 'melt') throw new CTSError('Cannot merge a swap package into a melt');
  assertValidPackage(pkg);
  assertMatches(
    pkg,
    digestOf(
      preview.inputs,
      preview.outputData.map((d) => d.blindedMessage),
      { quoteId: preview.quote.quote, amount: Amount.from(preview.quote.amount).toBigInt() },
    ),
  );
  return { ...preview, inputs: applyWitnesses(pkg, preview.inputs, plans) };
}

function assertMatches(pkg: ScriptPathSigningPackage, expected: Uint8Array): void {
  if (!equalBytes(expected, packageDigest(pkg))) {
    throw new CTSError(
      'Signing package does not match this transaction: its inputs, outputs or their order moved since it was extracted',
    );
  }
}

function applyWitnesses(
  pkg: ScriptPathSigningPackage,
  inputs: Proof[],
  plans: ScriptPathPlan[] = [],
): Proof[] {
  const digests = packageInputDigests(pkg);
  const bySecret = new Map(pkg.spends.map((s) => [s.secret, s]));
  const preimages = new Map(plans.map((p) => [p.secret, p.preimage]));
  return inputs.map((proof) => {
    const spend = bySecret.get(proof.secret);
    if (!spend || !isBlsKeyset(proof.id)) return proof;
    const leaf = parseNutrootLeaf(hexToBytes(spend.leaf));
    const preimage = preimages.get(proof.secret);
    if (leaf.type === 'hashlock' && preimage === undefined) {
      throw new CTSError(
        'A hashlock spend needs its preimage at merge: pass the plans the package was extracted with',
      );
    }
    const signatures = selectRequiredLeafSignatures(
      leaf,
      digests.get(proof.secret)!,
      spend.signatures,
    );
    return {
      ...proof,
      witness: JSON.stringify({
        leaf: spend.leaf,
        control: spend.control,
        signatures,
        ...(preimage !== undefined && { preimage }),
      }),
    };
  });
}

/**
 * The {@link ScriptPath} surface.
 */
export type ScriptPathApi = {
  /**
   * Builds a signing package for a swap preview's script path plans.
   */
  extractSwapPackage(preview: SwapPreview, plans: ScriptPathPlan[]): ScriptPathSigningPackage;
  /**
   * Builds a signing package for a melt preview's script path plans.
   */
  extractMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote' | 'amount'>>(
    preview: MeltPreview<TQuote>,
    plans: ScriptPathPlan[],
    feeIndex?: number,
  ): ScriptPathSigningPackage;
  /**
   * Serializes a package to its `nutspA...` transport string.
   */
  serializePackage(pkg: ScriptPathSigningPackage): string;
  /**
   * Parses a transport string and fully validates it: digest, commitments, spend shape.
   */
  deserializePackage(input: string): ScriptPathSigningPackage;
  /**
   * Signs every spend in the package whose leaf names a key derived from `privkey`.
   *
   * @remarks
   * Handles both forms a leaf key takes: verbatim, and blinded at a NUT-28 slot, which needs the
   * package's `E` to derive. Signatures are deduplicated, so signing twice is harmless.
   * @returns The package with any new signatures appended. Signs nothing if no leaf names the key.
   */
  signPackage(pkg: ScriptPathSigningPackage, privkey: string): ScriptPathSigningPackage;
  /**
   * Injects the package's witnesses into the swap preview it came from.
   *
   * @remarks
   * Recomputes the digest from the preview and refuses if it moved: a package signed against one
   * set of outputs cannot be spent against another, and output order is part of that. `plans` are
   * the ones the package was extracted with: a hashlock leaf takes its preimage from there, since
   * the package never carries it.
   * @throws If the package does not belong to this preview, a spend is short of its leaf's
   *   signature threshold, or a hashlock spend has no preimage in `plans`.
   */
  mergeSwapPackage(
    pkg: ScriptPathSigningPackage,
    preview: SwapPreview,
    plans?: ScriptPathPlan[],
  ): SwapPreview;
  /**
   * Melt counterpart of {@link ScriptPathApi.mergeSwapPackage}.
   */
  mergeMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote' | 'amount'>>(
    pkg: ScriptPathSigningPackage,
    preview: MeltPreview<TQuote>,
    plans?: ScriptPathPlan[],
  ): MeltPreview<TQuote>;
  /**
   * The witness a spend would produce, without a preview. Useful for inspection.
   */
  witnessFor(
    spend: ScriptPathSpendRequest,
    tree: string[],
    leafIndex: number,
    preimage?: string,
  ): string;
};

/**
 * Out-of-band signing for script path spends (NUT-10).
 *
 * @remarks
 * Extract a package from a preview, send it to whoever holds the keys, merge the signatures back,
 * then complete. The transaction is not in flight while signing happens, so the ceremony can
 * outlive the process: use this where a co-signer is a person or another device, and the `cosign`
 * hook on {@link ScriptPathPlan} where it is a service answering in seconds.
 * @experimental
 */
export const ScriptPath: ScriptPathApi = {
  extractSwapPackage,
  extractMeltPackage,
  serializePackage,
  deserializePackage,
  signPackage,
  mergeSwapPackage,
  mergeMeltPackage,
  witnessFor: (spend, tree, leafIndex, preimage) =>
    buildScriptPathWitness(tree, leafIndex, spend.control.K, spend.signatures, preimage),
};

export type { NutrootLeaf };

src/model/SigAll.ts.source:
import { utf8ToBytes } from '@noble/hashes/utils.js';

import {
  assertSigAllInputs,
  assertSignerAuthorised,
  buildP2PKSigAllMessageV0,
  computeMessageDigest,
  isValidSecpPubkey,
  pointFromHexAuto,
  schnorrSignDigest,
} from '../crypto';
import { parseWitnessData } from '../crypto/NUT11';
import {
  JSONInt,
  MAX_P2PK_SIGNATURES,
  MAX_PAYLOAD_LENGTH,
  decodeBase64UrlToUint8,
  decodeUtf8Document,
  encodeUint8ToBase64Url,
} from '../utils';
import { orderOutputsForPayload } from '../wallet/_internal';
import type { MeltPreview, SwapPreview } from '../wallet/types';

import { Amount } from './Amount';
import { CTSError } from './Errors';
import type { Proof, MeltQuoteBaseResponse, SerializedBlindedMessage } from './types';

/**
 * @experimental
 */
const SIGALL_PREFIX = 'sigallA';

/**
 * Per-format SIG_ALL digests, keyed by transcript version.
 *
 * @experimental
 */
export type SigAllDigests = {
  /**
   * Unframed concatenation format (CDK >= 0.14.0, Nutshell > 0.20.2).
   */
  v0: string;
};

/**
 * Represents a signing package for SigAll multi-party signing.
 *
 * This is a wallet-led transport format, it contains only the minimum data required to reconstruct
 * the SIG_ALL message.
 *
 * @experimental
 */
export type SigAllSigningPackage = {
  /**
   * Signing package version.
   */
  version: 'sigallA';
  /**
   * Type of signing package.
   */
  type: 'swap' | 'melt';
  /**
   * Required for melt packages, absent for swaps.
   */
  quote?: string;
  /**
   * Minimal input data required for signing verification.
   */
  inputs: Array<Pick<Proof, 'secret' | 'C'>>;
  /**
   * NUT-00 `BlindedMessages` for signing verification.
   */
  outputs: SerializedBlindedMessage[];
  /**
   * Signatures collected (to be injected into the first proof witness).
   */
  witness?: { signatures: string[] };
};

function computeDigests(
  inputs: Array<Pick<Proof, 'secret' | 'C'>>,
  outputs: SerializedBlindedMessage[],
  quoteId?: string,
): SigAllDigests {
  const sigAllOutputs = outputs.map((blindedMessage) => ({ blindedMessage }));
  const v0Msg = buildP2PKSigAllMessageV0(inputs, sigAllOutputs, quoteId);

  return {
    v0: computeMessageDigest(v0Msg, true),
  };
}

function serializePackage(pkg: SigAllSigningPackage): string {
  // Build object with fixed key order for determinism
  const ordered: Record<string, unknown> = { version: pkg.version, type: pkg.type };

  if (pkg.quote) ordered.quote = pkg.quote;

  ordered.inputs = pkg.inputs;
  ordered.outputs = pkg.outputs;

  if (pkg.witness) ordered.witness = pkg.witness;

  const json = JSONInt.stringify(ordered) ?? '{}';
  const base64url = encodeUint8ToBase64Url(utf8ToBytes(json));

  return `${SIGALL_PREFIX}${base64url}`;
}

function deserializePackage(input: string): SigAllSigningPackage {
  if (!input.startsWith(SIGALL_PREFIX)) {
    throw new CTSError(`Invalid signing package: must start with "${SIGALL_PREFIX}"`);
  }

  if (input.length - SIGALL_PREFIX.length > MAX_PAYLOAD_LENGTH) {
    throw new CTSError(`Signing package exceeds ${MAX_PAYLOAD_LENGTH} characters`);
  }

  const base64url = input.slice(SIGALL_PREFIX.length);
  let json: string;

  try {
    json = decodeUtf8Document(decodeBase64UrlToUint8(base64url));
  } catch (e) {
    throw new CTSError(
      `Failed to parse signing package: ${e instanceof Error ? e.message : String(e)}`,
      { cause: e },
    );
  }

  let data: unknown;

  try {
    data = JSONInt.parse(json, undefined, { strict: true });
  } catch (e) {
    throw new CTSError(
      `Failed to parse signing package JSON: ${e instanceof Error ? e.message : String(e)}`,
      { cause: e },
    );
  }

  if (!data || typeof data !== 'object') {
    throw new CTSError('Signing package must be a JSON object');
  }

  const pkg = data as SigAllSigningPackage;

  const version = pkg.version as string;
  if (version !== SIGALL_PREFIX) {
    throw new CTSError(`Invalid signing package version: ${version}`);
  }

  const type = pkg.type as string;
  if (type !== 'swap' && type !== 'melt') {
    throw new CTSError(`Invalid signing package type: ${type}`);
  }

  // The quote is part of the signed melt transcript; without it a melt package
  // would produce a swap-shaped message.
  if (type === 'melt' && (typeof pkg.quote !== 'string' || pkg.quote.length === 0)) {
    throw new CTSError('Melt signing package requires a quote');
  }

  if (!Array.isArray(pkg.inputs)) {
    throw new CTSError('Signing package inputs must be an array');
  }

  for (let i = 0; i < pkg.inputs.length; i++) {
    const inp = pkg.inputs[i] as Record<string, unknown>;

    if (!inp || typeof inp !== 'object') throw new CTSError(`Invalid input at index ${i}`);

    if (typeof inp.secret !== 'string') throw new CTSError(`Input ${i}: secret must be string`);

    if (typeof inp.C !== 'string') throw new CTSError(`Input ${i}: C must be string`);
  }

  if (!Array.isArray(pkg.outputs)) {
    throw new CTSError('Signing package outputs must be an array');
  }

  for (let i = 0; i < pkg.outputs.length; i++) {
    const output = pkg.outputs[i] as Record<string, unknown>;

    if (!output || typeof output !== 'object') throw new CTSError(`Invalid output at index ${i}`);

    if (typeof output.amount !== 'number' && typeof output.amount !== 'bigint') {
      throw new CTSError(`Output ${i}: amount must be a number or bigint`);
    }

    if (!output.B_ || typeof output.B_ !== 'string') throw new CTSError(`Output ${i}: B_ invalid`);

    if (!output.id || typeof output.id !== 'string') throw new CTSError(`Output ${i}: id invalid`);

    // Rehydrate SerializedBlindedMessage.amount
    output.amount = Amount.from(output.amount);
  }

  if (pkg.witness !== undefined) {
    const witness = pkg.witness as { signatures?: unknown };
    if (
      !witness ||
      typeof witness !== 'object' ||
      !Array.isArray(witness.signatures) ||
      witness.signatures.some((s) => typeof s !== 'string')
    ) {
      throw new CTSError('Signing package witness.signatures must be a string array');
    }
  }

  // Rebuild from validated fields only, so unknown keys never survive transport.
  return {
    version: SIGALL_PREFIX,
    type,
    ...(type === 'melt' ? { quote: pkg.quote } : {}),
    inputs: pkg.inputs.map((p) => ({ secret: p.secret, C: p.C })),
    outputs: pkg.outputs.map((o) => ({ amount: o.amount, id: o.id, B_: o.B_ })),
    ...(pkg.witness ? { witness: { signatures: pkg.witness.signatures } } : {}),
  };
}

// NUT-04/05 quote ids are UUIDs, and every current mint issues UUIDv7 ids.
const UUID_QUOTE_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PRIVKEY_HEX_RE = /^[0-9a-f]{64}$/i;

/**
 * Refuses to sign anything but a well-formed SIG_ALL transaction the key is a party to.
 *
 * @remarks
 * C, B_ and the quote are hashed into the transcript, so each must be a real point and the quote a
 * UUID. The witness is bounded before another signature is added to it.
 */
function assertSignable(pkg: SigAllSigningPackage, privkey: string): void {
  if (!PRIVKEY_HEX_RE.test(privkey)) {
    throw new CTSError('Private key must be 64 hex characters');
  }
  if ((pkg.witness?.signatures.length ?? 0) >= MAX_P2PK_SIGNATURES) {
    throw new CTSError(`Witness already at the ${MAX_P2PK_SIGNATURES}-signature limit`);
  }
  assertSigAllInputs(pkg.inputs);
  pkg.inputs.forEach((input, i) => {
    if (!isValidSecpPubkey(input.C)) {
      throw new CTSError(`Input ${i}: C must be a compressed secp256k1 point`);
    }
  });
  pkg.outputs.forEach((output, i) => {
    try {
      pointFromHexAuto(output.B_);
    } catch (e) {
      throw new CTSError(`Output ${i}: B_ must be a compressed curve point`, { cause: e });
    }
  });
  if (pkg.quote !== undefined && !UUID_QUOTE_RE.test(pkg.quote)) {
    throw new CTSError('Melt quote id must be a UUID');
  }
  // SIG_ALL inputs share one lock, so the first secret names every expected signer.
  assertSignerAuthorised(pkg.inputs[0].secret, privkey);
}

function signPackage(pkg: SigAllSigningPackage, privkey: string): SigAllSigningPackage {
  assertSignable(pkg, privkey);
  // Sign transcripts recomputed from the package contents; a signer only ever
  // signs what the package shows, never a digest chosen elsewhere.
  const digests = computeDigests(pkg.inputs, pkg.outputs, pkg.quote);
  const newSigs = [schnorrSignDigest(digests.v0, privkey)];

  return {
    ...pkg,
    witness: { signatures: [...(pkg.witness?.signatures || []), ...newSigs] },
  };
}

function extractSwapPackage(preview: SwapPreview): SigAllSigningPackage {
  // Both halves are needed for the message, in the order the payload will carry them: the same
  // ordering the swap applies, or the signatures cover outputs the mint never sees.
  const allOutputs = orderOutputsForPayload(
    preview.keepOutputs ?? [],
    preview.sendOutputs ?? [],
  ).outputData;
  return buildSigningPackage(
    'swap',
    preview.inputs,
    allOutputs.map((output) => output.blindedMessage),
  );
}

function extractMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote'>>(
  preview: MeltPreview<TQuote>,
): SigAllSigningPackage {
  return buildSigningPackage(
    'melt',
    preview.inputs,
    preview.outputData.map((output) => output.blindedMessage),
    preview.quote.quote,
  );
}

function buildSigningPackage(
  type: 'swap' | 'melt',
  inputs: Array<Pick<Proof, 'secret' | 'C'>>,
  outputs: SerializedBlindedMessage[],
  quoteId?: string,
): SigAllSigningPackage {
  return {
    version: SIGALL_PREFIX,
    type,
    ...(quoteId ? { quote: quoteId } : {}),
    inputs: inputs.map((p) => ({ secret: p.secret, C: p.C })),
    outputs,
  };
}

function mergeSwapPackage(pkg: SigAllSigningPackage, preview: SwapPreview): SwapPreview {
  const updatedInputs = mergeSignatures(preview.inputs, pkg);
  return { ...preview, inputs: updatedInputs };
}

function mergeMeltPackage<TQuote extends Pick<MeltQuoteBaseResponse, 'quote'>>(
  pkg: SigAllSigningPackage,
  preview: MeltPreview<TQuote>,
): MeltPreview<TQuote> {
  const updatedInputs = mergeSignatures(preview.inputs, pkg);
  return { ...preview, inputs: updatedInputs };
}

function mergeSignatures(proofs: Proof[], pkg: SigAllSigningPackage): Proof[] {
  if (!pkg.witness?.signatures.length) {
    throw new CTSError('No signatures to merge');
  }

  if (proofs.length === 0) return proofs;

  const [first, ...rest] = proofs;
  const witnessData = parseWitnessData(first.witness);
  const existingSignatures = witnessData?.signatures ?? [];
  const updatedFirst: Proof = {
    ...first,
    witness: {
      ...(witnessData ?? {}),
      signatures: [...existingSignatures, ...pkg.witness.signatures],
    },
  };

  return [updatedFirst, ...rest];
}

/**
 * Helpers for SigAll multi-party signing coordination.
 *
 * @experimental
 */
export type SigAllApi = {
  /**
   * Computes the SIG_ALL digests for a transaction, keyed by transcript version.
   *
   * @param inputs Proof array.
   * @param outputs Array of SerializedBlindMessage (NUT-00 `BlindMessages`).
   * @param quoteId Optional quote ID for melt transactions.
   * @returns Hex-encoded SHA256 digest per format.
   * @experimental
   */
  computeDigests: (
    inputs: Array<Pick<Proof, 'secret' | 'C'>>,
    outputs: SerializedBlindedMessage[],
    quoteId?: string,
  ) => SigAllDigests;

  /**
   * Extracts a signing package from a SwapPreview for multi-party SIG_ALL coordination.
   *
   * @remarks
   * This creates a minimal, serializable package that can be passed to other signers. Secrets and
   * blinding factors are NOT included - only what's needed to reconstruct the exact SIG_ALL message
   * and produce signatures.
   * @param preview SwapPreview from prepareSwapToSend or prepareSwapToReceive.
   * @returns SigAllSigningPackage for distribution to signers.
   * @experimental
   */
  extractSwapPackage: (preview: SwapPreview) => SigAllSigningPackage;

  /**
   * Extracts a signing package from a MeltPreview for multi-party SIG_ALL coordination.
   *
   * @param preview MeltPreview from prepareMelt.
   * @returns SigAllSigningPackage for distribution to signers.
   * @experimental
   */
  extractMeltPackage: <TQuote extends Pick<MeltQuoteBaseResponse, 'quote'>>(
    preview: MeltPreview<TQuote>,
  ) => SigAllSigningPackage;

  /**
   * @remarks
   * Produces a deterministic JSON representation, base64url-encodes it and prefixes with sigallA
   * for transport.
   *
   * - Field order is fixed and version field is always included for compatibility.
   * - This enables consistent hashing and verification of package integrity.
   *
   * @param pkg The signing package to serialize.
   * @returns JSON string with sorted keys.
   * @experimental
   */
  serializePackage: (pkg: SigAllSigningPackage) => string;

  /**
   * @remarks
   * Accepts a sigallA-prefixed base64url string and rehydrates it into a SigAllSigningPackage. Only
   * known fields survive the round trip.
   * @experimental
   */
  deserializePackage: (input: string) => SigAllSigningPackage;

  /**
   * Signs a SigAllSigningPackage and returns it with signatures attached.
   *
   * @remarks
   * Signs the SIG_ALL transcripts recomputed from the package's own inputs, outputs and quote.
   * Multiple parties can call this sequentially to aggregate signatures for multi-party signing.
   * @param pkg The signing package (from extract*SigningPackage or another signer)
   * @param privkey Private key to sign with.
   * @returns Package with signatures appended to witness field.
   * @throws {@link CTSError} If the inputs are not a valid SIG_ALL set, a C or B_ is not a
   *   compressed point, the melt quote id is not a UUID, the private key is not 64 hex characters,
   *   the witness is already at its signature limit, or the lock does not currently name the
   *   signing key. That last case includes an expired lock with no refund keys (nothing to sign)
   *   and a P2BK lock, whose keys are blinded: derive the blinded key before signing.
   * @experimental
   */
  signPackage: (pkg: SigAllSigningPackage, privkey: string) => SigAllSigningPackage;

  /**
   * Signs a hex-encoded digest with a Schnorr key.
   */
  signDigest: (hexDigest: string, privkey: string) => string;

  /**
   * Merges signatures from a signing package back into a SwapPreview.
   *
   * @remarks
   * Injects collected signatures into the first proof's witness for mint submission. Call this
   * after all parties have signed.
   * @param pkg Signing package with collected signatures.
   * @param preview Original SwapPreview.
   * @returns SwapPreview ready for completeSwap.
   * @experimental
   */
  mergeSwapPackage: (pkg: SigAllSigningPackage, preview: SwapPreview) => SwapPreview;

  /**
   * Merges signatures from a signing package back into a MeltPreview.
   *
   * @param pkg Signing package with collected signatures.
   * @param preview Original MeltPreview.
   * @returns MeltPreview ready for completeMelt.
   * @experimental
   */
  mergeMeltPackage: <TQuote extends Pick<MeltQuoteBaseResponse, 'quote'>>(
    pkg: SigAllSigningPackage,
    preview: MeltPreview<TQuote>,
  ) => MeltPreview<TQuote>;
};

/**
 * @experimental
 */
export const SigAll: SigAllApi = {
  computeDigests,
  extractSwapPackage,
  extractMeltPackage,
  serializePackage,
  deserializePackage,
  signPackage,
  signDigest: schnorrSignDigest,
  mergeSwapPackage,
  mergeMeltPackage,
};

