import {
  type MeltPreview,
  type OutputType,
  type OutputConfig,
  type SendConfig,
  type SendOfflineConfig,
  type ReceiveConfig,
  type MintProofsConfig,
  type MeltProofsConfig,
  type CompleteMeltOptions,
  type CompleteSwapOptions,
