// model helpers

const PENDING_KEYSET_ID = '__PENDING__';

// NUT-20 "Signature for mint request invalid"
const MINT_QUOTE_SIGNATURE_INVALID_CODE = 20008;

/**
 * One scanned counter range. `used` is proven by a SPENT state or a returned signature, and a used
 * range always names the last such counter.
 */
type ScanResult =
  | { proofs: Proof[]; used: false }
  | { proofs: Proof[]; lastCounterWithSignature: number; used: true };

/**
 * Class that represents a Cashu wallet.
 *
 * @remarks
 * This class should act as the entry point for this library. Can be instantiated with a mint
 * instance or mint url.
 * @example
 *
 * ```typescript
 * import { Wallet } from '@cashu/cashu-ts';
 * const wallet = new Wallet('http://localhost:3338', { unit: 'sat' });
 * await wallet.loadMint(); // Initialize mint info, keysets, and keys
 * // Wallet is now ready to use, eg:
 * const proofs = [...]; // your array of unspent proofs
 * const { keep, send } = await wallet.send(32, proofs);
 * ```
 */
class Wallet {
  /**
   * Mint instance - allows direct calls to the mint.
   */
  public readonly mint: Mint;
  /**
   * Entry point for the builder.
   *
   * @example
   *
   *     const { keep, send } = await wallet.ops
   *       .send(5, proofs)
   *       .asDeterministic() // counter: 0 = auto
   *       .keepAsRandom()
   *       .includeFees(true)
   *       .run();
   *
   *     const proofs = await wallet.ops
   *       .receive(token)
   *       .asDeterministic()
   *       .keyset(wallet.keysetId)
   *       .run();
   */
  public readonly ops: WalletOps;
  /**
   * Convenience wrapper for events.
   */
  public readonly on: WalletEvents;
  /**
   * Developer-friendly counters API.
   */
  public readonly counters: WalletCounters;
  private _keyChain: KeyChain;
  private _seed: Uint8Array | undefined = undefined;
  private _unit = 'sat';
  private _mintInfo: MintInfo | undefined = undefined;
  private _denominationTarget = 3;
  private _secretsPolicy: SecretsPolicy = 'auto';
  private _counterSource: CounterSource;
  private _boundKeysetId: string = PENDING_KEYSET_ID;
  private _pendingRepair: Promise<void> | null = null;
  private _lastRepairAt = 0;
  private _explicitBind: boolean = false;
  private _selectProofs: SelectProofs;
  private _outputDataCreator: OutputDataCreator;
  private _hashToCurve: (secret: string, keysetId: string) => string;
  private _requireSigDleq = false;
  private _strictCachedKeysets: boolean = false;
  private _logger: Logger;

  /**
   * Create a wallet for a given mint and unit. Call `loadMint` before use.
   *
   * Binding, if `options.keysetId` is omitted, the wallet binds to the cheapest active keyset for
   * this unit during `loadMint`.
   *
   * Caching, preload mint info and keychain data by calling `loadMintFromCache` after construction.
   *
   * The keychain stores all loaded keysets and filters query results by the wallet unit.
   *
   * Deterministic secrets, pass `bip39seed` and optionally `secretsPolicy`. Deterministic outputs
   * reserve counters from `counterSource`, or an ephemeral in memory source if not supplied.
   * `initialCounter` applies only with a supplied `keysetId` and the ephemeral source.
   *
   * Splitting, `denominationTarget` guides proof splits, default is 3. Override coin selection with
   * `selectProofs` if needed. Logging defaults to a null logger.
   *
   * @param mint Mint instance or URL.
   * @param options Optional settings.
   * @param options.unit Wallet unit, default 'sat'.
   * @param options.keysetId Bind to this keyset id, else bind on `loadMint`.
   * @param options.bip39seed BIP39 seed for deterministic secrets, 64 bytes.
   * @param options.secretsPolicy Secrets policy, default 'auto'.
   * @param options.counterSource Counter source for deterministic outputs. If provided, this takes
   *   precedence over counterInit. Use when you need persistence across processes or devices.
   * @param options.counterInit Seed values for the built-in EphemeralCounterSource. Ignored if
   *   counterSource is also provided.
   * @param options.denominationTarget Target proofs per denomination, default 3.
   * @param options.selectProofs Custom proof selection function. Default: selectProofsRotating.
   * @param options.outputDataCreator Custom OutputDataCreator implementation. The canonical and
   *   maintained implementation is the default Noble Curves based behavior exposed by
   *   `OutputData.create*()`. Custom creators are an escape hatch for runtime-specific needs, and
   *   compatibility and maintenance are the integrator's responsibility.
   * @param options.hashToCurve Custom `Y = hash_to_curve(secret)` returning compressed hex; hash
   *   the secret string as UTF-8, as `hashToCurveHex` does. The keyset id selects the curve (v3
   *   `02…` ids are BLS12-381 G1, all others secp256k1). Use it to plug a WASM or native
   *   implementation: a restore scan hashes every counter it visits, and the pure JS BLS hash
   *   dominates that cost. Same support terms as `outputDataCreator`.
   * @param options.requireSigDleq Fail mint/swap/melt responses when the mint advertises NUT-12
   *   support but omits DLEQ proofs on returned blinded signatures. This is a fail-fast consistency
   *   check, not protection against a malicious mint already consuming inputs or payments.
   * @param options.strictCachedKeysets Never fetch keyset data inside operations; only the snapshot
   *   you load is used. Insufficient state throws the same typed errors as non-strict mode's
   *   terminal cases. Default false.
   * @param options.customRequest Custom mint request function. Use this to route all mint HTTP
   *   requests through runtime-specific transports such as OHTTP, Tor, native HTTP clients, or
   *   proxies. Only used when `mint` is passed as a URL string; pass a configured `Mint` instance
   *   when you need full control.
   * @param options.requestFetch Custom fetch-compatible transport for mint HTTP requests. Use this
   *   for per-wallet OHTTP, Tor, native HTTP clients, or proxies while preserving the default
   *   request pipeline. Ignored when `customRequest` is supplied.
   * @param options.logger Logger instance, default null logger.
   */
  constructor(
    mint: Mint | string,
    options?: {
      unit?: string;
      authProvider?: AuthProvider;
      keysetId?: string; // if omitted, wallet binds to cheapest in loadMint
      bip39seed?: Uint8Array;
      secretsPolicy?: SecretsPolicy; // optional, auto
      counterSource?: CounterSource; // optional, otherwise ephemeral
      counterInit?: Record<string, number>; // optional, starting "next" per keyset
      denominationTarget?: number;
      selectProofs?: SelectProofs; // optional override
      outputDataCreator?: OutputDataCreator;
      hashToCurve?: (secret: string, keysetId: string) => string;
      requireSigDleq?: boolean;
      strictCachedKeysets?: boolean;
      customRequest?: RequestFn;
      requestFetch?: RequestFetch;
      logger?: Logger;
    },
  ) {
    this.ops = new WalletOps(this);
    this.on = new WalletEvents(this);
    this._logger = options?.logger ?? NULL_LOGGER; // init early (seed can throw)
    this._selectProofs = options?.selectProofs ?? selectProofsRotating; // vital
    this._outputDataCreator = options?.outputDataCreator ?? new DefaultOutputDataCreator();
    this._hashToCurve = options?.hashToCurve ?? hashToCurveHex;
    this.mint =
      typeof mint === 'string'
        ? new Mint(mint, {
            authProvider: options?.authProvider,
            customRequest: options?.customRequest,
            requestFetch: options?.requestFetch,
            logger: this._logger,
          })
        : mint;
    this._unit = options?.unit ?? this._unit;
    this._boundKeysetId = options?.keysetId ?? this._boundKeysetId;
    this._explicitBind = options?.keysetId !== undefined;
    if (options?.bip39seed) {
      // failIf forwards this context to the logger, so pass the type, never the seed.
      this.failIf(
        !(options.bip39seed instanceof Uint8Array),
        'bip39seed must be a valid Uint8Array',
        { received: typeof options.bip39seed },
      );
      // Fail here rather than at the first derivation: a wallet on a seed NUT-13 will refuse is
      // broken, and the deriver's own guard would surface it mid-operation.
      this.failIf(
        options.bip39seed.length !== SEED_BYTES,
        `bip39seed must be ${SEED_BYTES} bytes`,
        { length: options.bip39seed.length },
      );
      this._seed = options.bip39seed;
    }
    this._secretsPolicy = options?.secretsPolicy ?? this._secretsPolicy;
    if (options?.counterSource) {
      this._counterSource = options.counterSource;
    } else {
      this._counterSource = new EphemeralCounterSource(options?.counterInit);
    }
    this.counters = new WalletCounters(this._counterSource);
    this._keyChain = new KeyChain(this.mint, this._unit, this._logger);
    this._denominationTarget = options?.denominationTarget ?? this._denominationTarget;
    this._requireSigDleq = options?.requireSigDleq ?? this._requireSigDleq;
    this._strictCachedKeysets = options?.strictCachedKeysets ?? this._strictCachedKeysets;
  }

  // Convenience wrappers for "log and throw"
  private fail(message: string, context?: Record<string, unknown>): never {
    return fail(message, this._logger, context);
  }
  private failIf(
    condition: boolean,
    message: string,
    context?: Record<string, unknown>,
  ): asserts condition is false {
    return failIf(condition, message, this._logger, context);
  }
  private failIfNullish<T>(
    value: T,
    message: string,
    context?: Record<string, unknown>,
  ): asserts value is Exclude<T, null | undefined> {
    return failIfNullish(value, message, this._logger, context);
  }
  private requireSupport(op: 'mint' | 'melt', method: string): void {
    this.failIf(
      !this.getMintInfo().supportsMintMeltMethod(op, method, this._unit),
      `Mint does not support ${method} ${op} for unit '${this._unit}'`,
    );
  }
  private safeCallback<T>(
    cb: ((p: T) => void) | undefined,
    payload: T,
    context?: Record<string, unknown>,
  ): void {
    safeCallback(cb, payload, this._logger, context);
  }

  /**
   * Parses AmountLike to Amount.
   */
  private parseAmount(amount: AmountLike, op: string, allowZero = false): Amount {
    try {
      const parsed = Amount.from(amount);
      if (!allowZero) {
        this.failIf(parsed.isZero(), `Amount must be positive: ${parsed.toString()}`, {
          op,
          amount,
        });
      }
      return parsed;
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      this._logger.error(message, { op, amount });
      throw new CTSError(message, { cause: e });
    }
  }

  /**
   * Load mint information, keysets, and keys.
   *
   * @remarks
   * Must be called before other methods, unless loading from cache (`loadMintFromCache`). With
   * `forceRefresh`, metadata refreshes, held keys are kept, and an auto-bound wallet re-applies
   * cheapest-keyset selection on every refresh; pinned wallets stay pinned.
   * @param forceRefresh If true, re-fetches data even if cached.
   * @throws If fetching mint info, keysets, or keys fails.
   */
  async loadMint(forceRefresh?: boolean): Promise<void> {
    const promises = [];

    // Load mint info
    if (!this._mintInfo || forceRefresh) {
      promises.push(
        this.mint.getInfo().then((info) => {
          this._mintInfo = new MintInfo(info, this._logger);
          this.mint.setMintInfo(this._mintInfo);
          return null;
        }),
      );
    }

    // Load KeyChain
    promises.push(this._keyChain.init(forceRefresh));

    await Promise.all(promises);
    this.finishInit();
  }

  /**
   * Load mint information, keysets, and keys from cached data.
   *
   * @remarks
   * Use this when you already have cached mint info and keychain cache and want to avoid network
   * calls.
   *
   * The `cache` argument should usually come from `wallet.keyChain.cache`.
   */
  loadMintFromCache(mintInfo: GetInfoResponse, cache: KeyChainCache): void {
    // The keychain load is the step that can reject the cache, so it goes first and a rejected
    // cache leaves the wallet untouched.
    this._keyChain.loadFromCache(cache);
    this._mintInfo = new MintInfo(mintInfo, this._logger);
    this.mint.setMintInfo(this._mintInfo);
    this.finishInit();
  }

  /**
   * Finishes wiring up the wallet instance and checks we are "Go for launch".
   */
  private finishInit(): void {
    this._logger.debug('KeyChain', { keychain: this._keyChain.cache });

    // Go Keychain?
    if (this._boundKeysetId === PENDING_KEYSET_ID) {
      try {
        // Bind the cheapest active keyset
        this._boundKeysetId = this._keyChain.getCheapestKeyset().id;
      } catch (e) {
        // Edge case: mint has no active keysets, so leave wallet unbound
        // May happen if a mint is closing down and unwinding liabilities
        this._logger.warn('No active keyset available, wallet remains unbound', {
          unit: this._unit,
          err: (e as Error).message,
        });
      }
    } else if (this._explicitBind) {
      // Keyset ID was pinned by the caller, so ensure it exists and unit
      // matches, but do NOT require keys yet. It may be an inactive keyset for
      // restore, and if so, keys will be fetched async later.
      const k = this._keyChain.getKeyset(this._boundKeysetId);
      this.failIf(k.unit !== this._unit, 'Keyset unit does not match wallet unit', {
        keyset: k.id,
        unit: k.unit,
        walletUnit: this._unit,
      });
    } else {
      // Auto-bound: re-apply keyset selection so the binding tracks mint truth.
      // getCheapestKeyset prefers the newest version, then lowest fee, then latest expiry.
      const current = this._keyChain.hasKeyset(this._boundKeysetId)
        ? this._keyChain.getKeyset(this._boundKeysetId)
        : undefined;
      try {
        const next = this._keyChain.getCheapestKeyset().id;
        if (next !== this._boundKeysetId) {
          this._boundKeysetId = next;
          this._logger.info('Wallet rebound to cheapest active keyset after refresh', {
            keysetId: next,
          });
        }
      } catch (e) {
        // No active replacement: keep a still-known binding (melt stays possible),
        // unbind only if the keyset vanished from the mint entirely.
        if (!current) {
          this._boundKeysetId = PENDING_KEYSET_ID;
        }
        this._logger.warn('No active keyset available after refresh', {
          unit: this._unit,
          err: (e as Error).message,
        });
      }
    }

    // Go Mintinfo?
    this.getMintInfo();
  }

  // -----------------------------------------------------------------
  // Section: Getters
  // -----------------------------------------------------------------

  /**
   * Get the wallet's KeyChain.
   *
   * @returns The Keychain.
   */
  get keyChain(): KeyChain {
    return this._keyChain;
  }

  /**
   * Get the wallet's unit.
   *
   * @returns The unit (e.g., 'sat').
   */
  get unit(): string {
    return this._unit;
  }

  /**
   * Get information about the mint.
   *
   * @remarks
   * Returns cached mint info. Call `loadMint` first to initialize the wallet.
   * @returns Mint info.
   * @throws If mint info is not initialized.
   */
  getMintInfo(): MintInfo {
    this.failIfNullish(
      this._mintInfo,
      'Mint info not initialized; call loadMint or loadMintFromCache first',
    );
    return this._mintInfo;
  }

  /**
   * NUT-06: the mint's advertised cap on the length of any array in a request, used to size the
   * NUT-07 state check and NUT-09 restore batches. Falls back to the library default until mint
   * info is loaded.
   */
  private get maxArrayLength(): number {
    return this._mintInfo?.maxArrayLength ?? DEFAULT_MAX_ARRAY_LENGTH;
  }

  /**
   * The keyset ID bound to this wallet instance.
   */
  get keysetId(): string {
    this.failIf(
      this._boundKeysetId === PENDING_KEYSET_ID,
      'Wallet has no bound keyset. The mint may have no active keysets, or wallet was not initialized via loadMint or loadMintFromCache',
    );
    return this._boundKeysetId;
  }

  /**
   * Gets the requested keyset or the keyset bound to the wallet.
   *
   * @remarks
   * This method enforces wallet policies. If `id` is omitted, it returns the keyset bound to this
   * wallet, including validation that:
   *
   * - The keyset exists in the keychain,
   * - The unit matches the wallet's unit,
   * - Keys are loaded for that keyset.
   *
   * Contrast with `keyChain.getKeyset(id?)`, which, when called without an id, returns the cheapest
   * active keyset for the unit, ignoring the wallet binding.
   * @param id Optional keyset id to resolve. If omitted, the wallet's bound keyset is used.
   * @returns The resolved `Keyset`.
   * @throws If the keyset is not found, has no keys, or its unit differs from the wallet.
   */
  public getKeyset(id?: string): Keyset {
    const keyset = this._keyChain.getKeyset(id ?? this.keysetId);
    this.failIf(keyset.unit !== this._unit, 'Keyset unit does not match wallet unit', {
      keyset: keyset.id,
      unit: keyset.unit,
      walletUnit: this._unit,
    });
    this.failIf(!keyset.hasKeys, 'Keyset has no keys loaded', { keyset: keyset.id });
    return keyset;
  }

  /**
   * Resolves the keyset used to create new proofs, enforcing the output policy.
   *
   * @remarks
   * Legacy (pre-v1, base64-id) keysets may be spent and restored, but never used to create new
   * proofs. Inactive keysets are rejected per NUT-02, the mint would refuse to sign outputs on
   * them, so fail fast here. Unknown hex versions are already excluded upstream: their keys fail
   * verification and `getKeyset` rejects keysets without keys.
   *
   * Only the prepare-side ops use this gate. The `complete*` ops use plain `getKeyset` as the mint
   * will have signed.
   * @param id Optional keyset id to resolve. If omitted, the wallet's bound keyset is used.
   * @returns The resolved `Keyset`.
   * @throws If the keyset fails `getKeyset` validation, has a legacy (non-hex) id, or is inactive.
   */
  private getOutputKeyset(id?: string): Keyset {
    const keyset = this.getKeyset(id);
    this.failIf(!keyset.hasHexId, 'Legacy keyset cannot be used to create new proofs', {
      keyset: keyset.id,
    });
    this.failIf(!keyset.isActive, 'Inactive keyset cannot be used to create new proofs', {
      keyset: keyset.id,
    });
    return keyset;
  }

  /**
   * Whether a mint request's outputs sit on a v3 keyset, which selects the quote signing rule.
   *
   * @remarks
   * Chosen from the outputs, not the wallet keyset: custom data may name another. NUT-04 requires
   * every output of a v3 mint request to share one keyset.
   */
  private mintsOntoV3(outputs: SerializedBlindedMessage[]): boolean {
    const v3 = outputs.some((o) => isBlsKeyset(o.id));
    this.failIf(
      v3 && new Set(outputs.map((o) => o.id)).size > 1,
      'Outputs on a v3 keyset must all share that keyset (NUT-04)',
    );
    return v3;
  }

  /**
   * Make the snapshot usable for these keyset ids, without running an operation.
   *
   * @remarks
   * Repairs unknown ids with one `loadMint(true)` and loads any missing keys. An explicit call is
   * the consumer's own request, so it ignores `strictCachedKeysets` and the internal repair rate
   * limit. It emits no `keychainUpdated`: persist `keyChain.cache` yourself afterwards, as with
   * `loadMint`, and after a throw too, since keys for the other ids may still have landed. Aimed at
   * integrations that verify proofs without running wallet ops.
   * @param ids Keyset ids to make operable. Undefined entries are ignored.
   * @throws {@link UnknownKeysetError} For an id the mint does not know, or if the refresh fails.
   * @throws {@link CTSError} If the wallet has never loaded mint info, or if several key fetches
   *   fail, with the individual failures as `cause`. A lone failure is rethrown as-is.
   */
  public async ensureOperableKeysets(ids: Array<string | undefined>): Promise<void> {
    this.failIf(!Array.isArray(ids), 'ensureOperableKeysets: ids must be an array');
    this.failIf(
      !this._mintInfo,
      'Mint info not initialized; call loadMint or loadMintFromCache first',
    );
    return this._ensureOperableKeysets(ids, { implicit: false });
  }

  /**
   * Start, or join, the shared snapshot repair refresh.
   *
   * @remarks
   * Returns null when an implicit repair falls inside the cooldown window, which the caller must
   * treat as terminal. A repair already in flight is always joined, cooldown or not, so concurrent
   * ops still share one refresh. The window covers implicit repairs only: an explicit one neither
   * waits for it nor starts it, so a consumer's call never suppresses the wallet's own repair.
   */
  private startRepair(implicit: boolean): Promise<void> | null {
    if (this._pendingRepair) {
      return this._pendingRepair;
    }
    if (implicit) {
      if (Date.now() - this._lastRepairAt < REPAIR_COOLDOWN_MS) {
        return null;
      }
      this._lastRepairAt = Date.now();
    }
    this._pendingRepair = this.loadMint(true).finally(() => {
      this._pendingRepair = null;
    });
    return this._pendingRepair;
  }

  /**
   * Make the keychain usable for these keyset ids, at op entry or where the ids first become known.
   *
   * @remarks
   * Unknown ids repair once via `loadMint(true)`, throwing {@link UnknownKeysetError} with
   * `refreshed: true` if still unknown; known-but-keyless ids get keys fetched unless
   * `opts.fetchKeys` is false, which spend-side ops pass because their inputs need only the
   * keyset's fee metadata, never its keys. Calls left without an answer (strict mode, rate limited,
   * failed refresh) throw it with `refreshed: false`. Implicit (op-driven) calls honor
   * `strictCachedKeysets`, where unknown ids throw immediately and keyless ids are left for the
   * caller, and the repair cooldown, and emit `keychainUpdated` for anything they change. Explicit
   * calls do the full pass and emit nothing: the consumer who asked persists the cache.
   */
  private async _ensureOperableKeysets(
    ids: Array<string | undefined>,
    opts: { implicit: boolean; fetchKeys?: boolean },
  ): Promise<void> {
    // Never-loaded wallet: an empty keychain is not rotation evidence. Let the op's own
    // assertions report initialization instead of a hidden loadMint(true) here.
    if (!this._mintInfo) {
      return;
    }

    const wanted = [...new Set(ids.filter((id): id is string => !!id))];

    if (opts.implicit && this._strictCachedKeysets) {
      const strictUnknown = wanted.filter((id) => !this._keyChain.hasKeyset(id));
      if (strictUnknown.length > 0) {
        throw new UnknownKeysetError(strictUnknown[0]); // not refreshed: strict never asks the mint
      }
      return; // no backfill: downstream key checks report keyless keysets
    }

    const unknown = wanted.filter((id) => !this._keyChain.hasKeyset(id));
    let changed = false;

    if (unknown.length > 0) {
      const repair = this.startRepair(opts.implicit);
      if (!repair) {
        // Rate limited: terminal for this op, and not refreshed, so the id may well be genuine.
        throw new UnknownKeysetError(unknown[0]);
      }
      try {
        await repair;
      } catch (e) {
        throw new UnknownKeysetError(unknown[0], { cause: e });
      }
      changed = true;
      const still = unknown.filter((id) => !this._keyChain.hasKeyset(id));
      if (still.length > 0) {
        // The refresh itself succeeded and is worth persisting before we fail the op.
        if (opts.implicit) {
          this.on._emitKeychainUpdated();
        }
        throw new UnknownKeysetError(still[0], { refreshed: true });
      }
    }

    const keyless =
      opts.fetchKeys === false
        ? []
        : wanted.filter(
            (id) => this._keyChain.isUnitKeyset(id) && !this._keyChain.getKeyset(id).hasKeys,
          );
    if (keyless.length > 0) {
      // allSettled, not all: a sibling failure must not hide the keys that did land, or the
      // consumer never learns to persist them and refetches on every op.
      const fetches = await Promise.allSettled(
        keyless.map((id) => this._keyChain.ensureKeysetKeys(id)),
      );
      const failed = fetches.filter((f): f is PromiseRejectedResult => f.status === 'rejected');
      if (failed.length < fetches.length) {
        changed = true;
      }
      if (failed.length > 0) {
        if (changed && opts.implicit) {
          // Whatever landed (a repair above, or a sibling fetch) is worth persisting first.
          this.on._emitKeychainUpdated();
        }
        if (failed.length === 1) {
          throw failed[0].reason;
        }
        throw new CTSError(`Could not load keys for ${failed.length} keysets`, {
          cause: failed.map((f): unknown => f.reason),
        });
      }
    }

    // Explicit callers get no event: they asked for the change, so they persist the cache.
    if (changed && opts.implicit) {
      this.on._emitKeychainUpdated();
    }
  }

  /**
   * Refresh the snapshot after the mint rejected a keyset the wallet considered current.
   *
   * @returns True when the refresh ran, so the caller's operation is worth running again.
   */
  private async repairStaleSnapshot(): Promise<boolean> {
    if (this._strictCachedKeysets) {
      return false; // the snapshot is the consumer's to manage
    }
    const repair = this.startRepair(true);
    if (!repair) {
      return false; // rate limited
    }
    try {
      await repair;
    } catch (e) {
      this._logger.warn('Snapshot refresh after a mint keyset rejection failed', {
        err: (e as Error).message,
      });
      return false;
    }
    this.on._emitKeychainUpdated();
    return true;
  }

  /**
   * Run a mint request, treating a keyset rejection as evidence the snapshot is stale.
   *
   * @remarks
   * Repairs the snapshot once and rethrows as {@link StaleKeysetError}. Nothing retries: the outputs
   * were built on the rejected keyset, so the caller runs the operation again.
   */
  private async withStaleKeysetRepair<T>(request: () => Promise<T>): Promise<T> {
    try {
      return await request();
    } catch (e) {
      // NUT-00 reserves 12xxx for keyset errors (12001 unknown, 12002 inactive, 12003 expired).
      // Mints that answer without a structured code are unaffected, as are look-alike errors from
      // a custom request layer whose `code` is not a finite number (`Number(undefined)` is NaN):
      // every range comparison against those is false, so check before comparing.
      if (
        !isMintOperationError(e) ||
        !Number.isFinite(e.code) ||
        e.code < 12000 ||
        e.code >= 13000
      ) {
        throw e;
      }
      throw new StaleKeysetError(await this.repairStaleSnapshot(), { cause: e });
    }
  }

  /**
   * Asserts the mint has at least one usable (active, hex-id, keyed) keyset for the wallet's unit
   * before requesting a mint quote — a paid quote could otherwise never be redeemed for proofs.
   *
   * @param op Operation name for the error message.
   * @throws If the keychain is uninitialized or has no usable active keyset for the unit.
   */
  private requireMintableKeyset(op: string): void {
    try {
      this._keyChain.getCheapestKeyset();
    } catch (e) {
      this.fail(
        `${op}: no active keyset for unit '${this._unit}' — a paid mint quote could not be redeemed`,
        { reason: (e as Error).message },
      );
    }
  }

  public get logger(): Logger {
    return this._logger;
  }

  // -----------------------------------------------------------------
  // Section: Counters
  // -----------------------------------------------------------------

  private async reserveFor(keysetId: string, totalOutputs: number): Promise<CounterRange> {
    if (totalOutputs <= 0) return { start: 0, count: 0 };
    return this._counterSource.reserve(keysetId, totalOutputs);
  }

  private countersNeeded(ot: OutputType): number {
    if (ot.type !== 'deterministic' || ot.counter !== 0) return 0;
    return (ot.denominations ?? []).length;
  }

  private async addCountersToOutputTypes(
    keysetId: string,
    ...outputTypes: OutputType[]
  ): Promise<{ outputTypes: OutputType[]; used?: OperationCounters }> {
    // Get all outputTypes with a manual counter and denominations set.
    const manual = outputTypes.filter(
      (ot): ot is Extract<OutputType, { type: 'deterministic' }> =>
        ot.type === 'deterministic' && ot.counter > 0 && (ot.denominations?.length ?? 0) > 0,
    );

    // Reject if manual ranges overlap
    if (manual.length > 1) {
      const ranges = manual
        .map((ot) => ({
          start: ot.counter,
          end: ot.counter + ot.denominations!.length, // exclusive
        }))
        .sort((a, b) => a.start - b.start);
      for (let i = 1; i < ranges.length; i++) {
        this.failIf(ranges[i].start < ranges[i - 1].end, 'Manual counter ranges overlap', {
          keysetId,
          prev: ranges[i - 1],
          cur: ranges[i],
        });
      }
    }

    // Claim the manual range up front. Bumping the cursor afterwards would leave a window
    // for a concurrent auto reservation to hand out counters inside the range, and the bump
    // would then silently do nothing because the cursor had already moved past it.
    if (manual.length > 0) {
      const minManualStart = Math.min(...manual.map((ot) => ot.counter));
      const maxManualEnd = Math.max(...manual.map((ot) => ot.counter + ot.denominations!.length));

      await this._counterSource.reserveAt(keysetId, minManualStart, maxManualEnd - minManualStart);
      this._logger.debug('Counter source claimed manual deterministic range', {
        keysetId,
        minManualStart,
        maxManualEnd,
      });
    }

    // Reserve counters for deterministic outputTypes with auto counter (counter===0))
    const total = outputTypes.reduce((n, ot) => n + this.countersNeeded(ot), 0);
    if (total === 0) return { outputTypes };

    const range = await this.reserveFor(keysetId, total);
    let cursor = range.start;

    const patched = outputTypes.map((ot): OutputType => {
      if (ot.type === 'deterministic' && ot.counter === 0) {
        const need = ot.denominations?.length ?? 0;
        if (need > 0) {
          const patched: typeof ot = { ...ot, counter: cursor };
          cursor += need;
          return patched;
        }
      }
      return ot;
    });

    // Fire event after successful reservation (wallet does not await handlers)
    const used: OperationCounters = {
      counterKey: keysetId,
      start: range.start,
      count: range.count,
      next: range.start + range.count,
    };
    this.on._emitCountersReserved(used);
    return { outputTypes: patched, used };
  }

  /**
   * Bind this wallet to a specific keyset id.
   *
   * @remarks
   * This changes the default keyset used by all operations that do not explicitly pass a keysetId.
   * The method validates that the keyset exists in the keychain, matches the wallet unit, and has
   * keys loaded.
   *
   * Typical uses:
   *
   * 1. After loadMint, to pin the wallet to a particular active keyset.
   * 2. After a refresh, to rebind deliberately rather than falling back to cheapest.
   *
   * @param id The keyset identifier to bind to.
   * @throws If keyset not found, if it has no keys loaded, or if its unit is not the wallet unit.
   */
  public bindKeyset(id: string): void {
    const ks = this._keyChain.getKeyset(id);
    this.failIf(ks.unit !== this._unit, 'Keyset unit does not match wallet unit', {
      keyset: ks.id,
      unit: ks.unit,
      walletUnit: this._unit,
    });
    this.failIf(!ks.hasKeys, 'Keyset has no keys loaded', { keyset: ks.id });
    this._boundKeysetId = ks.id;
    this._explicitBind = true;
    this._logger.debug('Wallet bound to keyset', {
      keysetId: ks.id,
      unit: ks.unit,
      feePPK: ks.fee,
    });
  }

  /**
   * Creates a new Wallet bound to a different keyset, sharing the same CounterSource.
   *
   * Use this to operate on multiple keysets concurrently without mutating your original wallet.
   * Counters remain monotonic across instances because the same CounterSource is reused.
   *
   * Do NOT pass a fresh CounterSource for the same seed unless you know exactly why. Reusing
   * counters can recreate secrets that a mint will reject.
   *
   * @param id The keyset identifier to bind to.
   * @throws If keyset not found, if it has no keys loaded, or if its unit is not the wallet unit.
   */
  public withKeyset(id: string, opts?: { counterSource?: CounterSource }): Wallet {
    const newWallet = new Wallet(this.mint, {
      keysetId: id,
      bip39seed: this._seed,
      secretsPolicy: this._secretsPolicy,
      outputDataCreator: this._outputDataCreator,
      requireSigDleq: this._requireSigDleq,
      logger: this._logger,
      counterSource: opts?.counterSource ?? this._counterSource,
      strictCachedKeysets: this._strictCachedKeysets,
    });
    // Load mint info from our caches
    newWallet.loadMintFromCache(this.getMintInfo().cache, this._keyChain.cache);
    return newWallet;
  }

  /**
   * Returns the default OutputType for this wallet, based on its configured secrets policy
   * (options?.secretsPolicy) and seed state.
   *
   * - If the secrets policy is 'random', returns { type: 'random' }.
   * - If the policy is 'deterministic', requires a seed and returns { type: 'deterministic', counter:
   *   0 }. Counter 0 is a flag meaning "auto-increment from current state".
   * - If no explicit policy is set, falls back to:
   *
   *   - Deterministic if a seed is present.
   *   - Random if no seed is present.
   *
   * @returns An OutputType object describing the default output strategy.
   * @throws Error if the policy is 'deterministic' but no seed has been set.
   */
  public defaultOutputType(): OutputType {
    if (this._secretsPolicy === 'random') return { type: 'random' };
    if (this._secretsPolicy === 'deterministic') {
      this.failIfNullish(this._seed, 'Deterministic policy requires a seed');
      return { type: 'deterministic', counter: 0 }; // 0 = auto flag
    }
    return this._seed ? { type: 'deterministic', counter: 0 } : { type: 'random' };
  }

  // -----------------------------------------------------------------
  // Section: Output Creation
  // -----------------------------------------------------------------

  /**
   * Configures output denominations with fee adjustments and optimization.
   *
   * @remarks
   * If 'custom' outputType, data outputs MUST sum to the amount. Other outputTypes may supply
   * denominations. If no denominations are passed in, they will be calculated based on proofsWeHave
   * or the default split. If partial denominations are passed in, the balance will be added using
   * default split. Additional denominations to cover fees will then be added if required.
   * @param amount The total amount for outputs.
   * @param keyset The mint keyset.
   * @param outputType The output configuration.
   * @param includeFees Whether to include swap fees in the output amount.
   * @param proofsWeHave Optional proofs for optimizing denomination splitting.
   * @returns OutputType with required denominations.
   */
  private configureOutputs(
    amount: AmountLike,
    keyset: Keyset,
    outputType: OutputType,
    includeFees: boolean = false,
    proofsWeHave: Array<Pick<ProofLike, 'amount'>> = [],
  ): OutputType {
    let newAmount = this.parseAmount(amount, 'configureOutputs', true);
    const normalizedProofsWeHave = proofsWeHave.map((p) => ({ amount: Amount.from(p.amount) }));

    // Custom outputs don't have automatic optimizations or fee inclusion)
    if (outputType.type === 'custom') {
      this.failIf(includeFees, 'The custom OutputType does not support automatic fee inclusion');

      // Validate sum early, as no denominations to fill
      const customTotal = this.parseAmount(
        OutputData.sumOutputAmounts(outputType.data),
        'configureOutputs.customTotal',
        true,
      );
      this.failIf(
        !customTotal.equals(newAmount),
        `Custom output data total (${customTotal.toString()}) does not match amount (${newAmount.toString()})`,
      );
      // Custom data names its own keyset per output; check each is usable before anything is spent.
      for (const d of outputType.data) {
        this.getOutputKeyset(d.blindedMessage.id);
      }
      return outputType;
    }

    // Start with any denominations provided.
    // Note: These MAY be partial ("give me a [16,8], anything for the rest")
    // We will complete the denomination set before we are done.
    let denominations = outputType.denominations ?? [];

    // If no denominations, but proofsWeHave was provided - optimize
    // to get around _denominationTarget proofs of each denomination.
    if (denominations.length === 0 && normalizedProofsWeHave.length > 0) {
      denominations = getKeepAmounts(
        normalizedProofsWeHave,
        newAmount,
        keyset.keys,
        this._denominationTarget,
      );
    }

    // Fill in any missing denominations with default split.
    // NOTE: If we have to fill, the result will be in ASC order.
    // Original order is only maintained for exact denomination sets.
    denominations = splitAmount(newAmount, keyset.keys, denominations);

    // If includeFees, we create additional output amounts to cover the
    // fee the receiver will pay when they spend the proofs (ie sender pays fees)
    if (includeFees) {
      const receiveFeeAmounts = this.receiveFeeAmounts(denominations.length, keyset);
      newAmount = newAmount.add(Amount.sum(receiveFeeAmounts));
      denominations = [...denominations, ...receiveFeeAmounts];
    }
    return { ...outputType, denominations };
  }

  /**
   * Extra denominations that cover the input fee for spending `nOutputs` outputs plus themselves.
   *
   * Iterates until the fee is stable, since fee outputs also incur fees.
   */
  private receiveFeeAmounts(nOutputs: number, keyset: Keyset): Amount[] {
    // Bound the +1 convergence; any realistic keyset converges in a few dozen steps.
    const maxIters = 4_096;
    let receiveFee = this.getFeesForKeyset(nOutputs, keyset.id);
    let receiveFeeAmounts = splitAmount(receiveFee, keyset.keys);
    let iters = 0;
    while (
      this.getFeesForKeyset(nOutputs + receiveFeeAmounts.length, keyset.id).greaterThan(receiveFee)
    ) {
      if (iters++ > maxIters) {
        throw new CTSError(
          `Fee calculation for keyset ${keyset.id} did not converge (input_fee_ppk too high for its denominations)`,
        );
      }
      receiveFee = receiveFee.add(1);
      receiveFeeAmounts = splitAmount(receiveFee, keyset.keys);
    }
    return receiveFeeAmounts;
  }

  /**
   * Sum total implied by a prepared OutputType.
   *
   * Note: Empty denomination is valid (e.g: zero change).
   */
  private preparedTotal(ot: OutputType): Amount {
    if (ot.type === 'custom') return OutputData.sumOutputAmounts(ot.data);
    const denoms = ot.denominations ?? [];
    return Amount.sum(denoms);
  }

  /**
   * Generates blinded messages based on the specified output type.
   *
   * @param amount The total amount for outputs.
   * @param keyset The mint keys.
   * @param outputType The output configuration.
   * @returns Prepared output data.
   */
  private createOutputData(
    amount: AmountLike,
    keyset: Keyset,
    outputType: OutputType,
  ): OutputDataLike[] {
    const outputAmount = this.parseAmount(amount, 'createOutputData', true); // allow zero
    if (
      // 'custom' OutputType has no denominations. Every other OutputType does.
      // so let's sanity check those were filled properly (eg: configureOutputs)
      'custom' != outputType.type &&
      outputType.denominations &&
      outputType.denominations.length > 0
    ) {
      const splitSum = Amount.sum(outputType.denominations);
      this.failIf(
        !splitSum.equals(outputAmount),
        'Denominations do not sum to the expected amount',
        {
          splitSum: splitSum.toString(),
          expected: outputAmount.toString(),
        },
      );
    }
    let outputData: OutputDataLike[];
    switch (outputType.type) {
      case 'random':
        outputData = this._outputDataCreator.createRandomData(
          outputAmount,
          keyset,
          outputType.denominations,
        );
        break;
      case 'deterministic':
        this.failIfNullish(
          this._seed,
          'Deterministic outputs require a seed configured in the wallet',
        );
        outputData = this._outputDataCreator.createDeterministicData(
          outputAmount,
          this._seed,
          outputType.counter,
          keyset,
          outputType.denominations,
        );
        break;
      case 'lock':
        // The one place the keyset version is known: semantic lock options encode here, so
        // consumers never pick an encoding. Inexpressible shapes refuse naming the reason.
        outputData = isBlsKeyset(keyset.id)
          ? OutputData.createNutrootData(
              lockToNutrootOptions(outputType.options),
              outputAmount,
              keyset,
              outputType.denominations,
            )
          : this._outputDataCreator.createP2PKData(
              lockToP2PKOptions(outputType.options),
              outputAmount,
              keyset,
              outputType.denominations,
            );
        break;
      case 'factory': {
        const factorySplit = splitAmount(outputAmount, keyset.keys, outputType.denominations);
        outputData = factorySplit.map((a) => outputType.factory(a, keyset));
        break;
      }
      case 'custom': {
        outputData = outputType.data;
        const customTotal = this.parseAmount(
          OutputData.sumOutputAmounts(outputData),
          'createOutputData.customTotal',
          true,
        );
        this.failIf(
          !customTotal.equals(outputAmount),
          `Custom output data total (${customTotal.toString()}) does not match amount (${outputAmount.toString()})`,
        );

        break;
      }
      default: {
        this.fail('Invalid OutputType');
      }
    }
    // A key backs at most one secret, ever (NUT-10). Two outputs of the same amount sharing a
    // secret unblind to the same C, so the second is the first again and its value is gone
    // silently. Catches a factory handing every output one secret, or a reused ephemeral.
    // The mint cannot catch this for us: outputs are blinded, and the same secret under different
    // blinding factors gives different `B_`, so both get signed. It surfaces only when the first
    // spend burns the shared `Y`, mint-wide and permanently (NUT-10).
    this.assertUniqueOutputSecrets(outputData);
    // A random v3 output's key rides to the proof as spend info; mirror it for a custom
    // factory that set only secretKey, so the proof still carries its own key.
    for (const output of outputData) {
      const data = output as { secretKey?: Uint8Array; spendInfo?: SpendInfo };
      if (data.secretKey && !data.spendInfo) {
        data.spendInfo = { k: bytesToHex(data.secretKey) };
      }
    }
    return outputData;
  }

  /**
   * Creates a swap transaction with sorted outputs for privacy. This prevents a mint working out
   * which proofs will be sent or kept.
   *
   * @param inputs Prepared input proofs.
   * @param keepOutputs Outputs to keep (change or receiver's proofs).
   * @param sendOutputs Outputs to send (optional, default empty for receive/mint).
   * @returns Swap transaction with payload and metadata for processing signatures.
   */
  private assertUniqueOutputSecrets(outputData: OutputDataLike[]): void {
    const seenSecrets = new Set<string>();
    for (const [i, d] of outputData.entries()) {
      // Hex is a one-to-one key for the bytes; decoding is not, it merges invalid sequences.
      const secret = bytesToHex(d.secret);
      // Report the position, never the secret: it is the spending material.
      this.failIf(seenSecrets.has(secret), `Duplicate output secret at index ${i}`, { index: i });
      seenSecrets.add(secret);
    }
  }

  private createSwapTransaction(
    inputs: Proof[],
    keepOutputs: OutputDataLike[],
    sendOutputs: OutputDataLike[] = [],
  ): {
    payload: SwapRequest;
    outputData: OutputDataLike[];
    keepVector: boolean[];
    sortedIndices: number[];
  } {
    // Keep and send are generated separately; the duplicate-secret guard has to see them together.
    this.assertUniqueOutputSecrets([...keepOutputs, ...sendOutputs]);
    // Prepare inputs for mint
    inputs = this._prepareInputsForMint(inputs);

    // Sort ASC by amount for privacy, SIG_ALL included: its message is built from this same
    // ordering, so there is nothing left to fix in place.
    const {
      outputData: sortedOutputData,
      keepVector: sortedKeepVector,
      indices,
    } = orderOutputsForPayload(keepOutputs, sendOutputs);
    const outputs = sortedOutputData.map((d) => d.blindedMessage);
    // this._logger.debug('createSwapTransaction:', {
    //   indices,
    //   sortedKeepVector,
    //   outputs,
    // });
    const payload: SwapRequest = {
      inputs,
      outputs,
    };
    return {
      payload,
      outputData: sortedOutputData,
      keepVector: sortedKeepVector,
      sortedIndices: indices,
    };
  }

  // -----------------------------------------------------------------
  // Section: Send and Receive
  // -----------------------------------------------------------------

  /**
   * Receive a token (swaps with mint for new proofs)
   *
   * @remarks
   * The swap is the sweep (NUT-10): received proofs become the wallet's own seed-derived secrets,
   * which matters whatever the spend info says. A bearer `k` leaves the sender holding the same
   * scalar, and a bearer scalar can conceal a tweaked tree. A receiver-keyed `E` is wallet data and
   * not seed-derivable, so the proof is unrecoverable from the seed alone until swept. A disclosed
   * tree with neither leaves the key-path holder able to spend at any time, unless `K` is a NUMS
   * offset. Spending a locked proof needs its key: pass `config.privkey` for a receiver-keyed
   * proof, or `config.scriptPath` to take a leaf.
   * @example
   *
   * ```typescript
   * const result = await wallet.receive(
   *   token,
   *   { requireDleq: true },
   *   { type: 'deterministic', counter: 0 },
   * );
   * ```
   *
   * @param token Token string, decoded token, or raw proof array.
   * @param config Optional receive config.
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns Newly minted proofs.
   */
  async receive(
    token: Token | string | ProofLike[],
    config?: ReceiveConfig,
    outputType?: OutputType,
  ): Promise<Proof[]> {
    // Prepare and complete the send
    const txn = await this.prepareSwapToReceive(token, config, outputType);
    const { keep } = await this.completeSwap(
      txn,
      config?.privkey,
      config?.scriptPath?.length ? { scriptPath: config.scriptPath } : undefined,
    );
    return keep;
  }

  /**
   * Prepare A Receive Transaction.
   *
   * @remarks
   * Allows you to preview fees for a receive, get concrete outputs for P2PK SIG_ALL transactions,
   * and do any pre-swap tasks (such as marking proofs in-flight etc). Persist this preview
   * (`serializeSwapPreview`) to support NUT-19 replay safety.
   * @example
   *
   * ```typescript
   * // Prepare transaction
   * const txn = await wallet.prepareSwapToReceive(token, { requireDleq: true });
   * const fees = txn.fees;
   *
   * // Complete transaction
   * const { keep } = await wallet.completeSwap(txn);
   * ```
   *
   * @param token Token string, decoded token, or raw proof array.
   * @param config Optional receive config.
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns SwapPreview with metadata for swap transaction.
   */
  async prepareSwapToReceive(
    token: Token | string | ProofLike[],
    config?: ReceiveConfig,
    outputType?: OutputType,
  ): Promise<SwapPreview> {
    const { keysetId, requireDleq, proofsWeHave, onCountersReserved, preimage } = config || {};
    outputType = outputType ?? this.defaultOutputType(); // Fallback to policy

    // Extract proofs — either directly or by decoding the token
    let proofs: Proof[];
    if (Array.isArray(token)) {
      proofs = normalizeProofAmounts(token);
    } else {
      const decodedToken: Token = typeof token === 'string' ? this.decodeToken(token) : token;
      const tokenMintUrl = normalizeMintUrl(decodedToken.mint);
      this.failIf(tokenMintUrl !== this.mint.mintUrl, 'Token belongs to a different mint', {
        token: tokenMintUrl,
        wallet: this.mint.mintUrl,
      });
      this.failIf(decodedToken.unit !== this._unit, 'Token is not in wallet unit', {
        token: decodedToken.unit,
        wallet: this._unit,
      });
      // Token object may come from JSON.parse/localStorage and need runtime rehydration.
      proofs = normalizeProofAmounts(decodedToken.proofs);
    }

    // A v3 witness signs one transaction. An incoming proof cannot already carry a witness for
    // the outputs created below, so discard the sender's transcript. A script-path package for
    // this swap is merged into the completed preview later and is therefore preserved.
    proofs = proofs.map((proof) => {
      if (!isBlsKeyset(proof.id) || !isV3PointSecret(proof.secret) || proof.witness === undefined) {
        return proof;
      }
      const withoutWitness = { ...proof };
      delete withoutWitness.witness;
      return withoutWitness;
    });

    // Rotation evidence check: repair the snapshot and load any missing keys before
    // any assertion or fee math relies on it.
    await this._ensureOperableKeysets(
      proofs.map((p) => p.id),
      { implicit: true },
    );

    // Validate all proof keyset IDs use this wallet's unit
    this.assertProofsInWalletUnit(proofs);

    // Check total amount
    const totalAmount = this.parseAmount(sumProofs(proofs), 'prepareSwapToReceive', true);
    this.failIf(totalAmount.isZero(), 'Token contains no proofs', { proofs });

    // NUT-12: wallets MUST verify any DLEQ on a received proof (the spec default).
    // `requireDleq: true` opts into the stricter "DLEQ must also be present" policy.
    // For v3 (BLS) proofs the single multi-pairing replaces per-proof DLEQ verification.
    verifyProofsForReceive(proofs, (id) => this._keyChain.getKeyset(id), { requireDleq });

    // Shape receive output type and denominations
    const keyset = this.getOutputKeyset(keysetId); // specified or wallet keyset
    const swapFee = this.getFeesForProofs(proofs);
    const receiveAmount = totalAmount.subtract(swapFee);
    let receiveOT = this.configureOutputs(
      receiveAmount,
      keyset,
      outputType,
      false, // includeFees is not applicable for receive
      proofsWeHave,
    );

    // Assign counter atomically if OutputType is deterministic
    // and the counter is zero (auto-assign)
    const autoCounters = await this.addCountersToOutputTypes(keyset.id, receiveOT);
    [receiveOT] = autoCounters.outputTypes;
    if (autoCounters.used) {
      this.safeCallback(onCountersReserved, autoCounters.used, { op: 'receive' });
    }
    this._logger.debug('receive counter', {
      counter: autoCounters.used,
      receiveOT: stringifyOutputTypeForLog(receiveOT),
    });

    // Create outputs and execute swap
    const outputs = this.createOutputData(this.preparedTotal(receiveOT), keyset, receiveOT);

    // Return SwapPreview
    return {
      amount: receiveAmount,
      fees: swapFee,
      inputs: preimage === undefined ? proofs : attachHTLCPreimage(proofs, preimage),
      keepOutputs: outputs,
    };
  }

  /**
   * Sends proofs of a given amount from provided proofs.
   *
   * @remarks
   * If proofs are P2PK-locked to your public key, call signP2PKProofs first to sign them. The
   * default config uses exact match selection, and does not includeFees or requireDleq. Because the
   * send is offline, the user will unlock the signed proofs when they receive them online.
   * @param amount Amount to send.
   * @param proofs Array of proofs (must sum >= amount; pre-sign if P2PK-locked).
   * @param config Optional parameters for the send.
   * @returns SendResponse with keep/send proofs.
   * @throws If funds are insufficient, or no offline selection matches the amount.
   */
  sendOffline(amount: AmountLike, proofs: ProofLike[], config?: SendOfflineConfig): SendResponse {
    const sendAmount = this.parseAmount(amount, 'sendOffline');
    let normalizedProofs = normalizeProofAmounts(proofs);
    const { requireDleq = false, includeFees = false, exactMatch = true } = config || {};
    if (requireDleq) {
      // v3 (BLS, `02…`) proofs satisfy the "cryptographically-verified mint signature"
      // semantic of `requireDleq` via pairing equality rather than a DLEQ proof. Accept
      // them alongside v0/v1/v2 proofs that carry a DLEQ. Mirrors the receive-side
      // `hasValidDleq` dispatch (`utils/core.ts`).
      normalizedProofs = normalizedProofs.filter((p) => isBlsKeyset(p.id) || p.dleq != undefined);
    }
    this.failIf(
      sumProofs(normalizedProofs).lessThan(sendAmount),
      'Not enough funds available to send',
    );

    const { keep, send } = this.selectProofsToSend(
      normalizedProofs,
      sendAmount,
      includeFees,
      exactMatch,
    );
    // No selection covers the amount: fail rather than return an empty send. send() catches this
    // and falls back to a swap; direct callers get a clear failure instead of a silent no-op.
    this.failIf(
      !sendAmount.isZero() && send.length === 0,
      'Send cannot be completed offline for the requested amount',
    );
    // Keep NUT-11 witnesses, but never transfer a NUT-10 transaction witness: it signs only the
    // sender's old transcript and would prevent the receiver from attaching a current one.
    const sendPrepared = this._prepareInputsForMint(send, requireDleq, true, true).map((proof) => {
      if (!isBlsKeyset(proof.id) || !isV3PointSecret(proof.secret)) return proof;
      const withoutWitness = { ...proof };
      delete withoutWitness.witness;
      return withoutWitness;
    });
    return { keep, send: sendPrepared };
  }

  /**
   * Send proofs with online swap if necessary.
   *
   * @example
   *
   * ```typescript
   * // Simple send
   * const result = await wallet.send(5, proofs);
   *
   * // With a SendConfig
   * const result = await wallet.send(5, proofs, { includeFees: true });
   *
   * // With Custom output configuration
   * const customConfig: OutputConfig = {
   *   send: { type: 'p2pk', options: { kind: 'P2PK', data: '...' } },
   *   keep: { type: 'deterministic', counter: 0 },
   * };
   * const customResult = await wallet.send(5, proofs, { includeFees: true }, customConfig);
   * ```
   *
   * @param amount Amount to send (receiver gets this net amount).
   * @param proofs Array of proofs to split.
   * @param config Optional parameters for the swap.
   * @returns SendResponse with keep/send proofs.
   * @throws Throws if the send cannot be completed offline or if funds are insufficient.
   */
  async send(
    amount: AmountLike,
    proofs: ProofLike[],
    config?: SendConfig,
    outputConfig?: OutputConfig,
  ): Promise<SendResponse> {
    const sendAmount = this.parseAmount(amount, 'send');
    const { keysetId, includeFees = false } = config || {};
    // Fallback to policy defaults if no outputConfig
    outputConfig = outputConfig ?? {
      send: this.defaultOutputType(),
      keep: this.defaultOutputType(),
    };

    // First, let's see if we can avoid a swap (and fees)
    // by trying an exact match offline selection, including fees if
    // we are giving the receiver the amount + their fee to receive
    try {
      // Offline exact-match only allowed for plain-random defaults; deterministic implies swap.
      const wantsDeterministicByPolicy = this.defaultOutputType().type === 'deterministic';
      const isPlainRandom = (ot?: OutputType) =>
        !ot || (ot.type === 'random' && (!ot.denominations || ot.denominations.length === 0));

      if (
        keysetId ||
        config?.scriptPath?.length ||
        config?.preimage !== undefined ||
        wantsDeterministicByPolicy ||
        !isPlainRandom(outputConfig.send) ||
        (outputConfig.keep && !isPlainRandom(outputConfig.keep))
      ) {
        // Explain why we must fall back to swap
        const reasons: string[] = [];
        if (keysetId) reasons.push('keysetId override');
        if (config?.scriptPath?.length) reasons.push('script-path spend');
        if (config?.preimage !== undefined) reasons.push('HTLC preimage');
        if (wantsDeterministicByPolicy) reasons.push('wallet default is deterministic');
        if (!isPlainRandom(outputConfig.send)) reasons.push('non-default send output type');
        if (outputConfig.keep && !isPlainRandom(outputConfig.keep))
          reasons.push('non-default keep output type');

        throw new CTSError(`Options require a swap: ${reasons.join(', ')}`);
      }

      // Proceed with offline exact-match attempt
      const { keep, send } = this.sendOffline(sendAmount, proofs, {
        includeFees,
        exactMatch: true,
        requireDleq: false, // safety
      });
      // Only bearer material can be forwarded to a new holder without a v3 swap.
      const v3 = send.filter((p) => isBlsKeyset(p.id));
      const bearerKeys = collectSpendInfoKeys(v3, undefined, this._logger);
      for (const proof of v3) {
        this.failIf(!bearerKeys.has(proof.secret), 'A non-bearer v3 proof requires a swap');
        verifyNutrootSpendInfo(proof.secret, proof.spend_info!);
      }
      const expectedFee = includeFees ? this.getFeesForProofs(send) : Amount.zero();

      if (sumProofs(send).equals(sendAmount.add(expectedFee))) {
        this._logger.info('Successful exactMatch offline selection!');
        return { keep, send };
      }
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : 'Unknown error';
      this._logger.debug('ExactMatch offline selection failed.', { e: message });
    }

    // Prepare and complete the send
    const txn = await this.prepareSwapToSend(sendAmount, proofs, config, outputConfig);
    return await this.completeSwap(
      txn,
      config?.privkey,
      config?.scriptPath?.length ? { scriptPath: config.scriptPath } : undefined,
    );
  }

  /**
   * Prepare A Send Transaction.
   *
   * @remarks
   * Allows you to preview fees for a send, get concrete outputs for P2PK SIG_ALL transactions, and
   * do any pre-swap tasks (such as marking proofs in-flight etc). Persist this preview
   * (`serializeSwapPreview`) to support NUT-19 replay safety.
   * @example
   *
   * ```typescript
   * // Prepare transaction
   * const txn = await wallet.prepareSwapToSend(5, proofs, { includeFees: true });
   * const fees = txn.fees;
   *
   * // Complete transaction
   * const { keep, send } = await wallet.completeSwap(txn);
   * ```
   *
   * @param amount Amount to send (receiver gets this net amount).
   * @param proofs Array of proofs to split.
   * @param config Optional parameters for the swap.
   * @returns SwapPreview with metadata for swap transaction.
   * @throws Throws if the send cannot be completed offline or if funds are insufficient.
   */
  async prepareSwapToSend(
    amount: AmountLike,
    proofs: ProofLike[],
    config?: SendConfig,
    outputConfig?: OutputConfig,
  ): Promise<SwapPreview> {
    const sendAmountTarget = this.parseAmount(amount, 'prepareSwapToSend');
    const normalizedProofs = normalizeProofAmounts(proofs);
    const { keysetId, includeFees = false, onCountersReserved, preimage } = config || {};

    // Rotation evidence check: repair the snapshot before any assertion or fee math
    // relies on it. Inputs are priced from keyset metadata, so keys are not fetched.
    await this._ensureOperableKeysets(
      normalizedProofs.map((p) => p.id),
      { implicit: true, fetchKeys: false },
    );

    // Fallback to policy defaults if no outputConfig
    outputConfig = outputConfig ?? {
      send: this.defaultOutputType(),
      keep: this.defaultOutputType(),
    };

    // Fetch keys
    const keyset = this.getOutputKeyset(keysetId); // specified or wallet keyset

    // Shape SEND output type and denominations
    let sendOT = this.configureOutputs(
      sendAmountTarget,
      keyset,
      outputConfig.send ?? this.defaultOutputType(),
      includeFees,
    );
    const sendAmount = this.preparedTotal(sendOT);

    // Select the subset of proofs needed to cover the swap (sendTarget + swap fee)
    const { keep: unselectedProofs, send: selectedProofs } = this.selectProofsToSend(
      normalizedProofs,
      sendAmount,
      true, // Include fees to cover swap fee
    );
    // this._logger.debug('PROOFS SELECTED', {
    // 	unselectedProofs: unselectedProofs.map(p=>p.amount.toString()),
    // 	selectedProofs: selectedProofs.map(p=>p.amount.toString()),
    // });
    if (selectedProofs.length === 0) {
      throw new CTSError('Not enough funds available to send');
    }

    // Calculate our expected change from the swap (and sanity check!)
    const selectedSum = sumProofs(selectedProofs);
    const swapFee = this.getFeesForProofs(selectedProofs);
    const required = sendAmount.add(swapFee);
    if (selectedSum.lessThan(required)) {
      this.failIf(true, 'Not enough funds available for swap', {
        selectedSum: selectedSum.toString(),
        required: required.toString(),
      });
    }
    const changeAmount = selectedSum.subtract(required);

    // Shape KEEP (change) output type and denominations
    // No includeFees, as we are the receiver of the change
    let keepOT = this.configureOutputs(
      changeAmount,
      keyset,
      outputConfig.keep ?? this.defaultOutputType(),
      false,
      config?.proofsWeHave,
    );
    const keepAmount = this.preparedTotal(keepOT);

    // Assign counters atomically if either/both OutputTypes are deterministic
    // and the counter is zero (auto-assign)
    const autoCounters = await this.addCountersToOutputTypes(keyset.id, sendOT, keepOT);
    [sendOT, keepOT] = autoCounters.outputTypes;
    if (autoCounters.used) {
      this.safeCallback(onCountersReserved, autoCounters.used, { op: 'send' });
    }
    this._logger.debug('send counters', {
      counter: autoCounters.used,
      sendOT: stringifyOutputTypeForLog(sendOT),
      keepOT: stringifyOutputTypeForLog(keepOT),
    });

    // Create the output data
    const sendOutputs = this.createOutputData(sendAmount, keyset, sendOT);
    const keepOutputs = this.createOutputData(keepAmount, keyset, keepOT);

    // Return SwapPreview
    return {
      amount: sendAmountTarget,
      fees: swapFee,
      inputs:
        preimage === undefined ? selectedProofs : attachHTLCPreimage(selectedProofs, preimage),
      sendOutputs,
      keepOutputs,
      unselectedProofs,
    };
  }

  /**
   * Complete a prepared swap transaction.
   *
   * @example
   *
   * ```typescript
   * // Prepare transaction
   * const txn = await wallet.prepareSwapToSend(5, proofs, { includeFees: true });
   *
   * // Complete transaction
   * const result = await wallet.completeSwap(txn);
   * ```
   *
   * @param swapPreview With metadata for swap transaction.
   * @param privkey The private key(s) for signing.
   * @returns SendResponse with keep/send proofs.
   * @throws {@link StaleKeysetError} If the mint rejects the outputs' keyset.
   */
  async completeSwap(
    swapPreview: SwapPreview,
    privkey?: string | string[],
    options?: CompleteSwapOptions,
  ): Promise<SendResponse> {
    const scriptPath = options?.scriptPath;
    const keepOutputs: OutputDataLike[] = swapPreview?.keepOutputs ? swapPreview.keepOutputs : [];
    const sendOutputs: OutputDataLike[] = swapPreview.sendOutputs ? swapPreview.sendOutputs : [];
    const unselectedProofs: Proof[] = swapPreview.unselectedProofs
      ? swapPreview.unselectedProofs
      : [];

    // Sign proofs if needed. SIG_ALL covers the outputs, so it must see them in the order the
    // payload will carry, which is what orderOutputsForPayload decides for both.
    if (privkey) {
      swapPreview.inputs = this.signP2PKProofs(
        swapPreview.inputs,
        privkey,
        orderOutputsForPayload(keepOutputs, sendOutputs).outputData,
      );
    }

    // Create swap transaction
    const swapTransaction = this.createSwapTransaction(
      swapPreview.inputs,
      keepOutputs,
      sendOutputs,
    );

    // Execute swap and validate result
    const privkeys = privkey === undefined ? [] : [privkey].flat();
    const receipts = await attachTransactionWitnesses(
      swapTransaction.payload,
      undefined,
      collectSpendInfoKeys(swapPreview.inputs, privkey, this._logger),
      scriptPath?.length
        ? prepareScriptPathSpends(swapPreview.inputs, scriptPath, privkeys)
        : undefined,
      this._nutrootState(),
    );
    const { signatures } = await this.withStaleKeysetRepair(() =>
      this.mint.swap(swapTransaction.payload),
    );
    this.failIf(
      signatures.length !== swapTransaction.outputData.length,
      `Mint returned ${signatures.length} signatures, expected ${swapTransaction.outputData.length}. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
    );
    this.validateReturnedSignatures(signatures, swapTransaction.outputData);

    // Construct proofs. Each signature names the keyset it was made under, which custom outputs
    // may have chosen per output; unblinding must use that one.
    await this._ensureKeysetsForSignatures(signatures);
    const swapProofs = swapTransaction.outputData.map((d, i) =>
      d.toProof(signatures[i], this.keysetForSignature(signatures[i].id)),
    );
    const reorderedProofs = Array(swapProofs.length);
    const reorderedKeepVector = Array(swapTransaction.keepVector.length);
    swapTransaction.sortedIndices.forEach((s, i) => {
      reorderedKeepVector[s] = swapTransaction.keepVector[i];
      reorderedProofs[s] = swapProofs[i];
    });
    const keepProofs: Proof[] = [];
    const sendProofs: Proof[] = [];
    reorderedProofs.forEach((p: Proof, i) => {
      if (reorderedKeepVector[i]) {
        keepProofs.push(p);
      } else {
        sendProofs.push(p);
      }
    });
    this._logger.debug('SEND COMPLETED', {
      unselectedProofs: unselectedProofs.map((p) => p.amount.toString()),
      keepProofs: keepProofs.map((p) => p.amount.toString()),
      sendProofs: sendProofs.map((p) => p.amount.toString()),
    });
    return {
      keep: [...keepProofs, ...unselectedProofs],
      send: sendProofs,
      ...(receipts.length > 0 && { receipts }),
    };
  }

  // -----------------------------------------------------------------
  // Section: Transaction Helpers
  // -----------------------------------------------------------------

  /**
   * Selects proofs to send based on amount and fee inclusion.
   *
   * @remarks
   * Uses an adapted Randomized Greedy with Local Improvement (RGLI) algorithm, which has a time
   * complexity O(n log n) and space complexity O(n). The default selector prefers stale keysets
   * (base64, older versions, inactive) so balances rotate onto the current keyset; pass
   * `selectProofs: selectProofsRGLI` in the Wallet options for keyset-neutral selection.
   * @param proofs Array of proofs available to select from. Accepts {@link ProofLike} so proofs
   *   loaded from storage (with `amount: number`) work without manual conversion.
   * @param amountToSend The target amount to send.
   * @param includeFees Optional boolean to include fees; Default: false.
   * @param exactMatch Optional boolean to require exact match; Default: false.
   * @returns SendResponse containing proofs to keep and proofs to send.
   * @throws Throws an error if an exact match cannot be found within MAX_TIMEMS.
   * @see https://crypto.ethz.ch/publications/files/Przyda02.pdf
   */
  selectProofsToSend(
    proofs: ProofLike[],
    amountToSend: AmountLike,
    includeFees = false,
    exactMatch = false,
  ): SendResponse {
    const parsedAmountToSend = this.parseAmount(amountToSend, 'selectProofsToSend');
    const { keep, send } = this._selectProofs(
      proofs,
      parsedAmountToSend,
      this._keyChain,
      includeFees,
      exactMatch,
    );
    return { keep, send };
  }

  /**
   * Prepares proofs for sending by signing P2PK-locked proofs.
   *
   * @remarks
   * Call this method before operations like send if the proofs are P2PK-locked and need unlocking.
   * This is a public wrapper for signing.
   * @param proofs The proofs to sign.
   * @param privkey The private key(s) for signing.
   * @param outputData Optional. For signing of SIG_ALL transactions.
   * @param quoteId Optional. For signing SIG_ALL melt transactions.
   * @returns Signed proofs.
   */
  signP2PKProofs(
    proofs: ProofLike[],
    privkey: string | string[],
    outputData?: OutputDataLike[],
    quoteId?: string,
  ): Proof[] {
    const normalizedProofs = normalizeProofAmounts(proofs);
    // Normal case, sign everything as usual
    if (!isP2PKSigAll(normalizedProofs)) {
      return cryptoSignP2PKProofs(normalizedProofs, privkey, this._logger);
    }

    // Ensure SIG_ALL conditions are met
    this.failIfNullish(outputData, 'OutputData is required for SIG_ALL proof signing.');
    assertSigAllInputs(normalizedProofs);

    // SIG_ALL is in flux currently, so sign the first proof only against each
    // supported message format...
    const [first, ...rest] = normalizedProofs;
    let signedFirst = first;
    const digests = [
      computeMessageDigest(buildP2PKSigAllMessageV0(normalizedProofs, outputData, quoteId)),
    ];
    for (const digest of digests) {
      signedFirst = cryptoSignP2PKProofs([signedFirst], privkey, this._logger, digest)[0];
    }

    // Return the proofs in same order as before
    return [signedFirst, ...rest];
  }

  /**
   * Calculates the fees based on inputs (proofs)
   *
   * @param proofs Input proofs to calculate fees for.
   * @returns Fee amount.
   * @throws Throws an error if the proofs keyset is unknown.
   */
  getFeesForProofs(proofs: Array<Pick<Proof, 'id'>>): Amount {
    const sumPPK = Amount.sum(proofs.map((proof) => this.getProofFeePPK(proof))).toBigInt();
    return Amount.from((sumPPK + 999n) / 1000n);
  }

  /**
   * Payee-side NUT-18 settlement check: do these received proofs net the requested amount?
   *
   * @remarks
   * Verifies `sum(proofs) - inputFees >= amount + mf`, with input fees from this wallet's keysets
   * and `mf` priced from this mint's NUT-05 melt methods for the wallet unit. This mint must also
   * be admissible: inside a strict mint list, and able to melt via a method the request accepts. A
   * locked request also checks that each proof carries the lock that was asked for: exactly the
   * requested tree for a nutroot request, and exactly the requested condition for a nut10 one. A
   * receiver-keyed nutroot request needs `opts.privkeys`, because binding a proof to the receiver
   * key is an ECDH trial-match only that key can do (NUT-28); without it there is nothing to check
   * and the call throws rather than passing a payment the payee cannot spend. Proof integrity
   * (pairing/DLEQ) remains a separate check.
   * @param pr - The payment request being settled.
   * @param proofs - The received proofs (from this wallet's mint), with spend info when present.
   * @param expectedAmount - Expected amount for amountless requests; ignored when the request sets
   *   `a`.
   * @param opts.privkeys - The receiver key(s) the request locks to. Required for a receiver-keyed
   *   nutroot request, unused otherwise.
   * @throws If no amount is available to check against, this wallet's mint is not admissible for
   *   the request (unit, strict mint list, or no accepted melt method), a proof keyset is unknown,
   *   the request is invalid per NUT-18, a receiver-keyed nutroot request is checked without its
   *   key, or a proof does not carry the requested lock.
   */
  isPaymentRequestSatisfied(
    pr: PaymentRequest,
    proofs: Array<Pick<Proof, 'id' | 'amount' | 'secret' | 'spend_info'>>,
    expectedAmount?: AmountLike,
    opts?: { privkeys?: string | string[] },
  ): boolean {
    const expected =
      pr.amount ?? (expectedAmount !== undefined ? Amount.from(expectedAmount) : undefined);
    if (!expected) {
      throw new CTSError('amountless payment request: pass the expected amount to check against');
    }
    if (pr.unit && pr.unit !== this._unit) {
      throw new CTSError(`request unit '${pr.unit}' does not match wallet unit '${this._unit}'`);
    }
    this.assertProofsInWalletUnit(proofs);
    this.assertNoDuplicateProofs(proofs);
    // A locked request is satisfied only by proofs carrying the lock that was asked for. Spend
    // power the payee never requested is a payer clawback (NUT-18): an extra nutroot leaf, or the
    // legacy twin, a `refund`/`locktime` tag. A both-encoded request accepts either family, each
    // checked against its own option.
    const nutrootOption = pr.toNutrootOptions();
    if (nutrootOption || pr.nut10) {
      const statics = this.receiverKeysFor(nutrootOption, opts?.privkeys);
      const nut10Lock = pr.nut10 ? pr.toP2PKOptions() : undefined;
      this.failIf(
        !!pr.nut10 && !nut10Lock,
        `cannot check the request's nut10 lock kind '${pr.nut10?.kind}'`,
      );
      for (const p of proofs) {
        if (isBlsKeyset(p.id) && isV3PointSecret(p.secret)) {
          this.failIfNullish(nutrootOption, 'v3 proof: the request carries no nutroot option');
          verifyNutrootRequestTree(nutrootOption, p.spend_info, statics);
          verifyNutrootSpendInfo(p.secret, p.spend_info!);
          this.assertKeyedToReceiver(nutrootOption, p, statics);
          continue;
        }
        this.failIfNullish(nut10Lock, 'legacy proof: the request is for v3 proofs only');
        this.assertNut10Lock(nut10Lock, p.secret);
      }
    }
    // Admissibility, as the payer side checks it (NUT-18): a strict list binds the issuer, and the
    // proofs must be redeemable through a method the request accepts.
    const listed = pr.includesMint(this.mint.mintUrl);
    this.failIf(
      pr.isMintListStrict === true && !listed,
      "this wallet's mint is not in the request's strict mint list",
    );
    // mf applies only when this mint is outside the request's mint list (NUT-18).
    let mf = Amount.zero();
    if (pr.supportedMethods?.length) {
      const meltMethods = this.getMintInfo()
        .supportedMethods('melt')
        .filter((m) => m.unit === this._unit)
        .map((m) => m.method);
      this.failIf(
        !pr.supportedMethods.some((m) => meltMethods.includes(m.method)),
        `mint cannot melt ${this._unit} via any method the request accepts`,
      );
      mf = listed ? Amount.zero() : pr.feesFor(this.mint.mintUrl, meltMethods);
    }
    const needed = expected.add(mf).add(this.getFeesForProofs(proofs));
    return sumProofs(proofs).compareTo(needed) >= 0;
  }

  /**
   * The static keys a locked request must be checked against, validated.
   *
   * @remarks
   * Only a receiver-keyed nutroot request needs one: `K = P_receiver + r0*G` is an ECDH trial-match
   * no observer can do (NUT-28), so without the key there is nothing to check. A NUMS request needs
   * none, its internal key is pinned by the disclosed offset instead.
   * @throws If a receiver-keyed request is checked with no key, or a key is not a 32-byte scalar.
   */
  private receiverKeysFor(
    option: ParsedNutrootOption | undefined,
    privkeys: string | string[] | undefined,
  ): string[] {
    if (!option) return [];
    const keyed = option.receiverKey.toLowerCase() !== NUTROOT_NUMS_KEY;
    if (!keyed && !option.blindKeys?.length) return [];
    const statics = privkeys === undefined ? [] : [privkeys].flat();
    this.failIf(
      statics.length === 0,
      `${keyed ? 'receiver-keyed' : 'blind-me'} nutroot request: pass the requested key(s) as opts.privkeys, the proofs cannot be checked without them`,
    );
    const bad = statics.find((k) => !/^[0-9a-f]{64}$/i.test(k));
    this.failIf(bad !== undefined, 'opts.privkeys must be 32-byte hex private keys');
    return statics;
  }

  /**
   * Asserts a v3 proof is receiver-keyed to one of the payee's static keys (NUT-28).
   *
   * @remarks
   * No-op for a NUMS request, which has no receiver key to bind to. Otherwise the proof carries a
   * key path only the holder of the matching static key can walk; a proof keyed to anyone else, the
   * payer included, is not a payment the payee can spend.
   * @throws If no held key reproduces the proof's secret.
   */
  private assertKeyedToReceiver(
    option: ParsedNutrootOption,
    proof: Pick<Proof, 'secret' | 'spend_info'>,
    statics: string[],
  ): void {
    if (statics.length === 0 || option.receiverKey.toLowerCase() === NUTROOT_NUMS_KEY) return;
    // `E` is present: verifyNutrootRequestTree rejects a receiver-keyed proof without one.
    const E = proof.spend_info?.E as string;
    const tree = proof.spend_info?.tree;
    this.failIf(
      !statics.some((priv) => recoverReceiverKeyedSecretKey(proof.secret, E, priv, tree)),
      'Nutroot request: proof is not keyed to the requested receiver key',
    );
  }

  /**
   * Asserts a legacy proof's secret is exactly the lock the request asked for.
   *
   * @remarks
   * Both sides canonicalise through the same NUT-11 builder, so tag order and pubkey form do not
   * matter but content does: an unrequested `refund`/`locktime` pair is a payer clawback, and an
   * unlocked bearer secret is no lock at all.
   * @throws If the proof is unlocked, or carries a condition other than the requested one.
   */
  private assertNut10Lock(requested: P2PKOptions, secret: string): void {
    let held: P2PKOptions | undefined;
    try {
      const [kind, data] = parseSecret(secret);
      held = nut10ToP2PKOptions({ kind, data: data.data, tags: data.tags });
    } catch {
      held = undefined;
    }
    this.failIfNullish(
      held,
      'nut10 request: proof does not carry a NUT-10 lock of the requested kind',
    );
    this.failIf(
      JSON.stringify(p2pkOptionsToPRNut10(held)) !==
        JSON.stringify(p2pkOptionsToPRNut10(requested)),
      'nut10 request: proof lock is not the requested spending condition',
    );
  }

  /**
   * Asserts every proof belongs to a keyset of the wallet's unit.
   *
   * @remarks
   * Amounts are unit-less numbers, so a foreign-unit proof would otherwise count toward a total.
   * @throws If any proof's keyset is unknown or belongs to another unit of this mint.
   */
  private assertProofsInWalletUnit(proofs: Array<Pick<Proof, 'id'>>): void {
    const badProof = proofs.find((p) => !this._keyChain.isUnitKeyset(p.id));
    this.failIf(
      !!badProof,
      `Proof has unrecognised keyset. '${badProof?.id}' is not a ${this._unit} keyset from this mint`,
      { id: badProof?.id },
    );
  }

  /**
   * Asserts no proof appears twice.
   *
   * @remarks
   * A proof is bearer value redeemable once: the mint keys spent state on `Y =
   * hash_to_curve(secret)` (NUT-07), so copies sharing a secret are one proof, not two.
   * @throws If two proofs share a secret.
   */
  private assertNoDuplicateProofs(proofs: Array<Pick<Proof, 'secret'>>): void {
    const seen = new Set<string>();
    for (const [i, p] of proofs.entries()) {
      // Report the position, never the secret: it is the spending material.
      this.failIf(
        seen.has(p.secret),
        `Duplicate proof at index ${i}: each proof may appear only once`,
        { index: i },
      );
      seen.add(p.secret);
    }
  }

  /**
   * Returns the current fee PPK for a proof according to the cached keyset.
   *
   * @param proof {Proof} A single proof.
   * @returns FeePPK {number} The feePPK for the selected proof.
   * @throws Throws an error if the proofs keyset is unknown.
   */
  private getProofFeePPK(proof: Pick<Proof, 'id'>): number {
    try {
      // We need the proof's keyset so use keyChain here
      // We must NOT fallback to wallet's keyset
      return this._keyChain.getKeyset(proof.id).fee;
    } catch (e) {
      const message = `Could not get fee. No keyset found for keyset id: ${proof.id}`;
      this._logger.error(message, {
        e,
        keychain: this._keyChain.getKeysets(),
      });
      throw new CTSError(message, { cause: e });
    }
  }

  /**
   * Calculates the fees based on inputs for a given keyset.
   *
   * @param nInputs Number of inputs.
   * @param keysetId KeysetId used to lookup `input_fee_ppk`
   * @returns Fee amount.
   */
  getFeesForKeyset(nInputs: number, keysetId: string): Amount {
    let feePPK: number;
    try {
      // We must NOT fallback to wallet's keyset
      feePPK = this._keyChain.getKeyset(keysetId).fee;
    } catch (e) {
      const message = `No keyset found with ID ${keysetId}`;
      this._logger.error(message, { e });
      throw new CTSError(message, { cause: e });
    }
    // fee = ceil(nInputs * feePPK / 1000). ceilPercent keeps the product in bigint, so a large
    // (ingest-bounded) fee cannot lose integer precision the way number math would.
    return Amount.from(nInputs).ceilPercent(feePPK, 1000);
  }

  /**
   * Fee to add on top of `amount` so the resulting outputs can later be spent at no cost to the
   * receiver (ie sender pays fees). This is the amount `includeFees` adds.
   *
   * @remarks
   * The fee depends on the output count, taken from the default denomination split of `amount`.
   * Pass `nOutputs` when pricing up custom denomination sets.
   * @param amount The amount the receiver should net after swap fees.
   * @param opts.keysetId Optional `keysetId` to price against (default: the wallet's bound keyset)
   * @param opts.nOutputs Optional Override the output count for custom denoms (default: optimal
   *   split).
   * @returns The fee, zero when the keyset charges no input fees.
   */
  getFeesToInclude(amount: AmountLike, opts?: { keysetId?: string; nOutputs?: number }): Amount {
    const keyset = this.getKeyset(opts?.keysetId);
    const parsed = this.parseAmount(amount, 'getFeesToInclude', true);
    const nOutputs = opts?.nOutputs ?? splitAmount(parsed, keyset.keys).length;
    return Amount.sum(this.receiveFeeAmounts(nOutputs, keyset));
  }

  /**
   * Largest spendable amount from a proof set after subtracting the per-proof input fees the mint
   * charges and optionally a melt quote's `fee_reserve`.
   *
   * @remarks
   * Single step of a "melt all" iteration: fetch a melt quote, call this with the quote's
   * `fee_reserve` to get the largest amount that fits, then re-quote for that amount (since
   * `fee_reserve` may shrink with the smaller amount). Repeat until the result stabilises.
   * @param proofs Proofs the caller intends to spend.
   * @param feeReserve Optional. `fee_reserve` from a related melt quote (default: 0)
   * @returns The largest spendable amount, or zero if fees exceed the available total.
   */
  maxSpendableAfterFees(proofs: ProofLike[], feeReserve: AmountLike = 0): Amount {
    const total = sumProofs(proofs);
    const overhead = this.getFeesForProofs(proofs).add(feeReserve);
    return overhead.greaterThanOrEqual(total) ? Amount.zero() : total.subtract(overhead);
  }

  /**
   * Prepares inputs for a mint operation.
   *
   * @remarks
   * Internal method; strips DLEQ (NUT-12), p2pk_e (NUT-28) and spend_info for privacy and
   * serializes witnesses. Returns an array of new proof objects - does not mutate the originals.
   * @param proofs The proofs to prepare.
   * @param keepDleq Optional boolean to keep DLEQ (default: false, strips for privacy).
   * @param keepP2pkE Optional boolean to keep NUT-28 "E" (default: false, strips for privacy).
   * @param keepSpendInfo Optional boolean to keep spend_info (default: false, never for a mint
   *   payload; offline sends keep it because those proofs travel to the receiver, and for a v3
   *   proof spend_info is the only thing that can spend it).
   * @returns Prepared proofs for mint payload.
   */
  private _prepareInputsForMint(
    proofs: Proof[],
    keepDleq: boolean = false,
    keepP2pkE: boolean = false,
    keepSpendInfo: boolean = false,
  ): Proof[] {
    return proofs.map((p) => {
      const witness = this._normalizeWitness(p);
      const { dleq, p2pk_e, spend_info, ...rest } = p; // isolate the wallet-side fields
      let newProof: Proof = { ...rest, witness }; // add back normalized witness
      if (keepP2pkE && p2pk_e) newProof = { ...newProof, p2pk_e };
      if (keepDleq && dleq) newProof = { ...newProof, dleq };
      if (keepSpendInfo && spend_info) newProof = { ...newProof, spend_info };
      return newProof;
    });
  }

  /**
   * The wallet state slice the nutroot signing rules in `wallet/nutroot.ts` read.
   */
  private _nutrootState(): NutrootWalletState {
    return {
      seed: this._seed,
      counters: this.counters,
      logger: this._logger,
    };
  }

  /**
   * Reports what this wallet can do with a proof, it's available spending options.
   *
   * @remarks
   * Offline, and it changes nothing. Use it to triage received proofs of either lock family, decide
   * which leaf a script path plan should name, or show a user why a proof is stuck: `spendable` is
   * the one-line answer and `blockedBy` the why.
   *
   * A legacy NUT-11 lock is read into the same leaf shape (main path, then the refund path as an
   * `after` leaf), matched across key parity and through `p2pk_e` for blinded keys; an unlocked
   * legacy proof reports `keyPath: true`, since it spends with no witness at all.
   *
   * `satisfiable` is this wallet's own assessment from what it holds. The mint compares an `after`
   * leaf against its own clock, so a leaf that unlocked seconds ago may still be refused, and a
   * hashlock leaf is never satisfiable from the wallet alone: its preimage comes from the caller.
   * @param proof Any proof, with its spend info when it has one.
   * @param opts.privkeys Static keys to trial-match, for receiver-keyed proofs and leaf keys.
   * @param opts.now Unix seconds to judge locktimes against. Defaults to the current time.
   * @throws If a v3 keyset proof is not a point secret, a NUT-10 secret is of a kind this wallet
   *   cannot spend, a NUT-11 tag is malformed (a non-integer `n_sigs`, or a scalar tag with more
   *   than one value), or a disclosed tree holds a leaf it cannot parse (unknown version, type or
   *   constraint field): the same fail-closed rule the receive cascade applies.
   */
  spendOptions(proof: Proof, opts?: { privkeys?: string | string[]; now?: number }): SpendOptions {
    return proofSpendOptions(proof, opts, this._nutrootState());
  }

  /**
   * Builds script path plans for the v3 proofs the key path cannot spend: first satisfiable leaf
   * each, else the hashlock leaf a supplied preimage opens, for `ReceiveConfig.scriptPath`.
   *
   * @remarks
   * Skips non-v3 proofs (they sign in receive, not by plan), proofs the key path spends, and proofs
   * with no plannable leaf; ask {@link Wallet.spendOptions | spendOptions} why a missing proof is
   * stuck. A hashlock leaf is never satisfiable on its own: with `opts.preimage` it is planned when
   * its keys are covered and the preimage opens its hash. Leaf choice is policy: name plans
   * yourself when a later leaf is preferable (eg a cheaper key roster).
   * @throws If `opts.preimage` is not 64 hex characters.
   */
  planScriptPaths(
    proofs: Proof[],
    opts?: { privkeys?: string | string[]; now?: number; preimage?: string },
  ): ScriptPathPlan[] {
    const preimage = opts?.preimage;
    this.failIf(
      preimage !== undefined && !/^[0-9a-f]{64}$/i.test(preimage),
      'planScriptPaths: preimage must be 64 hex characters',
    );
    const plans: ScriptPathPlan[] = [];
    for (const proof of proofs) {
      if (!isBlsKeyset(proof.id) || !isV3PointSecret(proof.secret)) continue;
      const spend = proofSpendOptions(proof, opts, this._nutrootState());
      if (spend.keyPath) continue;
      const open = spend.script.find((o) => o.satisfiable);
      if (open) {
        plans.push({ secret: proof.secret, leafIndex: open.leafIndex });
        continue;
      }
      if (preimage === undefined) continue;
      const hashlock = spend.script.find(
        (o) =>
          o.blockedBy === 'preimage' &&
          o.leaf.hash !== undefined &&
          verifyHTLCHash(preimage, o.leaf.hash),
      );
      if (hashlock) plans.push({ secret: proof.secret, leafIndex: hashlock.leafIndex, preimage });
    }
    return plans;
  }

  /**
   * Normalizes a proof's witness for the mint payload.
   *
   * Serializes object witnesses to JSON and strips witnesses from non-NUT-10 secrets (plain secrets
   * with a witness field are rejected by mints).
   */
  private _normalizeWitness(proof: Proof): string | undefined {
    if (!proof.witness) return undefined;
    // Nutroot (v3) point secrets carry transaction witnesses (key or script path): keep them.
    if (isBlsKeyset(proof.id) && isV3PointSecret(proof.secret)) {
      return typeof proof.witness !== 'string' ? JSON.stringify(proof.witness) : proof.witness;
    }
    try {
      parseSecret(proof.secret);
    } catch {
      return undefined; // plain secret — strip stray witness
    }
    return typeof proof.witness !== 'string' ? JSON.stringify(proof.witness) : proof.witness;
  }

  /**
   * Decodes a string (`cashuB...`) or raw binary (`craw` + `B`) token.
   *
   * @remarks
   * Rehydrates a token from the space-saving CBOR format, including mapping short keyset ids to
   * their full representation.
   * @param token The token as a string or as binary bytes.
   * @returns Token object.
   */
  public decodeToken(token: string | Uint8Array): Token {
    const keysetIds = this._keyChain.getAllKeysetIds();
    return typeof token === 'string'
      ? getDecodedToken(token, keysetIds)
      : getDecodedTokenBinary(token, keysetIds);
  }

  // -----------------------------------------------------------------
  // Section: Restore
  // -----------------------------------------------------------------

  /**
   * Restores a keyset's deterministic proofs, scanning counters until the gap limit closes.
   *
   * @remarks
   * Each batch is state checked first and only unspent counters are restored, so spent proofs are
   * dropped without ever being blinded; pending ones are kept. `lastCounterWithSignature` covers
   * every issued counter found, spent included. For a raw NUT-09 replay use {@link Wallet.restore}.
   */
  async batchRestore(
    config?: BatchRestoreConfig,
  ): Promise<{ proofs: Proof[]; lastCounterWithSignature?: number }> {
    const keysetId = config?.keysetId ?? this.keysetId;
    const profile = scanProfile(keysetId);
    const { gapLimit = 300, batchSize = Math.min(this.maxArrayLength, profile.batchSize) } =
      config ?? {};
    let counter = config?.counter ?? 0;
    const bound = config?.maxCounter ?? Number.MAX_SAFE_INTEGER;
    this.failIf(
      !Number.isSafeInteger(counter) || counter < 0 || !Number.isSafeInteger(bound) || bound < 0,
      'counter and maxCounter must be non-negative safe integers',
    );
    // A zero batch would never advance the counter; gapLimit may be Infinity for a bounded scan,
    // but a fractional one would leave the probe width and gap count fractional.
    this.failIf(
      !Number.isSafeInteger(batchSize) ||
        batchSize < 1 ||
        batchSize > this.maxArrayLength ||
        !(Number.isSafeInteger(gapLimit) || gapLimit === Infinity) ||
        gapLimit < 1,
      `batchSize must be a positive integer up to ${this.maxArrayLength} and gapLimit a positive integer or Infinity`,
    );
    const probeSize = Math.min(gapLimit, this.maxArrayLength);
    const restoredProofs: Proof[] = [];

    let probe = Number.isFinite(gapLimit);
    let lastCounterWithSignature: undefined | number;
    let gapCount = 0; // consecutive never-used counters since the last used one
    let ramp = 1; // batches per wave: doubles while batches keep coming back used, up to the pool

    // Build restore batches in counter order
    while (gapCount < gapLimit && counter <= bound) {
      const batches: Array<{ start: number; count: number }> = [];
      // The one-time probe covers the gapLimit in one request (within the mint's array cap)
      // to save doing a full pool wave scan on unused keysets.
      if (probe) {
        probe = false;
        batches.push({ start: counter, count: Math.min(probeSize, bound - counter + 1) });
      } else {
        // Add enough batches to close the gapLimit from here, or the ramp's speculation if wider
        const needed = Math.ceil((gapLimit - gapCount) / batchSize);
        const width = Math.min(profile.poolSize, Math.max(needed, ramp));
        for (let i = 0; i < width; i++) {
          const start = counter + i * batchSize;
          if (start > bound) break;
          batches.push({ start, count: Math.min(batchSize, bound - start + 1) });
        }
      }
      // Restore the batches via a pool, keeping results in counter order
      const wave = await runPool(batches, profile.poolSize, ({ start, count }) =>
        this.restoreUnspent(start, count, keysetId),
      );
      const last = batches[batches.length - 1];
      counter = last.start + last.count;
      // Walk the results in counter order. A fully ramped up wave will likely overshoot
      // a valid gap, but the mint has seen those batches regardless, so check all batches
      // and reset the gapCount if we found anything after the gap.
      wave.forEach((res, i) => {
        const { start, count } = batches[i];
        // Unused batch: adds to gapCount
        if (!res.used) {
          gapCount += count;
          return;
        }
        // Used batch: the gap restarts after its last issued counter
        gapCount = start + count - 1 - res.lastCounterWithSignature;
        ramp = Math.min(ramp * 2, profile.poolSize);
        // push singly: a caller-set batchSize can exceed V8's ~65k spread-argument limit
        for (const p of res.proofs) {
          restoredProofs.push(p);
        }
        lastCounterWithSignature = res.lastCounterWithSignature;
      });
    }

    return { proofs: restoredProofs, lastCounterWithSignature };
  }

  /**
   * Restores deterministic proofs for every keyset in the wallet's unit.
   *
   * @remarks
   * Runs `batchRestore` per keyset, inactive keysets included, and merges the results. After
   * restoring, advance each keyset's counter from `lastCounters`.
   */
  async restoreAll(
    config?: RestoreAllConfig,
  ): Promise<{ proofs: Proof[]; lastCounters: Record<string, number> }> {
    const keysetIds = this._keyChain
      .getAllKeysetIds()
      .filter((id) => this._keyChain.getKeyset(id).unit === this.unit);
    let proofs: Proof[] = [];
    const lastCounters: Record<string, number> = {};
    for (const keysetId of keysetIds) {
      const res = await this.batchRestore({ ...config, keysetId });
      // concat, not push-spread: a keyset's result is unbounded and spread
      // arguments hit V8's call-size limit around ~65k elements.
      proofs = proofs.concat(res.proofs);
      if (res.lastCounterWithSignature !== undefined) {
        lastCounters[keysetId] = res.lastCounterWithSignature;
      }
    }
    return { proofs, lastCounters };
  }

  /**
   * Regenerates.
   *
   * @param start Set starting point for count (first cycle for each keyset should usually be 0)
   * @param count Set number of blinded messages that should be generated.
   * @param options.keysetId Set a custom keysetId to restore from. @see `keyChain)`
   */
  async restore(
    start: number,
    count: number,
    config?: RestoreConfig,
  ): Promise<{ proofs: Proof[]; lastCounterWithSignature?: number }> {
    this.failIfNullish(this._seed, 'Cashu Wallet must be initialized with a seed to use restore');
    const { keysetId } = config || {};

    // Ensure we have keys - wallet only loads active keysets by default.
    // Under strictCachedKeysets, skip the fetch: getKeyset below reports a keyless keyset.
    // Resolve once: an auto-bound wallet can rebind during the awaits below
    const scanId = keysetId ?? this.keysetId;
    if (!this._strictCachedKeysets) {
      await this._keyChain.ensureKeysetKeys(scanId);
    }
    const keyset = this.getKeyset(scanId);

    // create deterministic blank outputs for unknown restore amounts
    // Note: zero amount + zero denomination passes splitAmount validation
    const zeros = Array(count).fill(0);
    const outputData = this._outputDataCreator.createDeterministicData(
      0,
      this._seed,
      start,
      keyset,
      zeros,
    );

    const response = await this.mint.restore({
      outputs: outputData.map((d) => d.blindedMessage),
    });
    await this._ensureKeysetsForSignatures(response.signatures);
    // counters here are contiguous from `start`, so the index maps straight onto one
    const { proofs, lastIndex } = proofsFromRestoreResponse(outputData, response, (id) =>
      this.keysetForSignature(id),
    );

    return {
      proofs,
      lastCounterWithSignature: lastIndex < 0 ? undefined : start + lastIndex,
    };
  }

  /**
   * State checks a counter range, then restores only the counters that are not spent.
   *
   * @remarks
   * `Y = hash_to_curve(secret)` needs no blinding factor and no unblinding, so the whole range
   * costs one hash per counter. Spent counters are then dropped without ever revealing their `B_`,
   * which both shrinks the restore and avoids handing the mint a `B_`/`Y` pair it could use to tie
   * an issuance to its spend.
   *
   * `used` reports whether the range was ever issued into, which is what ends a scan: a range can
   * be fully spent, so "no proofs returned" does not mean "never used" here.
   */
  private async restoreUnspent(
    start: number,
    count: number,
    keysetId?: string,
  ): Promise<ScanResult> {
    this.failIfNullish(this._seed, 'Cashu Wallet must be initialized with a seed to use restore');
    const seed = this._seed;
    // Resolve once: an auto-bound wallet can rebind during the awaits below
    const scanId = keysetId ?? this.keysetId;
    // Under strictCachedKeysets, skip the fetch: getKeyset below reports a keyless keyset.
    if (!this._strictCachedKeysets) {
      await this._keyChain.ensureKeysetKeys(scanId);
    }
    const keyset = this.getKeyset(scanId);
    const derive = createSecretAndBlindingFactorDeriver(seed, keyset.id);

    // NUT-07 state check: needs only the secrets, so nothing is blinded until the spent counters have
    // dropped out below. An invalid-scalar counter failed at issuance too, so it holds nothing.
    const counters: number[] = [];
    const secrets: string[] = [];
    for (let c = start; c < start + count; c++) {
      try {
        secrets.push(bytesToHex(derive(c).secret));
        counters.push(c);
      } catch (e) {
        if (!(e instanceof InvalidScalarError)) throw e;
      }
    }
    if (counters.length === 0) return { proofs: [], used: false };
    const states = await this.checkProofsStates(
      secrets.map((secret) => ({ secret, id: keyset.id })),
    );

    // Spent counters drop out here, so their B_ is never built or sent and the mint never sees
    // the pair that would tie an issuance to its spend. The rest are blinded through the output
    // creator, so a custom crypto backend is honoured here as it is in a swap.
    let lastIssued = -1;
    const outputs: OutputDataLike[] = [];
    const outputCounters: number[] = [];
    states.forEach((state, i) => {
      if (state.state === CheckStateEnum.SPENT) {
        lastIssued = Math.max(lastIssued, counters[i]);
        return;
      }
      outputs.push(
        this._outputDataCreator.createSingleDeterministicData(0, seed, counters[i], keyset.id),
      );
      outputCounters.push(counters[i]);
    });
    // Every counter spent: the range is used but holds nothing, so skip the restore entirely.
    if (outputs.length === 0) {
      return { proofs: [], lastCounterWithSignature: lastIssued, used: true };
    }

    const response = await this.mint.restore({ outputs: outputs.map((d) => d.blindedMessage) });
    await this._ensureKeysetsForSignatures(response.signatures);
    // outputCounters is ascending, so the last signed index carries the highest live counter
    const { proofs, lastIndex } = proofsFromRestoreResponse(outputs, response, (id) =>
      this.keysetForSignature(id),
    );
    if (lastIndex >= 0) lastIssued = Math.max(lastIssued, outputCounters[lastIndex]);

    if (lastIssued < 0) return { proofs, used: false };
    return { proofs, lastCounterWithSignature: lastIssued, used: true };
  }

  // -----------------------------------------------------------------
  // Section: Create Mint Quote
  // -----------------------------------------------------------------

  /**
   * Creates a mint quote for any payment method.
   *
   * @remarks
   * Generic method for requesting a mint quote. The payload is method-specific but must at minimum
   * include the fields required by the mint for the given method. An optional `normalize` callback
   * can be used to coerce method-specific response fields.
   *
   * For first-class methods, prefer the typed helpers: `createMintQuoteBolt11()`,
   * `createMintQuoteBolt12()`.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param payload The request body to POST. `unit` is always set to the wallet's unit.
   * @param options.normalize Optional callback to normalize method-specific response fields.
   * @returns The mint quote response.
   */
  async createMintQuote<TRes extends MintQuoteBaseResponse = MintQuoteGenericResponse>(
    method: string,
    payload: Record<string, unknown>,
    options?: { normalize?: (raw: Record<string, unknown>) => TRes },
  ): Promise<TRes> {
    // Custom methods are fine, but NUT-04 requires the mint to advertise them
    this.requireSupport('mint', method);
    this.requireMintableKeyset('createMintQuote');
    // When the caller locks the quote (NUT-20), validate and normalize the pubkey.
    const rawPubkey = payload.pubkey;
    const normPubkey =
      rawPubkey !== undefined ? normalizeSecpPubkey(rawPubkey as string) : undefined;
    const body = { ...payload, unit: this._unit, ...(normPubkey ? { pubkey: normPubkey } : {}) };
    const res = await this.mint.createMintQuote<TRes>(method, body, {
      normalize: options?.normalize,
    });
    assertQuoteUnit(res, this.unit, this._logger);
    if (normPubkey) {
      assertQuoteLockedTo(res, normPubkey, this._logger);
    }
    return res;
  }

  /**
   * Asserts a bolt11 mint quote matches the amount the caller asked for.
   *
   * @remarks
   * For sat and msat quotes the invoice HRP amount is compared too; other units are not directly
   * comparable to the invoice, so only the quoted amount is checked.
   */
  private assertBolt11MintQuoteAmount(res: MintQuoteBolt11Response, expected: Amount): void {
    this.failIf(!res.amount.equals(expected), 'Mint quote amount does not match', {
      expected: expected.toString(),
      quoted: res.amount.toString(),
    });
    if (this._unit !== 'sat' && this._unit !== 'msat') return;
    let msat: bigint | null = null;
    try {
      msat = bolt11AmountMsat(res.request);
    } catch {
      // fall through: an unreadable invoice fails the comparison below
    }
    // Compare the invoice against the requested amount expressed in millisatoshis.
    const expectedMsat = this._unit === 'sat' ? expected.multiplyBy(1000) : expected;
    const matches = msat !== null && expectedMsat.equals(msat);
    this.failIf(!matches, 'Mint quote invoice amount does not match the quote', {
      expected: expected.toString(),
      invoiceMsat: msat,
    });
  }

  /**
   * Requests a bolt11 mint quote locked to `pubkey`. You hold its private key: minting signs with
   * it (`config.privkey`), and a lost key means an unredeemable quote.
   *
   * @remarks
   * Every new quote is locked: {@link Wallet.createQuoteLockKey | createQuoteLockKey} makes a
   * keypair, and a seeded wallet can re-derive a lost one
   * ({@link Wallet.recoverQuoteLockKey | recoverQuoteLockKey}). A mint that cannot lock (no NUT-20)
   * fails the echo check below, before the quote id is returned, so nothing is payable. For an
   * unlocked legacy quote, drop to the generic `createMintQuote()`.
   * @param amount Amount requesting for mint.
   * @param pubkey Public key to lock the quote to.
   * @param description Optional description for the mint quote.
   */
  async createMintQuoteBolt11(
    amount: AmountLike,
    pubkey: string,
    description?: string,
  ): Promise<MintQuoteBolt11Response> {
    this.requireSupport('mint', 'bolt11');
    this.requireMintableKeyset('createMintQuoteBolt11');
    this.failIf(typeof pubkey !== 'string', 'A pubkey is required to lock the mint quote');
    const normPubkey = normalizeSecpPubkey(pubkey);
    const mintAmount = this.parseAmount(amount, 'createMintQuoteBolt11');
    // Check if mint supports description for bolt11
    if (description) {
      const mintInfo = this.getMintInfo();
      if (!mintInfo.supportsNut04Description('bolt11', this._unit)) {
        this.fail('Mint does not support description for bolt11');
      }
    }
    const mintQuotePayload: MintQuoteBolt11Request = {
      unit: this._unit,
      amount: mintAmount,
      description: description,
      pubkey: normPubkey,
    };
    const res = await this.mint.createMintQuoteBolt11(mintQuotePayload);
    assertQuoteUnit(res, this.unit, this._logger);
    this.assertBolt11MintQuoteAmount(res, mintAmount);
    assertQuoteLockedTo(res, normPubkey, this._logger);
    return res;
  }

  /**
   * Creates a quote lock keypair: seed-derived (consuming the quote counter) when seeded, random
   * otherwise.
   *
   * @remarks
   * Derived keys are recoverable via {@link Wallet.recoverQuoteLockKey | recoverQuoteLockKey};
   * random ones exist only in the returned object, so persist the key with its quote. `{ random:
   * true }` forces a random key on a seeded wallet, consuming no counter: for throwaway quotes (eg
   * estimation) that must not pollute the recovery scan.
   */
  async createQuoteLockKey(opts?: {
    random?: boolean;
  }): Promise<{ pubkey: string; privkey: string }> {
    return createQuoteLockKeyPair(opts?.random ? undefined : this._seed, async () => {
      const range = await this._counterSource.reserve(QUOTE_COUNTER_KEY, 1);
      // Event-persisted sources must see the quote cursor move too, or a restart
      // re-derives keys already handed out.
      this.on._emitCountersReserved({
        counterKey: QUOTE_COUNTER_KEY,
        start: range.start,
        count: range.count,
        next: range.start + range.count,
      });
      return range.start;
    });
  }

  /**
   * Recovers a seed-derived quote lock key from the quote's lock pubkey by scanning the quote
   * counter. Returns undefined for a pubkey this seed never derived.
   *
   * @remarks
   * Offline disaster recovery for a lost quote `privkey`; the happy path is persisting the key the
   * quote response carries. Targeted, not discovery: one HMAC and one point multiply per counter.
   * No keyset is involved (NUT-13 type `0x04`), so a rotation cannot strand the key.
   * @throws {@link CTSError} On a seedless wallet, which has nothing to scan.
   */
  async recoverQuoteLockKey(pubkey: string): Promise<string | undefined> {
    return scanQuoteLockKey(pubkey, this._nutrootState());
  }

  /**
   * Requests a mint quote from the mint. Response returns a Lightning BOLT12 offer for the
   * requested given amount and unit.
   *
   * @param pubkey Public key to lock the quote to.
   * @param options.amount BOLT12 offer amount requesting for mint. If not specified, the offer will
   *   be amountless.
   * @param options.description Description for the mint quote.
   * @returns The mint will return a mint quote with a BOLT12 offer for minting tokens of the
   *   specified amount and unit.
   */
  async createMintQuoteBolt12(
    pubkey: string,
    options?: {
      amount?: AmountLike;
      description?: string;
    },
  ): Promise<MintQuoteBolt12Response> {
    this.requireSupport('mint', 'bolt12');
    this.requireMintableKeyset('createMintQuoteBolt12');
    this.failIf(typeof pubkey !== 'string', 'A pubkey is required to lock the mint quote');
    const normPubkey = normalizeSecpPubkey(pubkey);
    // Check if mint supports description for bolt12
    const mintInfo = this.getMintInfo();
    if (options?.description && !mintInfo.supportsNut04Description('bolt12', this._unit)) {
      this.fail('Mint does not support description for bolt12');
    }

    const amount =
      options?.amount !== undefined
        ? this.parseAmount(options.amount, 'createMintQuoteBolt12')
        : undefined;

    const mintQuotePayload: MintQuoteBolt12Request = {
      pubkey: normPubkey,
      unit: this._unit,
      amount,
      description: options?.description,
    };

    const res = await this.mint.createMintQuoteBolt12(mintQuotePayload);
    assertQuoteUnit(res, this.unit, this._logger);
    // The offer itself is opaque here, so the quoted amount is the only thing to hold the mint to.
    const amountMatches =
      amount === undefined ? res.amount === null : res.amount !== null && res.amount.equals(amount);
    this.failIf(!amountMatches, 'Mint quote amount does not match', {
      expected: amount?.toString() ?? null,
      quoted: res.amount?.toString() ?? null,
    });
    assertQuoteLockedTo(res, normPubkey, this._logger);
    return res;
  }

  /**
   * Requests an onchain mint quote from the mint. Response returns a Bitcoin address for the
   * requested unit.
   *
   * @param pubkey Public key to lock the quote to. Required for onchain minting.
   * @returns The mint will return a mint quote with a Bitcoin address for minting tokens.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async createMintQuoteOnchain(pubkey: string): Promise<MintQuoteOnchainResponse> {
    this.requireSupport('mint', 'onchain');
    this.requireMintableKeyset('createMintQuoteOnchain');
    this.failIf(typeof pubkey !== 'string', 'A pubkey is required to lock the mint quote');
    const normPubkey = normalizeSecpPubkey(pubkey);
    const res = await this.mint.createMintQuoteOnchain({ unit: this._unit, pubkey: normPubkey });
    assertQuoteUnit(res, this.unit, this._logger);
    assertQuoteLockedTo(res, normPubkey, this._logger);
    return res;
  }

  // -----------------------------------------------------------------
  // Section: Check Mint Quote
  // -----------------------------------------------------------------

  /**
   * Checks an existing mint quote for any payment method.
   *
   * @remarks
   * Generic method for checking a mint quote status. An optional `normalize` callback can be used
   * to coerce method-specific response fields.
   *
   * For first-class methods, prefer the typed helpers: `checkMintQuoteBolt11()`,
   * `checkMintQuoteBolt12()`.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param quote Quote ID or quote object (must have a `quote` field).
   * @param options.normalize Optional callback to normalize method-specific response fields.
   * @returns The mint quote response.
   */
  async checkMintQuote<TRes extends MintQuoteBaseResponse = MintQuoteGenericResponse>(
    method: string,
    quote: string | Pick<TRes, 'quote'>,
    options?: { normalize?: (raw: Record<string, unknown>) => TRes },
  ): Promise<TRes> {
    const quoteId = typeof quote === 'string' ? quote : (quote as { quote: string }).quote;
    return this.mint.checkMintQuote<TRes>(method, quoteId, {
      normalize: options?.normalize,
    });
  }

  /**
   * Gets an existing mint quote from the mint.
   *
   * @param quote Quote ID.
   * @returns The mint will create and return a Lightning invoice for the specified amount.
   */
  async checkMintQuoteBolt11(
    quote: string | MintQuoteBolt11Response,
  ): Promise<MintQuoteBolt11Response> {
    const quoteId = typeof quote === 'string' ? quote : quote.quote;
    const res = await this.mint.checkMintQuoteBolt11(quoteId);
    // No caller-side expectation here, so check the invoice against the quote's own amount.
    this.assertBolt11MintQuoteAmount(res, res.amount);
    return res;
  }

  /**
   * Gets an existing BOLT12 mint quote from the mint.
   *
   * @param quote Quote ID.
   * @returns The latest mint quote for the given quote ID.
   */
  async checkMintQuoteBolt12(quote: string): Promise<MintQuoteBolt12Response> {
    return this.mint.checkMintQuoteBolt12(quote);
  }

  /**
   * Gets an existing onchain mint quote from the mint.
   *
   * @param quote Quote ID.
   * @returns The latest mint quote for the given quote ID.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async checkMintQuoteOnchain(quote: string): Promise<MintQuoteOnchainResponse> {
    return this.mint.checkMintQuoteOnchain(quote);
  }

  /**
   * Checks existing mint quotes for any payment method in one batched request.
   *
   * @remarks
   * Generic method for checking multiple mint quote statuses. An optional `normalize` callback can
   * be used to coerce method-specific response fields. Mints that predate this endpoint return an
   * error; callers can fall back to `checkMintQuote()` per quote id when needed.
   *
   * For first-class methods, prefer the typed helpers: `checkMintQuoteBatchBolt11()`,
   * `checkMintQuoteBatchBolt12()`.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param quotes Quote IDs or quote objects (each object must have a `quote` field).
   * @param options.normalize Optional callback to normalize method-specific response fields.
   * @returns Mint quote responses in request order.
   * @experimental only supported by CDK mint >= 0.16.0
   */
  async checkMintQuoteBatch<TRes extends MintQuoteBaseResponse = MintQuoteGenericResponse>(
    method: string,
    quotes: Array<string | Pick<TRes, 'quote'>>,
    options?: { normalize?: (raw: Record<string, unknown>) => TRes },
  ): Promise<TRes[]> {
    const quoteIds = quotes.map((quote) => (typeof quote === 'string' ? quote : quote.quote));
    return this.mint.checkMintQuoteBatch<TRes>(method, quoteIds, {
      normalize: options?.normalize,
    });
  }

  /**
   * Checks existing BOLT11 mint quotes in one batched request.
   *
   * @remarks
   * Mints that predate this endpoint return an error; callers can fall back to
   * `checkMintQuoteBolt11()` per quote id when needed.
   * @param quotes Quote IDs or quote objects.
   * @returns Updated BOLT11 mint quotes in request order.
   * @experimental only supported by CDK mint >= 0.16.0
   */
  async checkMintQuoteBatchBolt11(
    quotes: Array<string | MintQuoteBolt11Response>,
  ): Promise<MintQuoteBolt11Response[]> {
    const quoteIds = quotes.map((quote) => (typeof quote === 'string' ? quote : quote.quote));
    const res = await this.mint.checkMintQuoteBatchBolt11(quoteIds);
    for (const quote of res) this.assertBolt11MintQuoteAmount(quote, quote.amount);
    return res;
  }

  /**
   * Checks existing BOLT12 mint quotes in one batched request.
   *
   * @remarks
   * Mints that predate this endpoint return an error; callers can fall back to
   * `checkMintQuoteBolt12()` per quote id when needed.
   * @param quotes Quote IDs or quote objects.
   * @returns Updated BOLT12 mint quotes in request order.
   * @experimental only supported by CDK mint >= 0.16.0
   */
  async checkMintQuoteBatchBolt12(
    quotes: Array<string | MintQuoteBolt12Response>,
  ): Promise<MintQuoteBolt12Response[]> {
    const quoteIds = quotes.map((quote) => (typeof quote === 'string' ? quote : quote.quote));
    return this.mint.checkMintQuoteBatchBolt12(quoteIds);
  }

  // -----------------------------------------------------------------
  // Section: Mint Proofs
  // -----------------------------------------------------------------

  private validateReturnedSignatures(
    signatures: SerializedBlindedSignature[],
    outputData: OutputDataLike[],
  ): void {
    // With DLEQ we can verify the returned blinded signature is paired to the original B_.
    // Without DLEQ, equal-denomination reordering is a protocol trust assumption.
    const requiresDleq =
      this._requireSigDleq && (this._mintInfo?.isSupported(12).supported ?? false);

    for (let i = 0; i < signatures.length; i++) {
      this.failIf(
        signatures[i] == undefined,
        `Mint response is missing a signature at index ${i}. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
      );
      // amount=0 marks a blank (NUT-08 fee change, NUT-09 restore): the mint chooses the amount
      // and, after a rotation, the keyset. Otherwise the mint must return exactly what was asked,
      // or it's a downgrade attack.
      const blank = outputData[i].blindedMessage.amount.isZero();
      // A zero-value signature on a blank carries no ecash and is dropped by the caller (NUT-08),
      // so nothing here applies to it, the DLEQ requirement included.
      if (blank && signatures[i].amount.isZero()) continue;
      this.failIf(
        !blank && signatures[i].id !== outputData[i].blindedMessage.id,
        `Mint signature keyset id at index ${i} does not match output: expected ${outputData[i].blindedMessage.id}, got ${signatures[i].id}. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
      );
      this.failIf(
        !blank && !signatures[i].amount.equals(outputData[i].blindedMessage.amount),
        `Mint returned signature with wrong amount at index ${i}: expected ${outputData[i].blindedMessage.amount.toString()}, got ${signatures[i].amount.toString()}. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
      );
      // v3 (BLS) signatures intentionally omit DLEQ — pairing verification replaces it.
      const isV3 = isBlsKeyset(signatures[i].id);
      this.failIf(
        requiresDleq && !isV3 && !signatures[i].dleq,
        `Mint supports NUT-12, but returned a signature without DLEQ proof at index ${i}. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
      );
    }
  }

  private validateMintQuoteAvailableAmount(
    method: string,
    paid: AmountLike,
    issued: AmountLike,
    requestedAmount: Amount,
  ): void {
    const amountPaid = Amount.from(paid);
    const amountIssued = Amount.from(issued);
    // A 0/0 snapshot may simply have been fetched before the payment was made (create -> pay
    // externally -> mint with the original object); the mint is the source of truth.
    if (amountPaid.isZero() && amountIssued.isZero()) {
      return;
    }
    const availableAmount = amountPaid.subtract(amountIssued);
    this.failIf(
      requestedAmount.greaterThan(availableAmount),
      `Mint quote has only ${availableAmount.toString()} available to mint; requested ${requestedAmount.toString()}`,
      {
        method,
        amount_paid: amountPaid.toString(),
        amount_issued: amountIssued.toString(),
        requestedAmount: requestedAmount.toString(),
      },
    );
  }

  /**
   * @internal
   */
  computeY(secret: string, keysetId: string): string {
    return this._hashToCurve(secret, keysetId);
  }

  /**
   * Mints proofs for any payment method.
   *
   * @remarks
   * Generic convenience method that calls `prepareMint(method, …)` followed by `completeMint()`.
   *
   * Intended primarily for custom payment methods. For first-class methods, prefer
   * `mintProofsBolt11()` or `mintProofsBolt12()`, which keep the method-specific wallet ergonomics
   * and validation.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param amount Amount to mint.
   * @param quote The mint quote object (must have at least a `quote` field).
   * @param config Optional parameters (e.g. privkey for locked quotes).
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns Minted proofs.
   */
  async mintProofs<TQuote extends Pick<MintQuoteBaseResponse, 'quote'>>(
    method: string,
    amount: AmountLike,
    quote: TQuote,
    config?: MintProofsConfig,
    outputType?: OutputType,
  ): Promise<Proof[]> {
    const preview = await this.prepareMint(method, amount, quote, config, outputType);
    return this.completeMint(preview);
  }

  /**
   * Mint proofs for a bolt11 quote.
   *
   * @remarks
   * Convenience helper for the common BOLT11 flow. Internally this uses `prepareMint('bolt11',…)`
   * followed by `completeMint()`. Use `prepareMint()` directly when you need the generic method
   * based API or want to persist a replay-safe preview before completion. A quote ID is fetched
   * before minting; pass a full quote object to avoid that request.
   * @param amount Amount to mint.
   * @param quote Mint quote ID or object (bolt11).
   * @param config Optional parameters (e.g. privkey for locked quotes).
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns Minted proofs.
   */
  async mintProofsBolt11(
    amount: AmountLike,
    quote: string | MintQuoteBolt11Response,
    config?: MintProofsConfig,
    outputType?: OutputType,
  ): Promise<Proof[]> {
    this.requireSupport('mint', 'bolt11');
    if (typeof quote === 'string') {
      quote = await this.checkMintQuoteBolt11(quote);
    }
    assertQuoteUnit(quote, this.unit, this._logger);
    const preview = await this.prepareMint('bolt11', amount, quote, config, outputType);
    return this.completeMint(preview);
  }

  /**
   * Mints proofs for a bolt12 quote.
   *
   * @remarks
   * Convenience helper for the common BOLT12 flow. Internally this uses `prepareMint('bolt12',…)`
   * followed by `completeMint()`. Use `prepareMint()` directly when you need the generic method
   * based API or want to persist a replay-safe preview before completion.
   * @param amount Amount to mint.
   * @param quote Bolt12 mint quote.
   * @param privkey Private key to unlock the quote.
   * @param config Optional parameters (e.g. keysetId).
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns Minted proofs.
   */
  async mintProofsBolt12(
    amount: AmountLike,
    quote: MintQuoteBolt12Response,
    privkey: string,
    config?: Omit<MintProofsConfig, 'privkey'>,
    outputType?: OutputType,
  ): Promise<Proof[]> {
    this.requireSupport('mint', 'bolt12');
    const preview = await this.prepareMint(
      'bolt12',
      amount,
      quote,
      { ...config, privkey },
      outputType,
    );
    return this.completeMint(preview);
  }

  /**
   * Mints proofs using an onchain quote.
   *
   * @remarks
   * Convenience helper for the onchain flow. Pubkey is always required for onchain mint quotes, so
   * `privkey` is always needed. Use `prepareMint()` directly when you need the generic method based
   * API or want to persist a replay-safe preview before completion.
   * @param amount Amount to mint.
   * @param quote Onchain mint quote.
   * @param privkey Private key matching the pubkey the quote is locked to.
   * @param config Optional parameters (e.g. keysetId).
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns Minted proofs.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async mintProofsOnchain(
    amount: AmountLike,
    quote: MintQuoteOnchainResponse,
    privkey: string,
    config?: Omit<MintProofsConfig, 'privkey'>,
    outputType?: OutputType,
  ): Promise<Proof[]> {
    this.requireSupport('mint', 'onchain');
    const preview = await this.prepareMint(
      'onchain',
      amount,
      quote,
      { ...config, privkey },
      outputType,
    );
    return this.completeMint(preview);
  }

  /**
   * Prepare a mint transaction for replay and later completion.
   *
   * @remarks
   * Generic method-oriented mint API. This supports current methods such as `bolt11` and `bolt12`
   * as well as future custom methods exposed by the mint. For first-class typed ergonomics with the
   * built-in methods, prefer `mintProofsBolt11()`, `mintProofsBolt12()`, or
   * `wallet.ops.mintBolt11()/mintBolt12()`.
   *
   * Returns a `MintPreview` with the quote, output data and NUT-20 signature that `completeMint`
   * sends. Persist this preview to support NUT-19 replay safety.
   * @param quote The mint quote for this method. A mint response is used as given; anything short
   *   of one, such as `{ quote: string }`, is read from the mint and merged over what you passed,
   *   so the unit and accounting checks run against the mint's values. Pass `config.privkey` to
   *   produce a NUT-20 signature regardless of whether the quote carries a `pubkey` field.
   */
  async prepareMint<TQuote extends Pick<MintQuoteBaseResponse, 'quote'>>(
    method: string,
    amount: AmountLike,
    quote: TQuote,
    config?: MintProofsConfig,
    outputType?: OutputType,
  ): Promise<MintPreview<TQuote>> {
    this.failIf(
      typeof quote === 'string',
      `prepareMint: expected a quote object, not a string ID. Pass { quote: id } and the wallet reads it from the mint.`,
    );
    this.failIf(
      typeof quote.quote !== 'string' || quote.quote.length === 0,
      'prepareMint: the quote needs its id',
    );
    // Keep the caller's quote type while reading optional protocol fields. Stored accounting
    // may still be AmountLike; validateMintQuoteAvailableAmount normalizes it before use.
    let resolvedQuote: TQuote & Partial<MintQuoteBaseResponse> = quote;
    // Mint fills the unit and accounting on every response; fetch any missing fields first.
    // Merge rather than swap: the mint's values win on every field it sends, and anything the
    // caller carries on its own quote type survives into the request, transcript and preview.
    if (
      resolvedQuote.unit == null ||
      resolvedQuote.amount_paid == null ||
      resolvedQuote.amount_issued == null
    ) {
      const fetched = await this.checkMintQuote<MintQuoteBaseResponse>(method, quote.quote);
      resolvedQuote = { ...quote, ...definedOnly(fetched) };
    }
    assertQuoteUnit(resolvedQuote, this.unit, this._logger);
    const requestedAmount = this.parseAmount(amount, `prepareMint: ${method}`);
    // Resolution above guarantees both, so a gap here is this wallet's bug, not the mint's.
    this.failIfNullish(resolvedQuote.amount_paid, 'prepareMint: quote accounting is unavailable');
    this.failIfNullish(resolvedQuote.amount_issued, 'prepareMint: quote accounting is unavailable');
    this.validateMintQuoteAvailableAmount(
      method,
      resolvedQuote.amount_paid,
      resolvedQuote.amount_issued,
      requestedAmount,
    );
    outputType = outputType ?? this.defaultOutputType(); // Fallback to policy
    const { keysetId, proofsWeHave, onCountersReserved } = config ?? {};
    const privkey = config?.privkey;

    // Shape output type and denominations for our proofs
    // we are receiving, so no includeFees.
    const keyset = this.getOutputKeyset(keysetId); // specified or wallet keyset
    let mintOT = this.configureOutputs(
      requestedAmount,
      keyset,
      outputType,
      false, // no fees
      proofsWeHave,
    );
    const mintAmount = this.preparedTotal(mintOT);

    // Assign counters atomically if OutputType is deterministic
    // and the counter is zero (auto-assign)
    const autoCounters = await this.addCountersToOutputTypes(keyset.id, mintOT);
    [mintOT] = autoCounters.outputTypes;
    if (autoCounters.used) {
      this.safeCallback(onCountersReserved, autoCounters.used, { op: 'mintProofs' });
    }
    this._logger.debug('mint counter', {
      counter: autoCounters.used,
      mintOT: stringifyOutputTypeForLog(mintOT),
    });

    const outputs = this.createOutputData(mintAmount, keyset, mintOT);
    const blindedMessages = outputs.map((d) => d.blindedMessage);
    const v3 = this.mintsOntoV3(blindedMessages);

    // Sign whenever a privkey or sign callback is provided — quote.pubkey may be absent if only
    // the quote ID was stored, but the caller still needs to produce a NUT-20 signature
    let signature: string | undefined;
    let legacySignature: string | undefined;
    // The key is caller state, passed in config; nothing is recovered implicitly
    // (recoverQuoteLockKey is the explicit tool for a seeded wallet that lost it).
    const sign = privkey ? undefined : config?.sign;
    const quotePubkey = resolvedQuote.pubkey;
    if (quotePubkey) {
      this.failIf(
        !privkey && !sign,
        'Can not sign locked quote without private key or sign callback (see recoverQuoteLockKey)',
      );
    }
    if (privkey || sign) {
      let signingKey: string | undefined;
      if (privkey) {
        this.failIf(
          !quotePubkey && Array.isArray(privkey),
          `prepareMint: multiple privkeys supplied for a quote without pubkey`,
        );
        signingKey = quotePubkey
          ? findSigningKey(quotePubkey, privkey)
          : Array.isArray(privkey)
            ? privkey[0]
            : privkey;
        this.failIf(!signingKey, 'prepareMint: privkey is empty or correct privkey not provided');
      }
      const request: MintQuoteSignRequest = {
        digest: new Uint8Array(),
        quoteId: resolvedQuote.quote,
        outputs: blindedMessages,
      };
      if (v3) {
        // V3 (nutroot secrets): the quote is a transaction input; its lock key signs the
        // quote input digest (NUT-10). No legacy fallback on v3 keysets.
        // The transcript commits the quote's face amount, not this draw: the output
        // section already binds the draw (NUT-10). Amountless quotes commit 0;
        // a bolt11 quote always has an amount, so an absent one is a caller omission.
        const quoteAmount =
          'amount' in resolvedQuote ? (resolvedQuote.amount as AmountLike) : undefined;
        this.failIf(
          quoteAmount === undefined && method === 'bolt11',
          'prepareMint: quote object lacks its amount; pass the full mint quote',
        );
        const tx = inputsForPayload({
          mintQuotes: [{ quoteId: resolvedQuote.quote, amount: quoteAmount ?? 0 }],
          outputs: blindedMessages,
        });
        const { digest, inputContainer } = tx.quotes.get(resolvedQuote.quote)!;
        Object.assign(request, {
          digest,
          transactionMessage: tx.transactionMessage,
          inputContainer,
        });
      } else {
        request.digest = mintQuoteDigest(resolvedQuote.quote, blindedMessages);
      }
      if (signingKey) {
        signature = schnorrSignDigest(request.digest, signingKey);
        // Keep a legacy (pre nuts#375) signature over the same outputs as a fallback for
        // not-yet-upgraded mints — see completeMint(). Never on v3 keysets.
        if (!v3) {
          legacySignature = signMintQuoteLegacy(signingKey, resolvedQuote.quote, blindedMessages);
        }
      } else {
        signature = await sign!(request);
        // A wrong signer fails here, not at the mint; without a quote pubkey there is nothing
        // to check against, as with a bare privkey.
        this.failIf(
          !!quotePubkey && !schnorrVerifyDigest(signature, request.digest, quotePubkey),
          'prepareMint: the sign callback returned a signature the quote pubkey does not verify',
        );
      }
    }

    return { method, quote: resolvedQuote, outputData: outputs, signature, legacySignature };
  }

  /**
   * Send a mint request, retrying with the legacy NUT-20 signature for legacy mints.
   *
   * TODO: Remove this compat shim when legacy message support is dropped.
   */
  private async withLegacyQuoteSigFallback(
    hasLegacySignature: boolean,
    attempt: () => Promise<MintResponse>,
    retryWithLegacySignature: () => Promise<MintResponse>,
  ): Promise<MintResponse> {
    try {
      return await attempt();
    } catch (e) {
      if (
        hasLegacySignature &&
        isMintOperationError(e) &&
        e.code === MINT_QUOTE_SIGNATURE_INVALID_CODE
      ) {
        this._logger.warn(
          'Mint rejected the amended NUT-20 quote signature (20008); retrying with the legacy message.',
        );
        return retryWithLegacySignature();
      }
      throw e;
    }
  }

  /**
   * Complete a prepared mint transaction.
   *
   * @remarks
   * Use with a `MintPreview` returned by `prepareMint()`. This is the second step of the generic
   * mint flow and is also what the named convenience helpers use internally.
   * @param mintPreview Preview returned by prepareMint.
   * @returns Minted proofs.
   * @throws {@link StaleKeysetError} If the mint rejects the outputs' keyset.
   */
  async completeMint(
    mintPreview: MintPreview<Pick<MintQuoteBaseResponse, 'quote'>>,
  ): Promise<Proof[]> {
    const { quote, outputData, method, signature, legacySignature } = mintPreview;
    const request: MintRequest = {
      quote: quote.quote,
      outputs: outputData.map((d) => d.blindedMessage),
      ...(signature !== undefined ? { signature } : {}),
    };
    // TODO: Remove legacy message support
    const { signatures } = await this.withStaleKeysetRepair(() =>
      this.withLegacyQuoteSigFallback(
        legacySignature !== undefined,
        () => this.mint.mint(method, request),
        () => this.mint.mint(method, { ...request, signature: legacySignature }),
      ),
    );
    this.failIf(
      signatures.length !== outputData.length,
      `Mint returned ${signatures.length} signatures, expected ${outputData.length}. The mint quote may already be marked issued; if the wallet is seeded, try restoring (NUT-09) to recover.`,
    );
    this.validateReturnedSignatures(signatures, outputData);

    // Unblind under the keyset each signature names, as custom outputs may pick their own.
    await this._ensureKeysetsForSignatures(signatures);
    this._logger.debug('MINT COMPLETED', {
      amounts: outputData.map((o) => o.blindedMessage.amount.toString()),
    });
    return outputData.map((d, i) =>
      d.toProof(signatures[i], this.keysetForSignature(signatures[i].id)),
    );
  }

  /**
   * Prepare a batched mint transaction (NUT-29).
   *
   * @remarks
   * Creates a single consolidated set of outputs for all quotes. Each requested amount is checked
   * against its quote's available balance before outputs or counters are allocated. A 0/0
   * accounting snapshot defers to the mint, as in prepareMint.
   *
   * NOTE:
   *
   * - Any quote without a pubkey is considered unlocked. Pass `pubkey` for locked quotes.
   * - Check all quotes are in the PAID state. If any quote is unpaid, the entire batch will fail.
   *
   * @param method Payment method identifier (e.g., 'bolt11', 'bolt12').
   * @param entries Array of per-quote parameters: `{ amount, quote }`. Quotes missing a unit or
   *   accounting are fetched in one batched lookup and merged over the supplied objects. The mint's
   *   values, including nulls, win; caller-only fields survive in the preview.
   * @param config Optional config applied to the entire batch (keysetId, privkey, counters, etc.).
   * @param outputType Optional output type override applied to the consolidated outputs.
   * @returns A `BatchMintPreview` ready to pass to `completeBatchMint`.
   * @experimental only supported by CDK mint >= 0.16.0
   */
  async prepareBatchMint<TQuote extends Pick<MintQuoteBaseResponse, 'quote' | 'pubkey'>>(
    method: string,
    entries: Array<{
      amount: AmountLike;
      quote: TQuote;
    }>,
    config?: MintProofsConfig,
    outputType?: OutputType,
  ): Promise<BatchMintPreview<TQuote>> {
    this.failIf(entries.length === 0, 'prepareBatchMint: no entries provided');

    // Enforce NUT-29 batch-size limit advertised by the mint, clamped to our absolute cap.
    // If the mint does not advertise NUT-29 info, the absolute cap still applies.
    const nut29 = this._mintInfo?.isSupported(29);
    const nut29Params = nut29?.supported ? nut29.params : undefined;

    const effectiveLimit = nut29Params?.max_batch_size ?? ABSOLUTE_MAX_BATCH_SIZE;

    if (entries.length > effectiveLimit) {
      const limitSource =
        nut29Params?.max_batch_size != null ? `mint's advertised limit` : `cashu-ts internal cap`;
      this.failIf(
        true,
        `prepareBatchMint: batch size ${entries.length} exceeds ` +
          `${limitSource} of ${effectiveLimit}`,
      );
    }

    // Warn if the requested method is not in the mint's NUT-29 supported methods
    if (nut29Params?.methods?.length) {
      if (!nut29Params.methods.includes(method)) {
        this._logger.warn(
          `prepareBatchMint: method '${method}' is not in mint's advertised NUT-29 methods`,
        );
      }
    }

    const { privkey, keysetId, proofsWeHave, onCountersReserved } = config ?? {};

    let resolvedEntries: Array<{
      amount: AmountLike;
      quote: TQuote & Partial<MintQuoteBaseResponse>;
    }> = entries;
    // Validate every quote, and sort them: as in prepareMint, a mint response is used as given
    // and anything the caller built is read back, all of those in one request.
    const unresolved: string[] = [];
    for (const entry of resolvedEntries) {
      this.failIf(
        typeof entry.quote !== 'object' || entry.quote === null,
        `prepareBatchMint: expected a quote object, not a string ID. Pass { quote: id } and the wallet reads it from the mint.`,
      );
      this.failIf(
        typeof entry.quote.quote !== 'string' || entry.quote.quote.length === 0,
        'prepareBatchMint: every quote needs its id',
      );
      if (
        entry.quote.unit != null &&
        entry.quote.amount_paid != null &&
        entry.quote.amount_issued != null
      ) {
        assertQuoteUnit(entry.quote, this.unit, this._logger);
      } else {
        unresolved.push(entry.quote.quote);
      }
    }
    if (unresolved.length) {
      const fetched = new Map<string, MintQuoteBaseResponse>();
      for (const quote of await this.checkMintQuoteBatch<MintQuoteBaseResponse>(method, [
        ...new Set(unresolved),
      ])) {
        assertQuoteUnit(quote, this.unit, this._logger);
        fetched.set(quote.quote, quote);
      }
      // As in prepareMint, the mint's values win and the caller's own fields survive.
      resolvedEntries = resolvedEntries.map((entry) => {
        const resolved = fetched.get(entry.quote.quote);
        return resolved ? { ...entry, quote: { ...entry.quote, ...definedOnly(resolved) } } : entry;
      });
    }

    const keyset = this.getOutputKeyset(keysetId);
    // Keys are caller state, passed in config; findSigningKey matches each locked quote's pubkey.
    const signingKeys = privkey ? [privkey].flat() : [];

    // Check locked quotes: require a privkey and verify it can sign
    const hasLockedQuotes = resolvedEntries.some((e) => e.quote.pubkey);
    if (hasLockedQuotes) {
      this.failIf(
        signingKeys.length === 0,
        'Can not sign locked quotes without private key (see recoverQuoteLockKey)',
      );
    }

    // Parse amounts and determine keyset
    const amounts = resolvedEntries.map(({ amount, quote }) => {
      const requestedAmount = this.parseAmount(amount, `prepareBatchMint: ${method}`);
      this.failIfNullish(quote.amount_paid, 'prepareBatchMint: quote accounting is unavailable');
      this.failIfNullish(quote.amount_issued, 'prepareBatchMint: quote accounting is unavailable');
      this.validateMintQuoteAvailableAmount(
        method,
        quote.amount_paid,
        quote.amount_issued,
        requestedAmount,
      );
      return requestedAmount;
    });
    const totalAmount = Amount.sum(amounts);

    // Shape consolidated outputs over the total amount
    outputType = outputType ?? this.defaultOutputType();
    let mintOT = this.configureOutputs(
      totalAmount,
      keyset,
      outputType,
      false, // no fees
      proofsWeHave,
    );

    // Assign counters atomically if deterministic
    const autoCounters = await this.addCountersToOutputTypes(keyset.id, mintOT);
    [mintOT] = autoCounters.outputTypes;
    if (autoCounters.used) {
      this.safeCallback(onCountersReserved, autoCounters.used, { op: 'mintProofs' });
    }

    // Create consolidated output data
    const outputs = this.createOutputData(totalAmount, keyset, mintOT);
    const blindedMessages = outputs.map((d) => d.blindedMessage);
    const v3 = this.mintsOntoV3(blindedMessages);

    // Sign each locked quote over ALL blinded messages (NUT-29).
    // Unlocked quotes get null. If no quotes are locked, omit signatures entirely.
    // Each locked quote's pubkey is matched against the provided privkey(s).
    const signatures: Array<string | null> = [];
    const legacySignatures: Array<string | null> = []; // Temporary legacy message support
    let hasSignatures = false;
    // V3: the batch is one transaction; every locked quote signs its own input
    // digest over the shared transcript covering all quote inputs (request order)
    // and all outputs (NUT-10).
    // Every quote in a v3 batch is a signing input, so an unlocked one has no witness and the
    // mint must reject the batch (NUT-29). Fail here, before any request is built.
    if (v3) {
      const unlocked = resolvedEntries.findIndex((e) => !e.quote.pubkey);
      this.failIf(
        unlocked >= 0,
        `prepareBatchMint: quote #${unlocked + 1} is unlocked; every quote minting onto a v3 keyset must be locked`,
      );
    }
    const v3BatchDigests = v3
      ? inputsForPayload({
          mintQuotes: resolvedEntries.map((e, i) => {
            // Face amount, as in prepareMint: the transcript never commits the draw,
            // so a slim bolt11 quote object cannot stand in for it.
            const quoteAmount = 'amount' in e.quote ? (e.quote.amount as AmountLike) : undefined;
            this.failIf(
              quoteAmount === undefined && method === 'bolt11',
              `prepareBatchMint: quote #${i + 1} lacks its amount; pass the full mint quote`,
            );
            return { quoteId: e.quote.quote, amount: quoteAmount ?? 0 };
          }),
          outputs: blindedMessages,
        }).quotes
      : undefined;
    for (const [i, entry] of resolvedEntries.entries()) {
      const quotePubkey = entry.quote.pubkey;
      if (quotePubkey && signingKeys.length > 0) {
        const signingKey = findSigningKey(quotePubkey, signingKeys);
        if (v3BatchDigests) {
          signatures.push(
            schnorrSignDigest(v3BatchDigests.get(entry.quote.quote)!.digest, signingKey),
          );
          legacySignatures.push(null);
        } else {
          signatures.push(signMintQuote(signingKey, entry.quote.quote, blindedMessages));
          legacySignatures.push(
            signMintQuoteLegacy(signingKey, entry.quote.quote, blindedMessages),
          );
        }
        hasSignatures = true;
      } else {
        if (privkey && !quotePubkey) {
          this._logger.warn(
            `prepareBatchMint: privkey supplied but quote #${i + 1} has no pubkey; treating as unlocked`,
          );
        }
        signatures.push(null);
        legacySignatures.push(null);
      }
    }

    return {
      method,
      quotes: resolvedEntries.map((e) => e.quote),
      amounts,
      outputData: outputs,
      ...(hasSignatures ? { signatures, legacySignatures } : {}),
    };
  }

  /**
   * Complete a prepared batch mint transaction.
   *
   * @remarks
   * Use with a `BatchMintPreview` returned by `prepareBatchMint()`.
   * @param batchPreview Preview returned by prepareBatchMint.
   * @returns Minted proofs.
   * @throws {@link StaleKeysetError} If the mint rejects the outputs' keyset.
   * @experimental only supported by CDK mint >= 0.16.0
   */
  async completeBatchMint(
    batchPreview: BatchMintPreview<Pick<MintQuoteBaseResponse, 'quote'>>,
  ): Promise<Proof[]> {
    const { method, quotes, amounts, outputData, signatures, legacySignatures } = batchPreview;
    const request: BatchMintRequest = {
      quotes: quotes.map((q) => q.quote),
      quote_amounts: amounts,
      outputs: outputData.map((d) => d.blindedMessage),
      ...(signatures ? { signatures } : {}),
    };
    // TODO: Remove legacy message support
    const { signatures: sigs } = await this.withStaleKeysetRepair(() =>
      this.withLegacyQuoteSigFallback(
        legacySignatures !== undefined,
        () => this.mint.mintBatch(method, request),
        () => this.mint.mintBatch(method, { ...request, signatures: legacySignatures! }),
      ),
    );
    this.failIf(
      sigs.length !== outputData.length,
      `Mint returned ${sigs.length} signatures, expected ${outputData.length}. The mint quote may already be marked issued; if the wallet is seeded, try restoring (NUT-09) to recover.`,
    );
    this.validateReturnedSignatures(sigs, outputData);

    // Unblind under the keyset each signature names, as custom outputs may pick their own.
    await this._ensureKeysetsForSignatures(sigs);
    this._logger.debug('BATCH MINT COMPLETED', {
      quotes: quotes.length,
      amounts: outputData.map((o) => o.blindedMessage.amount.toString()),
    });
    return outputData.map((d, i) => d.toProof(sigs[i], this.keysetForSignature(sigs[i].id)));
  }

  // -----------------------------------------------------------------
  // Section: Create Melt Quote
  // -----------------------------------------------------------------

  /**
   * Creates a melt quote for any payment method.
   *
   * @remarks
   * Generic method for requesting a melt quote. The payload is method-specific but must at minimum
   * include the fields required by the mint for the given method. An optional `normalize` callback
   * can be used to coerce method-specific response fields.
   *
   * For first-class methods, prefer the typed helpers: `createMeltQuoteBolt11()`,
   * `createMeltQuoteBolt12()`.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param payload The request body to POST. `unit` is always set to the wallet's unit.
   * @param options.normalize Optional callback to normalize method-specific response fields.
   * @returns The melt quote response.
   */
  async createMeltQuote<TRes extends MeltQuoteBaseResponse = MeltQuoteGenericResponse>(
    method: string,
    payload: Record<string, unknown>,
    options?: { normalize?: (raw: Record<string, unknown>) => TRes },
  ): Promise<TRes> {
    // Custom methods are fine, but NUT-05 requires the mint to advertise them
    this.requireSupport('melt', method);
    const body = { ...payload, unit: this._unit };
    const res = await this.mint.createMeltQuote<TRes>(method, body, {
      normalize: options?.normalize,
    });
    assertQuoteUnit(res, this.unit, this._logger);
    return res;
  }

  /**
   * Asserts a lightning melt quote does not charge more than the millisat request asks for.
   *
   * @remarks
   * Sat and msat quotes only; other units need a conversion policy. One-sided by design: a quote
   * may round a sub-sat request up to the next sat, and undercharging is the mint's loss. Pass
   * `null` when there is no millisat expectation to compare against.
   */
  private assertBolt11MeltQuoteAmount(
    res: MeltQuoteBolt11Response,
    expectedMsat: AmountLike | null,
  ): void {
    if ((this._unit !== 'sat' && this._unit !== 'msat') || expectedMsat === null) return;
    const msat = Amount.from(expectedMsat);
    const maxAmount = this._unit === 'sat' ? msat.ceilPercent(1, 1000) : msat;
    this.failIf(
      res.amount.greaterThan(maxAmount),
      'Melt quote amount exceeds the requested amount',
      {
        quoted: res.amount.toString(),
        requestedMsat: msat.toString(),
      },
    );
  }

  /**
   * Requests a melt quote from the mint. Response returns amount and fees for a given unit in order
   * to pay a Lightning invoice.
   *
   * @param invoice LN invoice that needs to get a fee estimate.
   * @param amountMsat Optional amount in millisatoshis to attach for amountless invoices, must not
   *   be provided for invoices that already encode an amount.
   * @returns The mint will create and return a melt quote for the invoice with an amount and fee
   *   reserve.
   */
  async createMeltQuoteBolt11(
    invoice: string,
    amountMsat?: AmountLike,
  ): Promise<MeltQuoteBolt11Response> {
    this.requireSupport('melt', 'bolt11');
    const normalizedAmountMsat =
      amountMsat !== undefined ? this.parseAmount(amountMsat, 'createMeltQuoteBolt11') : undefined;

    if (amountMsat !== undefined) {
      this.failIf(
        invoiceHasAmountInHRP(invoice),
        'amountMsat supplied but invoice already contains an amount. Leave amountMsat undefined for non-zero invoices.',
      );
    }

    const supportsAmountless = this._mintInfo?.supportsAmountless?.('bolt11', this._unit) ?? false;

    const meltQuotePayload: MeltQuoteBolt11Request = {
      unit: this._unit,
      request: invoice,

      ...(supportsAmountless && normalizedAmountMsat !== undefined
        ? {
            options: {
              amountless: {
                amount_msat: normalizedAmountMsat,
              },
            },
          }
        : {}),
    };
    const meltQuote = await this.mint.createMeltQuoteBolt11(meltQuotePayload);
    assertQuoteUnit(meltQuote, this.unit, this._logger);
    let expectedMsat: AmountLike | null = null;
    try {
      expectedMsat = bolt11AmountMsat(invoice);
    } catch {
      // Unreadable caller invoice: the mint validates it; nothing to compare against.
    }
    if (expectedMsat === null && normalizedAmountMsat !== undefined) {
      expectedMsat = normalizedAmountMsat;
    }
    this.assertBolt11MeltQuoteAmount(meltQuote, expectedMsat);
    return meltQuote;
  }

  /**
   * Requests a melt quote from the mint. Response returns amount and fees for a given unit in order
   * to pay a BOLT12 offer.
   *
   * @param offer BOLT12 offer that needs to get a fee estimate.
   * @param amountMsat Amount in millisatoshis for amount-less offers. If this is defined and the
   *   offer has an amount, they **MUST** be equal.
   * @returns The mint will create and return a melt quote for the offer with an amount and fee
   *   reserve.
   */
  async createMeltQuoteBolt12(
    offer: string,
    amountMsat?: AmountLike,
  ): Promise<MeltQuoteBolt12Response> {
    this.requireSupport('melt', 'bolt12');
    const normalizedAmountMsat =
      amountMsat !== undefined ? this.parseAmount(amountMsat, 'createMeltQuoteBolt12') : undefined;
    const meltQuote = await this.mint.createMeltQuoteBolt12({
      unit: this._unit,
      request: offer,
      options: normalizedAmountMsat
        ? {
            amountless: {
              amount_msat: normalizedAmountMsat,
            },
          }
        : undefined,
    });
    assertQuoteUnit(meltQuote, this.unit, this._logger);
    // The offer itself is opaque here, so only an explicit caller amount bounds the quote.
    this.assertBolt11MeltQuoteAmount(meltQuote, normalizedAmountMsat ?? null);
    return meltQuote;
  }

  /**
   * Requests an onchain melt quote from the mint.
   *
   * @param address Bitcoin address to send to.
   * @param amount Amount to melt.
   * @returns Melt quote with fee options.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async createMeltQuoteOnchain(
    address: string,
    amount: AmountLike,
  ): Promise<MeltQuoteOnchainResponse> {
    this.requireSupport('melt', 'onchain');
    const normalizedAmount = this.parseAmount(amount, 'createMeltQuoteOnchain');
    const quote = await this.mint.createMeltQuoteOnchain({
      unit: this._unit,
      request: address,
      amount: normalizedAmount,
    });
    assertQuoteUnit(quote, this.unit, this._logger);
    // Onchain amounts are already in the wallet unit, so the quote must match exactly.
    this.failIf(!quote.amount.equals(normalizedAmount), 'Melt quote amount does not match', {
      expected: normalizedAmount.toString(),
      quoted: quote.amount.toString(),
    });
    return quote;
  }

  /**
   * Requests a multi path melt quote from the mint.
   *
   * @remarks
   * Uses NUT-15 Partial multi-path payments for BOLT11.
   * @param invoice LN invoice that needs to get a fee estimate.
   * @param partialAmount The partial amount of the invoice's total to be paid by this instance.
   * @returns The mint will create and return a melt quote for the invoice with an amount and fee
   *   reserve.
   * @see https://github.com/cashubtc/nuts/blob/main/15.md
   */
  async createMultiPathMeltQuote(
    invoice: string,
    millisatPartialAmount: AmountLike,
  ): Promise<MeltQuoteBolt11Response> {
    const normalizedMillisatPartialAmount = this.parseAmount(
      millisatPartialAmount,
      'createMultiPathMeltQuote',
    );
    const { supported, params } = this.getMintInfo().isSupported(15);
    this.failIf(!supported, 'Mint does not support NUT-15');
    this.failIf(
      !params?.some((p) => p.method === 'bolt11' && p.unit === this._unit),
      `Mint does not support MPP for bolt11 and ${this._unit}`,
    );
    const meltQuotePayload: MeltQuoteBolt11Request = {
      unit: this._unit,
      request: invoice,
      options: { mpp: { amount: normalizedMillisatPartialAmount } },
    };
    const meltQuote = await this.mint.createMeltQuoteBolt11(meltQuotePayload);
    assertQuoteUnit(meltQuote, this.unit, this._logger);
    // A partial quote is bounded by the caller's own millisat share, not the invoice total.
    this.assertBolt11MeltQuoteAmount(meltQuote, normalizedMillisatPartialAmount);
    return meltQuote;
  }

  // -----------------------------------------------------------------
  // Section: Check Melt Quote
  // -----------------------------------------------------------------

  /**
   * Checks an existing melt quote for any payment method.
   *
   * @remarks
   * Generic method for checking a melt quote status. An optional `normalize` callback can be used
   * to coerce method-specific response fields.
   *
   * For first-class methods, prefer the typed helpers: `checkMeltQuoteBolt11()`,
   * `checkMeltQuoteBolt12()`.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param quote Quote ID or quote object (must have a `quote` field).
   * @param options.normalize Optional callback to normalize method-specific response fields.
   * @returns The melt quote response.
   */
  async checkMeltQuote<TRes extends MeltQuoteBaseResponse = MeltQuoteGenericResponse>(
    method: string,
    quote: string | Pick<TRes, 'quote'>,
    options?: { normalize?: (raw: Record<string, unknown>) => TRes },
  ): Promise<TRes> {
    const quoteId = typeof quote === 'string' ? quote : (quote as { quote: string }).quote;
    return this.mint.checkMeltQuote<TRes>(method, quoteId, {
      normalize: options?.normalize,
    });
  }

  /**
   * Returns an existing bolt11 melt quote from the mint.
   *
   * @param quote ID of the melt quote.
   * @returns The mint will return an existing melt quote.
   */
  async checkMeltQuoteBolt11(
    quote: string | MeltQuoteBolt11Response,
  ): Promise<MeltQuoteBolt11Response> {
    const quoteId = typeof quote === 'string' ? quote : quote.quote;
    const res = await this.mint.checkMeltQuoteBolt11(quoteId);
    // No caller-side expectation here, so check the quote against its own invoice.
    if (this._unit === 'sat' || this._unit === 'msat') {
      let expectedMsat: bigint | null = null;
      try {
        expectedMsat = bolt11AmountMsat(res.request);
      } catch {
        this.fail('Melt quote request is not a valid bolt11 invoice', { quote: res.quote });
      }
      this.assertBolt11MeltQuoteAmount(res, expectedMsat);
    }
    return res;
  }

  /**
   * Returns an existing bolt12 melt quote from the mint.
   *
   * @param quote ID of the melt quote.
   * @returns The mint will return an existing melt quote.
   */
  async checkMeltQuoteBolt12(quote: string): Promise<MeltQuoteBolt12Response> {
    return this.mint.checkMeltQuoteBolt12(quote);
  }

  /**
   * Returns an existing onchain melt quote from the mint.
   *
   * @param quote ID of the melt quote.
   * @returns The mint will return an existing melt quote.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async checkMeltQuoteOnchain(quote: string): Promise<MeltQuoteOnchainResponse> {
    return this.mint.checkMeltQuoteOnchain(quote);
  }

  // -----------------------------------------------------------------
  // Section: Melt Proofs
  // -----------------------------------------------------------------

  /**
   * Melts proofs for any payment method.
   *
   * @remarks
   * Generic convenience method that calls `prepareMelt(method, …)` followed by `completeMelt()`.
   *
   * Intended primarily for custom payment methods. For first-class methods, prefer
   * `meltProofsBolt11()` or `meltProofsBolt12()`, which keep the method-specific wallet
   * ergonomics.
   * @param method The payment method (e.g., 'bolt11', 'bolt12', 'bacs', 'swift').
   * @param meltQuote The melt quote object (must have at least `quote` and `amount` fields).
   * @param proofsToSend Proofs to melt.
   * @param config Optional parameters.
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns MeltProofsResponse with quote and change proofs.
   */
  async meltProofs<TQuote extends Pick<MeltQuoteBaseResponse, 'amount' | 'quote'>>(
    method: string,
    meltQuote: TQuote,
    proofsToSend: ProofLike[],
    config?: MeltProofsConfig,
    outputType?: OutputType,
  ): Promise<MeltProofsResponse<TQuote>> {
    const meltTxn = await this.prepareMelt(method, meltQuote, proofsToSend, config, outputType);
    return this.completeMelt<TQuote>(
      meltTxn,
      config?.privkey,
      config?.scriptPath?.length ? { scriptPath: config.scriptPath } : undefined,
    );
  }

  /**
   * Melt proofs for a bolt11 melt quote.
   *
   * @remarks
   * ProofsToSend must be at least amount+fee_reserve from the melt quote. This function does not
   * perform coin selection!.
   * @param meltQuote ID of the melt quote.
   * @param proofsToSend Proofs to melt.
   * @param config Optional parameters.
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns MeltProofsResponse with quote and change proofs.
   */
  async meltProofsBolt11(
    meltQuote: MeltQuoteBolt11Response,
    proofsToSend: ProofLike[],
    config?: MeltProofsConfig,
    outputType?: OutputType,
  ): Promise<MeltProofsResponse<MeltQuoteBolt11Response>> {
    this.requireSupport('melt', 'bolt11');
    const meltTxn = await this.prepareMelt('bolt11', meltQuote, proofsToSend, config, outputType);
    return this.completeMelt<MeltQuoteBolt11Response>(
      meltTxn,
      config?.privkey,
      config?.scriptPath?.length ? { scriptPath: config.scriptPath } : undefined,
    );
  }

  /**
   * Melt proofs for a bolt12 melt quote, returns change proofs using specified outputType.
   *
   * @remarks
   * ProofsToSend must be at least amount+fee_reserve from the melt quote. This function does not
   * perform coin selection!.
   * @param meltQuote ID of the melt quote.
   * @param proofsToSend Proofs to melt.
   * @param config Optional parameters.
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns MeltProofsResponse with quote and change proofs.
   */
  async meltProofsBolt12(
    meltQuote: MeltQuoteBolt12Response,
    proofsToSend: ProofLike[],
    config?: MeltProofsConfig,
    outputType?: OutputType,
  ): Promise<MeltProofsResponse<MeltQuoteBolt12Response>> {
    this.requireSupport('melt', 'bolt12');
    const meltTxn = await this.prepareMelt('bolt12', meltQuote, proofsToSend, config, outputType);
    return this.completeMelt<MeltQuoteBolt12Response>(
      meltTxn,
      config?.privkey,
      config?.scriptPath?.length ? { scriptPath: config.scriptPath } : undefined,
    );
  }

  /**
   * Melt proofs via an onchain Bitcoin transaction.
   *
   * @remarks
   * ProofsToSend must cover `quote.amount + selected fee + input fee`. Any additional amount is
   * offered as NUT-08 change. This function does not perform coin selection!
   *
   * Any `change` is only returned once the quote is `PAID` (mined and confirmed). Poll the quote
   * until broadcast, then unblind change with the returned `outputData` via
   * `wallet.createMeltChangeProofs()`.
   * @param meltQuote The onchain melt quote.
   * @param proofsToSend Proofs to melt.
   * @param feeIndex Selected `fee_index` value from `meltQuote.fee_options`.
   * @param config Optional parameters (e.g. privkey for P2PK proofs, keysetId).
   * @returns MeltProofsResponse with quote, any immediate change, and `outputData` for
   *   deferred-change reconstruction.
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  async meltProofsOnchain(
    meltQuote: MeltQuoteOnchainResponse,
    proofsToSend: ProofLike[],
    feeIndex: number,
    config?: MeltProofsConfig,
  ): Promise<MeltProofsResponse<MeltQuoteOnchainResponse>> {
    this.requireSupport('melt', 'onchain');
    assertQuoteUnit(meltQuote, this.unit, this._logger);
    // Validate fee_option selection
    const feeOption = meltQuote.fee_options.find((o) => o.fee_index === feeIndex);
    this.failIfNullish(feeOption, 'feeIndex must match an onchain melt quote fee option', {
      feeIndex,
      feeOptions: meltQuote.fee_options.map((o) => o.fee_index),
    });
    const normalizedProofs = normalizeProofAmounts(proofsToSend);

    // Rotation evidence check: repair the snapshot before the input fee lookup relies on
    // it. Inputs are priced from keyset metadata, so keys are not fetched. prepareMelt
    // checks again below, a no-op by then.
    await this._ensureOperableKeysets(
      normalizedProofs.map((p) => p.id),
      { implicit: true, fetchKeys: false },
    );

    // Ensure we have enough proofs
    const inputFee = this.getFeesForProofs(normalizedProofs);
    const sendAmount = sumProofs(normalizedProofs);
    const totalRequired = meltQuote.amount.add(feeOption.fee_reserve).add(inputFee);
    this.failIf(sendAmount.lessThan(totalRequired), 'Not enough proofs to cover amount + fee', {
      sendAmount: sendAmount.toString(),
      totalRequired: totalRequired.toString(),
      amount: meltQuote.amount.toString(),
      fee_reserve: feeOption.fee_reserve.toString(),
      inputFee: inputFee.toString(),
    });
    // Perform melt
    const meltTxn = await this.prepareMelt('onchain', meltQuote, normalizedProofs, config);
    const response = await this.completeMelt<MeltQuoteOnchainResponse>(meltTxn, config?.privkey, {
      extraPayload: { fee_index: feeIndex },
      ...(config?.scriptPath?.length && { scriptPath: config.scriptPath }),
    });
    return response;
  }

  /**
   * Prepare A Melt Transaction.
   *
   * @remarks
   * Allows you to preview fees for a melt, get concrete outputs for P2PK SIG_ALL melts, and do any
   * pre-melt tasks (such as marking proofs in-flight etc). Creates NUT-08 blanks (amount 0) for
   * melt change and returns a MeltPreview, which you can melt using completeMelt.
   * @param method Payment method of the quote.
   * @param meltQuote The melt quote for this method. A mint response is used as given. Anything
   *   short of one, such as `{ quote: string, amount: Amount }`, is read from the mint and merged
   *   over what you passed, so an `amount` you supply is replaced by the mint's and is not compared
   *   against it; pass the response from `createMeltQuote*` or `checkMeltQuote*` to melt the amount
   *   you hold.
   * @param proofsToSend Proofs to melt.
   * @param config Optional configuration (keysetId, privkey, etc.).
   * @param outputType Configuration for proof generation. Defaults to wallet.defaultOutputType().
   * @returns MeltPreview.
   * @throws If params are invalid, or the quote is not in the wallet's unit.
   * @see https://github.com/cashubtc/nuts/blob/main/08.md.
   */
  async prepareMelt<TQuote extends Pick<MeltQuoteBaseResponse, 'amount' | 'quote'>>(
    method: string,
    meltQuote: TQuote,
    proofsToSend: ProofLike[],
    config?: MeltProofsConfig,
    outputType?: OutputType,
  ): Promise<MeltPreview<TQuote>> {
    this.failIf(
      typeof meltQuote.quote !== 'string' || meltQuote.quote.length === 0,
      'prepareMelt: the quote needs its id',
    );
    let resolvedQuote: TQuote & Partial<MeltQuoteBaseResponse> = meltQuote;
    // As in prepareMint, fetch any missing fields required on a mint response (NUT-05).
    if (resolvedQuote.unit == null || resolvedQuote.state == null) {
      const fetched = await this.checkMeltQuote<MeltQuoteBaseResponse>(method, meltQuote.quote);
      resolvedQuote = { ...meltQuote, ...definedOnly(fetched) };
    }
    assertQuoteUnit(resolvedQuote, this.unit, this._logger);
    outputType = outputType ?? this.defaultOutputType(); // Fallback to policy
    const { keysetId, onCountersReserved, nut08Change = true, preimage } = config || {};

    // Rotation evidence check: repair the snapshot so the output binding is current.
    // bolt11/bolt12 melts never consult the input keyset (no keys, no fee metadata), so an
    // id the mint delisted but still honors must not block the withdrawal: proceed and let
    // the mint judge. Strict mode still refuses; so do non-keyset errors.
    try {
      await this._ensureOperableKeysets(
        proofsToSend.map((p) => p.id),
        { implicit: true, fetchKeys: false },
      );
    } catch (e) {
      if (this._strictCachedKeysets || !(e instanceof UnknownKeysetError)) {
        throw e;
      }
      this._logger.warn('Melt input keyset is not listed by the mint; proceeding anyway', {
        keyset: e.keysetId,
      });
    }

    // Plain getKeyset: melting needs no new outputs, so an inactive/legacy keyset must not
    // block withdrawal. A mint unwinding liabilities deactivates keysets but
    // keeps melt open; gate output creation below, not the melt itself.
    let keyset = this.getKeyset(keysetId); // specified or wallet keyset
    const normalizedProofs = normalizeProofAmounts(proofsToSend);
    const sendAmount = sumProofs(normalizedProofs);
    let outputData: OutputDataLike[] = [];

    // feeReserve is the overage above the invoice/offer amount.
    // In the common case where selected proofs = amount + fee_reserve,
    // this equals the quote’s fee_reserve. If you overshoot more,
    // the extra also becomes NUT-08 change, if melt method allows.
    this.failIf(
      sendAmount.lessThan(resolvedQuote.amount),
      'Not enough proofs to cover amount + fee reserve',
      {
        sendAmount: sendAmount.toString(),
        quoteAmount: resolvedQuote.amount.toString(),
      },
    );
    const feeReserve = sendAmount.subtract(resolvedQuote.amount);

    // Custom OT is definitive (no extra NUT-08 blanks)
    if (outputType.type === 'custom') {
      outputData = outputType.data;
    }

    // Create NUT-08 blanks for return of melt change (if supported)
    // Note: zero amount + zero denomination passes splitAmount validation
    else if (nut08Change && feeReserve.greaterThan(0)) {
      // Now we actually create outputs the mint must sign: enforce the output policy.
      this.failIf(
        !keyset.isActive,
        'Melt change keyset is inactive. Use an active keyset or set nut08Change: false to forfeit it',
        { keyset: keyset.id },
      );
      keyset = this.getOutputKeyset(keysetId);
      // NUT-08 blank outputs: ceil(log2(feeReserve)) blinded messages, at least one.
      // Computed on bigint so a u64-scale reserve cannot lose precision to a float.
      const count = Math.max(ceilLog2(feeReserve.toBigInt()), 1);
      const denominations: number[] = new Array<number>(count).fill(0);
      this._logger.debug('Creating NUT-08 blanks for fee reserve', {
        feeReserve: feeReserve,
        denominations,
      });

      let meltOT: OutputType = { ...outputType, denominations };
      // Assign counter atomically if OutputType is deterministic
      // and the counter is zero (auto-assign)
      const autoCounters = await this.addCountersToOutputTypes(keyset.id, meltOT);
      [meltOT] = autoCounters.outputTypes;
      if (autoCounters.used) {
        this.safeCallback(onCountersReserved, autoCounters.used, { op: 'meltProofs' });
      }
      this._logger.debug('melt counter', {
        counter: autoCounters.used,
        meltOT: stringifyOutputTypeForLog(meltOT),
      });
      // Generate the blank outputs (no fees as we are receiving change)
      // Remember, zero amount + zero denomination passes splitAmount validation
      outputData = this.createOutputData(0, keyset, meltOT);
    }

    // Create melt preview
    const meltPreview: MeltPreview<TQuote> = {
      method,
      inputs:
        preimage === undefined ? normalizedProofs : attachHTLCPreimage(normalizedProofs, preimage),
      outputData,
      quote: resolvedQuote,
    };

    return meltPreview;
  }

  /**
   * Completes a pending melt by calling the melt endpoint and constructing change proofs.
   *
   * @remarks
   * Use with a `MeltPreview` returned from `prepareMelt()`. This method lets you sign P2PK locked
   * proofs before melting. If the payment is pending or unpaid, the change array will be empty.
   * @param meltPreview The preview from prepareMelt().
   * @param privkey The private key(s) for signing.
   * @param options Optional override to request NUT-06 asynchronous melt or method-specific fields.
   * @returns Updated MeltProofsResponse.
   * @throws If melt fails or signatures don't match output count.
   * @throws {@link StaleKeysetError} If the mint rejects the outputs' keyset.
   * @throws {@link MeltChangeError} If the melt went through but its change could not be built.
   *   Carries the `outputData` and quote needed to recover the change later.
   */
  async completeMelt<TQuote extends Pick<MeltQuoteBaseResponse, 'quote'> = MeltQuoteBaseResponse>(
    meltPreview: MeltPreview<TQuote>,
    privkey?: string | string[],
    options?: CompleteMeltOptions,
  ): Promise<MeltProofsResponse<TQuote>> {
    const completeOptions: CompleteMeltOptions = options ?? {};

    this.assertUniqueOutputSecrets(meltPreview.outputData);

    // Extract vars from MeltPreview
    let inputs = meltPreview.inputs;
    const outputs = meltPreview.outputData.map((d) => d.blindedMessage);
    const quote = meltPreview.quote.quote;

    // Sign proofs if needed
    if (privkey) {
      inputs = this.signP2PKProofs(inputs, privkey, meltPreview.outputData, quote);
    }

    // Prepare proofs for mint
    inputs = this._prepareInputsForMint(inputs);

    // Construct melt payload. Extension fields must not clobber the prepared request.
    const extra = completeOptions.extraPayload;
    if (extra) {
      // Object.keys mirrors what the spread below copies (own enumerable keys).
      const owned = ['quote', 'inputs', 'outputs', 'prefer_async'];
      const reserved = Object.keys(extra).filter((k) => owned.includes(k));
      this.failIf(reserved.length > 0, 'extraPayload cannot override reserved melt fields', {
        reserved,
      });
    }
    const meltPayload: MeltRequest = {
      quote,
      inputs,
      outputs,
      ...(completeOptions.preferAsync ? { prefer_async: true } : {}),
      ...extra,
    };

    // Attach nutroot transaction witnesses (v3 keysets). The digest binds the melt output's
    // amount (quote amount plus the selected fee reserve), so a slim quote object cannot sign v3
    // inputs: fail fast rather than send them unsigned.
    const quoteAmount =
      'amount' in meltPreview.quote ? (meltPreview.quote.amount as AmountLike) : undefined;
    this.failIf(
      quoteAmount === undefined &&
        inputs.some((p) => isBlsKeyset(p.id) && isV3PointSecret(p.secret)),
      'melting v3 inputs needs the melt quote amount; pass the full quote object',
    );
    let receipts: SpendReceipt[] = [];
    if (quoteAmount !== undefined) {
      const feeIndex = typeof extra?.fee_index === 'number' ? extra.fee_index : undefined;
      receipts = await attachTransactionWitnesses(
        meltPayload,
        {
          quoteId: quote,
          amount: meltOutputAmount({ ...meltPreview.quote, amount: quoteAmount }, feeIndex),
        },
        collectSpendInfoKeys(meltPreview.inputs, privkey, this._logger),
        completeOptions.scriptPath?.length
          ? prepareScriptPathSpends(
              meltPreview.inputs,
              completeOptions.scriptPath,
              privkey === undefined ? [] : [privkey].flat(),
            )
          : undefined,
        this._nutrootState(),
      );
    }

    // Execute melt and validate result
    const meltResponse: MeltQuoteBaseResponse = await this.withStaleKeysetRepair(() =>
      this.mint.melt<TQuote>(meltPreview.method, meltPayload),
    );

    // Merge preview quote with response to protect against incomplete response.
    const mergedQuote = { ...meltPreview.quote, ...meltResponse };

    // Create any change Proofs. The spec is silent on which keyset settles change after a
    // rotation, so take the keyset each signature names. The inputs are spent by now, so a
    // failure here must hand back what recovery needs.
    const changeSigs = meltResponse.change ?? [];
    let change: Proof[];
    try {
      if (changeSigs.length > 0) {
        await this._ensureOperableKeysets(
          changeSigs.filter((s) => !s.amount.isZero()).map((s) => s.id),
          { implicit: true },
        );
      }
      change = this.createMeltChangeProofs(meltPreview.outputData, changeSigs);
    } catch (e) {
      throw new MeltChangeError(meltPreview.outputData, mergedQuote, { cause: e });
    }

    const changeAmounts = change.map((p) => p.amount.toString());
    if (completeOptions.preferAsync) {
      this._logger.debug('ASYNC MELT REQUESTED', { state: meltResponse.state, changeAmounts });
    } else {
      this._logger.debug('MELT COMPLETED', { changeAmounts });
    }

    // Retain outputData if no change was returned, so async/onchain can recover it later.
    return {
      quote: mergedQuote,
      change,
      outputData: change.length > 0 ? [] : meltPreview.outputData,
      ...(receipts.length > 0 && { receipts }),
    };
  }

  /**
   * Constructs melt change proofs from prepared OutputData and mint returned Change Signatures.
   *
   * @remarks
   * Synchronous by design and called internally by `completeMelt` (which ensures keys first);
   * direct callers deferring change construction (NUT-06 async melts, crash recovery) should `await
   * wallet.ensureOperableKeysets(ids)` first for the ids of the value-bearing signatures, which
   * also picks up a keyset rotated in while the melt was pending.
   * @param outputData Outputs from `prepareMelt()`, or deserialised persisted OutputData.
   * @param changeSigs The optional `change` signatures from the melt response or paid quote.
   * @returns Spendable change proofs (possibly empty).
   * @throws {@link CTSError} If signature count exceeds output count, a signature names a keyset
   *   that is not loaded or not in the wallet's unit, or signatures cannot be verified.
   * @see {@link OutputData.serialize} for the persist/restore lifecycle example.
   */
  createMeltChangeProofs(
    outputData: OutputDataLike[],
    changeSigs: SerializedBlindedSignature[],
  ): Proof[] {
    // Change may not use all outputs (shorter is ok)
    this.failIf(
      changeSigs.length > outputData.length,
      `Mint returned ${changeSigs.length} signatures, but only ${outputData.length} blanks were provided. Inputs may already be spent; if the wallet is seeded, try restoring (NUT-09) to recover.`,
    );
    // A paid quote from a WebSocket update or rehydrated from storage carries raw JSON amounts,
    // so normalise here rather than trust the type at this public boundary.
    const sigs = changeSigs.map((s) => (s ? { ...s, amount: Amount.from(s.amount) } : s));
    this.validateReturnedSignatures(sigs, outputData);
    // NUT-08 requires the mint to omit zero-value signatures; they carry no ecash, so drop them
    // rather than fail a settled melt, but make the conformance slip visible.
    const zeroSigs = sigs.filter((s) => s.amount.isZero()).length;
    if (zeroSigs > 0) {
      this._logger.warn(
        'Mint returned zero-value change signatures, which NUT-08 requires it to omit',
        {
          mintUrl: this.mint.mintUrl,
          count: zeroSigs,
        },
      );
    }
    const change: Proof[] = [];
    sigs.forEach((s, i) => {
      // NUT-08 pairs signatures to blanks by index
      if (s.amount.isZero()) return;
      change.push(outputData[i].toProof(s, this.keysetForSignature(s.id)));
    });
    return change;
  }

  /**
   * Loads the keysets a mint response was signed under.
   *
   * @remarks
   * Each signature names its own keyset, which need not be the one the preview or scan used.
   * Zero-value entries are dropped by the caller and need no keys.
   */
  private _ensureKeysetsForSignatures(signatures: SerializedBlindedSignature[]): Promise<void> {
    return this._ensureOperableKeysets(
      signatures.map((s) => (s?.amount.isZero() ? undefined : s?.id)),
      { implicit: true },
    );
  }

  /**
   * Keyset a signature was issued under, for unblinding.
   *
   * @remarks
   * Must already be loaded (see `_ensureOperableKeysets`); `getKeyset` also rejects a keyset from
   * another unit, which the signature cannot vouch for itself.
   */
  private keysetForSignature(id: string): Keyset {
    try {
      return this.getKeyset(id);
    } catch (e) {
      throw new CTSError(
        `Cannot reconstruct proof: keyset ${id} is not loaded in this wallet (may be inactive after rotation). If the wallet is seeded, try restoring (NUT-09) to recover.`,
        { cause: e },
      );
    }
  }

  // -----------------------------------------------------------------
  // Section: Proof States
  // -----------------------------------------------------------------

  /**
   * Get an array of the states of proofs from the mint (as an array of CheckStateEnum's)
   *
   * @param proofs Each proof must carry `id` and `secret`. The keyset id selects the hash-to-curve
   *   variant: v0/v1/v2 use secp256k1; v3 (`02…`) uses BLS12-381 G1.
   * @returns NUT-07 state for each proof, in same order.
   */
  async checkProofsStates(proofs: Array<Pick<ProofLike, 'secret' | 'id'>>): Promise<ProofState[]> {
    const Ys = proofs.map((p) => this.computeY(p.secret, p.id));
    // Shuffle the wire order to reduce linkability with B_'s (eg when coupled with a restore scan).
    // Indices travel with the request, so callers still get their original order back.
    const order = Ys.map((_, i) => i);
    for (let i = order.length - 1; i > 0; i--) {
      // Stryker disable next-line ArithmeticOperator: any in-range index yields a valid permutation; the shuffle need not be uniform
      const j = Math.floor(Math.random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    const batchSize = this.maxArrayLength;
    const slices: number[][] = [];
    for (let i = 0; i < order.length; i += batchSize) {
      slices.push(order.slice(i, i + batchSize));
    }
    const states = new Array<ProofState>(Ys.length);
    // Slices are independent, so run them through the bounded pool.
    await runPool(slices, BATCH_POOL_SIZE, async (slice) => {
      const { states: batchStates } = await this.mint.check({ Ys: slice.map((i) => Ys[i]) });
      // don't trust the mint's ordering: map results onto the request slice so order is
      // guaranteed and any omitted Y fails loudly instead of misaligning states
      const proofStatesByY: { [y: string]: ProofState } = {};
      batchStates.forEach((s) => {
        proofStatesByY[s.Y] = s;
      });
      slice.forEach((i) => {
        const state = proofStatesByY[Ys[i]];
        this.failIfNullish(state, 'Could not find state for proof with Y: ' + Ys[i]);
        states[i] = state;
      });
    });
    return states;
  }

  /**
   * Groups proofs by their corresponding state, preserving order within each group.
   *
   * @remarks
   * Returns the same type you supply, eg: pass `MyProof[]` in, get `MyProof[]` back.
   * @param proofs Accepts {@link ProofLike} so proofs from storage work without conversion. Only the
   *   `secret` field is used for the state check; amounts are passed through as-is.
   * @returns An object with arrays of proofs grouped by CheckStateEnum state.
   */
  async groupProofsByState<T extends ProofLike = Proof>(
    proofs: T[],
  ): Promise<{ unspent: T[]; pending: T[]; spent: T[] }> {
    const states: ProofState[] = await this.checkProofsStates(proofs);
    const result = {
      unspent: [] as T[],
      pending: [] as T[],
      spent: [] as T[],
    };
    for (let i = 0; i < states.length; i++) {
      const proof = proofs[i];
      switch (states[i].state) {
        case CheckStateEnum.UNSPENT:
          result.unspent.push(proof);
          break;
        case CheckStateEnum.PENDING:
          result.pending.push(proof);
          break;
        case CheckStateEnum.SPENT:
          result.spent.push(proof);
          break;
      }
    }
    return result;
  }
}

export { Wallet };

