import { attachHTLCPreimage, isBlsKeyset } from '../crypto';
import { Amount, type AmountLike } from '../model/Amount';
import { CTSError } from '../model/Errors';
import { type OutputDataLike, type OutputDataFactory } from '../model/OutputData';
import type { PaymentRequest } from '../model/PaymentRequest';
import {
  type MeltQuoteBolt11Response,
  type MeltQuoteBolt12Response,
  type MeltQuoteBaseResponse,
  type MeltQuoteOnchainResponse,
  type MintQuoteBolt12Response,
  type MintQuoteBolt11Response,
  type MintQuoteOnchainResponse,
} from '../model/types';
import type { ProofLike } from '../model/types/proof';
import type { Token } from '../model/types/token';

import { assertQuoteUnit } from './_internal';
import { nutrootToLockOptions, p2pkToLockOptions, type LockOptions } from './lock';
import { LockBuilder } from './LockBuilder';
import {
  type OutputType,
  type OutputConfig,
  type SendConfig,
  type ReceiveConfig,
  type MintProofsConfig,
  type OnCountersReserved,
  type MeltProofsConfig,
  type MeltProofsResponse,
  type ScriptPathPlan,
  type MeltPreview,
  type MintPreview,
} from './types';
import type { Wallet } from './Wallet';

export type MintMethod = 'bolt11' | 'bolt12' | 'onchain';

export type MintQuoteFor<M extends MintMethod> = M extends 'bolt11'
  ? string | MintQuoteBolt11Response
  : M extends 'bolt12'
    ? MintQuoteBolt12Response
    : MintQuoteOnchainResponse;

/**
 * Fluent operations builder for a Wallet instance.
 *
 * @remarks
 * Provides chainable builders for sending, receiving, and minting. Each builder is single use. If
 * you do not customise an output side, the wallet’s policy defaults apply.
 */
export class WalletOps {
  constructor(private wallet: Wallet) {}
  send(amount: AmountLike, proofs: ProofLike[]) {
    return new SendBuilder(this.wallet, amount, proofs);
  }
  /**
   * Builds a send that satisfies a NUT-18 payment request from this wallet's mint.
   *
   * @remarks
   * Enforces the payer-side MUSTs: strict mint list, unit rule, NUT-05 melt-method support
   * (resolved from this wallet's MintInfo), the applicable per-method fee (`mf`), the request's
   * `nut10` lock, and net-of-input-fees selection (`includeFees(true)`). Requires a loaded mint.
   * @param pr - The decoded payment request.
   * @param proofs - Proofs to select from.
   * @param amount - Payer-chosen amount for amountless requests; forbidden when the request sets
   *   `a`.
   * @returns A preconfigured {@link SendBuilder}; chain further options and `.run()`. The terms the
   *   request set are fixed: chaining cannot replace its lock or disable `includeFees`.
   * @throws If the wallet's mint, unit, or melt methods are unacceptable to the request, the
   *   request's lock cannot be honoured, or the request is invalid per NUT-18.
   */
  sendToRequest(pr: PaymentRequest, proofs: ProofLike[], amount?: AmountLike) {
    const wallet = this.wallet;
    if (pr.amount && amount !== undefined) {
      throw new CTSError('the request specifies its amount; omit the amount argument');
    }
    const base = pr.amount ?? (amount !== undefined ? Amount.from(amount) : undefined);
    if (!base) {
      throw new CTSError('amountless payment request: pass the chosen amount');
    }
    // NUT-18: u MUST be set if a or sm is set, since mf is denominated in the request unit.
    if (!pr.unit && (pr.amount !== undefined || pr.supportedMethods?.length)) {
      throw new CTSError(
        'invalid payment request: unit (u) is required when an amount (a) or supported methods (sm) are set',
      );
    }
    if (pr.unit && pr.unit !== wallet.unit) {
      throw new CTSError(`request unit '${pr.unit}' does not match wallet unit '${wallet.unit}'`);
    }
    // Strict mint list: the payer MUST only send proofs from listed mints (NUT-18).
    const listed = pr.includesMint(wallet.mint.mintUrl);
    if (pr.isMintListStrict && !listed) {
      throw new CTSError("this wallet's mint is not in the request's strict mint list");
    }
    // Melt-method support and per-method fee (sm/mf): the mint MUST be able to melt the request
    // unit via at least one listed method; the fee applies only from non-listed mints.
    let fee = Amount.zero();
    if (pr.supportedMethods?.length) {
      const meltMethods = wallet
        .getMintInfo()
        .supportedMethods('melt')
        .filter((m) => m.unit === wallet.unit)
        .map((m) => m.method);
      if (!pr.supportedMethods.some((m) => meltMethods.includes(m.method))) {
        throw new CTSError(`mint cannot melt ${wallet.unit} via any method the request accepts`);
      }
      fee = listed ? Amount.zero() : pr.feesFor(wallet.mint.mintUrl, meltMethods);
    }
    // A nut10 kind toP2PKOptions cannot express would otherwise send unlocked; fail instead.
    const lock = pr.toP2PKOptions();
    if (pr.nut10 && !lock) {
      throw new CTSError(`cannot honour the request's nut10 lock kind '${pr.nut10.kind}'`);
    }
    // Both options are one condition in two encodings (NUT-18): follow the one this wallet's
    // keyset takes, preferring nutroot on a v3 keyset.
    const nutroot = pr.toNutrootOptions();
    // Net of input fees (NUT-18): the payee must net the requested amount after swapping.
    const v3 = isBlsKeyset(wallet.keysetId);
    // Only a locked request negotiates an encoding; an unlocked one may use any keyset.
    const family = lock || nutroot ? (v3 ? 'v3' : 'legacy') : undefined;
    const builder = new SendBuilder(wallet, base.add(fee), proofs, family, true).includeFees(true);
    if (family) builder.keyset(wallet.keysetId);
    if (nutroot && v3) {
      return builder.asLocked(nutrootToLockOptions(nutroot));
    }
    // Nutroot alone asks for v3 outputs only (NUT-18): a payer that cannot
    // produce them must refuse, never lock to the key verbatim.
    if (nutroot && !lock) {
      throw new CTSError("the request's nutroot lock needs a v3 keyset this wallet does not use");
    }
    // nut10 alone is the pre-v3 encoding (NUT-18): a payee that published no nutroot option has
    // not said it can read v3 proofs, so a v3 payer refuses rather than translating the lock.
    if (lock && v3) {
      throw new CTSError(
        "the request's nut10 lock is pre-v3 only; this wallet's v3 keyset needs a nutroot option",
      );
    }
    return lock ? builder.asLocked(p2pkToLockOptions(lock)) : builder;
  }
  receive(token: Token | string | ProofLike[]) {
    return new ReceiveBuilder(this.wallet, token);
  }
  /**
   * @param quote Full `MintQuoteBolt11Response` or a bare quote ID string. Passing a string fetches
   *   the latest quote state from the mint (unit/expiry validation included). Pass the full object
   *   if you already have it to avoid the extra round-trip.
   */
  mintBolt11(amount: AmountLike, quote: MintQuoteFor<'bolt11'>) {
    return new MintBuilder<'bolt11'>(this.wallet, 'bolt11', amount, quote);
  }
  mintBolt12(amount: AmountLike, quote: MintQuoteFor<'bolt12'>) {
    return new MintBuilder<'bolt12'>(this.wallet, 'bolt12', amount, quote);
  }
  /**
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  mintOnchain(amount: AmountLike, quote: MintQuoteFor<'onchain'>) {
    return new MintBuilder<'onchain'>(this.wallet, 'onchain', amount, quote);
  }
  meltBolt11(quote: MeltQuoteBolt11Response, proofs: ProofLike[]) {
    return new MeltBuilder<MeltQuoteBolt11Response>(this.wallet, 'bolt11', quote, proofs);
  }
  meltBolt12(quote: MeltQuoteBolt12Response, proofs: ProofLike[]) {
    return new MeltBuilder<MeltQuoteBolt12Response>(this.wallet, 'bolt12', quote, proofs);
  }
  /**
   * @experimental Onchain support follows NUT-30 semantics and may change.
   */
  meltOnchain(quote: MeltQuoteOnchainResponse, proofs: ProofLike[]) {
    return new MeltOnchainBuilder(this.wallet, quote, proofs);
  }
}

/**
 * Builder for composing a send or swap.
 *
 * @remarks
 * If you only customise the send side, keep is omitted so the wallet may still attempt an offline
 * exact match selection where possible.
 * @example
 *
 *     const { keep, send } = await wallet.ops
 *       .send(5, proofs)
 *       .asDeterministic() // counter 0 means auto reserve via CounterSource
 *       .keepAsRandom()
 *       .includeFees(true) // sender pays receiver’s future spend fee
 *       .run();
 */
export class SendBuilder {
  private sendOT?: OutputType;
  private keepOT?: OutputType;
  private config: SendConfig = {};
  private offlineExact?: { requireDleq: boolean };
  private offlineClose?: { requireDleq: boolean };
  private amount: Amount;

  /**
   * @param lockFamily Set by `sendToRequest`: the keyset family the request was negotiated for
   *   (NUT-18). `keyset()` then refuses an id from the other family.
   * @param fromRequest Set by `sendToRequest`: the request's own terms (its lock, and selection net
   *   of input fees) are then fixed, and chaining cannot replace them.
   */
  constructor(
    private wallet: Wallet,
    amount: AmountLike,
    private proofs: ProofLike[],
    private lockFamily?: 'v3' | 'legacy',
    private fromRequest = false,
  ) {
    this.amount = Amount.from(amount);
  }

  /**
   * Guards a send output the payment request itself asked for (NUT-18).
   */
  private assertSendOutputMutable(): void {
    if (this.fromRequest && this.sendOT) {
      throw new CTSError(
        'the payment request mandates this send output; it cannot be replaced by chaining',
      );
    }
  }

  /**
   * Use random blinding for the sent outputs.
   *
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asRandom(denoms?: AmountLike[]) {
    this.assertSendOutputMutable();
    this.sendOT = { type: 'random', denominations: denoms };
    return this;
  }

  /**
   * Use deterministic outputs for the sent proofs.
   *
   * @param counter Starting counter. Zero means auto reserve using the wallet’s CounterSource.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asDeterministic(counter = 0, denoms?: AmountLike[]) {
    this.assertSendOutputMutable();
    this.sendOT = { type: 'deterministic', counter, denominations: denoms };
    return this;
  }

  /**
   * Lock the sent proofs to spending conditions; the wallet encodes them for the active keyset.
   *
   * @param lock Semantic {@link LockOptions}, or a {@link LockBuilder} to take them from.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asLocked(lock: LockOptions | LockBuilder, denoms?: AmountLike[]) {
    this.assertSendOutputMutable();
    const options = lock instanceof LockBuilder ? lock.toOptions() : lock;
    this.sendOT = { type: 'lock', options, denominations: denoms };
    return this;
  }

  /**
   * Use a factory to generate OutputData for the sent proofs.
   *
   * @param factory OutputDataFactory used to produce blinded messages.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asFactory(factory: OutputDataFactory, denoms?: AmountLike[]) {
    this.assertSendOutputMutable();
    this.sendOT = { type: 'factory', factory, denominations: denoms };
    return this;
  }

  /**
   * Provide pre created OutputData for the sent proofs.
   *
   * @param data Fully formed OutputData. Their amounts must sum to the send amount, otherwise the
   *   wallet will throw.
   */
  asCustom(data: OutputDataLike[]) {
    this.assertSendOutputMutable();
    this.sendOT = { type: 'custom', data };
    return this;
  }

  /**
   * Use random blinding for change outputs.
   *
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  keepAsRandom(denoms?: AmountLike[]) {
    this.keepOT = { type: 'random', denominations: denoms };
    return this;
  }

  /**
   * Use deterministic outputs for change.
   *
   * @param counter Starting counter. Zero means auto reserve using the wallet’s CounterSource.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  keepAsDeterministic(counter = 0, denoms?: AmountLike[]) {
    this.keepOT = { type: 'deterministic', counter, denominations: denoms };
    return this;
  }

  /**
   * Lock the change to spending conditions; the wallet encodes them for the active keyset.
   *
   * @param lock Semantic {@link LockOptions}, or a {@link LockBuilder} to take them from.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  keepAsLocked(lock: LockOptions | LockBuilder, denoms?: AmountLike[]) {
    const options = lock instanceof LockBuilder ? lock.toOptions() : lock;
    this.keepOT = { type: 'lock', options, denominations: denoms };
    return this;
  }

  /**
   * Use a factory to generate OutputData for change.
   *
   * @param factory OutputDataFactory used to produce blinded messages.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  keepAsFactory(factory: OutputDataFactory, denoms?: AmountLike[]) {
    this.keepOT = { type: 'factory', factory, denominations: denoms };
    return this;
  }

  /**
   * Provide pre created OutputData for change.
   *
   * @param data Fully formed OutputData for the keep (change) amount.
   */
  keepAsCustom(data: OutputDataLike[]) {
    this.keepOT = { type: 'custom', data };
    return this;
  }

  /**
   * Make the sender cover the receiver’s future spend fee.
   *
   * @param on When true, include fees in the sent amount. Default true if called.
   */
  includeFees(on = true) {
    // A payment request is settled net of input fees (NUT-18), so the payee nets the amount asked.
    if (this.fromRequest && !on) {
      throw new CTSError(
        'a payment request is sent net of input fees; includeFees cannot be disabled',
      );
    }
    this.config.includeFees = on;
    return this;
  }

  /**
   * Use a specific keyset for the operation.
   *
   * @param id Keyset id to use for mint keys and fee lookup.
   */
  keyset(id: string) {
    // The lock encoding was negotiated for one family (NUT-18); the other would re-encode it.
    if (this.lockFamily && (isBlsKeyset(id) ? 'v3' : 'legacy') !== this.lockFamily) {
      throw new CTSError(
        `keyset ${id} is not in the family this payment request was negotiated for`,
      );
    }
    this.config.keysetId = id;
    return this;
  }

  /**
   * Private key(s) used to sign P2PK locked proofs.
   *
   * @param k Single key or array of multisig keys.
   */
  privkey(k: string | string[]) {
    this.config.privkey = k;
    return this;
  }

  /**
   * Script-path spend plans for v3 locked inputs (NUT-10).
   */
  scriptPath(plans: ScriptPathPlan[]) {
    this.config.scriptPath = plans;
    return this;
  }

  /**
   * NUT-14: preimage for HTLC inputs, placed on their witness before signing.
   *
   * @param preimage 64 hex characters.
   */
  preimage(preimage: string) {
    this.config.preimage = preimage;
    return this;
  }

  /**
   * Provide existing proofs to help optimise denomination selection.
   *
   * @remarks
   * Has no effect if denominations (custom split) was specified.
   * @param p Proofs currently held by the wallet, used to hit denomination targets.
   */
  proofsWeHave(p: Array<Pick<ProofLike, 'amount'>>) {
    this.config.proofsWeHave = p;
    return this;
  }

  /**
   * Receive a callback once counters are atomically reserved for deterministic outputs.
   *
   * @param cb Called with OperationCounters when counters are reserved.
   */
  onCountersReserved(cb: OnCountersReserved) {
    this.config.onCountersReserved = cb;
    return this;
  }

  /**
   * Force a pure offline, exact match selection. No mint calls are made. If an exact match cannot
   * be found, this throws.
   *
   * @param requireDleq Only consider proofs with a DLEQ when true.
   */
  offlineExactOnly(requireDleq = false) {
    this.offlineExact = { requireDleq };
    return this;
  }

  /**
   * Force a pure offline selection that allows a close match, overspend permitted per wallet RGLI.
   * No mint calls are made. Returns the best offline subset found, or throws if funds are
   * insufficient.
   *
   * @param requireDleq Only consider proofs with a DLEQ when true.
   */
  offlineCloseMatch(requireDleq = false) {
    this.offlineClose = { requireDleq };
    return this;
  }

  /**
   * Prepare the swap to send.
   *
   * @remarks
   * Call `wallet.completeSwap(SwapPreview)` to complete the send.
   * @returns A SwapPreview containing inputs, outputs, amount, fee and unselectedProofs.
   * @throws If an offline mode is set: an offline selection has no swap to complete.
   */
  async prepare() {
    // An offline selection reuses existing proofs and never reaches the mint, so there is no
    // preview to hand to completeSwap.
    if (this.offlineExact || this.offlineClose) {
      throw new CTSError(
        'Offline selection has nothing to prepare; call run() instead, or drop the offline mode for an online swap.',
      );
    }

    // Construct an OutputConfig using default send if no customizations
    const outputConfig: OutputConfig = {
      send: this.sendOT ?? this.wallet.defaultOutputType(),
      ...(this.keepOT ? { keep: this.keepOT } : {}),
    };
    return this.wallet.prepareSwapToSend(this.amount, this.proofs, this.config, outputConfig);
  }

  /**
   * Execute the send.
   *
   * @returns The split result with kept and sent proofs.
   */
  async run() {
    // If an offline mode is requested, forbid custom OutputTypes,
    // because offline uses existing proofs and cannot honour new outputs.
    if ((this.offlineExact || this.offlineClose) && (this.sendOT || this.keepOT)) {
      throw new CTSError(
        'Offline selection cannot be combined with custom output types. Remove send/keep output configuration, or use an online swap.',
      );
    }

    if ((this.offlineExact || this.offlineClose) && this.config.scriptPath?.length) {
      throw new CTSError(
        'Offline selection cannot execute a script-path spend; use an online swap.',
      );
    }

    // Strict offline, exact match only
    if (this.offlineExact) {
      // Stamp and sign if needed
      if (this.config.preimage !== undefined) {
        this.proofs = attachHTLCPreimage(this.proofs, this.config.preimage);
      }
      if (this.config.privkey) {
        this.proofs = this.wallet.signP2PKProofs(this.proofs, this.config.privkey);
      }
      return this.wallet.sendOffline(this.amount, this.proofs, {
        includeFees: this.config.includeFees,
        exactMatch: true,
        requireDleq: this.offlineExact.requireDleq,
      });
    }

    // Offline close match, may overshoot
    if (this.offlineClose) {
      // Stamp and sign if needed
      if (this.config.preimage !== undefined) {
        this.proofs = attachHTLCPreimage(this.proofs, this.config.preimage);
      }
      if (this.config.privkey) {
        this.proofs = this.wallet.signP2PKProofs(this.proofs, this.config.privkey);
      }
      return this.wallet.sendOffline(this.amount, this.proofs, {
        includeFees: this.config.includeFees,
        exactMatch: false,
        requireDleq: this.offlineClose.requireDleq,
      });
    }

    // Construct an OutputConfig using default send if no customizations
    const outputConfig: OutputConfig = {
      send: this.sendOT ?? this.wallet.defaultOutputType(),
      ...(this.keepOT ? { keep: this.keepOT } : {}),
    };
    return this.wallet.send(this.amount, this.proofs, this.config, outputConfig);
  }
}

