/**
 * Builder for minting proofs from a quote.
 *
 * @remarks
 * Bolt12 requires privkey by default. The compiler will throw an error if bolt12 and privkey() is
 * omitted: MintBuilder<"bolt12", false>' is not assignable...
 *
 * Use this builder for the typed, first-class mint methods. For arbitrary or future mint methods,
 * use the generic `wallet.prepareMint(method, …)` / `wallet.completeMint()` flow.
 * @example
 *
 *     const proofs = await wallet.ops
 *       .mintBolt11(100, quote)
 *       .asDeterministic() // counter 0 auto reserves
 *       .onCountersReserved((info) => console.log(info))
 *       .privkey('sk')
 *       .run();
 */
export class MintBuilder<
  M extends MintMethod,
  HasPrivKey extends boolean = M extends 'bolt12' | 'onchain' ? false : true,
> {
  private outputType?: OutputType;
  private config: MintProofsConfig = {};
  private amount: Amount;

  // phantom field to satisfy linter (erased at emit)
  private readonly _hasPrivkey!: HasPrivKey;

  constructor(
    private wallet: Wallet,
    private method: M,
    amount: AmountLike,
    private quote: MintQuoteFor<M>,
  ) {
    this.amount = Amount.from(amount);
    void this._hasPrivkey; // intentionally unused (phantom field)
  }

  /**
   * Use random blinding for the minted proofs.
   *
   * @remarks
   * If denoms specified, proofsWeHave() will have no effect.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asRandom(denoms?: AmountLike[]) {
    this.outputType = { type: 'random', denominations: denoms };
    return this;
  }

  /**
   * Use deterministic outputs for the minted proofs.
   *
   * @remarks
   * If denoms specified, proofsWeHave() will have no effect.
   * @param counter Starting counter. Zero means auto reserve using the wallet’s CounterSource.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asDeterministic(counter = 0, denoms?: AmountLike[]) {
    this.outputType = { type: 'deterministic', counter, denominations: denoms };
    return this;
  }

  /**
   * Lock the minted proofs to spending conditions; the wallet encodes them for the active keyset.
   *
   * @remarks
   * If `denoms` is specified, `proofsWeHave()` has no effect.
   * @param lock Semantic {@link LockOptions}, or a {@link LockBuilder} to take them from.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asLocked(lock: LockOptions | LockBuilder, denoms?: AmountLike[]) {
    const options = lock instanceof LockBuilder ? lock.toOptions() : lock;
    this.outputType = { type: 'lock', options, denominations: denoms };
    return this;
  }

  /**
   * Use a factory to generate OutputData for minted proofs.
   *
   * @remarks
   * If denoms specified, proofsWeHave() will have no effect.
   * @param factory OutputDataFactory used to produce blinded messages.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asFactory(factory: OutputDataFactory, denoms?: AmountLike[]) {
    this.outputType = { type: 'factory', factory, denominations: denoms };
    return this;
  }

  /**
   * Provide pre created OutputData for minted proofs.
   *
   * @param data Fully formed OutputData for the final amount.
   */
  asCustom(data: OutputDataLike[]) {
    this.outputType = { type: 'custom', data };
    return this;
  }

  /**
   * Use a specific keyset for the operation.
   *
   * @param id Keyset id to use for mint keys and fee lookup.
   */
  keyset(id: string) {
    this.config.keysetId = id;
    return this;
  }

  /**
   * Private key to sign locked mint quotes.
   *
   * @param k Private key for locked quotes.
   */
  privkey(k: string): MintBuilder<M, true> {
    // For bolt11 - privkey is sent in the config
    // For bolt12 - privkey is sent positionally in run()
    this.config.privkey = k;
    return this as MintBuilder<M, true>;
  }

  /**
   * Sign a locked mint quote through a callback that holds the key, eg a NIP-07 extension.
   *
   * @param fn See {@link MintProofsConfig.sign}; ignored when `.privkey()` is also set.
   */
  sign(fn: NonNullable<MintProofsConfig['sign']>): MintBuilder<M, true> {
    this.config.sign = fn;
    return this as MintBuilder<M, true>;
  }

  /**
   * Provide existing proofs to help optimise denomination selection.
   *
   * @remarks
   * Has no effect if denominations (custom split) was specified.
   * @param p Proofs currently held by the wallet, used to hit denomination targets.
   */
  proofsWeHave(p: Array<Pick<ProofLike, 'amount'>>) {
    this.config.proofsWeHave = p;
    return this;
  }

  /**
   * Receive a callback once counters are atomically reserved for deterministic outputs.
   *
   * @param cb Called with OperationCounters when counters are reserved.
   */
  onCountersReserved(cb: OnCountersReserved) {
    this.config.onCountersReserved = cb;
    return this;
  }

  /**
   * Prepare the mint.
   *
   * @remarks
   * Call `wallet.completeMint(MintPreview)` to complete the mint. This method can only be called
   * for bolt12 quotes when `.privkey()` is set.
   * @returns A MintPreview containing the quote, output data and signature needed to complete the
   *   mint.
   */
  async prepare(
    this: MintBuilder<M, true>,
  ): Promise<
    M extends 'bolt11'
      ? MintPreview<MintQuoteBolt11Response>
      : M extends 'bolt12'
        ? MintPreview<MintQuoteBolt12Response>
        : MintPreview<MintQuoteOnchainResponse>
  > {
    type ReturnType = M extends 'bolt11'
      ? MintPreview<MintQuoteBolt11Response>
      : M extends 'bolt12'
        ? MintPreview<MintQuoteBolt12Response>
        : MintPreview<MintQuoteOnchainResponse>;

    // BOLT 11
    if (this.method === 'bolt11') {
      const raw = this.quote as string | MintQuoteBolt11Response;
      const quote = typeof raw === 'string' ? await this.wallet.checkMintQuoteBolt11(raw) : raw;
      assertQuoteUnit(quote, this.wallet.unit, this.wallet.logger);
      return this.wallet.prepareMint(
        this.method,
        this.amount,
        quote,
        this.config,
        this.outputType,
      ) as Promise<ReturnType>;
    }

    // BOLT 12
    if (this.method === 'bolt12') {
      const bolt12 = this.quote as MintQuoteBolt12Response;
      assertQuoteUnit(bolt12, this.wallet.unit, this.wallet.logger);
      if (!this.config.privkey) {
        throw new CTSError('privkey is required for BOLT12 mint quotes');
      }
      return this.wallet.prepareMint(
        this.method,
        this.amount,
        bolt12,
        this.config,
        this.outputType,
      ) as Promise<ReturnType>;
    }

    // Onchain
    const onchain = this.quote as MintQuoteOnchainResponse;
    assertQuoteUnit(onchain, this.wallet.unit, this.wallet.logger);
    if (!this.config.privkey) {
      throw new CTSError('privkey is required for onchain mint quotes');
    }
    return this.wallet.prepareMint(
      this.method,
      this.amount,
      onchain,
      this.config,
      this.outputType,
    ) as Promise<ReturnType>;
  }

  /**
   * Execute minting against the quote.
   *
   * @remarks
   * This is equivalent to `const preview = await prepare(); await wallet.completeMint(preview)`.
   * This method can only be called for bolt12 quotes when `.privkey()` is set. Builders are single
   * use: run a fresh one after a `StaleKeysetError` with `repaired` true.
   * @returns The newly minted proofs.
   */
  async run(this: MintBuilder<M, true>) {
    const preview = await this.prepare();
    return this.wallet.completeMint(preview);
  }
}

/**
 * Builder for melting proofs to pay a Lightning invoice or BOLT12 offer.
 *
 * @remarks
 * Uses the generic prepareMelt / completeMelt flow under the hood, so it works for any NUT-05 style
 * melt quote, not just BOLT11 / BOLT12.
 * @example
 *
 * ```typescript
 * // Basic BOLT11 melt
 * await wallet.ops.meltBolt11(quote, proofs).run();
 *
 * // BOLT12 melt with deterministic change and NUT-08 blanks callback
 * await wallet.ops
 *   .meltBolt12(quote12, proofs)
 *   .asDeterministic() // counter 0 auto reserves
 *   .onCountersReserved((info) => console.log('Reserved', info))
 *   .run();
 * ```
 */
export class MeltBuilder<
  TQuote extends Pick<MeltQuoteBaseResponse, 'amount' | 'quote'> = MeltQuoteBolt11Response,
> {
  private outputType?: OutputType;
  private config: MeltProofsConfig = {};

  constructor(
    private wallet: Wallet,
    private method: string,
    private quote: TQuote,
    private proofs: ProofLike[],
  ) {}

  /**
   * Use random blinding for change outputs.
   *
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asRandom(denoms?: AmountLike[]) {
    this.outputType = { type: 'random', denominations: denoms };
    return this;
  }

  /**
   * Use deterministic outputs for change.
   *
   * @param counter Starting counter. Zero means auto reserve using the wallet’s CounterSource.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asDeterministic(counter = 0, denoms?: AmountLike[]) {
    this.outputType = { type: 'deterministic', counter, denominations: denoms };
    return this;
  }

  /**
   * Lock the change to spending conditions; the wallet encodes them for the active keyset.
   *
   * @param lock Semantic {@link LockOptions}, or a {@link LockBuilder} to take them from.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asLocked(lock: LockOptions | LockBuilder, denoms?: AmountLike[]) {
    const options = lock instanceof LockBuilder ? lock.toOptions() : lock;
    this.outputType = { type: 'lock', options, denominations: denoms };
    return this;
  }

  /**
   * Use a factory to generate OutputData for change.
   *
   * @param factory Factory used to produce blinded messages.
   * @param denoms Optional custom split. Can be partial if you only need SOME specific amounts.
   */
  asFactory(factory: OutputDataFactory, denoms?: AmountLike[]) {
    this.outputType = { type: 'factory', factory, denominations: denoms };
    return this;
  }

  /**
   * Provide pre-created OutputData for change.
   *
   * @param data Fully formed OutputData for the change amount.
   */
  asCustom(data: OutputDataLike[]) {
    this.outputType = { type: 'custom', data };
    return this;
  }

  /**
   * Use a specific keyset for the melt operation.
   *
   * @param id Keyset id to use for mint keys and fee lookup.
   */
  keyset(id: string) {
    this.config.keysetId = id;
    return this;
  }

  /**
   * Private key(s) used to sign P2PK locked proofs.
   *
   * @param k Single key or array of multisig keys.
   */
  privkey(k: string | string[]) {
    this.config.privkey = k;
    return this;
  }

  /**
   * Script-path spend plans for v3 locked inputs (NUT-10).
   */
  scriptPath(plans: ScriptPathPlan[]) {
    this.config.scriptPath = plans;
    return this;
  }

  /**
   * NUT-14: preimage for HTLC inputs, placed on their witness before signing.
   *
   * @param preimage 64 hex characters.
   */
  preimage(preimage: string) {
    this.config.preimage = preimage;
    return this;
  }

  /**
   * Receive a callback once counters are atomically reserved for deterministic outputs.
   *
   * @param cb Called with OperationCounters when counters are reserved.
   */
  onCountersReserved(cb: OnCountersReserved) {
    this.config.onCountersReserved = cb;
    return this;
  }

  /**
   * Prepare the melt.
   *
   * @remarks
   * Call `wallet.completeMelt(MeltPreview)` to complete the melt.
   * @returns A MeltPreview containing inputs, outputs, amount, and fee.
   */
  async prepare(): Promise<MeltPreview<TQuote>> {
    return await this.wallet.prepareMelt<TQuote>(
      this.method,
      this.quote,
      this.proofs,
      this.config,
      this.outputType,
    );
  }

  /**
   * Execute the melt against the quote.
   *
   * @remarks
   * Builders are single use: run a fresh one after a `StaleKeysetError` with `repaired` true.
   * @returns The melt result: `{ quote, change, outputData }`.
   */
  async run(): Promise<MeltProofsResponse<TQuote>> {
    // Step 1, preview and allocate NUT-08 blanks
    const preview = await this.wallet.prepareMelt<TQuote>(
      this.method,
      this.quote,
      this.proofs,
      this.config,
      this.outputType,
    );

    // Step 2, sign if needed and complete the melt
    return this.wallet.completeMelt(preview, this.config.privkey, {
      ...(this.config.scriptPath && { scriptPath: this.config.scriptPath }),
    });
  }
}

/**
 * Builder for melting proofs via an onchain Bitcoin transaction.
 *
 * @remarks
 * Any overage above the selected quote amount and fee option is offered as NUT-08 change.
 * @example
 *
 * ```typescript
 * // Basic onchain melt (1 fee option)
 * const result = await wallet.ops.meltOnchain(quote, proofs).privkey('sk').run();
 *
 * // with custom keyset ID and selected fee option
 * await wallet.ops
 *   .meltOnchain(quote, proofs)
 *   .keyset('01abc...')
 *   .privkey('sk')
 *   .feeIndex(0)
 *   .run();
 * ```
 *
 * @experimental Onchain support follows NUT-30 semantics and may change.
 */
export class MeltOnchainBuilder {
  private config: MeltProofsConfig = {};
  private selectedFeeIndex?: number;

  constructor(
    private wallet: Wallet,
    private quote: MeltQuoteOnchainResponse,
    private proofs: ProofLike[],
  ) {}

  /**
   * Use a specific keyset for the melt operation.
   *
   * @param id Keyset id to use for mint keys and fee lookup.
   */
  keyset(id: string) {
    this.config.keysetId = id;
    return this;
  }

  /**
   * Private key(s) used to sign P2PK locked proofs.
   *
   * @param k Single key or array of multisig keys.
   */
  privkey(k: string | string[]) {
    this.config.privkey = k;
    return this;
  }

  /**
   * Script-path spend plans for v3 locked inputs (NUT-10).
   */
  scriptPath(plans: ScriptPathPlan[]) {
    this.config.scriptPath = plans;
    return this;
  }

  /**
   * NUT-14: preimage for HTLC inputs, placed on their witness before signing.
   *
   * @param preimage 64 hex characters.
   */
  preimage(preimage: string) {
    this.config.preimage = preimage;
    return this;
  }

  /**
   * Select a fee option by its `fee_index`.
   *
   * @param index `fee_index` value from the quote's fee_options.
   */
  feeIndex(index: number) {
    this.selectedFeeIndex = index;
    return this;
  }

  /**
   * Execute the onchain melt against the quote.
   *
   * @returns The melt result: `{ quote, change, outputData }`. Use `outputData` with the polled
   *   quote's `change` to unblind deferred change after broadcast.
   */
  async run(): Promise<MeltProofsResponse<MeltQuoteOnchainResponse>> {
    // Ensure fee_option is selected if there is only one
    if (this.selectedFeeIndex === undefined && this.quote.fee_options.length === 1) {
      this.selectedFeeIndex = this.quote.fee_options[0].fee_index;
    }

    if (this.selectedFeeIndex === undefined) {
      throw new CTSError(
        'feeIndex is required when an onchain melt quote has multiple fee options',
      );
    }

    return this.wallet.meltProofsOnchain(
      this.quote,
      this.proofs,
      this.selectedFeeIndex,
      this.config,
    );
  }
}

