import { schnorr, secp256k1 } from '@noble/curves/secp256k1.js';
import { sha256 } from '@noble/hashes/sha2.js';
import { hexToBytes, bytesToHex, randomBytes, utf8ToBytes } from '@noble/hashes/utils.js';
import { afterEach, describe, expect, test, vi } from 'vitest';

import { Amount, type OutputDataLike } from '../../src';
import {
  createP2PKsecret,
  signP2PKProof,
  signP2PKProofs,
  parseP2PKSecret,
  getP2PKExpectedWitnessPubkeys,
  getP2PKSigFlag,
  getP2PKWitnessSignatures,
  type Secret,
  isP2PKSpendAuthorised,
  getPubKeyFromPrivKey,
  createRandomSecretKey,
  hasP2PKSignedProof,
  schnorrSignMessage,
  computeMessageDigest,
  schnorrVerifyDigest,
  schnorrSignDigest,
  schnorrVerifyMessage,
  deriveP2BKBlindedPubkeys,
  buildP2PKSigAllMessageV0,
  assertSigAllInputs,
  createSecret,
  dedupeP2PKPubkeys,
  isHTLCSpendAuthorised,
  isP2PKSigAll,
  maybeDeriveP2BKPrivateKeys,
  normalizeHashlock,
  normalizeP2PKOptions,
  parseWitnessData,
  verifyP2PKSpendingConditions,
} from '../../src/crypto';
import { ConsoleLogger, type Logger, NULL_LOGGER } from '../../src/logger';
import { type Proof, type P2PKWitness } from '../../src/model/types';

const PRIVKEY = schnorr.utils.randomSecretKey();
const PUBKEY = bytesToHex(getPubKeyFromPrivKey(PRIVKEY));

afterEach(() => {
  vi.restoreAllMocks();
});

describe('test create p2pk secret', () => {
  test('create from key', async () => {
    const secret = createP2PKsecret(PUBKEY);
    const decodedSecret = parseP2PKSecret(secret);
    expect(decodedSecret[0]).toBe('P2PK');
    // console.log(JSON.stringify(decodedSecret))
    expect(Object.keys(decodedSecret[1]).includes('nonce')).toBe(true);
    expect(Object.keys(decodedSecret[1]).includes('data')).toBe(true);
    const decodedSecret2 = parseP2PKSecret(secret);
    expect(decodedSecret2[0]).toBe('P2PK');
  });
  test('sign and verify proof', async () => {
    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}"}]`;
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };
    const signedProof = signP2PKProof(proof, bytesToHex(PRIVKEY));
    const verify = isP2PKSpendAuthorised(signedProof);
    expect(verify).toBe(true);
  });

  test('rejects an oversized serialized secret before parsing it', () => {
    const padding = 'a'.repeat(2048);
    const oversized = `["P2PK",{"nonce":"a","data":"${PUBKEY}","tags":[["padding","${padding}"]]}]`;
    const parseSpy = vi.spyOn(JSON, 'parse');
    try {
      expect(() => parseP2PKSecret(oversized)).toThrow(/Secret too long/);
      expect(parseSpy).not.toHaveBeenCalled();
    } finally {
      parseSpy.mockRestore();
    }
  });

  test('rejects an oversized serialized witness before parsing it', () => {
    const oversized = `{"padding":"${'a'.repeat(65_536)}","signatures":[]}`;
    const parseSpy = vi.spyOn(JSON, 'parse');
    try {
      expect(() => getP2PKWitnessSignatures(oversized)).toThrow(/Witness too long/);
      expect(parseSpy).not.toHaveBeenCalled();
    } finally {
      parseSpy.mockRestore();
    }
  });

  test('SIG_INPUTS signatures are always checked against the proof secret', () => {
    const secret = createP2PKsecret(PUBKEY);
    const other = computeMessageDigest('some other message');
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret,
      witness: { signatures: [schnorrSignDigest(other, bytesToHex(PRIVKEY))] },
    };
    // A signature over anything but the secret never authorises a SIG_INPUTS spend,
    // whatever message the caller passes along.
    expect(isP2PKSpendAuthorised(proof)).toBe(false);
    expect(isP2PKSpendAuthorised(proof, NULL_LOGGER, other)).toBe(false);
    expect(hasP2PKSignedProof(PUBKEY, proof, other)).toBe(false);
    // ...and a signature over the secret still verifies when a message is passed.
    const signed = signP2PKProof({ ...proof, witness: undefined }, bytesToHex(PRIVKEY));
    expect(isP2PKSpendAuthorised(signed, NULL_LOGGER, other)).toBe(true);
    expect(hasP2PKSignedProof(PUBKEY, signed, other)).toBe(true);
  });

  test('non-array witness signatures verify as false, not a thrown TypeError', () => {
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: `["P2PK",{"nonce":"a","data":"${PUBKEY}"}]`,
      witness: JSON.stringify({ signatures: 'not-an-array' }),
    };
    expect(isP2PKSpendAuthorised(proof)).toBe(false);
  });

  test('a JSON-primitive witness (eg "null") verifies as false, not a thrown TypeError', () => {
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: `["P2PK",{"nonce":"a","data":"${PUBKEY}"}]`,
      witness: 'null', // JSON.parse("null") === null, not an object
    };
    expect(isP2PKSpendAuthorised(proof)).toBe(false);
    expect(parseWitnessData('null')).toBeUndefined();
    expect(parseWitnessData('1')).toBeUndefined();
  });

  test('accepts a SIG_ALL-sized witness (multiple signatures per signer)', () => {
    // SIG_ALL signs each message variant per signer, so a legitimate witness carries well over
    // the 11-slot lock size; the cap must not reject it.
    const sigAll = JSON.stringify({
      signatures: Array.from({ length: 33 }, () => 'ab'.repeat(64)),
    });
    expect(getP2PKWitnessSignatures(sigAll)).toHaveLength(33);
  });

  test('a witness with too many signatures is rejected with a CTSError', () => {
    const many = JSON.stringify({ signatures: Array.from({ length: 65 }, () => 'ab'.repeat(64)) });
    expect(() => getP2PKWitnessSignatures(many)).toThrow(/Too many witness signatures/);
  });

  test('signing a witness already at the cap throws instead of producing an over-cap proof', () => {
    // A hostile proof arrives locked to our key with the maximum witness signatures already set.
    // Appending our signature would make the verify path reject the proof we just produced.
    const witness = JSON.stringify({
      signatures: Array.from({ length: 64 }, () => 'ab'.repeat(64)),
    });
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: `["P2PK",{"nonce":"a","data":"${PUBKEY}"}]`,
      witness,
    };
    expect(() => signP2PKProof(proof, bytesToHex(PRIVKEY))).toThrow(/signature limit/);
  });

  test('a secret with too many pubkeys is rejected before per-key work', () => {
    const keys = Array.from({ length: 65 }, () => PUBKEY);
    const tag = keys.map((k) => `"${k}"`).join(',');
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: `["P2PK",{"nonce":"a","data":"${PUBKEY}","tags":[["pubkeys",${tag}]]}]`,
    };
    // As a string the secret trips the length cap first; a pre-parsed Secret reaches the key cap.
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/Secret too long/);
    const secret: Secret = ['P2PK', { nonce: 'a', data: PUBKEY, tags: [['pubkeys', ...keys]] }];
    expect(() => getP2PKExpectedWitnessPubkeys(secret)).toThrow(/Too many pubkeys/);
  });

  test('a secret with too many refund pubkeys is rejected before per-key work', () => {
    const keys = Array.from({ length: 65 }, () => PUBKEY);
    const tag = keys.map((k) => `"${k}"`).join(',');
    const proof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      // A normal main key passes its cap; the oversized refund tag trips the refund cap.
      secret: `["P2PK",{"nonce":"a","data":"${PUBKEY}","tags":[["refund",${tag}]]}]`,
    };
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/Secret too long/);
    const secret: Secret = [
      'P2PK',
      {
        nonce: 'a',
        data: PUBKEY,
        tags: [
          ['locktime', '1'],
          ['refund', ...keys],
        ],
      },
    ];
    expect(() => getP2PKExpectedWitnessPubkeys(secret)).toThrow(/Too many refund pubkeys/);
  });

  test('sign and verify proofs', async () => {
    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}"}]`;
    const proof1: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };

    const proof2: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };

    const proofs = [proof1, proof2];

    const signedProofs = signP2PKProofs(proofs, bytesToHex(PRIVKEY));
    const verify0 = isP2PKSpendAuthorised(signedProofs[0]);
    const verify1 = isP2PKSpendAuthorised(signedProofs[1]);
    expect(verify0).toBe(true);
    expect(verify1).toBe(true);
  });

  test('leaves v3 point secrets untouched and unlogged', async () => {
    // Mixed inputs reach this pass whenever a melt or send carries a privkey.
    // The v3 proof signs the transaction elsewhere, so it must not be parsed here.
    const warn = vi.fn();
    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}"}]`;
    const p2pkProof: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };
    const v3Proof: Proof = {
      amount: Amount.from(1),
      C: 'b7a4881059133fd91a8753600d9a5e524c65d6224f6fe2d5aef9e59f1507fdad90b3b4d48ee46da5c8dfaa0b88e28b69',
      id: '02ce4c47836fd0e64f37a08254777b7fd0dedb95fc1ddd0acadf5600674c743c5d',
      secret: '02' + 'ab'.repeat(32),
    };

    const signedProofs = signP2PKProofs([p2pkProof, v3Proof], bytesToHex(PRIVKEY), {
      warn,
    } as never);

    expect(isP2PKSpendAuthorised(signedProofs[0])).toBe(true);
    expect(signedProofs[1]).toBe(v3Proof); // untouched, no witness added
    expect(warn).not.toHaveBeenCalled();
  });

  test('sign and verify proofs, different keys', async () => {
    const PRIVKEY2 = schnorr.utils.randomSecretKey();
    const PUBKEY2 = bytesToHex(getPubKeyFromPrivKey(PRIVKEY2));

    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}"}]`;
    const secretStr2 = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY2}"}]`;
    const proof1: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };

    const proof2: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr2,
    };

    const proofs = [proof1, proof2];

    const signedProofs = signP2PKProofs(proofs, [bytesToHex(PRIVKEY), bytesToHex(PRIVKEY2)]);
    const verify0 = isP2PKSpendAuthorised(signedProofs[0]);
    const verify1 = isP2PKSpendAuthorised(signedProofs[1]);
    expect(verify0).toBe(true);
    expect(verify1).toBe(true);
  });

  test('sign and verify proofs, multiple keys', async () => {
    const PRIVKEY2 = schnorr.utils.randomSecretKey();
    const PUBKEY2 = bytesToHex(getPubKeyFromPrivKey(PRIVKEY2));

    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}","tags":[["n_sigs","2"],["pubkeys","${PUBKEY2}"]]}]`;
    const secretStr2 = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}","tags":[["n_sigs","1"],["pubkeys","${PUBKEY2}"]]}]`;
    const proof1: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };

    const proof2: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr2,
    };

    const proofs = [proof1, proof2];
    expect(hasP2PKSignedProof(PUBKEY, proof1)).toBe(false);
    const signedProofs = signP2PKProofs(proofs, [bytesToHex(PRIVKEY), bytesToHex(PRIVKEY2)]);
    const verify0 = isP2PKSpendAuthorised(signedProofs[0]);
    const verify1 = isP2PKSpendAuthorised(signedProofs[1]);
    expect(verify0).toBe(true);
    expect(verify1).toBe(true);
  });

  test('sign and verify proofs, insufficient and incorrect keys', async () => {
    const PRIVKEY2 = schnorr.utils.randomSecretKey();
    const PUBKEY2 = bytesToHex(getPubKeyFromPrivKey(PRIVKEY2));

    const secretStr = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY}","tags":[["n_sigs","2"],["pubkeys","${PUBKEY2}"]]}]`;
    const secretStr2 = `["P2PK",{"nonce":"76f5bf3e36273bf1a09006ef32d4551c07a34e218c2fc84958425ad00abdfe06","data":"${PUBKEY2}","tags":[["n_sigs","1"]]}]`;
    const proof1: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr,
    };

    const proof2: Proof = {
      amount: Amount.from(1),
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      id: '00000000000',
      secret: secretStr2,
    };

    const proofs = [proof1, proof2];

    const signedProofs = signP2PKProofs(proofs, [bytesToHex(PRIVKEY)]);
    const verify0 = isP2PKSpendAuthorised(signedProofs[0]);
