// helpers to make valid on-curve keys, deterministically derived per label char
const _X: Record<string, string> = {};
const _xonly = (ch: string) =>
  (_X[ch] ??= bytesToHex(schnorr.getPublicKey(new Uint8Array(32).fill(ch.charCodeAt(0)))));
const _comp = (ch: string, prefix: '02' | '03' = '02') => `${prefix}${_xonly(ch)}`;

describe('normalizeP2PKOptions', () => {
  const pk = _comp('a', '02');
  const pk2 = _comp('c', '02');
  const refundPk = _comp('b', '02');
  const hashlock = 'ec4916dd28fc4c10d78e287ca5d9cc51ee1ae73cbfde08c6b37324cbfaac8bc5';

  test('throws on an unknown lock kind', () => {
    expect(() => normalizeP2PKOptions({ kind: 'FOO', data: pk } as any)).toThrow(
      /unknown lock kind: FOO/i,
    );
  });

  test('P2PK: data pubkey counts as a slot, so 11 keys fill 11 slots and 12 overflow (NUT-28)', () => {
    // NUT-28 allows up to 11 slots in [data, ...pubkeys, ...refund] (i_byte 0x00..0x0A).
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'a', 'b', 'c'].map((c) => _comp(c));
    const [data, ...rest] = keys; // rest has 11 distinct pubkeys
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data, pubkeys: rest.slice(0, 10) }),
    ).not.toThrow(); // data + 10 pubkeys = 11 slots
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data, pubkeys: rest })).toThrow(
      /maximum allowed is 11/,
    ); // data + 11 pubkeys = 12 slots
  });

  test('HTLC: hashlock fills slot 0, so only 10 keys fit before overflowing 11 slots (NUT-28)', () => {
    // For HTLC the data slot is a hash, not a key, so signing keys max out one lower than P2PK.
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'a', 'b'].map((c) => _comp(c));
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, pubkeys: keys.slice(0, 10) }),
    ).not.toThrow(); // hash + 10 pubkeys = 11 slots
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, pubkeys: keys })).toThrow(
      /maximum allowed is 11/,
    ); // hash + 11 pubkeys = 12 slots
  });

  test('throws when P2PK data is missing or empty', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: '' })).toThrow(
      /P2PK requires a pubkey in data/i,
    );
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: undefined } as any)).toThrow(
      /P2PK requires a pubkey in data/i,
    );
  });

  test('throws when HTLC data is empty', () => {
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: '' })).toThrow(
      /HTLC requires a hashlock in data/i,
    );
  });

  test('throws when HTLC hashlock is not 64-char hex', () => {
    // A malformed hashlock yields an unspendable lock (no preimage can hash to it),
    // so reject it at construction rather than minting a dead token.
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'invalid_hashlock' })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
    // Right length, non-hex char.
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'z'.repeat(64) })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
    // Valid hex, wrong length (32 bytes expected).
    expect(() => normalizeP2PKOptions({ kind: 'HTLC', data: 'ab'.repeat(20) })).toThrow(
      /HTLC hashlock must be a 64-character hex string/i,
    );
  });

  test('lowercases the HTLC hashlock so it matches createHTLCHash output', () => {
    // verifyHTLCHash compares against lowercase bytesToHex(sha256(preimage)); an
    // uppercase hashlock passes the hex check but must be canonicalised to match.
    expect(normalizeP2PKOptions({ kind: 'HTLC', data: hashlock.toUpperCase() })).toEqual({
      kind: 'HTLC',
      data: hashlock,
    });
  });

  test('splits a P2PK lock into canonical data slot + pubkeys tag', () => {
    // `data` is the NUT-10 data slot; extra keys ride the `pubkeys` tag. Empty key
    // sets are dropped from the canonical result.
    expect(
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, pubkeys: [pk2], requiredSignatures: 2 }),
    ).toEqual({
      kind: 'P2PK',
      data: pk,
      pubkeys: [pk2],
      requiredSignatures: 2,
    });
  });

  test('allows a hashlock-only HTLC with no pubkeys (NUT-14)', () => {
    // An HTLC carries its lock in the hashlock, so a pubkeys list is optional.
    expect(normalizeP2PKOptions({ kind: 'HTLC', data: hashlock })).toEqual({
      kind: 'HTLC',
      data: hashlock,
    });
  });

  test('rejects an explicit n_sigs on a hashlock-only HTLC (no signers)', () => {
    // Skipping the *default* n_sigs is fine, but an explicit threshold with zero
    // signers is impossible and must fail loudly, not silently weaken the lock.
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, requiredSignatures: 2 }),
    ).toThrow(/exceeds available pubkeys/i);
    expect(() =>
      normalizeP2PKOptions({ kind: 'HTLC', data: hashlock, requiredSignatures: 0 }),
    ).toThrow(/positive integer/i);
  });

  test('throws when a pubkeys-tag entry is an empty string', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, pubkeys: [''] })).toThrow(
      /invalid pubkey/i,
    );
  });

  test('throws when refundKeys contains an empty string', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, locktime: 9999, refundKeys: [refundPk, ''] }),
    ).toThrow(/invalid pubkey/i);
  });

  test('throws when requiredSignatures is not an integer', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, requiredSignatures: 1.5 })).toThrow(
      /requiredSignatures \(n_sigs\) must be a positive integer/i,
    );
  });

  test('throws when requiredSignatures is less than 1', () => {
    expect(() => normalizeP2PKOptions({ kind: 'P2PK', data: pk, requiredSignatures: 0 })).toThrow(
      /requiredSignatures \(n_sigs\) must be a positive integer/i,
    );
  });

  test('throws when requiredRefundSignatures is set without refundKeys', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, locktime: 9999, requiredRefundSignatures: 1 }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) requires refund keys/i);
  });

  test('throws when requiredRefundSignatures is not an integer', () => {
    expect(() =>
      normalizeP2PKOptions({
        kind: 'P2PK',
        data: pk,
        locktime: 9999,
        refundKeys: [refundPk],
        requiredRefundSignatures: 1.5,
      }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) must be a positive integer/i);
  });

  test('throws when requiredRefundSignatures is less than 1', () => {
    expect(() =>
      normalizeP2PKOptions({
        kind: 'P2PK',
        data: pk,
        locktime: 9999,
        refundKeys: [refundPk],
        requiredRefundSignatures: 0,
      }),
    ).toThrow(/requiredRefundSignatures \(n_sigs_refund\) must be a positive integer/i);
  });

  test('throws when sigFlag is not a valid SigFlag value', () => {
    expect(() =>
      normalizeP2PKOptions({ kind: 'P2PK', data: pk, sigFlag: 'FOOBAR' as any }),
    ).toThrow(/invalid sigflag/i);
  });
});

describe('parseP2PKSecret — duplicate tag rejection', () => {
  const makePk = () => bytesToHex(getPubKeyFromPrivKey(schnorr.utils.randomSecretKey()));
  const pk1 = makePk();
  const pk2 = makePk();

  function makeSecret(tags: string[][]): string {
    return JSON.stringify(['P2PK', { nonce: bytesToHex(randomBytes(32)), data: pk1, tags }]);
  }

  test('rejects duplicate locktime tags', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['locktime', '1'],
      ['refund', pk2],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "locktime"/);
  });

  test('rejects duplicate sigflag tags', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['sigflag', 'SIG_ALL'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "sigflag"/);
  });

  test('rejects duplicate n_sigs tags', () => {
    const secret = makeSecret([
      ['pubkeys', pk2],
      ['n_sigs', '1'],
      ['n_sigs', '2'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "n_sigs"/);
  });

  test('rejects duplicate n_sigs_refund tags', () => {
    const secret = makeSecret([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '1'],
      ['n_sigs_refund', '2'],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "n_sigs_refund"/);
  });

  test('rejects duplicate pubkeys tags', () => {
    const secret = makeSecret([
      ['pubkeys', pk2],
      ['pubkeys', makePk()],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "pubkeys"/);
  });

  test('rejects duplicate refund tags', () => {
    const secret = makeSecret([
      ['locktime', '1'],
      ['refund', pk2],
      ['refund', makePk()],
    ]);
    expect(() => parseP2PKSecret(secret)).toThrow(/Duplicate P2PK tag "refund"/);
  });

  test('allows unknown/custom tags (forward compatibility)', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['custom_tag', 'value1'],
      ['custom_tag', 'value2'], // duplicate custom tag is fine
    ]);
    expect(() => parseP2PKSecret(secret)).not.toThrow();
  });

  test('allows valid secret with one of each tag', () => {
    const secret = makeSecret([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['pubkeys', pk2],
      ['n_sigs', '2'],
      ['refund', makePk()],
      ['n_sigs_refund', '1'],
    ]);
    expect(() => parseP2PKSecret(secret)).not.toThrow();
  });

  test('applies to HTLC secrets too', () => {
    const htlcSecret = JSON.stringify([
      'HTLC',
      {
        nonce: bytesToHex(randomBytes(32)),
        data: bytesToHex(randomBytes(32)), // hash
        tags: [
          ['locktime', '99999999999'],
          ['locktime', '1'],
          ['pubkeys', pk1],
          ['refund', pk2],
        ],
      },
    ]);
    expect(() => parseP2PKSecret(htlcSecret)).toThrow(/Duplicate P2PK tag "locktime"/);
  });
});

describe('verifyP2PKSpendingConditions — semantic validation', () => {
  const makePk = () => bytesToHex(getPubKeyFromPrivKey(schnorr.utils.randomSecretKey()));
  const pk1 = makePk();
  const pk2 = makePk();
  const pk3 = makePk();

  function makeProof(tags: string[][], data?: string): Proof {
    return {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: JSON.stringify([
        'P2PK',
        { nonce: bytesToHex(randomBytes(32)), data: data ?? pk1, tags },
      ]),
    };
  }

  test('rejects n_sigs=0', () => {
    const proof = makeProof([
      ['sigflag', 'SIG_INPUTS'],
      ['n_sigs', '0'],
      ['pubkeys', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) must be a positive integer/,
    );
  });

  test('rejects negative n_sigs', () => {
    const proof = makeProof([
      ['n_sigs', '-1'],
      ['pubkeys', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) must be a positive integer/,
    );
  });

  test('rejects a malformed n_sigs instead of applying the default threshold', () => {
    // A present but unparseable threshold must not read as an absent tag.
    for (const bad of ['2oops', '2 ', '9007199254740992']) {
      const proof = makeProof(
        [
          ['n_sigs', bad],
          ['pubkeys', pk2],
        ],
        PUBKEY,
      );
      const signedProof = signP2PKProof(proof, bytesToHex(PRIVKEY));
      expect(() => verifyP2PKSpendingConditions(signedProof)).toThrow(
        /tag "n_sigs": must be an integer/,
      );
    }
  });

  test('rejects a malformed n_sigs_refund instead of ignoring it', () => {
    const badRefund = makeProof([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '1.0'],
    ]);
    expect(() => verifyP2PKSpendingConditions(badRefund)).toThrow(
      /tag "n_sigs_refund": must be an integer/,
    );
  });

  test('a malformed locktime reads as a permanent lock, not a rejection', () => {
    // NUT-11: a locktime that is not a valid unix time makes the lock permanent, so the refund
    // path never opens and only the main key can sign; the mint makes the final call.
    const proof = makeProof([
      ['locktime', 'never'],
      ['refund', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).not.toThrow(/must be an integer/);
    expect(getP2PKExpectedWitnessPubkeys(proof.secret)).toEqual([pk1]);
  });

  test('rejects a scalar tag carrying more than one value', () => {
    const nSigs = makeProof([
      ['n_sigs', '1', '2'],
      ['pubkeys', pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(nSigs)).toThrow(
      /tag "n_sigs": must carry a single value/,
    );
    const sigflag = makeProof([['sigflag', 'SIG_INPUTS', 'SIG_ALL']]);
    expect(() => parseP2PKSecret(sigflag.secret)).toThrow(
      /tag "sigflag": must carry a single value/,
    );
  });

  test('rejects impossible n_sigs threshold (n_sigs > available keys)', () => {
    // 1 key in data, none in pubkeys, but n_sigs=3
    const proof = makeProof([['n_sigs', '3']]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs\) \(3\) exceeds available pubkeys \(1\)/,
    );
  });

  test('rejects n_sigs_refund=0', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '0'],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs_refund\) must be a positive integer/,
    );
  });

  test('rejects impossible n_sigs_refund threshold', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2],
      ['n_sigs_refund', '3'],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(
      /n_sigs_refund\) \(3\) exceeds available refund keys \(1\)/,
    );
  });

  test('rejects refund without locktime', () => {
    const proof = makeProof([['refund', pk2]]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/refund keys require a locktime/);
  });

  test('rejects data pubkey duplicated in pubkeys tag', () => {
    const proof = makeProof([
      ['pubkeys', pk1], // same as data field
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate main pubkeys/i);
  });

  test('rejects an x-only key in the pubkeys tag as non-compliant', () => {
    const xOnly = pk1.slice(2);
    const proof = makeProof([
      ['pubkeys', xOnly], // NUT-11 requires 33-byte compressed keys
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/prepend '02'/);
  });

  test('rejects the data pubkey repeated in the pubkeys tag with flipped parity', () => {
    const proof = makeProof([
      ['pubkeys', `03${pk1.slice(2)}`], // same key, different parity byte
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate main pubkeys/i);
  });

  test('rejects duplicate refund pubkeys', () => {
    const proof = makeProof([
      ['locktime', '1'],
      ['refund', pk2, pk2],
    ]);
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/duplicate refund pubkeys/i);
  });

  test('returns result for well-formed unsigned proof', () => {
    const proof = makeProof([
      ['sigflag', 'SIG_INPUTS'],
      ['locktime', '99999999999'],
      ['pubkeys', pk2],
      ['n_sigs', '2'],
      ['refund', pk3],
    ]);
    const result = verifyP2PKSpendingConditions(proof);
    expect(result.success).toBe(false);
    expect(result.path).toBe('FAILED');
    expect(result.main.requiredSigners).toBe(2);
    expect(result.main.pubkeys).toHaveLength(2);
    expect(result.main.receivedSigners).toEqual([]);
  });

  test('returns success for signed proof meeting threshold', () => {
    const privKey = schnorr.utils.randomSecretKey();
    const pubKey = bytesToHex(getPubKeyFromPrivKey(privKey));
    const proof = makeProof([], pubKey);
    const signedProof = signP2PKProof(proof, bytesToHex(privKey));
    const result = verifyP2PKSpendingConditions(signedProof);
    expect(result.success).toBe(true);
    expect(result.path).toBe('MAIN');
  });

  test('duplicate locktime attack blocked at parse level before reaching semantics', () => {
    // This is the exact attack from duplicate-tag-locktime.md
    const attackerPk = makePk();
    const victimPk = makePk();
    const proof: Proof = {
      amount: Amount.from(1),
      id: '00000000000',
      C: '034268c0bd30b945adf578aca2dc0d1e26ef089869aaf9a08ba3a6da40fda1d8be',
      secret: JSON.stringify([
        'P2PK',
        {
          nonce: bytesToHex(randomBytes(32)),
          data: victimPk,
          tags: [
            ['sigflag', 'SIG_INPUTS'],
            ['locktime', '99999999999'], // wallet would show this
            ['locktime', '1'], // mint (CDK HashMap) would see this
            ['refund', attackerPk],
          ],
        },
      ]),
    };
    // parseP2PKSecret catches this before any signature logic
    expect(() => verifyP2PKSpendingConditions(proof)).toThrow(/Duplicate P2PK tag "locktime"/);
  });
});

