import { bytesToHex, hexToBytes } from '@noble/hashes/utils.js';
import { HttpResponse, http } from 'msw';
import { test, describe, expect, vi } from 'vitest';

import {
  Wallet,
  type Proof,
  type MeltQuoteBolt11Response,
  type MeltQuoteBaseResponse,
  type MeltQuoteOnchainResponse,
  type MintQuoteBaseResponse,
  type MintQuoteBolt12Response,
  type MintQuoteOnchainResponse,
  MeltQuoteState,
  MintQuoteState,
  type MintQuoteBolt11Response,
  type MintQuoteSignRequest,
  Amount,
  type AmountLike,
  Mint,
  OutputData,
  MintOperationError,
  type RequestFn,
} from '../../src';
import { schnorrSignDigest, schnorrVerifyDigest, verifyMintQuoteSignature } from '../../src/crypto';
import { getPubKeyFromPrivKey } from '../../src/crypto/curve_secp';
import { verifyMintQuoteSignatureLegacy } from '../../src/crypto/NUT20';
import { inputsForPayload } from '../../src/crypto/transcript';
import request from '../../src/transport';
import { sumProofs } from '../../src/utils';
import {
  DUMMY_TEST_KEYS,
  DUMMY_TEST_KEYSET,
  NUT02_V3_VECTOR1_KEYS,
  NUT02_V3_VECTOR1_KEYSET,
} from '../consts';

import { useTestServer, mint, mintUrl, unit, logger, mintInfoResp, invoice } from './_setup';

const server = useTestServer();
const mintInfoRespWithNut12 = {
  ...mintInfoResp,
  nuts: { ...mintInfoResp.nuts, 12: { supported: true } },
};
// NUT-04/05 require mints to advertise every supported method, custom ones included
const mintInfoRespWithBacs = {
  ...mintInfoResp,
  nuts: {
    ...mintInfoResp.nuts,
    4: {
      methods: [
        ...mintInfoResp.nuts['4'].methods,
        { method: 'bacs', unit: 'sat' },
        { method: 'swift', unit: 'sat' },
      ],
      disabled: false,
    },
    5: {
      methods: [
        ...mintInfoResp.nuts['5'].methods,
        { method: 'bacs', unit: 'sat' },
        { method: 'swift', unit: 'sat' },
      ],
      disabled: false,
    },
  },
};

function normalizeProofsForTest(proofs: Parameters<Wallet['signP2PKProofs']>[0]): Proof[] {
  return proofs.map((proof) => ({ ...proof, amount: Amount.from(proof.amount) }));
}

describe('requestTokens', () => {
  test('test requestTokens', async () => {
    server.use(
      http.post(mintUrl + '/v1/mint/bolt11', () => {
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const mintQuote: MintQuoteBolt11Response = {
      quote: 'test-quote-id',
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      method: 'bolt11',
      state: MintQuoteState.UNPAID,
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      updated_at: null,
      expiry: null,
    };
    const proofs = await wallet.mintProofsBolt11(1, mintQuote);

    expect(proofs).toHaveLength(1);
    expect(proofs[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
    expect(/[0-9a-f]{64}/.test(proofs[0].C)).toBe(true);
    expect(/[0-9a-f]{64}/.test(proofs[0].secret)).toBe(true);
  });

  test('prepareMint defers request until completeMint', async () => {
    let mintCalls = 0;
    server.use(
      http.post(mintUrl + '/v1/mint/bolt11', () => {
        mintCalls += 1;
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const mintQuote: MintQuoteBolt11Response = {
      quote: 'deferred-quote-id',
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      method: 'bolt11',
      state: MintQuoteState.UNPAID,
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      updated_at: null,
      expiry: null,
    };
    const preview = await wallet.prepareMint('bolt11', 1, mintQuote);
    expect(mintCalls).toBe(0);
    expect(preview.method).toBe('bolt11');
    expect(preview.quote.quote).toBe('deferred-quote-id');
    expect(preview.outputData).toHaveLength(1);

    const proofs = await wallet.completeMint(preview);

    expect(mintCalls).toBe(1);
    expect(proofs).toHaveLength(1);
    expect(proofs[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
  });

  test('mints the blinded messages in outputData; the preview carries no wire copy', async () => {
    let sent: Array<{ B_: string; id: string }> = [];
    server.use(
      http.post(mintUrl + '/v1/mint/bolt11', async ({ request }) => {
        sent = ((await request.json()) as { outputs: Array<{ B_: string; id: string }> }).outputs;
        return HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
            },
          ],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const preview = await wallet.prepareMint('bolt11', 1, {
      quote: 'restored-quote-id',
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      method: 'bolt11',
      state: MintQuoteState.PAID,
      amount_paid: Amount.from(1),
      amount_issued: Amount.from(0),
      updated_at: null,
      expiry: null,
    });
    const prepared = preview.outputData[0].blindedMessage.B_;
    expect(preview).not.toHaveProperty('payload');

    const proofs = await wallet.completeMint(preview);

    expect(sent[0].B_).toBe(prepared);
    expect(proofs[0]).toMatchObject({ amount: Amount.from(1), id: '00bd033559de27d0' });
  });

  test('prepareMint accepts expiry: 0 as "no expiry" (CDK quirk)', async () => {
    // Spec says expiry is <int|null> with null meaning "no expiry". CDK emits 0
    // for the same meaning. Treat 0 as null rather than "expired in 1970".
    server.use(
      http.post(mintUrl + '/v1/mint/bolt11', () =>
        HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
            },
          ],
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const quote = {
      quote: 'no-expiry-quote',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      state: MintQuoteState.PAID,
      expiry: 0,
    } as unknown as MintQuoteBolt11Response;

    const preview = await wallet.prepareMint('bolt11', 1, quote);
    const proofs = await wallet.completeMint(preview);
    expect(proofs).toHaveLength(1);
  });

  test('completeMint rejects missing DLEQ when mint advertises NUT-12', async () => {
    server.use(
      http.get(mintUrl + '/v1/info', () => HttpResponse.json(mintInfoRespWithNut12)),
      http.post(mintUrl + '/v1/mint/bolt11', () =>
        HttpResponse.json({
          signatures: [
            {
              id: '00bd033559de27d0',
              amount: 1,
              C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
            },
          ],
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit, requireSigDleq: true });
    await wallet.loadMint();

    const preview = await wallet.prepareMint('bolt11', 1, {
      quote: 'quote-dleq-required',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      state: MintQuoteState.UNPAID,
      expiry: null,
    });

    await expect(wallet.completeMint(preview)).rejects.toThrow(
      'Mint supports NUT-12, but returned a signature without DLEQ proof',
    );
  });

  test('batch-mints the blinded messages in outputData; the preview carries no wire copy', async () => {
    let sent: Array<{ B_: string }> = [];
    server.use(
      http.post(mintUrl + '/v1/mint/bolt11/batch', async ({ request }) => {
        const body = (await request.json()) as { outputs: Array<{ B_: string; amount: unknown }> };
        sent = body.outputs;
        return HttpResponse.json({
          signatures: body.outputs.map((o) => ({
            id: '00bd033559de27d0',
            amount: o.amount,
            C_: '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625',
          })),
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const quote: MintQuoteBolt11Response = {
      quote: 'restored-batch-quote',
      request: 'lnbc...',
      amount: Amount.from(1),
      unit: 'sat',
      method: 'bolt11',
      state: MintQuoteState.PAID,
      amount_paid: Amount.from(1),
      amount_issued: Amount.from(0),
      updated_at: null,
      expiry: null,
    };
    const preview = await wallet.prepareBatchMint('bolt11', [{ amount: 1, quote }]);
    const prepared = preview.outputData[0].blindedMessage.B_;
    expect(preview).not.toHaveProperty('payload');

    const proofs = await wallet.completeBatchMint(preview);

    expect(sent[0].B_).toBe(prepared);
