    });

    const captureInputs = (
      sink: { inputs?: Array<Record<string, unknown>> },
      response: unknown,
    ): RequestFn =>
      (async (options: ReqArgs) => {
        sink.inputs = (
          sentBody(options.requestBody) as { inputs: Array<Record<string, unknown>> }
        ).inputs;
