      expect(sink.inputs?.[0]).not.toHaveProperty('dleq');
      expect(sink.inputs?.[0]).not.toHaveProperty('p2pk_e');
      expect(sink.inputs?.[0]).not.toHaveProperty('spend_info');
      expect(sink.inputs?.[0]).toMatchObject({
