    const invoiceFor = (hashHex: string) =>
      bech32.encode(
        'lnbc',
        [...new Array<number>(7).fill(0), 1, 1, 20, ...bech32.toWords(hexToBytes(hashHex))].concat(
          new Array<number>(104).fill(0),
        ),
        false,
      );
    const paidResponse = (request: string, payment_preimage: string | null) => ({
      quote: 'my-quote',
