import { hexToBytes } from '@noble/curves/utils.js';
import { HttpResponse, http } from 'msw';
import { test, describe, expect, vi } from 'vitest';

import {
  Wallet,
  KeyChain,
  OutputData,
  Amount,
  MintQuoteState,
  MeltQuoteState,
  createEphemeralCounterSource,
  type Proof,
  type OutputType,
  type MintQuoteBolt11Response,
  type MintQuoteBolt12Response,
  type MeltQuoteBolt11Response,
} from '../../src';
import { assertQuoteUnit } from '../../src/wallet/_internal';
import { NUT02_V3_VECTOR1_KEYS, NUT02_V3_VECTOR1_KEYSET } from '../consts';

import {
  useTestServer,
  mint,
  mintUrl,
  unit,
  invoice,
  mintInfoResp,
  dummyKeysResp,
  dummyKeysetResp,
} from './_setup';

const server = useTestServer();

const KEYSET_ID = '00bd033559de27d0';
// A valid compressed secp256k1 point (the generator), accepted by normalizeSecpPubkey.
const LOCK_PUBKEY = '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798';
const SIG_C = '0361a2725cfd88f60ded718378e8049a4a6cee32e214a9870b44c3ffea2dc9e625';
const SEED = hexToBytes(
  'dd44ee516b0647e80b488e8dcc56d736a148f15276bef588b37057476d4b2b25780d3688a32b37353d6995997842c0fd8b412475c891c16310471fbc86dcbda8',
);

// Minimal Keyset-shaped stub for spying keyChain.getKeyset.
function ks(id: string, unitStr = unit, hasKeys = true, fee = 0) {
  return { id, unit: unitStr, hasKeys, fee, isActive: true, hasHexId: true } as never;
}

// Mint info with a single active keyset that charges input fees.
function useFeeKeyset(feePPK: number) {
  server.use(
    http.get(mintUrl + '/v1/keysets', () =>
      HttpResponse.json({
        keysets: [{ id: KEYSET_ID, unit: 'sat', active: true, input_fee_ppk: feePPK }],
      }),
    ),
  );
}

describe('constructor mutants', () => {
  test('rejects a bip39seed that is not a Uint8Array', () => {
    expect(() => new Wallet(mint, { unit, bip39seed: 'not-bytes' as never })).toThrow(
      'bip39seed must be a valid Uint8Array',
    );
  });

  test('rejects a bip39seed that is not 64 bytes', () => {
    for (const length of [1, 32, 63, 65]) {
      expect(() => new Wallet(mint, { unit, bip39seed: new Uint8Array(length) })).toThrow(
        /bip39seed must be 64 bytes/,
      );
    }
    expect(() => new Wallet(mint, { unit, bip39seed: new Uint8Array(64) })).not.toThrow();
  });

  test('never logs the rejected seed value', () => {
    // failIf logs its context before throwing, so the value must not appear there.
    const mnemonic = 'abandon abandon abandon abandon about';
    const error = vi.fn();
    const logger = {
      error,
      warn: vi.fn(),
      info: vi.fn(),
      debug: vi.fn(),
      trace: vi.fn(),
      log: vi.fn(),
    };

    expect(() => new Wallet(mint, { unit, logger, bip39seed: mnemonic as never })).toThrow();

    const logged = JSON.stringify(error.mock.calls);
    expect(logged).not.toContain(mnemonic);
    expect(logged).not.toContain('abandon');
  });

  test('secretsPolicy overrides the default rather than being ANDed with it', () => {
    // `options.secretsPolicy ?? this._secretsPolicy`: an explicit 'random' must win even
    // when a seed is present (a `&&` mutant would collapse to the 'auto' default).
    const wallet = new Wallet(mint, { unit, secretsPolicy: 'random', bip39seed: SEED });
    expect(wallet.defaultOutputType().type).toBe('random');
  });

  test('uses a supplied counterSource instead of a fresh ephemeral one', async () => {
    const source = createEphemeralCounterSource({ [KEYSET_ID]: 7 });
    const wallet = new Wallet(mint, { unit, counterSource: source });
    // A mutant that ignores the supplied source starts a new source seeded at 0.
    expect(await wallet.counters.peekNext(KEYSET_ID)).toBe(7);
  });
});

describe('finishInit / getKeyset mutants', () => {
  test('a constructor-bound keyset with a mismatched unit is rejected on load', () => {
    const wallet = new Wallet(mint, { unit, keysetId: '00ffffffffffffff' });
    const cache = KeyChain.mintToCacheDTO(mintUrl, dummyKeysetResp.keysets, dummyKeysResp.keysets);
    vi.spyOn(wallet.keyChain, 'getKeyset').mockReturnValue(ks('00ffffffffffffff', 'eur'));
    expect(() => wallet.loadMintFromCache(mintInfoResp, cache)).toThrow(
      'Keyset unit does not match wallet unit',
    );
  });

  test('getKeyset rejects a keyset whose unit differs from the wallet', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    vi.spyOn(wallet.keyChain, 'getKeyset').mockReturnValue(ks('00cc000000000000', 'eur'));
    expect(() => wallet.getKeyset('00cc000000000000')).toThrow(
      'Keyset unit does not match wallet unit',
    );
  });

  test('getKeyset rejects a keyset with no keys loaded', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    vi.spyOn(wallet.keyChain, 'getKeyset').mockReturnValue(ks('00dd000000000000', unit, false));
    expect(() => wallet.getKeyset('00dd000000000000')).toThrow('Keyset has no keys loaded');
  });
});

describe('_prepareInputsForMint mutants', () => {
  test('does not dispatch a point-shaped legacy secret as v3', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const proof = {
      id: KEYSET_ID,
      amount: Amount.from(1),
      secret: LOCK_PUBKEY,
      C: SIG_C,
      witness: '{"signatures":["stale"]}',
    } as Proof;

    const [prepared] = (
      wallet as unknown as { _prepareInputsForMint(proofs: Proof[]): Proof[] }
    )._prepareInputsForMint([proof]);
    expect(prepared.witness).toBeUndefined();
  });

  test('completeMelt strips dleq and p2pk_e from the inputs sent to the mint', async () => {
    let sentInputs: Array<Record<string, unknown>> = [];
    server.use(
      http.post(mintUrl + '/v1/melt/bolt11', async ({ request }) => {
        const body = (await request.json()) as { inputs: Array<Record<string, unknown>> };
        sentInputs = body.inputs;
        return HttpResponse.json({
          quote: 'melt-strip',
          amount: 10,
          unit: 'sat',
          fee_reserve: 0,
          state: MeltQuoteState.PAID,
          expiry: 1234567890,
          payment_preimage: 'preimage',
          request: 'bolt11request',
          change: [],
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const meltQuote: MeltQuoteBolt11Response = {
      quote: 'melt-strip',
      amount: Amount.from(10),
      fee_reserve: Amount.from(0),
      request: 'bolt11request',
      state: MeltQuoteState.UNPAID,
      expiry: 1234567890,
      payment_preimage: null,
      unit: 'sat',
      method: 'bolt11',
    };
    const proofsToSend = [
      {
        id: KEYSET_ID,
        amount: Amount.from(12),
        secret: 'secret1',
        C: 'C1',
        dleq: { s: 'aa', e: 'bb', r: 'cc' },
        p2pk_e: 'deadbeef',
      },
    ] as unknown as Proof[];

    await wallet.meltProofsBolt11(meltQuote, proofsToSend, { nut08Change: false });

    expect(sentInputs).toHaveLength(1);
    expect(sentInputs[0]).not.toHaveProperty('dleq');
    expect(sentInputs[0]).not.toHaveProperty('p2pk_e');
  });

  test('sendOffline with requireDleq retains the dleq on the sent proofs', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const proofs = [
      { id: KEYSET_ID, amount: Amount.from(4), secret: 's4', C: 'C4', dleq: { s: 'a', e: 'b' } },
    ] as unknown as Proof[];

    const { send } = wallet.sendOffline(4, proofs, { requireDleq: true });
    expect(send).toHaveLength(1);
    expect(send[0].dleq).toBeDefined();
  });
});

describe('restore mutants', () => {
  test('restore requires a seed', async () => {
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    await expect(wallet.restore(0, 3)).rejects.toThrow(
      'Cashu Wallet must be initialized with a seed to use restore',
    );
  });

  test('lastCounterWithSignature is start + index, not start - index', async () => {
    const wallet = new Wallet(mint, { unit, bip39seed: SEED });
    await wallet.loadMint();
    const VALID_POINT = '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422';
    server.use(
      http.post(mintUrl + '/v1/restore', async ({ request }) => {
        const body = (await request.json()) as { outputs: Array<{ B_: string }> };
        return HttpResponse.json({
          outputs: body.outputs,
          signatures: body.outputs.map(() => ({ id: KEYSET_ID, amount: 1, C_: VALID_POINT })),
        });
      }),
    );

    const res = await wallet.restore(5, 3);
    // 3 matching signatures starting at counter 5 → last is 5 + 2 = 7.
    expect(res.lastCounterWithSignature).toBe(7);
  });
});

describe('createMintQuoteBolt11 mutants', () => {
  function useV3Keyset() {
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [NUT02_V3_VECTOR1_KEYSET] }),
      ),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [NUT02_V3_VECTOR1_KEYS] })),
    );
  }

  // Echoes the requested lock pubkey, as an honest mint does.
  function useEchoQuote(id: string, amount = 1, transform?: (pubkey: string) => string) {
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', async ({ request }) => {
        const body = (await request.json()) as { pubkey: string };
        return HttpResponse.json({
          quote: id,
          request: amount === 2 ? 'lnbc20n1pfake' : 'lnbc10n1pfake', // HRP encodes the amount
          unit: 'sat',
          amount,
          state: MintQuoteState.PAID,
          expiry: null,
          pubkey: transform ? transform(body.pubkey) : body.pubkey,
        });
      }),
    );
  }

  test('rejects substitution of the requested quote lock', async () => {
    useV3Keyset();
    useEchoQuote('q-substituted', 1, (pk) => (pk.startsWith('02') ? '03' : '02') + pk.slice(2));
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const { pubkey } = await wallet.createQuoteLockKey();
    await expect(wallet.createMintQuoteBolt11(1, pubkey)).rejects.toThrow(
      'Mint quote is not locked to the requested pubkey',
    );
  });

  test('batch mint signs each locked quote from the config keys', async () => {
    useV3Keyset();
    let n = 0;
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', async ({ request }) => {
        const body = (await request.json()) as { pubkey: string };
        return HttpResponse.json({
          quote: `q-batch-${++n}`,
          request: 'lnbc10n1pfake', // HRP encodes the quoted 1 sat
          unit: 'sat',
          amount: 1,
          state: MintQuoteState.PAID,
          expiry: null,
          pubkey: body.pubkey,
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const lockA = await wallet.createQuoteLockKey();
    const lockB = await wallet.createQuoteLockKey();
    const quotes = await Promise.all([
      wallet.createMintQuoteBolt11(1, lockA.pubkey),
      wallet.createMintQuoteBolt11(1, lockB.pubkey),
    ]);

    const preview = await wallet.prepareBatchMint(
      'bolt11',
      quotes.map((quote) => ({ amount: 1, quote })),
      { privkey: [lockA.privkey, lockB.privkey] },
    );
    expect(preview.signatures).toHaveLength(2);
    expect(preview.signatures?.every((signature) => typeof signature === 'string')).toBe(true);
  });

  test('batch mint refuses a locked quote object missing its face amount', async () => {
    useV3Keyset();
    useEchoQuote('q-slim-batch', 2);
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();
    const lock = await wallet.createQuoteLockKey();
    const quote = await wallet.createMintQuoteBolt11(2, lock.pubkey);
    // A partial draw against a slim quote: the transcript commits the face
    // amount (NUT-10), which the slim object cannot supply.
    const slim = { quote: quote.quote, unit: quote.unit, pubkey: quote.pubkey };
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11/check', () => HttpResponse.json([quote])),
    );

    // The mint's copy supplies the face amount the transcript commits to, so a slim object works.
    const preview = await wallet.prepareBatchMint('bolt11', [{ amount: 1, quote: slim }], {
      privkey: lock.privkey,
    });
    expect(preview.quotes.map((q) => q.quote)).toEqual([quote.quote]);
    expect(preview.signatures).toHaveLength(1);
  });

  test('a locked quote without its key fails fast, and recoverQuoteLockKey repairs it', async () => {
    useV3Keyset();
    // Uppercase echo: recovery and signing must be case-insensitive on the pubkey.
    useEchoQuote('q-lost-key', 1, (pk) => pk.toUpperCase());
    const first = new Wallet(mint, { unit, bip39seed: SEED });
    await first.loadMint();
    const { pubkey } = await first.createQuoteLockKey();
    const stored = await first.createMintQuoteBolt11(1, pubkey);

    // The stored quote's key was lost: nothing is recovered implicitly.
    const restarted = new Wallet(mint, { unit, bip39seed: SEED });
    await restarted.loadMint();
    await expect(restarted.prepareMint('bolt11', 1, stored)).rejects.toThrow(/recoverQuoteLockKey/);
    // The explicit repair: scan the seed to the quote's pubkey, pass the key in config.
    const privkey = await restarted.recoverQuoteLockKey(stored.pubkey!);
    expect(privkey).toMatch(/^[0-9a-f]{64}$/);
    const preview = await restarted.prepareMint('bolt11', 1, stored, { privkey });
    expect(preview.signature).toMatch(/^[0-9a-f]{128}$/);
  });

  test('forwards the description and keeps the quoted unit', async () => {
    let body: Record<string, unknown> = {};
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', async ({ request }) => {
        body = (await request.json()) as Record<string, unknown>;
        return HttpResponse.json({
          quote: 'q-desc',
          amount_paid: Amount.from(0),
          amount_issued: Amount.from(0),
          request: 'lnbc10u1pfake', // HRP encodes the quoted 1,000 sat
          unit,
          amount: 1000,
          state: MintQuoteState.UNPAID,
          expiry: null,
          pubkey: body.pubkey,
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    const quote = await wallet.createMintQuoteBolt11(1000, LOCK_PUBKEY, 'a description');
    expect(body.description).toBe('a description');
    expect(quote.unit).toBe('sat');
  });

  test('looks up a quote supplied as an id alone and rejects a foreign unit', async () => {
    let lookups = 0;
    server.use(
      http.get(mintUrl + '/v1/mint/quote/bolt11/stored-id', () => {
        lookups += 1;
        return HttpResponse.json({
          quote: 'stored-id',
          request: 'lnbc10u1pfake',
          unit: 'usd',
          amount: 1000,
          state: MintQuoteState.PAID,
          amount_paid: 1000,
          amount_issued: 0,
          expiry: null,
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    // A bare id carries no unit, state or accounting, so the mint is asked rather than assumed.
    await expect(wallet.prepareMint('bolt11', 1000, { quote: 'stored-id' })).rejects.toThrow(
      "Quote unit 'usd' does not match wallet unit 'sat'",
    );
    expect(lookups).toBe(1);
  });

  test('a quote supplied as an id alone has its accounting checked against the mint', async () => {
    server.use(
      http.get(mintUrl + '/v1/mint/quote/bolt11/stored-capped', () =>
        HttpResponse.json({
          quote: 'stored-capped',
          request: 'lnbc10u1pfake',
          unit,
          amount: 1000,
          state: MintQuoteState.PAID,
          amount_paid: 1,
          amount_issued: 0,
          expiry: null,
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    await expect(wallet.prepareMint('bolt11', 100, { quote: 'stored-capped' })).rejects.toThrow(
      'has only 1 available to mint; requested 100',
    );
  });

  test('batch mint looks up id-only entries and rejects a foreign unit', async () => {
    let checks = 0;
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11/check', async ({ request }) => {
        checks += 1;
        const body = (await request.json()) as { quotes: string[] };
        return HttpResponse.json(
          body.quotes.map((q) => ({
            quote: q,
            request: 'lnbc10u1pfake',
            unit: 'usd',
            amount: 1,
            state: MintQuoteState.PAID,
            amount_paid: 1,
            amount_issued: 0,
            expiry: null,
          })),
        );
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    // The entry that states its unit passes; the id-only one is read from the mint.
    await expect(
      wallet.prepareBatchMint('bolt11', [
        {
          amount: 1,
          quote: {
            quote: 'stated',
            unit,
            amount_paid: Amount.from(0),
            amount_issued: Amount.from(0),
          },
        },
        { amount: 1, quote: { quote: 'bare' } },
      ]),
    ).rejects.toThrow("Quote unit 'usd' does not match wallet unit 'sat'");
    // One batched request covers every id-only entry.
    expect(checks).toBe(1);
  });

  test('prepareMelt looks up an id-only quote and rejects a foreign unit', async () => {
    let checks = 0;
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/bare-melt', () => {
        checks += 1;
        return HttpResponse.json({
          quote: 'bare-melt',
          method: 'bolt11',
          request: invoice,
          unit: 'usd',
          amount: 1,
          fee_reserve: 0,
          state: MeltQuoteState.UNPAID,
          expiry: 0,
        });
      }),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    // Enough proofs to cover the melt, so the unit is the only thing that can fail.
    const proofs = [
      { id: KEYSET_ID, amount: Amount.from(4), secret: 's4', C: 'C4' },
    ] as unknown as Proof[];

    await expect(
      wallet.prepareMelt('bolt11', { quote: 'bare-melt', amount: Amount.from(1) }, proofs),
    ).rejects.toThrow("Quote unit 'usd' does not match wallet unit 'sat'");
    expect(checks).toBe(1);
  });

  test('rejects a melt quote response whose unit is an empty string', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/empty-unit', () =>
        HttpResponse.json({
          quote: 'empty-unit',
          method: 'bolt11',
          request: invoice,
          unit: '',
          amount: 1,
          fee_reserve: 0,
          state: MeltQuoteState.UNPAID,
          expiry: 0,
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    await expect(wallet.checkMeltQuoteBolt11('empty-unit')).rejects.toThrow(
      /Invalid response from mint/i,
    );
  });

  test('rejects a quote response whose unit is an empty string', async () => {
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', () =>
        HttpResponse.json({
          quote: 'q-emptyunit',
          amount_paid: Amount.from(0),
          amount_issued: Amount.from(0),
          request: 'lnbc10u1pfake',
          unit: '',
          amount: 1000,
          state: MintQuoteState.UNPAID,
          expiry: null,
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    await expect(wallet.createMintQuoteBolt11(1000, LOCK_PUBKEY)).rejects.toThrow(
      /Invalid response from mint/i,
    );
  });

  test('rejects a quote response the mint sent with no usable unit', async () => {
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', () =>
        HttpResponse.json({
          quote: 'q-nounit',
          amount_paid: Amount.from(0),
          amount_issued: Amount.from(0),
          request: 'lnbc10u1pfake',
          amount: 1000,
          state: MintQuoteState.UNPAID,
          expiry: null,
        }),
      ),
    );
    const wallet = new Wallet(mint, { unit });
    await wallet.loadMint();

    // NUT-04 requires unit on the response, so Mint refuses it before the wallet compares.
    await expect(wallet.createMintQuoteBolt11(1000, LOCK_PUBKEY)).rejects.toThrow(
      /Invalid response from mint/i,
    );
  });

  test('rejects a description when the mint does not advertise bolt11 description support', async () => {
    server.use(
      http.get(mintUrl + '/v1/info', () =>
        HttpResponse.json({
          ...mintInfoResp,
          nuts: {
            ...mintInfoResp.nuts,
