import { HttpResponse, http, delay } from 'msw';
import { setupServer } from 'msw/node';
import { beforeAll, beforeEach, test, describe, expect, afterAll, afterEach, vi } from 'vitest';

import {
  Wallet,
  HttpResponseError,
  NetworkError,
  MintOperationError,
  RateLimitError,
  type ResponseMeta,
  type RequestFetch,
  setGlobalRequestOptions,
  type Nut19Policy,
} from '../../src';
import { NULL_LOGGER, type Logger } from '../../src/logger';
import request, { setRequestLogger } from '../../src/transport';
import {
  parseRetryAfter,
  detectBrowserLike,
  buildRequestHeaders,
  errorMessage,
  readBodyText,
} from '../../src/transport/request';
import { MINTCACHE } from '../consts';

// Setup mint cache for loadMint()
const mintUrl = MINTCACHE.mintUrl;
const server = setupServer();

beforeAll(() => {
  server.listen({ onUnhandledRequest: 'error' });
});

afterEach(() => {
  server.resetHandlers();
  setRequestLogger(NULL_LOGGER);
  setGlobalRequestOptions({});
});

afterAll(() => {
  server.close();
  setRequestLogger(NULL_LOGGER);
  setGlobalRequestOptions({});
});

beforeEach(() => {
  server.use(
    http.get(mintUrl + '/v1/info', () => {
      return HttpResponse.json(MINTCACHE.mintInfo);
    }),
  );
});

describe('requests', { timeout: 7500 }, () => {
  test('request with body contains the correct headers', async () => {
    let headers: Headers;

    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', ({ request }) => {
        headers = request.headers;
        return HttpResponse.json({
          quote: 'test',
          amount: 2000,
          fee_reserve: 20,
          payment_preimage: null,
          state: 'UNPAID',
          unit: 'sat',
          expiry: 9999999999,
          request: 'lnbc20u1pfake',
        });
      }),
    );
    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await wallet.checkMeltQuoteBolt11('test');

    expect(headers!).toBeDefined();
    // expect(request!['content-type']).toContain('application/json');
    expect(headers!.get('accept')).toContain('application/json, text/plain, */*');
  });

  test('global custom headers can be set', async () => {
    let headers: Headers;
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', ({ request }) => {
        headers = request.headers;
        return HttpResponse.json({
          quote: 'test',
          amount: 2000,
          fee_reserve: 20,
          payment_preimage: null,
          state: 'UNPAID',
          unit: 'sat',
          expiry: 9999999999,
          request: 'lnbc20u1pfake',
        });
      }),
    );

    try {
      const wallet = new Wallet(mintUrl);
      wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
      setGlobalRequestOptions({ headers: { 'x-cashu': 'xyz-123-abc' } });

      await wallet.checkMeltQuoteBolt11('test');

      expect(headers!).toBeDefined();
      expect(headers!.get('x-cashu')).toContain('xyz-123-abc');
    } finally {
      setGlobalRequestOptions({});
    }
  });

  test('global custom fetch can be set', async () => {
    const fetchCalls: Array<{ endpoint: string; method?: string }> = [];
    const customFetch = (async (
      input: Parameters<RequestFetch>[0],
      init?: Parameters<RequestFetch>[1],
    ) => {
      fetchCalls.push({ endpoint: String(input), method: init?.method });
      return new Response(
        JSON.stringify({
          quote: 'test',
          amount: 2000,
          fee_reserve: 20,
          payment_preimage: null,
          state: 'UNPAID',
          unit: 'sat',
          expiry: 9999999999,
          request: 'lnbc20u1pfake',
        }),
        { status: 200, headers: { 'Content-Type': 'application/json' } },
      );
    }) as RequestFetch;

    try {
      const wallet = new Wallet(mintUrl);
      wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
      setGlobalRequestOptions({ fetch: customFetch });

      await wallet.checkMeltQuoteBolt11('test');

      expect(fetchCalls).toEqual([
        { endpoint: `${mintUrl}/v1/melt/quote/bolt11/test`, method: 'GET' },
      ]);
    } finally {
      setGlobalRequestOptions({});
    }
  });

  test('request fetch overrides global custom fetch', async () => {
    const globalFetch = vi.fn(async () => {
      return new Response(JSON.stringify({ error: 'global fetch should not run' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;
    const localFetch = vi.fn(async () => {
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;

    try {
      setGlobalRequestOptions({ fetch: globalFetch });

      const result = await request<{ ok: true }>({
        endpoint: `${mintUrl}/v1/info`,
        fetch: localFetch,
      });

      expect(result).toEqual({ ok: true });
      expect(localFetch).toHaveBeenCalledTimes(1);
      expect(globalFetch).not.toHaveBeenCalled();
    } finally {
      setGlobalRequestOptions({});
    }
  });

  test('global RequestInit overrides the per-request value', async () => {
    let init: Parameters<RequestFetch>[1];
    const captureFetch = (async (
      _input: Parameters<RequestFetch>[0],
      requestInit?: Parameters<RequestFetch>[1],
    ) => {
      init = requestInit;
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;

    setGlobalRequestOptions({ redirect: 'follow', cache: 'default' });

    await request({ endpoint: `${mintUrl}/v1/info`, redirect: 'error', fetch: captureFetch });

    expect(init?.redirect).toBe('follow');
    expect(init?.cache).toBe('default');
  });

  test('redirect is error on requests carrying auth headers', async () => {
    let init: Parameters<RequestFetch>[1];
    const captureFetch = (async (
      _input: Parameters<RequestFetch>[0],
      requestInit?: Parameters<RequestFetch>[1],
    ) => {
      init = requestInit;
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;

    setGlobalRequestOptions({ redirect: 'follow' });

    await request({
      endpoint: `${mintUrl}/v1/info`,
      headers: { 'Blind-auth': 'authABC' },
      redirect: 'follow',
      fetch: captureFetch,
    });

    expect(init?.redirect).toBe('error');
  });

  test('redirect defaults to error on requests carrying a body, and stays overridable', async () => {
    let init: Parameters<RequestFetch>[1];
    const captureFetch = (async (
      _input: Parameters<RequestFetch>[0],
      requestInit?: Parameters<RequestFetch>[1],
    ) => {
      init = requestInit;
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;

    await request({
      endpoint: `${mintUrl}/v1/swap`,
      method: 'POST',
      requestBody: { inputs: [] },
      fetch: captureFetch,
    });
    expect(init?.redirect).toBe('error');

    await request({
      endpoint: `${mintUrl}/v1/swap`,
      method: 'POST',
      requestBody: { inputs: [] },
      redirect: 'follow',
      fetch: captureFetch,
    });
    expect(init?.redirect).toBe('follow');

    await request({ endpoint: `${mintUrl}/v1/info`, fetch: captureFetch });
    expect(init?.redirect).toBeUndefined();
  });

  test('per-request library options override the global default', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, async () => {
        await delay(3000);
        return HttpResponse.json({ keysets: [] });
      }),
    );

    setGlobalRequestOptions({ requestTimeout: 2000 });

    const thrown = await request({ endpoint, requestTimeout: 20, idempotent: false }).catch(
      (e) => e,
    );

    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).message).toContain('Request timed out after 20ms');
  });

  test('global library options apply when the request does not set them', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, async () => {
        await delay(3000);
        return HttpResponse.json({ keysets: [] });
      }),
    );

    setGlobalRequestOptions({ requestTimeout: 20 });

    const thrown = await request({ endpoint, idempotent: false }).catch((e) => e);

    expect(thrown).toBeInstanceOf(NetworkError);
    expect((thrown as Error).message).toContain('Request timed out after 20ms');
  });

  test('global and per-request headers merge, per-request winning', async () => {
    let headers: Headers;
    server.use(
      http.get(mintUrl + '/v1/keys', ({ request }) => {
        headers = request.headers;
        return HttpResponse.json({ keysets: [] });
      }),
    );

    setGlobalRequestOptions({ headers: { 'x-app': 'global', 'x-both': 'global' } });

    await request({
      endpoint: mintUrl + '/v1/keys',
      headers: { 'x-call': 'per-request', 'x-both': 'per-request' },
    });

    expect(headers!.get('x-app')).toBe('global');
    expect(headers!.get('x-call')).toBe('per-request');
    expect(headers!.get('x-both')).toBe('per-request');
  });

  test('a per-request header overrides a global one differing only in case', async () => {
    let observed: Headers | undefined;
    const captureFetch = (async (
      _input: Parameters<RequestFetch>[0],
      init?: Parameters<RequestFetch>[1],
    ) => {
      observed = new Headers(init?.headers);
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }) as RequestFetch;

    setGlobalRequestOptions({ headers: { Authorization: 'Bearer global' } });
    await request({
      endpoint: `${mintUrl}/v1/info`,
      headers: { authorization: 'Bearer per-request' },
      fetch: captureFetch,
    });

    // A combined value ("Bearer global, Bearer per-request") means both headers were sent;
    // Headers itself joins duplicates this way, so an exact match proves only one survived.
    expect(observed?.get('authorization')).toBe('Bearer per-request');
  });

  test('handles HttpResponseError on non-200 response', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse(JSON.stringify({ error: 'Not Found' }), { status: 404 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow(HttpResponseError);
  });
  test('handles NetworkError on network failure', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        // This simulates a network failure at the fetch level
        return Response.error();
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow(NetworkError);
  });

  test('handles MintOperationError on 400 response with code and detail', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse(JSON.stringify({ code: 20003, detail: 'Minting is disabled' }), {
          status: 400,
        });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    const promise = wallet.checkMeltQuoteBolt11('test');
    await expect(promise).rejects.toThrow(MintOperationError);
    // assert that the error message is set correctly by the code
    await expect(promise).rejects.toThrow('Minting is disabled');
  });

  test('uses raw text response as HttpResponseError message', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse('plain text failure', { status: 404 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow('plain text failure');
  });

  test('uses string detail field as HttpResponseError message', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse(JSON.stringify({ detail: 'mint detail error' }), { status: 404 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow('mint detail error');
  });

  test('uses primitive JSON error body as HttpResponseError message', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse(JSON.stringify('primitive failure'), { status: 404 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow('primitive failure');
  });

  test('falls back to raw text for an error body with a duplicate JSON key', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse('{"detail":"trusted","detail":"attacker"}', { status: 404 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow(
      '{"detail":"trusted","detail":"attacker"}',
    );
  });

  test('maps empty error response body to bad response', async () => {
    server.use(
      http.get(mintUrl + '/v1/melt/quote/bolt11/test', () => {
        return new HttpResponse('', { status: 400 });
      }),
    );

    const wallet = new Wallet(mintUrl);
    wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);
    await expect(wallet.checkMeltQuoteBolt11('test')).rejects.toThrow('bad response');
  });

  test('maps empty success response body to bad response', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse('', { status: 200 });
      }),
    );

    const thrown = await request({ endpoint }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect(thrown).toMatchObject({ message: 'bad response', status: 200 });
    expect((thrown as HttpResponseError).cause).toMatchObject({ message: 'Empty response body' });
  });

  test('rejects a response body with a duplicate JSON key instead of taking the last value', async () => {
    const endpoint = mintUrl + '/v1/keys';
    server.use(
      http.get(endpoint, () => {
        return new HttpResponse('{"id":"trusted","id":"attacker"}', { status: 200 });
      }),
    );

    const thrown = await request({ endpoint }).catch((e) => e);
    expect(thrown).toBeInstanceOf(HttpResponseError);
    expect(thrown).toMatchObject({ message: 'bad response', status: 200 });
  });

  test('maps malformed success JSON to bad response and logs parsing failure', async () => {
    const endpoint = mintUrl + '/v1/keys';
    const logger: Logger = {
      error: vi.fn(),
      warn: vi.fn(),
      info: vi.fn(),
      debug: vi.fn(),
      trace: vi.fn(),
      log: vi.fn(),
    };

    server.use(
      http.get(endpoint, () => {
        return new HttpResponse('{not-valid-json', { status: 200 });
      }),
    );

    setRequestLogger(logger);
    try {
      const thrown = await request({ endpoint }).catch((e) => e);
      expect(thrown).toBeInstanceOf(HttpResponseError);
      expect(thrown).toMatchObject({ message: 'bad response' });
      expect((thrown as HttpResponseError).cause).toBeInstanceOf(Error);
