      }),
    );
    const data = await request<{ ok: boolean }>({ endpoint });
    expect(data.ok).toBe(true);
    expect(requestCount).toBe(2);
  });

  test('GET retries only once', async () => {
    const endpoint = mintUrl + '/v1/keys';
