function decodeBAT(batHeader: string): { id: string; secret: string; C: string; witness?: string } {
  const base64url = batHeader.slice('authA'.length);
  return JSON.parse(new TextDecoder('utf-8').decode(decodeBase64UrlToUint8(base64url)));
}

/**
 * Minimal signature stub — toProof is mocked so only `amount` needs to be a valid AmountLike.
 */
const fakeSig = { amount: 1, id: 'k', C_: 'C_' };

function stubOutputs(n: number, keysetId = '00authkeyset0001') {
  return vi.spyOn(OutputData, 'createRandomData').mockImplementation((): any[] => {
    return Array.from({ length: n }, (_, i) => ({
      blindedMessage: `BM_${i}`,
      toProof: () => ({
        id: keysetId,
        C: `C_${i}`,
        secret: `SECRET_${i}`,
        dleq: { e: 'e', s: 's' },
        amount: 1,
      }),
    }));
  });
}

function fakeInfo({
  batMax = 10,
  needCATForMint = false,
  blindProtected = true,
}: {
  batMax?: number;
  needCATForMint?: boolean;
  blindProtected?: boolean;
}) {
  return {
    nuts: { '22': { bat_max_mint: batMax } },
    requiresClearAuthToken: (method: string, path: string) =>
      needCATForMint && method === 'POST' && path === '/v1/auth/blind/mint',
    requiresBlindAuthToken: () => blindProtected,
  } as any;
}

// Minimal provider fixture; real OIDC callback ordering is covered by createAuthWallet tests.
function providerStub(refresh: () => Promise<unknown> = vi.fn()) {
  type Listener = (t: unknown, origin: 'signin' | 'refresh') => void;
  const listeners: Listener[] = [];
  return {
    listeners,
    addTokenListener: (fn: Listener) => listeners.push(fn),
    removeTokenListener: (fn: Listener) => {
      const i = listeners.indexOf(fn);
      if (i >= 0) listeners.splice(i, 1);
    },
    refresh,
    // Simulate a delayed authorization/device-flow completion.
    fire: (t: unknown, origin: 'signin' | 'refresh' = 'signin') =>
      [...listeners].forEach((l) => l(t, origin)),
  };
}

