describe('AuthManager: BAT pool minting/topUp/ensure', () => {
  function seedKeychain(am: AuthManager, keysetId = '00authkeyset0001') {
    am['keychain'] = {
      getCheapestKeyset: vi.fn().mockReturnValue({
        id: keysetId,
        unit: 'auth',
        keys: { 1: '02deadbeef' },
      }),
    } as any;
  }

  test('topUp refuses redirects when a CAT accompanies the BAT mint', async () => {
    const am = new AuthManager(mintUrl, {
      request: reqSpy as RequestFn,
      desiredPoolSize: 5,
      maxPerMint: 99,
    });
    am['info'] = fakeInfo({ batMax: 2, needCATForMint: true });
    am.setCAT('cat-token');
    seedKeychain(am);

    stubOutputs(2);
    reqSpy.mockResolvedValueOnce({ signatures: [fakeSig, fakeSig] });
    await am.ensure(5);

    expect(reqSpy).toHaveBeenCalledWith(
      expect.objectContaining({
        endpoint: expect.stringContaining('/v1/auth/blind/mint'),
        redirect: 'error',
      }),
    );
  });

  test('a BAT mint that completes after setCAT(undefined) does not fill the pool', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, desiredPoolSize: 1 });
    am['info'] = fakeInfo({ batMax: 1, needCATForMint: true });
    am.setCAT('cat-token');
    seedKeychain(am);
    stubOutputs(1);

    let finishMint!: (value: { signatures: Array<typeof fakeSig> }) => void;
    reqSpy.mockReturnValueOnce(
      new Promise<{ signatures: Array<typeof fakeSig> }>((resolve) => {
        finishMint = resolve;
      }),
    );

    const pending = am.ensure(1);
    await vi.waitFor(() => expect(reqSpy).toHaveBeenCalledOnce());
    am.setCAT(undefined);
    finishMint({ signatures: [fakeSig] });
    await expect(pending).rejects.toThrow('session changed while obtaining BATs');

    expect(am.poolSize).toBe(0);
  });

  test.each([true, false])(
    'CAT acquisition observes a session change (protected: %s)',
    async (needsCAT) => {
      const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, desiredPoolSize: 1 });
      am['info'] = fakeInfo({ batMax: 1, needCATForMint: needsCAT });
      am.setCAT('old-cat');
      seedKeychain(am);
      stubOutputs(1);
      reqSpy.mockResolvedValueOnce({ signatures: [fakeSig] });

      const pending = am.ensure(1);
      queueMicrotask(() => am.setCAT(undefined));
      if (needsCAT) await expect(pending).rejects.toThrow('session changed while obtaining BATs');
      else await pending;

      expect(am.getCAT()).toBeUndefined();
      expect(reqSpy).toHaveBeenCalledTimes(needsCAT ? 0 : 1);
      expect(am.poolSize).toBe(needsCAT ? 0 : 1);
    },
  );

  test('a BAT mint that spans a CAT refresh still fills the pool', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, desiredPoolSize: 1 });
    am['info'] = fakeInfo({ batMax: 1, needCATForMint: true });
    const provider = providerStub();
    am.attachOIDC(provider as any);
    am.setCAT('cat-token');
    seedKeychain(am);
    stubOutputs(1);

    let finishMint!: (value: { signatures: Array<typeof fakeSig> }) => void;
    reqSpy.mockReturnValueOnce(
      new Promise<{ signatures: Array<typeof fakeSig> }>((resolve) => {
        finishMint = resolve;
      }),
    );

    const pending = am.ensure(1);
    await vi.waitFor(() => expect(reqSpy).toHaveBeenCalledOnce());
    // A refreshed CAT for the same account arrives while the mint is outstanding.
    provider.fire(
      { access_token: 'refreshed-cat', refresh_token: 'refreshed-r', expires_in: 300 },
      'refresh',
    );
    finishMint({ signatures: [fakeSig] });
    await pending;

    expect(am.getCAT()).toBe('refreshed-cat');
    expect(am.poolSize).toBe(1);
  });

  test('a BAT mint that spans a sign-in as another account does not fill the pool', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, desiredPoolSize: 1 });
    am['info'] = fakeInfo({ batMax: 1, needCATForMint: true });
    const provider = providerStub();
    am.attachOIDC(provider as any);
    am.setCAT('cat-token');
    seedKeychain(am);
    stubOutputs(1);

    let finishMint!: (value: { signatures: Array<typeof fakeSig> }) => void;
    reqSpy.mockReturnValueOnce(
      new Promise<{ signatures: Array<typeof fakeSig> }>((resolve) => {
        finishMint = resolve;
      }),
    );

    const pending = am.ensure(1);
    await vi.waitFor(() => expect(reqSpy).toHaveBeenCalledOnce());
    // A sign-in is a different account, so tokens minted under the old one are not this user's.
    provider.fire({ access_token: 'other-cat', refresh_token: 'other-r', expires_in: 300 });
    finishMint({ signatures: [fakeSig] });
    await expect(pending).rejects.toThrow('session changed while obtaining BATs');

    expect(am.getCAT()).toBe('other-cat');
    expect(am.poolSize).toBe(0);
  });

  test('ensure() mints up to desired target but not beyond bat_max_mint', async () => {
    const am = new AuthManager(mintUrl, {
      request: reqSpy as RequestFn,
      desiredPoolSize: 5,
      maxPerMint: 99,
    });
    am['info'] = fakeInfo({ batMax: 2 });
    seedKeychain(am);

    const outputsSpy = stubOutputs(2);
    reqSpy.mockResolvedValueOnce({ signatures: [fakeSig, fakeSig] });
    await am.ensure(5);

    expect(outputsSpy).toHaveBeenCalled();
    expect(am.poolSize).toBe(2);
  });

  test('ensure() normalizes bigint info and auth keyset fields during init', async () => {
    const am = new AuthManager(mintUrl, {
      request: reqSpy as RequestFn,
      desiredPoolSize: 5,
      maxPerMint: 99,
    });
    const outputsSpy = stubOutputs(2);
    reqSpy
      .mockResolvedValueOnce({
        name: 'mint',
        pubkey: '02abcd',
        version: 'test',
        contact: [],
        nuts: {
          '4': { disabled: false, methods: [] },
          '5': { disabled: false, methods: [] },
          '22': { bat_max_mint: 2n },
        },
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 250n }],
      })
      .mockResolvedValueOnce({
        keysets: [
          {
            id: '00k',
            unit: 'auth',
            input_fee_ppk: 250n,
            final_expiry: 1_754_296_607n,
            keys: { 1: '02aa' },
          },
        ],
      })
      .mockResolvedValueOnce({ signatures: [fakeSig, fakeSig] });

    await am.ensure(5);

    const KeyChainMock = getKeyChainMock();
    expect(KeyChainMock.mintToCacheDTO).toHaveBeenCalledWith(
      mintUrl,
      [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 250 }],
      [
        {
          id: '00k',
          unit: 'auth',
          input_fee_ppk: 250,
          final_expiry: 1_754_296_607,
          keys: { 1: '02aa' },
        },
      ],
    );
    expect(KeyChainMock.fromCache).toHaveBeenCalledWith(mintUrl, 'auth', expect.any(Object));
    expect(outputsSpy).toHaveBeenCalledWith(2, expect.any(Object));
    expect(am.poolSize).toBe(2);
  });

  test('ensure() rejects out-of-range auth keyset metadata during init', async () => {
    const am = new AuthManager(mintUrl, {
      request: reqSpy as RequestFn,
      desiredPoolSize: 5,
      maxPerMint: 99,
    });
    reqSpy
      .mockResolvedValueOnce({
        name: 'mint',
        pubkey: '02abcd',
        version: 'test',
        contact: [],
        nuts: {
          '4': { disabled: false, methods: [] },
          '5': { disabled: false, methods: [] },
          '22': { bat_max_mint: 2n },
        },
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 9007199254740993n }],
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', input_fee_ppk: 250n, keys: { 1: '02aa' } }],
      });

    await expect(am.ensure(5)).rejects.toThrow('keyset.input_fee_ppk');
  });

  test('topUp/end-to-end: creates proofs, validates DLEQ, pushes to pool', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn });
    am['info'] = fakeInfo({ batMax: 3 });
    seedKeychain(am);

    const outputsSpy = stubOutputs(3);
    reqSpy.mockResolvedValueOnce({ signatures: [fakeSig, fakeSig, fakeSig] });
    await am.ensure(3);

    expect(am.poolSize).toBe(3);
    expect(outputsSpy).toHaveBeenCalledWith(3, expect.any(Object));
  });

  test('topUp threads the configured logger into the BAT mint request', async () => {
    const logger: Logger = {
      error: vi.fn(),
      warn: vi.fn(),
      info: vi.fn(),
      debug: vi.fn(),
      trace: vi.fn(),
      log: vi.fn(),
    };
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, logger });
    am['info'] = fakeInfo({ batMax: 3 });
    seedKeychain(am);
    stubOutputs(3);
    reqSpy.mockResolvedValueOnce({ signatures: [fakeSig, fakeSig, fakeSig] });

    await am.ensure(3);

    expect(reqSpy).toHaveBeenCalledTimes(1);
    expect((reqSpy.mock.calls[0][0] as { logger?: Logger }).logger).toBe(logger);
  });
});

/* --------------------------
 * init behaviour
