describe('AuthManager: init fetches info then builds KeyChain via wallet mock', () => {
  test('init fetches /v1/info, keysets, keys and constructs KeyChain once', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn });

    reqSpy
      .mockResolvedValueOnce({
        name: 'mint',
        version: 'x',
        methods: {},
        nuts: { '22': { bat_max_mint: 7 }, '21': { client_id: 'cashu-client' } },
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 0 }],
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', keys: { 1: '02aa' } }],
      });

    await am['init']();

    expect(am['info']).toBeTruthy();

    const KeyChainMock = getKeyChainMock();
    expect(vi.isMockFunction(KeyChainMock)).toBe(true);
    // AuthManager now uses mintToCacheDTO + fromCache instead of the raw constructor
    expect(KeyChainMock.mintToCacheDTO).toHaveBeenCalledWith(
      mintUrl,
      [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 0 }],
      [{ id: '00k', unit: 'auth', keys: { 1: '02aa' } }],
    );
    expect(KeyChainMock.fromCache).toHaveBeenCalledWith(mintUrl, 'auth', expect.any(Object));

    expect(am.activeAuthKeysetId).toBe('00authkeyset0001');
  });

  test('threads the configured logger into every init request, not the process-global', async () => {
    const logger: Logger = {
      error: vi.fn(),
      warn: vi.fn(),
      info: vi.fn(),
      debug: vi.fn(),
      trace: vi.fn(),
      log: vi.fn(),
    };
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn, logger });

    reqSpy
      .mockResolvedValueOnce({
        name: 'mint',
        version: 'x',
        methods: {},
        nuts: { '22': { bat_max_mint: 7 }, '21': { client_id: 'cashu-client' } },
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 0 }],
      })
      .mockResolvedValueOnce({
        keysets: [{ id: '00k', unit: 'auth', keys: { 1: '02aa' } }],
      });

    await am['init']();

    expect(reqSpy).toHaveBeenCalledTimes(3);
    for (const call of reqSpy.mock.calls) {
      expect((call[0] as { logger?: Logger }).logger).toBe(logger);
    }
  });

  const oversized = Array.from({ length: MAX_KEYSET_LIST + 1 }, (_, i) => ({
    id: `00auth${i}`,
    unit: 'auth',
    active: true,
    input_fee_ppk: 0,
    keys: { 1: '02aa' },
  }));
  const single = [{ id: '00k', unit: 'auth', active: true, input_fee_ppk: 0, keys: { 1: '02aa' } }];

  test.each([
    ['keysets', {}, { keysets: single }],
    ['keys', { keysets: single }, {}],
  ])('init rejects a %s response that is not a list', async (_name, keysetsBody, keysBody) => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn });
    reqSpy
      .mockResolvedValueOnce({ name: 'mint', version: 'x', nuts: {} })
      .mockResolvedValueOnce(keysetsBody)
      .mockResolvedValueOnce(keysBody);

    await expect(am['init']()).rejects.toThrow('malformed auth keysets');
  });

  test('init rejects a keyset list longer than the cap', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn });
    reqSpy
      .mockResolvedValueOnce({ name: 'mint', version: 'x', nuts: {} })
      .mockResolvedValueOnce({ keysets: oversized })
      .mockResolvedValueOnce({ keysets: single });

    await expect(am['init']()).rejects.toThrow('mint returned more auth keysets');
  });

  test('init rejects a keys list longer than the cap', async () => {
    const am = new AuthManager(mintUrl, { request: reqSpy as RequestFn });
    reqSpy
      .mockResolvedValueOnce({ name: 'mint', version: 'x', nuts: {} })
      .mockResolvedValueOnce({ keysets: single })
      .mockResolvedValueOnce({ keysets: oversized });

    await expect(am['init']()).rejects.toThrow('mint returned more auth keysets');
  });
});

