import { HttpResponse, http } from 'msw';
import { setupServer } from 'msw/node';
import { beforeAll, beforeEach, afterAll, afterEach, test, describe, expect, vi } from 'vitest';

import {
  Mint,
  KeyChain,
  Keyset,
  type MintKeyset,
  type MintKeys,
  type Keys,
  type KeyChainCache,
} from '../../src';
import { NULL_LOGGER } from '../../src/logger';
import { deriveKeysetId, isValidHex } from '../../src/utils';
import { DUMMY_TEST_KEYS, DUMMY_TEST_KEYSET, PUBKEYS } from '../consts';

const mintUrl = 'http://localhost:3338';
const mint = new Mint(mintUrl);
const unit = 'sat';

// Rotation fixtures: mint starts with A active, then A goes inactive and B appears.
const keysetA: MintKeyset = { ...DUMMY_TEST_KEYSET };
const keysetAInactive: MintKeyset = { ...DUMMY_TEST_KEYSET, active: false };
const keysetB: MintKeyset = { id: '009a1f293253e41e', unit: 'sat', active: true, input_fee_ppk: 0 };
const keysB: MintKeys = { ...keysetB, keys: PUBKEYS };

const dummyKeysResp: { keysets: MintKeys[] } = {
  keysets: [
    DUMMY_TEST_KEYS,
    {
      id: '009a1f293253e41e',
      unit: 'sat',
      active: true,
      input_fee_ppk: 2,
      final_expiry: undefined,
      keys: PUBKEYS,
    },
    {
      id: 'invalidbase64',
      unit: 'sat',
      active: true,
      input_fee_ppk: 1,
      keys: {
        1: '03pubkey1invalid',
        2: '03pubkey2invalid',
      },
    },
    {
      id: '00inactive',
      unit: 'sat',
      active: false,
      input_fee_ppk: 0,
      keys: {
        1: '03pubkey1inactive',
        2: '03pubkey2inactive',
      },
    },
  ],
};

const dummyKeysetResp: { keysets: MintKeyset[] } = {
  keysets: [
    DUMMY_TEST_KEYSET,
    {
      id: '009a1f293253e41e',
      unit: 'sat',
      active: true,
      input_fee_ppk: 2,
      final_expiry: undefined,
    },
    {
      id: 'invalidbase64',
      unit: 'sat',
      active: true,
      input_fee_ppk: 1,
    },
    {
      id: '00inactive',
      unit: 'sat',
      active: false,
      input_fee_ppk: 0,
    },
  ],
};

const server = setupServer();

beforeAll(() => {
  server.listen({ onUnhandledRequest: 'error' });
});

beforeEach(() => {
  server.use(
    http.get(mintUrl + '/v1/keys', () => {
      return HttpResponse.json(dummyKeysResp);
    }),
  );
  server.use(
    http.get(mintUrl + '/v1/keysets', () => {
      return HttpResponse.json(dummyKeysetResp);
    }),
  );
});

afterEach(() => {
  server.resetHandlers();
  vi.restoreAllMocks();
});

afterAll(() => {
  server.close();
});

describe('KeyChain initialization', () => {
  test('should initialize with mint instance and load keys and keysets', async () => {
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();

    // Verify keysets loaded and filtered by unit
    const keysets = keyChain.getKeysets();
    expect(keysets).toHaveLength(4); // All from dummy, assuming same unit
    expect(keysets.map((k) => k.id)).toEqual(dummyKeysetResp.keysets.map((ks) => ks.id));

    // Verify keys assigned
    const keysForFirst = keyChain.getKeyset('00bd033559de27d0').toMintKeys();
    expect(keysForFirst).toEqual(dummyKeysResp.keysets[0]);

    // Verify active keyset (lowest fee, active, hex ID)
    const active = keyChain.getCheapestKeyset();
    expect(active.id).toBe('00bd033559de27d0'); // Fee 0, hex ID
    expect(active.fee).toBe(0);
    expect(active.hasHexId).toBe(true);
    expect(isValidHex(active.id)).toBe(true);

    // Verify final_expiry assigned
    expect(active.expiry).toBe(1754296607);
  });

  test('getKeyset rejects prototype-chain ids instead of returning inherited values', async () => {
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();
    // A bare object map resolves these to Object.prototype members (truthy), bypassing
    // the not-found guard; the lookup must return nothing for a non-own id.
    for (const id of ['__proto__', 'constructor', 'toString', 'hasOwnProperty']) {
      expect(() => keyChain.getKeyset(id)).toThrow(/not found/i);
    }
  });

  test('should initialize with mintUrl and load keys and keysets', async () => {
    const keyChain = new KeyChain('http://localhost:3338', unit);
    await keyChain.init();

    // Verify keysets loaded and filtered by unit
    const keysets = keyChain.getKeysets();
    expect(keysets).toHaveLength(4); // All from dummy, assuming same unit
    expect(keysets.map((k) => k.id)).toEqual(dummyKeysetResp.keysets.map((ks) => ks.id));

    // Verify keys assigned
    const keysForFirst = keyChain.getKeyset('00bd033559de27d0').toMintKeys();
    expect(keysForFirst).toEqual(dummyKeysResp.keysets[0]);

    // Verify active keyset (lowest fee, active, hex ID)
    const active = keyChain.getCheapestKeyset();
    expect(active.id).toBe('00bd033559de27d0'); // Fee 0, hex ID
    expect(active.fee).toBe(0);
    expect(active.hasHexId).toBe(true);
    expect(isValidHex(active.id)).toBe(true);

    // Verify final_expiry assigned
    expect(active.expiry).toBe(1754296607);
  });

  test('should skip loading if already initialized unless forceRefresh', async () => {
    const keyChain = new KeyChain(mint, unit);
    const spyGetKeySets = vi.spyOn(mint, 'getKeySets');
    const spyGetKeys = vi.spyOn(mint, 'getKeys');

    await keyChain.init(); // First load
    expect(spyGetKeySets).toHaveBeenCalledTimes(1);
    expect(spyGetKeys).toHaveBeenCalledTimes(1);

    await keyChain.init(); // Second, should skip
    expect(spyGetKeySets).toHaveBeenCalledTimes(1);
    expect(spyGetKeys).toHaveBeenCalledTimes(1);

    await keyChain.init(true); // Force refresh
    expect(spyGetKeySets).toHaveBeenCalledTimes(2);
    expect(spyGetKeys).toHaveBeenCalledTimes(2);
  });

  test('should throw if no active hex keyset found', async () => {
    // Only include inactive and non-hex keysets
    const limitedKeysetResp = { keysets: dummyKeysetResp.keysets.slice(2) }; // 'invalidbase64' and '00inactive'
    const limitedKeysResp = { keysets: dummyKeysResp.keysets.slice(2) };

    server.use(
      http.get(mintUrl + '/v1/keys', () => {
        return HttpResponse.json(limitedKeysResp);
      }),
      http.get(mintUrl + '/v1/keysets', () => {
        return HttpResponse.json(limitedKeysetResp);
      }),
    );

    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();
    expect(() => keyChain.getCheapestKeyset()).toThrow('No active keyset found for unit: sat');
  });

  test('should remove keys if verification fails', async () => {
    // Create mismatched data by changing ID but keeping keys the same (derived ID won't match)
    const mismatchedKeysetResp = JSON.parse(JSON.stringify(dummyKeysetResp));
    const mismatchedKeysResp = JSON.parse(JSON.stringify(dummyKeysResp));

    // Change ID of first keyset and corresponding keys entry
    const newId = '00bd033559de27d1'; // Mismatched by changing last character
    mismatchedKeysetResp.keysets[0].id = newId;
    mismatchedKeysResp.keysets[0].id = newId;

    server.use(
      http.get(mintUrl + '/v1/keys', () => {
        return HttpResponse.json(mismatchedKeysResp);
      }),
      http.get(mintUrl + '/v1/keysets', () => {
        return HttpResponse.json(mismatchedKeysetResp);
      }),
    );

    const warn = vi.fn();
    const keyChain = new KeyChain(mint, unit, { ...NULL_LOGGER, warn });
    await keyChain.init();
    expect(keyChain.getKeyset('00bd033559de27d1').id).toEqual('00bd033559de27d1');
    expect(keyChain.getKeyset('00bd033559de27d1').keys).toEqual({});
    expect(warn).toHaveBeenCalledWith(expect.stringMatching(/do not derive/), { id: newId });
  });

  test('should not throw on init with empty keysets; queries throw instead', async () => {
    server.use(
      http.get(mintUrl + '/v1/keysets', () => {
        return HttpResponse.json({ keysets: [] }); // Empty keysets
      }),
    );

    const keyChain = new KeyChain(mint, unit);
    await expect(keyChain.init()).resolves.toBeUndefined(); // init itself succeeds
    expect(() => keyChain.getCheapestKeyset()).toThrow('KeyChain not initialized');
    expect(() => keyChain.getKeysets()).toThrow('KeyChain not initialized');
  });

  test('init(true) keeps keys for a keyset the mint no longer serves keys for', async () => {
    const keyChain = new KeyChain(mint, unit);
    // Pre-rotation: A active with keys
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [keysetA] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [DUMMY_TEST_KEYS] })),
    );
    await keyChain.init();
    expect(keyChain.getKeyset('00bd033559de27d0').hasKeys).toBe(true);

    // Rotation: A inactive and gone from /v1/keys, B active
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [keysetAInactive, keysetB] }),
      ),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [keysB] })),
    );
    await keyChain.init(true);

    expect(keyChain.getKeyset('00bd033559de27d0').hasKeys).toBe(true); // carried forward
    expect(keyChain.getKeyset('00bd033559de27d0').isActive).toBe(false); // metadata is fresh
    expect(keyChain.getKeyset('009a1f293253e41e').hasKeys).toBe(true);
  });

  test('init(true) drops a keyset absent from the fresh metadata', async () => {
    const keyChain = new KeyChain(mint, unit);
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [keysetA] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [DUMMY_TEST_KEYS] })),
    );
    await keyChain.init();
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [keysetB] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [keysB] })),
    );
    await keyChain.init(true);
    expect(keyChain.hasKeyset('00bd033559de27d0')).toBe(false);
  });

  test('init(true) discards unverifiable fresh keys and carries forward prior verified keys', async () => {
    const keyChain = new KeyChain(mint, unit);
    // Pre-rotation: A active with valid DUMMY_TEST_KEYS
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [keysetA] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [DUMMY_TEST_KEYS] })),
    );
    await keyChain.init();
    expect(keyChain.getKeyset('00bd033559de27d0').hasKeys).toBe(true);

    // Refresh: A still active but /v1/keys serves PUBKEYS (wrong keys for A's id, fail verification)
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [keysetA] })),
      http.get(mintUrl + '/v1/keys', () =>
        HttpResponse.json({ keysets: [{ ...DUMMY_TEST_KEYSET, keys: PUBKEYS }] }),
      ),
    );
    await keyChain.init(true);

    // Prior verified keys carried forward (not replaced by bad fresh keys)
    expect(keyChain.getKeyset('00bd033559de27d0').hasKeys).toBe(true);
    expect(keyChain.getKeyset('00bd033559de27d0').keys).toEqual(DUMMY_TEST_KEYS.keys);
  });

  test('init(true) drops carried-forward keys when the fresh metadata no longer derives their id', async () => {
    const original = makeKeyset(7, 1);
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [original.meta] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [original.keys] })),
    );
    const warn = vi.fn();
    const keyChain = new KeyChain(mint, unit, { ...NULL_LOGGER, warn });
    await keyChain.init();
    expect(keyChain.getKeyset(original.meta.id).verify()).toBe(true);

    // A v1 id commits to the fee, so the same keys under a changed fee no longer derive it.
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [{ ...original.meta, input_fee_ppk: 8 }] }),
      ),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [] })),
    );
    await keyChain.init(true);

    const changed = keyChain.getKeyset(original.meta.id);
    expect(changed.hasKeys).toBe(false);
    expect(changed.verify()).toBe(false);
    expect(warn).toHaveBeenCalledWith(expect.stringMatching(/carried keys/), {
      id: original.meta.id,
    });
  });

  test('init(true) carries forward keys for a v0 id when the unit is unchanged', async () => {
    const original = makeKeyset(7, 0);
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [original.meta] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [original.keys] })),
    );
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();
    const priorKeys = keyChain.getKeyset(original.meta.id).keys;

    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [{ ...original.meta, active: false }] }),
      ),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [] })),
    );
    await keyChain.init(true);

    const carried = keyChain.getKeyset(original.meta.id);
    expect(carried.hasKeys).toBe(true);
    expect(carried.keys).toEqual(PUBKEYS);
    // Carried keys are copied, so a keyset held from before the refresh shares nothing live.
    expect(carried.keys).not.toBe(priorKeys);
  });

  test('init(true) drops carried-forward keys for a v0 id served under a different unit', async () => {
    const original = makeKeyset(7, 0);
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [original.meta] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [original.keys] })),
    );
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();
    expect(keyChain.getKeyset(original.meta.id).hasKeys).toBe(true);

    // A v0 id hashes the keys alone, so a relabelled unit still derives it.
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [{ ...original.meta, unit: 'usd' }] }),
      ),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [] })),
    );
    await keyChain.init(true);

    expect(keyChain.getKeyset(original.meta.id).hasKeys).toBe(false);
  });

  test('an older overlapping refresh does not replace the newer keychain', async () => {
    const debug = vi.fn();
    const keyChain = new KeyChain(mint, unit, { ...NULL_LOGGER, debug });
    await keyChain.init();

    let releaseOldMeta!: (value: { keysets: MintKeyset[] }) => void;
    let releaseOldKeys!: (value: { keysets: MintKeys[] }) => void;
    const oldMeta = new Promise<{ keysets: MintKeyset[] }>((resolve) => {
      releaseOldMeta = resolve;
    });
    const oldKeys = new Promise<{ keysets: MintKeys[] }>((resolve) => {
      releaseOldKeys = resolve;
    });
    vi.spyOn(mint, 'getKeySets')
      .mockImplementationOnce(() => oldMeta)
      .mockResolvedValueOnce({ keysets: [keysetB] });
    vi.spyOn(mint, 'getKeys')
      .mockImplementationOnce(() => oldKeys)
      .mockResolvedValueOnce({ keysets: [keysB] });

    const olderRefresh = keyChain.init(true);
    await keyChain.init(true);
    expect(keyChain.hasKeyset(keysetB.id)).toBe(true);
    expect(keyChain.hasKeyset(keysetA.id)).toBe(false);

    releaseOldMeta({ keysets: [keysetA] });
    releaseOldKeys({ keysets: [DUMMY_TEST_KEYS] });
    await olderRefresh;

    expect(keyChain.hasKeyset(keysetA.id)).toBe(false);
    expect(keyChain.hasKeyset(keysetB.id)).toBe(true);
    expect(debug).toHaveBeenCalledWith(expect.stringMatching(/superseded/), { seq: 2 });
  });

  test('the newer overlapping refresh wins even when it returns last', async () => {
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();

    let releaseNewMeta!: (value: { keysets: MintKeyset[] }) => void;
    let releaseNewKeys!: (value: { keysets: MintKeys[] }) => void;
    const newMeta = new Promise<{ keysets: MintKeyset[] }>((resolve) => {
      releaseNewMeta = resolve;
    });
    const newKeys = new Promise<{ keysets: MintKeys[] }>((resolve) => {
      releaseNewKeys = resolve;
    });
    vi.spyOn(mint, 'getKeySets')
      .mockResolvedValueOnce({ keysets: [keysetA] })
      .mockImplementationOnce(() => newMeta);
    vi.spyOn(mint, 'getKeys')
      .mockResolvedValueOnce({ keysets: [DUMMY_TEST_KEYS] })
      .mockImplementationOnce(() => newKeys);

    const olderRefresh = keyChain.init(true);
    const newerRefresh = keyChain.init(true);
    await olderRefresh;

    releaseNewMeta({ keysets: [keysetB] });
    releaseNewKeys({ keysets: [keysB] });
    await newerRefresh;

    expect(keyChain.hasKeyset(keysetB.id)).toBe(true);
    expect(keyChain.hasKeyset(keysetA.id)).toBe(false);
  });

  test('loadFromCache keeps the current keychain when the cache fails validation', async () => {
    const keyChain = new KeyChain(mint, unit);
    await keyChain.init();
    const injected = makeKeyset(7, 1);
    const cache = KeyChain.mintToCacheDTO(
      mintUrl,
      [
        injected.meta,
        { id: '00badbadbadbadba', unit, active: true, input_fee_ppk: Number.MAX_SAFE_INTEGER + 1 },
      ],
      [injected.keys],
    );

    expect(() => keyChain.loadFromCache(cache)).toThrow(/input_fee_ppk/);
    expect(keyChain.hasKeyset(DUMMY_TEST_KEYSET.id)).toBe(true);
    expect(keyChain.hasKeyset(injected.meta.id)).toBe(false);
  });

  test('fromCache rejects a cache recorded for a different mint', async () => {
    const chain = new KeyChain(mint, unit);
    await chain.init();
    const foreign = { ...chain.cache, mintUrl: 'https://other-mint.example' };
    expect(() => KeyChain.fromCache(mint, unit, foreign)).toThrow(/different mint/);
  });

  test('fromCache names the missing mint URL on a cache that has none', async () => {
    const chain = new KeyChain(mint, unit);
    await chain.init();
    const { mintUrl: _dropped, ...nameless } = chain.cache;
    expect(() => KeyChain.fromCache(mint, unit, nameless as KeyChainCache)).toThrow(
      /missing its mint URL/,
    );
  });

  test('fromCache accepts a cache whose mint URL differs only in normalization', async () => {
    const chain = new KeyChain(mint, unit);
    await chain.init();
    const unnormalized = { ...chain.cache, mintUrl: 'HTTP://LOCALHOST:3338/' };
    const restored = KeyChain.fromCache(mint, unit, unnormalized);
    expect(restored.getAllKeysetIds()).toEqual(chain.getAllKeysetIds());
  });

  test('cache snapshots do not share key objects with the live keyset', async () => {
    const chain = new KeyChain(mint, unit);
    await chain.init();
    const live = chain.getKeyset(DUMMY_TEST_KEYSET.id);
    expect(live.verify()).toBe(true);

    const cached = chain.cache.keysets.find((k) => k.id === DUMMY_TEST_KEYSET.id);
    expect(cached?.keys).toBeDefined();
    cached!.keys!['3'] = '02' + '0'.repeat(64);

    expect(Object.prototype.hasOwnProperty.call(live.keys, '3')).toBe(false);
    expect(live.verify()).toBe(true);
  });

  test('cacheToMintDTO does not share key objects with the cache', async () => {
    const chain = new KeyChain(mint, unit);
    await chain.init();
    const cache = chain.cache;
    const { keys } = KeyChain.cacheToMintDTO(cache);
    keys[0].keys['3'] = '02' + '0'.repeat(64);

    const source = cache.keysets.find((k) => k.id === keys[0].id);
    expect(Object.prototype.hasOwnProperty.call(source!.keys, '3')).toBe(false);
  });

  test('should preload from cache and match original cache', async () => {
    const originalChain = new KeyChain(mint, unit);
    await originalChain.init();

    // New consolidated cache shape
    const originalCache = originalChain.cache;

    // Instantiate new KeyChain from consolidated cache (unit now explicit)
    const cachedChain = KeyChain.fromCache(mint, unit, originalCache);

    // Verify preloaded without calling init()
    const cachedActive = cachedChain.getCheapestKeyset();
    expect(cachedActive.id).toBe(originalChain.getCheapestKeyset().id);
    expect(cachedActive.fee).toBe(0);
    expect(cachedChain.getKeysets().length).toBe(originalChain.getKeysets().length);

    // Round-trip cache check (savedAt may differ between snapshots — compare structure)
    const newCache = cachedChain.cache;
    expect(newCache.keysets).toEqual(originalCache.keysets);
    expect(newCache.mintUrl).toEqual(originalCache.mintUrl);
  });

  test('carries the loaded savedAt through a reserialization, and stamps a fetch', async () => {
    const originalChain = new KeyChain(mint, unit);
    await originalChain.init();
    const fetchedAt = originalChain.cache.savedAt;
    expect(fetchedAt).toBeGreaterThan(0);

    const savedAt = 1_600_000_000_000;
    const restored = KeyChain.fromCache(mint, unit, { ...originalChain.cache, savedAt });
    expect(restored.cache.savedAt).toBe(savedAt);

    // A cache saved without the timestamp cannot invent one for the data it carries.
    const undated = KeyChain.fromCache(mint, unit, { ...originalChain.cache, savedAt: undefined });
    expect(undated.cache.savedAt).toBeUndefined();

    // A refresh from the mint is fresh data, so it takes the current time.
    await restored.init(true);
    expect(restored.cache.savedAt).toBeGreaterThan(savedAt);
  });

  test('loading a sat cache into a usd KeyChain still loads data; getKeysets throws for missing unit', async () => {
    const originalChain = new KeyChain(mint, unit); // 'sat'
    await originalChain.init();

    // Cache contains only sat keysets from dummy data
    const originalCache = originalChain.cache;

    // Load into a 'usd' KeyChain — no longer an error; queries filter by unit
    const usdChain = new KeyChain(mint, 'usd');
    usdChain.loadFromCache(originalCache);
    expect(() => usdChain.getKeysets()).toThrow(/No keysets found for unit: usd/);
    expect(() => usdChain.getCheapestKeyset()).toThrow(/No active keyset found for unit: usd/);
  });

  test('should preload from wire DTOs via mintToCacheDTO + fromCache', async () => {
    const originalChain = new KeyChain(mint, unit);
    await originalChain.init();

    // Decompose to wire DTOs and rebuild via static helpers
    const { keysets, keys } = KeyChain.cacheToMintDTO(originalChain.cache);
    const singleKeyset = keysets.filter((ks) => ks.id === keys[0].id);
    const singleKeys = [keys[0]];

    const cache = KeyChain.mintToCacheDTO(mintUrl, singleKeyset, singleKeys);
    const cachedChain = KeyChain.fromCache(mint, unit, cache);

    // Verify preloaded
    const cachedActive = cachedChain.getCheapestKeyset();
    expect(cachedActive.id).toBe(singleKeys[0].id);
    expect(cachedChain.getKeysets().length).toBe(1);
  });
});

describe('KeyChain getters', () => {
  let keyChain: KeyChain;

  beforeEach(async () => {
