import { bls12_381 } from '@noble/curves/bls12-381.js';
import { secp256k1 } from '@noble/curves/secp256k1.js';
import { bytesToHex, hexToBytes } from '@noble/curves/utils.js';
import { randomBytes } from '@noble/hashes/utils.js';
import { describe, expect, test } from 'vitest';

import {
  blindMessageBls,
  createBlindSignatureBls,
  deriveSecretAndBlindingFactor,
  pointFromHexG1,
  verifyUnblindedSignatureBls,
} from '../../src/crypto';
import { verifyUnblindedSignature } from '../../src/crypto/NUT01';
import {
  parseNutrootLeaf,
  recoverLeafKeySecretKeys,
  recoverReceiverKeyedSecretKey,
  type NutrootLeaf,
  type NutrootConditionLeaf,
} from '../../src/crypto/nutroot';
import { Amount } from '../../src/model/Amount';
import { CTSError } from '../../src/model/Errors';
import { OutputData } from '../../src/model/OutputData';
import type { HasKeysetKeys, SerializedBlindedSignature } from '../../src/model/types';
import { deriveKeysetId } from '../../src/utils';

// v3 (BLS12-381) round-trip through OutputData → simulated mint sign → toProof → pairing verify.
//
// Mint side is simulated with createBlindSignatureBls: there is no live mint, but the curve math
// is identical to what Nutshell PR #999 runs, so a successful pairing equality at the end is
// sufficient to demonstrate the wallet path (mint quote → swap → melt) is curve-correct end to end.

const AMOUNTS = [1, 2, 4, 8, 16, 32, 64];

function makeV3Keyset(): {
  keyset: HasKeysetKeys;
  privKeys: Record<string, Uint8Array>;
  G2PubKeys: Record<string, ReturnType<typeof bls12_381.G2.Point.BASE.multiply>>;
} {
  // Deterministic per-amount mint secrets so the test vector is stable.
  const privKeys: Record<string, Uint8Array> = {};
  const G2PubKeys: Record<string, ReturnType<typeof bls12_381.G2.Point.BASE.multiply>> = {};
  const keys: Record<string, string> = {};
  for (let i = 0; i < AMOUNTS.length; i++) {
    const a = AMOUNTS[i];
    const seed = new Uint8Array(32);
    seed[31] = i + 1; // 1..n, all in-range for Fr
    privKeys[String(a)] = seed;
    const aScalar = bls12_381.fields.Fr.fromBytes(seed);
    const K2 = bls12_381.G2.Point.BASE.multiply(aScalar);
    G2PubKeys[String(a)] = K2;
    keys[String(a)] = bytesToHex(K2.toBytes(true));
  }
  const id = deriveKeysetId(keys, { versionByte: 2, unit: 'sat' });
  return { keyset: { id, keys }, privKeys, G2PubKeys };
}

function signWithMint(
  output: OutputData,
  privKeys: Record<string, Uint8Array>,
  id: string,
): SerializedBlindedSignature {
  const amount = output.blindedMessage.amount;
  const a = privKeys[amount.toString()];
  const B_ = pointFromHexG1(output.blindedMessage.B_);
  const blind = createBlindSignatureBls(B_, a, id);
  return { id: blind.id, amount, C_: blind.C_.toHex(true) };
}

describe('OutputData v3 round-trip (BLS12-381)', () => {
  const { keyset, privKeys, G2PubKeys } = makeV3Keyset();

  // v3 secrets are 33-byte compressed points: the key behind the point signs the
  // spend witness, so outputs are built from a real keypair.
  const v3Output = (amount: number): OutputData =>
    OutputData.createSingleNutrootData(
      bytesToHex(secp256k1.getPublicKey(randomBytes(32), true)),
      amount,
      keyset.id,
    );

  test('keyset id is a valid v3 id (prefix 02, 66 hex chars)', () => {
    expect(keyset.id).toMatch(/^02[0-9a-f]{64}$/);
  });

  test('a v3 output produces a 96-hex G1 B_', () => {
    const out = v3Output(1);
    expect(out.blindedMessage.B_).toMatch(/^[0-9a-f]{96}$/);
    expect(out.blindedMessage.id).toBe(keyset.id);
  });

  test('nutroot output construction rejects the wrong keyset and off-curve secrets', () => {
    const valid = bytesToHex(secp256k1.getPublicKey(randomBytes(32), true));
    expect(() => OutputData.createSingleNutrootData(valid, 1, `01${'11'.repeat(32)}`)).toThrow(
      /v3 keyset/,
    );
    expect(() => OutputData.createSingleNutrootData(`02${'ff'.repeat(32)}`, 1, keyset.id)).toThrow(
      /point secrets/,
    );
  });

  test('createSingleRandomData gives a v3 output a real keypair', () => {
    // v3 secrets are points, so a random secret is a random keypair; the key
    // rides along because it signs the spend witness later.
    const out = OutputData.createSingleRandomData(1, keyset.id);
    const secretHex = new TextDecoder().decode(out.secret);
    expect(secretHex).toMatch(/^0[23][0-9a-f]{64}$/);
    expect(out.secretKey).toBeDefined();
    expect(bytesToHex(secp256k1.getPublicKey(out.secretKey as Uint8Array, true))).toBe(secretHex);
    expect(out.spendInfo?.k).toBe(bytesToHex(out.secretKey as Uint8Array));
    const proof = out.toProof(signWithMint(out, privKeys, keyset.id), keyset);
    expect(proof.spend_info?.k).toBe(out.spendInfo?.k);
  });

  test('deserialize round-trips a v3 output, including its spend info', () => {
    const out = OutputData.createSingleRandomData(1, keyset.id);
    const restored = OutputData.deserialize(OutputData.serialize(out));
    expect(restored.blindedMessage.B_).toBe(out.blindedMessage.B_);
    expect(restored.spendInfo).toEqual(out.spendInfo);
  });

  test('deserialize rejects a v3 payload whose secret is not a point', () => {
    const serialized = OutputData.serialize(OutputData.createSingleRandomData(1, keyset.id));
    expect(() =>
      OutputData.deserialize({
        ...serialized,
        secret: bytesToHex(new TextEncoder().encode('not-a-point')),
      }),
    ).toThrow(/point secret/i);
  });

  // ~21 BLS pairings (7 amounts × 3 verifications each). Locally ~700ms, but under the
  // 4-environment parallel run (node + chromium + firefox + webkit), CPU contention can
  // push this past the 5s default. Bumped to absorb that noise.
  test('full mint → swap path: outputs round-trip and verify under pairing', () => {
    const outputs = AMOUNTS.map((a) => v3Output(a));
    const sigs = outputs.map((o) => signWithMint(o, privKeys, keyset.id));

    const proofs = outputs.map((o, i) => o.toProof(sigs[i], keyset));

    expect(proofs).toHaveLength(AMOUNTS.length);
    for (let i = 0; i < proofs.length; i++) {
      const p = proofs[i];
      expect(p.id).toBe(keyset.id);
      expect(p.C).toMatch(/^[0-9a-f]{96}$/);
      expect(p.amount).toEqual(Amount.from(AMOUNTS[i]));
      expect((p as { dleq?: unknown }).dleq).toBeUndefined();
      // Wallet-side pairing check (mirrors what the next mint operation will run in batch).
      const K2 = G2PubKeys[p.amount.toString()];
      const C = pointFromHexG1(p.C);
      const secret = new TextEncoder().encode(p.secret);
      expect(verifyUnblindedSignatureBls(K2, C, secret)).toBe(true);
      // Mint-side equality check matches verifyUnblindedSignature dispatch.
      expect(verifyUnblindedSignature({ id: p.id, C, secret }, privKeys[p.amount.toString()])).toBe(
        true,
      );
    }
  }, 15000);

  test('deterministic v3 derivation produces a verifiable proof', () => {
    const seed = hexToBytes('11'.repeat(32));
    const out = OutputData.createSingleDeterministicData(4, seed, 0, keyset.id);
    expect(out.blindedMessage.B_).toMatch(/^[0-9a-f]{96}$/);

    const sig = signWithMint(out, privKeys, keyset.id);
    const proof = out.toProof(sig, keyset);
    expect(proof.dleq).toBeUndefined();
    expect(proof.spend_info?.k).toBe(bytesToHex(out.secretKey!));
    expect(bytesToHex(secp256k1.getPublicKey(out.secretKey!, true))).toBe(proof.secret);

    const C = pointFromHexG1(proof.C);
    const secret = new TextEncoder().encode(proof.secret);
    expect(verifyUnblindedSignatureBls(G2PubKeys['4'], C, secret)).toBe(true);
  });

  test('deterministic v3 outputs carry their derived key as spend info', () => {
    const seed = hexToBytes('22'.repeat(32));
    const outputs = OutputData.createDeterministicData(7, seed, 5, keyset);
    expect(outputs).toHaveLength(3);
    outputs.forEach((out, i) => {
      const derived = deriveSecretAndBlindingFactor(seed, keyset.id, 5 + i);
      const secretHex = new TextDecoder().decode(out.secret);
      expect(out.secretKey).toEqual(derived.secretKey);
      expect(bytesToHex(secp256k1.getPublicKey(out.secretKey as Uint8Array, true))).toBe(secretHex);
      expect(out.spendInfo).toEqual({ k: bytesToHex(derived.secretKey as Uint8Array) });
      const proof = out.toProof(signWithMint(out, privKeys, keyset.id), keyset);
      expect(proof.spend_info).toEqual(out.spendInfo);
    });
  });

  test('deterministic secp outputs carry no key or spend info', () => {
    const seed = hexToBytes('22'.repeat(32));
    const out = OutputData.createSingleDeterministicData(1, seed, 0, `01${'ab'.repeat(32)}`);
    expect(out.secretKey).toBeUndefined();
    expect(out.spendInfo).toBeUndefined();
  });

  test('toProof rejects a forged C_ via inline pairing check', () => {
    const out = v3Output(8);

    // Forge: substitute another amount's signing key on the same B_. The resulting C does not
    // satisfy `e(C, G2) == e(Y, K2_8)`, so toProof's inline pairing check MUST throw. This is
    // the mint/swap-path defence against a malicious mint returning garbage — without it the
    // wallet would store an invalid proof, mark inputs spent, and lose funds.
    const B_ = pointFromHexG1(out.blindedMessage.B_);
    const forged = createBlindSignatureBls(B_, privKeys['16'], keyset.id);
    const tamperedSig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: out.blindedMessage.amount,
      C_: forged.C_.toHex(true),
    };
    expect(() => out.toProof(tamperedSig, keyset)).toThrowError(/BLS pairing verification failed/);
  });

  test('toProof rejects a completely garbage C_ (CTF: malicious mint)', () => {
    const out = v3Output(8);
    // A G1 point unrelated to the output's Y is overwhelmingly unlikely to satisfy the pairing.
    const garbageC_ = bls12_381.G1.Point.BASE.multiply(424242n);
    const garbageSig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: out.blindedMessage.amount,
      C_: garbageC_.toHex(true),
    };
    expect(() => out.toProof(garbageSig, keyset)).toThrowError(/BLS pairing verification failed/);
  });

  test('round-trip preserves the wallet-chosen secret bytes', () => {
    const out = v3Output(2);
    const originalSecret = new TextDecoder().decode(out.secret);
    const sig = signWithMint(out, privKeys, keyset.id);
    const proof = out.toProof(sig, keyset);
    expect(proof.secret).toBe(originalSecret);
  });

  test('toProof rejects amount downgrade (malicious mint)', () => {
    // Request amount=8; mint returns a perfectly valid v3 signature for amount=4 on the
    // same B_. The pairing check against K2_4 would succeed — funds-loss vector if the
    // request/response amount mismatch is not enforced before key lookup.
    const out = v3Output(8);
    const B_ = pointFromHexG1(out.blindedMessage.B_);
    const downgraded = createBlindSignatureBls(B_, privKeys['4'], keyset.id);
    const downgradedSig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: Amount.from(4),
      C_: downgraded.C_.toHex(true),
    };
    expect(() => out.toProof(downgradedSig, keyset)).toThrowError(
      /does not match requested amount/,
    );
  });

  test('maps malformed BLS C_ to a CTSError with NUT-09 hint', () => {
    // A buggy or malicious mint that returns un-parseable hex must not leak a generic
    // Error after the inputs have been destroyed. toProof must surface a CTSError that
    // tells the wallet how to recover.
    const out = v3Output(1);
    const sig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: Amount.from(1),
      C_: 'not-hex',
    };
    expect(() => out.toProof(sig, keyset)).toThrowError(
      /Mint returned invalid signature or amount\. .*NUT-09/,
    );
  });

  test('maps missing keyset key for blank output to a CTSError with NUT-09 hint', () => {
    // Blank outputs (amount=0) let the mint pick the denomination. If the picked amount
    // isn't in our keyset, keys[amount] is undefined and pointFromHexG2(undefined) used
    // to throw an opaque TypeError — now it must be a CTSError with the recovery hint.
    const blank = v3Output(0);
    const B_ = pointFromHexG1(blank.blindedMessage.B_);
    // 128 (not in AMOUNTS) — mint signs with some scalar but the wallet has no K2_128.
    const signed = createBlindSignatureBls(B_, privKeys['2'], keyset.id);
    const sig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: Amount.from(128),
      C_: signed.C_.toHex(true),
    };
    expect(() => blank.toProof(sig, keyset)).toThrowError(
      /Mint returned invalid signature or amount\. .*NUT-09/,
    );
  });

  test('toProof accepts amount=0 blank (NUT-08 fee change / NUT-09 restore)', () => {
    // Blank outputs declare amount=0 up front; the mint chooses the actual denomination.
    // toProof must trust sig.amount for key lookup and final Proof.amount in this case.
    const blank = v3Output(0);
    const B_ = pointFromHexG1(blank.blindedMessage.B_);
    // Mint fills in amount=2 from the blank
    const filled = createBlindSignatureBls(B_, privKeys['2'], keyset.id);
    const sig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: Amount.from(2),
      C_: filled.C_.toHex(true),
    };
    const proof = blank.toProof(sig, keyset);
    expect(proof.amount).toEqual(Amount.from(2));
    const C = pointFromHexG1(proof.C);
    const secret = new TextEncoder().encode(proof.secret);
    expect(verifyUnblindedSignatureBls(G2PubKeys['2'], C, secret)).toBe(true);
  });

  test('wraps a missing v3 keyset key with the underlying cause', () => {
    // Blank output, mint returns amount=128 which is not in the keyset, so `keys[128]` is
    // undefined. The CTSError must carry a cause that names the offending amount, not an opaque
    // downstream parse error.
    const blank = v3Output(0);
    const B_ = pointFromHexG1(blank.blindedMessage.B_);
    const signed = createBlindSignatureBls(B_, privKeys['2'], keyset.id);
    const sig: SerializedBlindedSignature = {
      id: keyset.id,
      amount: Amount.from(128),
      C_: signed.C_.toHex(true),
    };
    let caught: unknown;
    try {
      blank.toProof(sig, keyset);
    } catch (e) {
      caught = e;
    }
    expect(caught).toBeInstanceOf(CTSError);
    expect((caught as CTSError).message).toMatch(/Mint returned invalid signature or amount/);
    const cause = (caught as CTSError).cause;
    expect(cause).toBeInstanceOf(Error);
    expect((cause as Error).message).toMatch(/Amount 128 not in keyset/);
  });

  test('does not attach p2pk_e when the output has no ephemeral key', () => {
    const out = v3Output(1);
    const proof = out.toProof(signWithMint(out, privKeys, keyset.id), keyset);
    expect('p2pk_e' in proof).toBe(false);
  });

  test('refuses a NUT-10 P2PK output on a v3 keyset', () => {
    // P2PK is a NUT-10 well-known secret, which belongs to legacy/v1/v2 keysets.
    // The v3 way to lock to a key is a point secret, tweaked or bare.
    const secpPubkey = '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798';
    expect(() =>
      OutputData.createSingleP2PKData(
        { kind: 'P2PK', data: secpPubkey, blindKeys: true },
        1,
        keyset.id,
      ),
    ).toThrow(CTSError);
  });
});

describe('OutputData v3 — Nutshell PR #999 deterministic test vector', () => {
  // Cross-check the integration path against the locked Nutshell vector (secret="test_message",
  // r=3, mint scalar a=2). This is the same vector as test/crypto/bls.test.ts but exercised
  // through the OutputData factory + toProof path, so any future regression in the path
  // (and not the primitives) is caught here.
  const SECRET = 'test_message';
  const NUTSHELL_B_HEX =
    '8e88c5f6a93f653784a66b033a00e52128499e18b095c2a56f080d1c2a937ffc9ef4600804a48d087bbd1f662f6b068f';
  const NUTSHELL_C_HEX =
    'b7a4881059133fd91a8753600d9a5e524c65d6224f6fe2d5aef9e59f1507fdad90b3b4d48ee46da5c8dfaa0b88e28b69';

  test('matches Nutshell B_ and C through toProof', () => {
    // Drive the deterministic blinding directly via blindMessageBls so we hit the exact r=3.
    const secretBytes = new TextEncoder().encode(SECRET);
    const { B_, r } = blindMessageBls(secretBytes, 3n);
    expect(bytesToHex(B_.toBytes(true))).toBe(NUTSHELL_B_HEX);

    const id = '02' + '00'.repeat(32); // arbitrary v3-shaped id — toProof dispatches on prefix only
    // Construct the OutputData directly (not via deserialize, which requires a v3 point secret)
    // so we can lock r=3 exactly against this plain-text cross-implementation vector.
    const od = new OutputData({ amount: Amount.from(1), B_: B_.toHex(true), id }, r, secretBytes);

    const aBytes = hexToBytes('0'.repeat(63) + '2'); // mint scalar a=2
    const { C_ } = createBlindSignatureBls(B_, aBytes, id);

    const sig: SerializedBlindedSignature = {
      id,
      amount: Amount.from(1),
      C_: C_.toHex(true),
    };
    // K2 = a·G2_BASE for a=2 — required for the inline pairing check inside toProof.
    const K2Hex = bytesToHex(bls12_381.G2.Point.BASE.multiply(2n).toBytes(true));
    const proof = od.toProof(sig, { id, keys: { '1': K2Hex } });
    expect(proof.C).toBe(NUTSHELL_C_HEX);
    expect(proof.secret).toBe(SECRET);
  });
});

describe('OutputData.createNutrootData (receiver-keyed, NUT-28)', () => {
  const { keyset, privKeys } = makeV3Keyset();
  const bobPriv = bytesToHex(randomBytes(32));
  const bobPub = bytesToHex(secp256k1.getPublicKey(hexToBytes(bobPriv), true));

  test('one fresh ephemeral per output, and the payee recovers each key', () => {
    const outputs = OutputData.createNutrootData({ receiverKey: bobPub }, 7, keyset);
    expect(outputs.map((o) => o.blindedMessage.amount.toString()).sort()).toEqual(['1', '2', '4']);
    // Fresh e per output (NUT-28): distinct ephemerals, so distinct secrets.
    const ephemerals = outputs.map((o) => o.spendInfo?.E);
    expect(new Set(ephemerals).size).toBe(3);
    expect(new Set(outputs.map((o) => new TextDecoder().decode(o.secret))).size).toBe(3);
    for (const out of outputs) {
      const proof = out.toProof(signWithMint(out, privKeys, keyset.id), keyset);
      // Spend info travels onto the proof, and Bob trial-matches it.
      expect(proof.spend_info?.E).toBe(out.spendInfo?.E);
      expect(proof.spend_info?.tree).toBeUndefined();
      const hit = recoverReceiverKeyedSecretKey(proof.secret, proof.spend_info!.E!, bobPriv);
      expect(hit).toBeDefined();
      expect(bytesToHex(secp256k1.getPublicKey(hexToBytes(hit!.secretKey), true))).toBe(
        proof.secret,
      );
    }
  });

  test('a requested tree travels with each output, with blind-me keys blinded', () => {
    const alicePriv = bytesToHex(randomBytes(32));
    const alicePub = bytesToHex(secp256k1.getPublicKey(hexToBytes(alicePriv), true));
    const leaves: NutrootLeaf[] = [{ type: 'after', n: 1, keys: [alicePub], time: 4102444800 }];
    const [out] = OutputData.createNutrootData(
      { receiverKey: bobPub, leaves, blindKeys: [alicePub] },
      1,
      keyset,
    );
    const proof = out.toProof(signWithMint(out, privKeys, keyset.id), keyset);
    const tree = proof.spend_info!.tree!;
    expect(tree).toHaveLength(1);
    // The leaf key is not Alice's key verbatim, but Alice still finds it at slot 1.
    expect((parseNutrootLeaf(hexToBytes(tree[0])) as NutrootConditionLeaf).keys[0]).not.toBe(
      alicePub,
    );
    expect(recoverLeafKeySecretKeys(tree, proof.spend_info!.E, [alicePriv])).toEqual([
      { leafIndex: 0, keyIndex: 0, slot: 1, secretKey: expect.any(String), blinded: true },
    ]);
    // And Bob's key path still reconstructs the tweaked secret over that tree.
    const hit = recoverReceiverKeyedSecretKey(proof.secret, proof.spend_info!.E!, bobPriv, tree);
    expect(hit).toBeDefined();
  });

  test('nutroot outputs are refused on a pre-v3 keyset', () => {
    const secpKeyset = { id: '00ad268c4d1f5826', keys: { '1': '02'.padEnd(66, 'a') } };
    expect(() => OutputData.createNutrootData({ receiverKey: bobPub }, 1, secpKeyset)).toThrow(
      /v3 keyset/,
    );
  });
});

