import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { JSONInt } from '../../src/utils/JSONInt';

describe('bigint support baseline', () => {
  const input = '{"big":9223372036854775807,"small":123}';

  test('classic JSON.parse lacks bigint precision', () => {
    const obj = JSON.parse(input) as { big: number; small: number };
    expect(obj.small.toString()).toBe('123');
    expect(obj.big.toString()).not.toBe('9223372036854775807');

    const output = JSON.stringify(obj);
    expect(output).not.toBe(input);
  });
});

describe('native BigInt support: parse', () => {
  const input = '{"big":92233720368547758070,"small":123}';

  test('parses oversized integer tokens as bigint', () => {
    const obj = JSONInt.parse(input) as { big: bigint; small: number };
    expect(obj.small).toBe(123);
    expect(obj.big.toString()).toBe('92233720368547758070');
    expect(typeof obj.big).toBe('bigint');
  });

  test('supports parse/stringify roundtrip', () => {
    const obj = JSONInt.parse(input);
    const output = JSONInt.stringify(obj);
    expect(output).toBe(input);
  });

  test('supports long floats', () => {
    const obj = JSONInt.parse('{"float":0.333333333333333333333333333333333333333333333333}') as {
      float: number;
    };
    expect(obj.float).toBe(0.3333333333333333);
  });
});

describe('native BigInt support: stringify', () => {
  test('stringifies native BigInt values as JSON number tokens', () => {
    const obj = {
      big: BigInt('123456789012345678901234567890'),
      small: -42,
      bigConstructed: BigInt(1),
      smallConstructed: Number(2),
    };

    expect(obj.small.toString()).toBe('-42');
    expect(obj.big.toString()).toBe('123456789012345678901234567890');
    expect(typeof obj.big).toBe('bigint');

    const output = JSONInt.stringify(obj);
    expect(output).toBe(
      '{"big":123456789012345678901234567890,"small":-42,"bigConstructed":1,"smallConstructed":2}',
    );
  });

  test('rejects a BigInt whose decimal form exceeds the token cap (symmetric with parse)', () => {
    const ok = BigInt('9'.repeat(100));
    const out = JSONInt.stringify(ok)!;
    expect(out).toBe('9'.repeat(100));
    expect(JSONInt.parse(out)).toBe(ok); // round-trips at the boundary
    // A value the parser would reject must not be emittable, so output always round-trips.
    expect(() => JSONInt.stringify(BigInt('9'.repeat(101)))).toThrow('exceeds 100 characters');
  });

  test('stringifies arrays with undefined as null', () => {
    const output = JSONInt.stringify([1, undefined, 3]);
    expect(output).toBe('[1,null,3]');
  });

  test('stringifies objects dropping undefined values', () => {
    const output = JSONInt.stringify({ a: 1, b: undefined, c: 3 });
    expect(output).toBe('{"a":1,"c":3}');
  });

  test('returns undefined for root undefined', () => {
    expect(JSONInt.stringify(undefined)).toBeUndefined();
  });

  test('respects toJSON output', () => {
    const output = JSONInt.stringify({ value: { toJSON: () => 'ok' } });
    expect(output).toBe('{"value":"ok"}');
  });

  test('supports replacer array and pretty spacing', () => {
    const output = JSONInt.stringify({ a: 1, b: 2, c: 3 }, ['b', 'c'], 2);
    expect(output).toBe('{\n  "b": 2,\n  "c": 3\n}');
  });

  test('deduplicates repeated replacer keys like native JSON.stringify', () => {
    const payload = 'x'.repeat(2_048);
    const repeatedKeys = Array.from({ length: 64 }, () => 'payload');
    expect(JSONInt.stringify({ payload }, repeatedKeys)).toBe(
      JSON.stringify({ payload }, repeatedKeys),
    );
  });

  test('skips replacer entries that are not strings or numbers like native JSON.stringify', () => {
    const value = { a: 1, null: 2, '[object Object]': 3, true: 4, 5: 6 };
    const replacer = ['a', null, {}, true, 5] as unknown as string[];
    expect(JSONInt.stringify(value, replacer)).toBe(JSON.stringify(value, replacer));
  });

  test('caps a string space argument to 10 characters like native JSON.stringify', () => {
    const value = { outer: { value: 1 }, sibling: 2 };
    const longSpace = ' '.repeat(1_000);
    expect(JSONInt.stringify(value, undefined, longSpace)).toBe(
      JSON.stringify(value, undefined, longSpace),
    );
  });

  test('supports replacer function for filtering', () => {
    const output = JSONInt.stringify({ a: 1, b: 2 }, (key, value) =>
      key === 'b' ? undefined : value,
    );
    expect(output).toBe('{"a":1}');
  });

  test('unboxes boxed primitives like native JSON.stringify', () => {
    expect(JSONInt.stringify(new Number(2))).toBe('2');
    expect(JSONInt.stringify(new String('x'))).toBe('"x"');
    expect(JSONInt.stringify(new Boolean(false))).toBe('false');
  });

  test('unboxes boxed primitives nested in objects and arrays', () => {
    const output = JSONInt.stringify({
      amount: new Number(2),
      label: new String('x'),
      flags: [new Boolean(false), new Number(3)],
    });
    expect(output).toBe('{"amount":2,"label":"x","flags":[false,3]}');
  });

  test('throws TypeError on circular references', () => {
    const obj: { self?: unknown } = {};
    obj.self = obj;

    expect(() => JSONInt.stringify(obj)).toThrow(TypeError);
    expect(() => JSONInt.stringify(obj)).toThrow('Converting circular structure to JSON');
  });
});

describe('parse option: strict', () => {
  const dupkeys = '{ "dupkey": "value 1", "dupkey": "value 2"}';

  test('duplicate keys overwrite by default', () => {
    let result: unknown = 'before';
    const tryParse = () => {
      result = JSONInt.parse(dupkeys);
    };
    expect(tryParse).not.toThrow();
    expect((result as { dupkey: string }).dupkey).toBe('value 2');
  });

  test('strict=true fails fast on duplicate keys', () => {
    let result: unknown = 'before';
    const tryParse = () => {
      result = JSONInt.parse(dupkeys, undefined, { strict: true });
    };

    expect(tryParse).toThrow('Duplicate key "dupkey"');
    expect(result).toBe('before');
  });
});

describe('parse option: fallbackTo', () => {
  const input = '{ "key": 12345678901234567 }';
  const originalBigInt = globalThis.BigInt;

  beforeAll(() => {
    Object.defineProperty(globalThis, 'BigInt', {
      configurable: true,
      writable: true,
      value: undefined,
    });
  });

  afterAll(() => {
    Object.defineProperty(globalThis, 'BigInt', {
      configurable: true,
      writable: true,
      value: originalBigInt,
    });
  });

  test('defaults to number when BigInt is unavailable', () => {
    const result = JSONInt.parse(input) as { key: number };
    expect(typeof result.key).toBe('number');
    // eslint-disable-next-line no-loss-of-precision -- precision loss is what's asserted
    expect(result.key).toBe(12345678901234567);
  });

  test('returns string when fallbackTo=string', () => {
    const result = JSONInt.parse(input, undefined, { fallbackTo: 'string' }) as {
      key: string;
    };
    expect(typeof result.key).toBe('string');
    expect(result.key).toBe('12345678901234567');
  });

  test('throws when fallbackTo=error', () => {
    expect(() => {
      JSONInt.parse(input, undefined, { fallbackTo: 'error' });
    }).toThrow();
  });

  test('throws when fallbackTo has invalid value', () => {
    expect(() => {
      JSONInt.parse(input, undefined, { fallbackTo: 'nope' as never });
    }).toThrow('Incorrect value for fallbackTo option');
  });
});

describe('__proto__ and constructor assignment', () => {
  test('sets __proto__ property without changing object prototype', () => {
    const obj1 = JSONInt.parse('{ "__proto__": 1000000000000000 }') as Record<string, unknown>;
    expect(Object.getPrototypeOf(obj1)).toBe(Object.prototype);

    const obj2 = JSONInt.parse('{ "__proto__": { "admin": true } }') as {
      admin?: boolean;
    };
    expect(obj2.admin).not.toBe(true);
  });

  test('reviver write-back keeps __proto__ as an own data property', () => {
    const parsed = JSONInt.parse('{"__proto__":{"admin":true}}', function (key, value) {
      if (key === '__proto__') {
        Reflect.deleteProperty(this as object, key);
      }
      return value;
    }) as { admin?: boolean };

    expect(Object.getPrototypeOf(parsed)).toBe(Object.prototype);
    expect(Object.prototype.hasOwnProperty.call(parsed, '__proto__')).toBe(true);
    expect(parsed.admin).toBeUndefined();
  });

  test('reviver write-back keeps the earlier value when a key was made non-configurable mid-walk', () => {
    // Matches native JSON.parse: CreateDataProperty ignores a failed define instead of throwing.
    const parsed = JSONInt.parse('{"a":1}', function (key, value) {
      if (key === 'a') {
        Object.defineProperty(this as object, key, {
          value: 99,
          writable: false,
          enumerable: true,
          configurable: false,
        });
        return 2;
      }
      return value;
    }) as { a: number };

    expect(parsed.a).toBe(99);
  });
});

describe('parse errors', () => {
  test('rejects invalid escape sequences', () => {
    expect(() => JSONInt.parse('"\\x"')).toThrow('Invalid escape');
  });

  test('rejects invalid unicode escapes', () => {
    expect(() => JSONInt.parse('"\\u12G4"')).toThrow('Invalid unicode escape');
  });

  test('rejects unterminated strings', () => {
    expect(() => JSONInt.parse('"unterminated')).toThrow('Unterminated string');
  });

  test('rejects unterminated arrays', () => {
    expect(() => JSONInt.parse('[1, 2')).toThrow("Expected ','");
  });

  test('rejects unterminated objects', () => {
    expect(() => JSONInt.parse('{"a": 1')).toThrow("Expected ','");
  });

  test('rejects bad number tokens', () => {
    expect(() => JSONInt.parse('-')).toThrow('Bad number');
    expect(() => JSONInt.parse('1e+')).toThrow('Bad number');
  });

  test('rejects trailing input', () => {
    expect(() => JSONInt.parse('true false')).toThrow('Unexpected trailing input');
  });

  test('rejects oversized integer tokens', () => {
    expect(JSONInt.parse('9'.repeat(100))).toBe(BigInt('9'.repeat(100)));
    expect(() => JSONInt.parse('9'.repeat(101))).toThrow('Number token too long');
    expect(() => JSONInt.parse(`{"amount":${'9'.repeat(101)}}`)).toThrow('Number token too long');
  });

  test('accepts nesting up to the depth cap and rejects one level beyond', () => {
    const nested = (depth: number) => '['.repeat(depth) + ']'.repeat(depth);
    expect(JSONInt.parse(nested(65))).toBeDefined();
    expect(() => JSONInt.parse(nested(66))).toThrow('nesting exceeds the maximum depth');
  });

  test('deeply nested input throws a parse error, not a stack overflow', () => {
    const deep = '['.repeat(100_000) + ']'.repeat(100_000);
    expect(() => JSONInt.parse(deep)).toThrow(SyntaxError);
    expect(() => JSONInt.parse(deep)).not.toThrow(RangeError);
  });
});

describe('reviver behavior', () => {
  test('reviver can drop object properties', () => {
    const out = JSONInt.parse('{"a":1,"b":2}', (key, value) => (key === 'b' ? undefined : value));
    expect(out).toEqual({ a: 1 });
  });

  test('reviver can transform array entries', () => {
    const out = JSONInt.parse('[1,2,3]', (key, value) => (key === '1' ? 20 : value));
    expect(out).toEqual([1, 20, 3]);
  });

  test('reviver can delete array entries', () => {
    const out = JSONInt.parse('[1,2,3]', (key, value) =>
      key === '1' ? undefined : value,
    ) as number[];
    expect(out.length).toBe(3);
    expect(1 in out).toBe(false);
  });
});

describe('JSON conformance: native JSON is the oracle', () => {
  test('escape sequences parse exactly as native JSON.parse', () => {
    const input = '"a\\b\\f\\n\\r\\t\\u0041\\\\\\"\\/z"';
    expect(JSONInt.parse(input)).toBe(JSON.parse(input));
  });

  test('invalid escapes and raw control characters reject', () => {
    expect(() => JSONInt.parse('"\\uZZZZ"')).toThrow(/unicode escape/i);
    expect(() => JSONInt.parse('"a\x01b"')).toThrow(/control character/i);
    expect(() => JSON.parse('"a\x01b"')).toThrow(); // native agrees both are invalid
    expect(() => JSON.parse('"\\uZZZZ"')).toThrow();
  });

  test('unterminated containers reject', () => {
    expect(() => JSONInt.parse('{"a":1')).toThrow(/Expected/);
    expect(() => JSONInt.parse('[1,2')).toThrow(/Expected/);
    expect(() => JSONInt.parse('{"a":1,')).toThrow(/Unterminated object/);
    expect(() => JSONInt.parse('[1,')).toThrow(/Unterminated array/);
    for (const input of ['{"a":1', '[1,2', '{"a":1,', '[1,']) {
      expect(() => JSON.parse(input)).toThrow(); // native agrees all four are invalid
    }
  });

  test('stringify honours space exactly as native, including the 10-char clamp', () => {
    const obj = { a: [1, { b: 'x' }], c: null };
    for (const space of [2, 10, 20, '\t', '--'] as const) {
      expect(JSONInt.stringify(obj, undefined, space)).toBe(JSON.stringify(obj, undefined, space));
    }
  });

  test('functions and symbols drop exactly as native', () => {
    expect(JSONInt.stringify(() => 1)).toBe(undefined);
    expect(JSONInt.stringify(Symbol('s'))).toBe(undefined);
    const mixed = { f: () => 1, s: Symbol('s'), keep: 1 };
    expect(JSONInt.stringify(mixed)).toBe(JSON.stringify(mixed));
  });

  test('a non-function, non-array replacer throws instead of being silently ignored', () => {
    // Deliberately stricter than native (which ignores it): a bad replacer is a caller bug.
    expect(() =>
      JSONInt.stringify({ a: 1 }, 42 as unknown as (k: string, v: unknown) => unknown),
    ).toThrow(/replacer/);
  });
});

