import { randomBytes } from '@noble/hashes/utils.js';
import { HttpResponse, http } from 'msw';
import { test, describe, expect } from 'vitest';

import { Wallet, type MintKeys, type MintKeyset } from '../../src';
import { Amount } from '../../src/model/Amount';
import { deriveKeysetId, isValidHex, isBase64String } from '../../src/utils';
import { DUMMY_TEST_KEYS, DUMMY_TEST_KEYSET, PUBKEYS } from '../consts';

import { useTestServer, mint, mintUrl, token3sat } from './_setup';

const server = useTestServer();

// Legacy (pre-v1) deprecated base64 keyset whose id verifies against its keys
const legacyId = deriveKeysetId(PUBKEYS, { isDeprecatedBase64: true });
const legacyKeyset: MintKeyset = { id: legacyId, unit: 'sat', active: true, input_fee_ppk: 0 };
const legacyKeys: MintKeys = { ...legacyKeyset, keys: PUBKEYS };

// Inactive v2 (01-prefixed) keyset whose id verifies against its keys
const inactiveId = deriveKeysetId(PUBKEYS, { versionByte: 1, unit: 'sat' });
const inactiveKeyset: MintKeyset = { id: inactiveId, unit: 'sat', active: false, input_fee_ppk: 0 };
const inactiveKeys: MintKeys = { ...inactiveKeyset, keys: PUBKEYS };

// valid compressed secp point (any well-formed 33-byte point will do)
const VALID_POINT = '021179b095a67380ab3285424b563b7aab9818bd38068e1930641b3dceb364d422';

function useLegacyHandlers() {
  server.use(
    http.get(mintUrl + '/v1/keysets', () =>
      HttpResponse.json({ keysets: [DUMMY_TEST_KEYSET, legacyKeyset] }),
    ),
    http.get(mintUrl + '/v1/keys', () =>
      HttpResponse.json({ keysets: [DUMMY_TEST_KEYS, legacyKeys] }),
    ),
  );
}

function useInactiveHandlers() {
  server.use(
    http.get(mintUrl + '/v1/keysets', () =>
      HttpResponse.json({ keysets: [DUMMY_TEST_KEYSET, inactiveKeyset] }),
    ),
    http.get(mintUrl + '/v1/keys', () =>
      HttpResponse.json({ keysets: [DUMMY_TEST_KEYS, inactiveKeys] }),
    ),
  );
}

describe('Legacy (pre-v1) keyset output gating', () => {
  test('fixture sanity: legacy keyset id is base64, not hex, and verifies', async () => {
    expect(isValidHex(legacyId)).toBe(false);
    expect(isBase64String(legacyId)).toBe(true);

    useLegacyHandlers();
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    // Keys must survive keychain verification, or the gate test below would
    // pass for the wrong reason ('Keyset has no keys loaded').
    const keyset = wallet.keyChain.getKeyset(legacyId);
    expect(keyset.hasKeys).toBe(true);
    expect(keyset.hasHexId).toBe(false);
  });

  test('prepareMint refuses to create proofs on a legacy keyset', async () => {
    useLegacyHandlers();
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    await expect(
      wallet.prepareMint(
        'bolt11',
        3,
        {
          quote: 'test-quote',
          unit: 'sat',
          amount_paid: Amount.from(0),
          amount_issued: Amount.from(0),
        },
        { keysetId: legacyId },
      ),
    ).rejects.toThrow(/legacy keyset/i);
  });

  test('receive refuses to create proofs on a legacy keyset', async () => {
    useLegacyHandlers();
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    await expect(wallet.receive(token3sat, { keysetId: legacyId })).rejects.toThrow(
      /legacy keyset/i,
    );
  });

  test('prepareMint still works on the bound (hex) keyset', async () => {
    useLegacyHandlers();
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    const preview = await wallet.prepareMint('bolt11', 3, {
      quote: 'test-quote',
      unit: 'sat',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
    });
    expect(preview.outputData[0].blindedMessage.id).toBe(DUMMY_TEST_KEYSET.id);
  });

  test('prepareMint refuses to create proofs on an inactive keyset', async () => {
    useInactiveHandlers();
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    // Fixture sanity: keys must survive verification so the gate fails for
    // the right reason (not 'Keyset has no keys loaded').
    const keyset = wallet.keyChain.getKeyset(inactiveId);
    expect(keyset.hasKeys).toBe(true);
    expect(keyset.isActive).toBe(false);

    await expect(
      wallet.prepareMint(
        'bolt11',
        3,
        {
          quote: 'test-quote',
          unit: 'sat',
          amount_paid: Amount.from(0),
          amount_issued: Amount.from(0),
        },
        { keysetId: inactiveId },
      ),
    ).rejects.toThrow(/inactive keyset/i);
  });

  test('completeMint constructs proofs even if the keyset was deactivated after prepare', async () => {
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    const preview = await wallet.prepareMint('bolt11', 3, {
      quote: 'test-quote',
      unit: 'sat',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
    });

    // Keyset rotates to inactive between prepare and complete. The mint has
    // already signed; refusing to construct proofs would strand the ecash.
    server.use(
      http.get(mintUrl + '/v1/keysets', () =>
        HttpResponse.json({ keysets: [{ ...DUMMY_TEST_KEYSET, active: false }] }),
      ),
      http.get(mintUrl + '/v1/keys', () =>
        HttpResponse.json({ keysets: [{ ...DUMMY_TEST_KEYS, active: false }] }),
      ),
      http.post(mintUrl + '/v1/mint/bolt11', () =>
        HttpResponse.json({
          signatures: preview.outputData.map((d) => ({
            id: d.blindedMessage.id,
            amount: Number(d.blindedMessage.amount.toString()),
            C_: VALID_POINT,
          })),
        }),
      ),
    );
    await wallet.loadMint(true);

    const proofs = await wallet.completeMint(preview);
    expect(proofs).toHaveLength(preview.outputData.length);
  });

  test('mint quotes are refused when the mint has no active keyset', async () => {
    // Mint only has an inactive keyset: loadMint tolerates this (wallet
    // remains unbound), but a paid quote could never be redeemed for proofs.
    server.use(
      http.get(mintUrl + '/v1/keysets', () => HttpResponse.json({ keysets: [inactiveKeyset] })),
      http.get(mintUrl + '/v1/keys', () => HttpResponse.json({ keysets: [inactiveKeys] })),
    );
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    await expect(
      wallet.createMintQuoteBolt11(
        1000,
        '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798',
      ),
    ).rejects.toThrow(/no active keyset/i);
    await expect(wallet.createMintQuote('bolt11', { amount: 1000 })).rejects.toThrow(
      /no active keyset/i,
    );
  });

  test('generic quote methods refuse methods the mint does not advertise (NUT-04/05)', async () => {
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    await expect(wallet.createMintQuote('fancypay', { amount: 1000 })).rejects.toThrow(
      /does not support/i,
    );
    await expect(wallet.createMeltQuote('fancypay', { request: 'x' })).rejects.toThrow(
      /does not support/i,
    );
  });

  test('mint quotes still work when an active keyset exists', async () => {
    server.use(
      http.post(mintUrl + '/v1/mint/quote/bolt11', () =>
        HttpResponse.json({
          quote: 'bolt11-quote-1',
          request: 'lnbc10u1pfake', // HRP encodes the quoted 1,000 sat
          unit: 'sat',
          amount: 1000,
          state: 'UNPAID',
          expiry: 3600,
          pubkey: '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798',
        }),
      ),
    );
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    const quote = await wallet.createMintQuoteBolt11(
      1000,
      '0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798',
    );
    expect(quote.quote).toBe('bolt11-quote-1');
  });

  test('restore still works on a legacy keyset', async () => {
    useLegacyHandlers();
    server.use(
      http.post(mintUrl + '/v1/restore', () => HttpResponse.json({ outputs: [], signatures: [] })),
    );

    const wallet = new Wallet(mint, { bip39seed: randomBytes(64) });
    await wallet.loadMint();

    const res = await wallet.restore(0, 2, { keysetId: legacyId });
    expect(res.proofs).toEqual([]);
  });
});

test/wallet/wallet-custom-outputs.node.t.source:
import { describe, expect, test } from 'vitest';

import {
  Amount,
  KeyChain,
  Mint,
  OutputData,
  Wallet,
  createBlindSignature,
  createNewMintKeys,
  hashToCurve,
  pointFromHex,
  serializeMintKeys,
  type KeysetPair,
  type Proof,
  type RequestArgs,
  type SerializedBlindedMessage,
} from '../../src';

import { mintInfoResp } from './_setup';

// Two active keysets on one synthetic mint: the wallet prefers the cheaper one, so custom
// outputs built under the dearer one no longer match the wallet's own keyset choice.
const mintUrl = 'https://mint.test';
const unit = 'sat';
const dear = createNewMintKeys(8, new Uint8Array(32).fill(2), { input_fee_ppk: 1000 });
const cheap = createNewMintKeys(8, new Uint8Array(32).fill(3), { input_fee_ppk: 0 });
const retired = createNewMintKeys(8, new Uint8Array(32).fill(4), { input_fee_ppk: 0 });
const usd = createNewMintKeys(8, new Uint8Array(32).fill(5), { input_fee_ppk: 0, unit: 'usd' });
const unknown = createNewMintKeys(8, new Uint8Array(32).fill(6), { input_fee_ppk: 0 });
const pairs = [dear, cheap, retired, usd, unknown];
const seed = new Uint8Array(64).fill(1);

function keysFor(pair: KeysetPair, keysetUnit = unit) {
  return { id: pair.keysetId, unit: keysetUnit, keys: serializeMintKeys(pair.pubKeys) };
}

function signatureFor(pair: KeysetPair, secret: string, amount: Amount): string {
  const key = pair.privKeys[amount.toString()];
  return createBlindSignature(
    hashToCurve(new TextEncoder().encode(secret)),
    key,
    pair.keysetId,
  ).C_.toHex(true);
}

function inputUnder(pair: KeysetPair, amount: number, secret: string): Proof {
  return {
    id: pair.keysetId,
    secret,
    amount: Amount.from(amount),
    C: signatureFor(pair, secret, Amount.from(amount)),
  };
}

function proofIsValid(p: Proof): boolean {
  const pair = pairs.find((k) => k.keysetId === p.id);
  return pair !== undefined && p.C === signatureFor(pair, p.secret, p.amount);
}

// A mint that signs every output under the keyset the output names.
function makeWallet() {
  const calls: string[] = [];
  const mint = new Mint(mintUrl, {
    customRequest: async <T>(args: RequestArgs): Promise<T> => {
      calls.push(args.endpoint);
      // The transport serialises the body before handing it over.
      const body = JSON.parse(args.requestBody as string) as {
        outputs: SerializedBlindedMessage[];
      };
      const signatures = body.outputs.map((o) => {
        const pair = pairs.find((k) => k.keysetId === o.id);
        if (!pair) throw new Error(`mint does not know keyset ${o.id}`);
        const amount = Amount.from(o.amount);
        const C_ = createBlindSignature(
          pointFromHex(o.B_),
          pair.privKeys[amount.toString()],
          o.id,
        ).C_.toHex(true);
        return { id: o.id, amount: amount.toString(), C_ };
      });
      return { signatures } as T;
    },
  });
  const wallet = new Wallet(mint, { unit });
  const info = {
    ...mintInfoResp,
    nuts: { 4: { methods: [{ method: 'bolt11', unit }], disabled: false } },
  };
  wallet.loadMintFromCache(
    info,
    KeyChain.mintToCacheDTO(
      mintUrl,
      [
        { id: dear.keysetId, unit, active: true, input_fee_ppk: 1000 },
        { id: cheap.keysetId, unit, active: true, input_fee_ppk: 0 },
        { id: retired.keysetId, unit, active: false, input_fee_ppk: 0 },
        { id: usd.keysetId, unit: 'usd', active: true, input_fee_ppk: 0 },
      ],
      [keysFor(dear), keysFor(cheap), keysFor(retired), keysFor(usd, 'usd')],
    ),
  );
  return { wallet, calls };
}

describe('custom outputs on a keyset other than the wallet default', () => {
  test('send unblinds each output with the keyset that signed it', async () => {
    const { wallet, calls } = makeWallet();
    const keep = OutputData.createDeterministicData(Amount.from(7), seed, 0, keysFor(dear));
    const send = OutputData.createDeterministicData(
      Amount.from(8),
      seed,
      keep.length,
      keysFor(dear),
    );
    const input = inputUnder(dear, 16, 'custom-send-input');

    const result = await wallet.send(8, [input], undefined, {
      keep: { type: 'custom', data: keep },
      send: { type: 'custom', data: send },
    });

    expect(calls).toHaveLength(1);
    expect([...result.keep, ...result.send].every(proofIsValid)).toBe(true);
    expect(result.send.map((p) => p.id)).toEqual([dear.keysetId]);
  });

  test('send accepts a plan that mixes active keysets', async () => {
    const { wallet } = makeWallet();
    const keep = OutputData.createDeterministicData(Amount.from(7), seed, 0, keysFor(cheap));
    const send = OutputData.createDeterministicData(
      Amount.from(8),
      seed,
      keep.length,
      keysFor(dear),
    );
    const input = inputUnder(dear, 16, 'custom-mixed-input');

    const result = await wallet.send(8, [input], undefined, {
      keep: { type: 'custom', data: keep },
      send: { type: 'custom', data: send },
    });

    expect([...result.keep, ...result.send].every(proofIsValid)).toBe(true);
    expect(new Set(result.keep.map((p) => p.id))).toEqual(new Set([cheap.keysetId]));
    expect(new Set(result.send.map((p) => p.id))).toEqual(new Set([dear.keysetId]));
  });

  test('receive unblinds custom outputs with the keyset that signed them', async () => {
    const { wallet } = makeWallet();
    const input = inputUnder(dear, 16, 'custom-receive-input');
    // The 16 sat input pays 1 sat in fees under the dearer keyset.
    const data = OutputData.createDeterministicData(Amount.from(15), seed, 0, keysFor(dear));

    const proofs = await wallet.receive([input], undefined, { type: 'custom', data });

    expect(proofs.every(proofIsValid)).toBe(true);
    expect(new Set(proofs.map((p) => p.id))).toEqual(new Set([dear.keysetId]));
  });

  test('mint unblinds custom outputs with the keyset that signed them', async () => {
    const { wallet } = makeWallet();
    const data = OutputData.createDeterministicData(Amount.from(16), seed, 0, keysFor(dear));

    const proofs = await wallet.mintProofs(
      'bolt11',
      16,
      {
        quote: 'quote-id',
        unit: 'sat',
        amount_paid: Amount.from(0),
        amount_issued: Amount.from(0),
      },
      undefined,
      {
        type: 'custom',
        data,
      },
    );

    expect(proofs.every(proofIsValid)).toBe(true);
    expect(new Set(proofs.map((p) => p.id))).toEqual(new Set([dear.keysetId]));
  });

  test('batch mint unblinds custom outputs with the keyset that signed them', async () => {
    const { wallet } = makeWallet();
    const data = OutputData.createDeterministicData(Amount.from(16), seed, 0, keysFor(dear));

    const preview = await wallet.prepareBatchMint(
      'bolt11',
      [
        {
          amount: 16,
          quote: {
            quote: 'quote-id',
            unit: 'sat',
            amount_paid: Amount.from(0),
            amount_issued: Amount.from(0),
          },
        },
      ],
      undefined,
      { type: 'custom', data },
    );
    const proofs = await wallet.completeBatchMint(preview);

    expect(proofs.every(proofIsValid)).toBe(true);
    expect(new Set(proofs.map((p) => p.id))).toEqual(new Set([dear.keysetId]));
  });

  test.each([
    ['unknown', unknown, /Keyset '/],
    ['inactive', retired, /Inactive keyset/],
    ['other-unit', usd, /Keyset unit does not match wallet unit/],
  ])('rejects a custom plan on an %s keyset before calling the mint', async (_, pair, msg) => {
    const { wallet, calls } = makeWallet();
    const keep = OutputData.createDeterministicData(Amount.from(7), seed, 0, keysFor(dear));
    const send = OutputData.createDeterministicData(
      Amount.from(8),
      seed,
      keep.length,
      keysFor(pair),
    );
    const input = inputUnder(dear, 16, `custom-${pair.keysetId}`);

    await expect(
      wallet.send(8, [input], undefined, {
        keep: { type: 'custom', data: keep },
        send: { type: 'custom', data: send },
      }),
    ).rejects.toThrow(msg);
    expect(calls).toHaveLength(0);
  });
});

test/wallet/wallet-v3-units.node.test.ts.source:
import { hexToBytes, bytesToHex } from '@noble/hashes/utils.js';
import { describe, expect, test, vi } from 'vitest';

import { Wallet, QUOTE_COUNTER_KEY, type OperationCounters } from '../../src';
import { getPubKeyFromPrivKey } from '../../src/crypto/curve_secp';
import { deriveQuoteLockKey } from '../../src/crypto/NUT13';
import { Amount } from '../../src/model/Amount';
import type { Proof } from '../../src/model/types';

const mintUrl = 'http://localhost:3338';
const BLS_ID = `02${'ab'.repeat(32)}`;
const POINT = `02${'cd'.repeat(32)}`;

describe('Wallet._normalizeWitness', () => {
  const wallet = new Wallet(mintUrl, { unit: 'sat' });
  const normalize = (proof: Proof) =>
    (wallet as unknown as { _normalizeWitness(p: Proof): string | undefined })._normalizeWitness(
      proof,
    );

  test('keeps a v3 transaction witness, serializing object forms', () => {
    const base: Proof = { id: BLS_ID, amount: Amount.from(1), secret: POINT, C: '00'.repeat(48) };
    expect(normalize({ ...base, witness: '{"signatures":["ab"]}' })).toBe('{"signatures":["ab"]}');
    expect(normalize({ ...base, witness: { signatures: ['ab'] } })).toBe('{"signatures":["ab"]}');
    expect(normalize(base)).toBeUndefined();
  });

  test('strips a stray witness from a plain pre-v3 secret', () => {
    const legacy: Proof = {
      id: `00${'11'.repeat(16)}`,
      amount: Amount.from(1),
      secret: 'plain-text-secret',
      C: 'aa'.repeat(33),
      witness: '{"signatures":["ab"]}',
    };
    expect(normalize(legacy)).toBeUndefined();
  });
});

describe('Wallet quote lock keys', () => {
  const SEED = hexToBytes('11'.repeat(64));

  test('createQuoteLockKey derives from the seed and consumes the quote counter', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat', bip39seed: SEED });
    const first = await wallet.createQuoteLockKey();
    expect(bytesToHex(deriveQuoteLockKey(SEED, 0))).toBe(first.privkey);
    expect(bytesToHex(getPubKeyFromPrivKey(hexToBytes(first.privkey)))).toBe(first.pubkey);
    // The counter moved: the next key is a different derivation.
    const second = await wallet.createQuoteLockKey();
    expect(bytesToHex(deriveQuoteLockKey(SEED, 1))).toBe(second.privkey);
  });

  test('createQuoteLockKey is random without a seed', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat' });
    const a = await wallet.createQuoteLockKey();
    const b = await wallet.createQuoteLockKey();
    expect(a.privkey).not.toBe(b.privkey);
    expect(bytesToHex(getPubKeyFromPrivKey(hexToBytes(a.privkey)))).toBe(a.pubkey);
  });

  test('createQuoteLockKey emits countersReserved so persistence hooks see the cursor', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat', bip39seed: SEED });
    const seen: OperationCounters[] = [];
    wallet.on.countersReserved((p) => seen.push(p));
    await wallet.createQuoteLockKey();
    await wallet.createQuoteLockKey();
    expect(seen).toEqual([
      { counterKey: QUOTE_COUNTER_KEY, start: 0, count: 1, next: 1 },
      { counterKey: QUOTE_COUNTER_KEY, start: 1, count: 1, next: 2 },
    ]);
  });

  test('createQuoteLockKey({ random: true }) skips the seed and the quote counter', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat', bip39seed: SEED });
    const seen: OperationCounters[] = [];
    wallet.on.countersReserved((p) => seen.push(p));
    const throwaway = await wallet.createQuoteLockKey({ random: true });
    expect(throwaway.privkey).not.toBe(bytesToHex(deriveQuoteLockKey(SEED, 0)));
    expect(bytesToHex(getPubKeyFromPrivKey(hexToBytes(throwaway.privkey)))).toBe(throwaway.pubkey);
    expect(seen).toEqual([]);
    // The counter did not move: the next seeded key still derives at 0.
    const first = await wallet.createQuoteLockKey();
    expect(bytesToHex(deriveQuoteLockKey(SEED, 0))).toBe(first.privkey);
  });

  test('recoverQuoteLockKey scans the seed to the quote pubkey, and misses cleanly', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat', bip39seed: SEED });
    const expected = deriveQuoteLockKey(SEED, 3);
    const pubkey = bytesToHex(getPubKeyFromPrivKey(expected));
    await expect(wallet.recoverQuoteLockKey(pubkey.toUpperCase())).resolves.toBe(
      bytesToHex(expected),
    );
    // A pubkey this seed never derived scans to nothing rather than guessing.
    const foreign = bytesToHex(getPubKeyFromPrivKey(hexToBytes('22'.repeat(32))));
    await expect(wallet.recoverQuoteLockKey(foreign)).resolves.toBeUndefined();
  });

  test('recoverQuoteLockKey without a seed throws, not a silent miss', async () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat' });
    await expect(wallet.recoverQuoteLockKey(POINT)).rejects.toThrow(
      'recoverQuoteLockKey requires a seeded wallet',
    );
  });
});

describe('Wallet v3 mint preparation', () => {
  const v3Keyset = { id: BLS_ID, hasHexId: true, active: true, keys: { 1: 'aa'.repeat(48) } };
  const withV3Keyset = () => {
    const wallet = new Wallet(mintUrl, { unit: 'sat' });
    vi.spyOn(
      wallet as unknown as { getOutputKeyset: () => unknown },
      'getOutputKeyset',
    ).mockReturnValue(v3Keyset);
    vi.spyOn(
      wallet as unknown as { requireSupport: () => void },
      'requireSupport',
    ).mockImplementation(() => undefined);
    return wallet;
  };

  test('mintProofsBolt11 with a bare quote ID fetches the quote on a v3 keyset', async () => {
    // The transcript commits the quote's face amount and the lock key must be known (NUT-04):
    // the pre-v3 `{ quote }` stub cannot mint here, so the full quote is fetched first.
    const wallet = withV3Keyset();
    const full = {
      quote: 'q1',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      amount: 1,
      unit: 'sat',
      pubkey: '02'.padEnd(66, 'c'),
    };
    const check = vi.spyOn(wallet, 'checkMintQuoteBolt11').mockResolvedValue(full as never);
    const prepare = vi.spyOn(wallet, 'prepareMint').mockResolvedValue({} as never);
    vi.spyOn(wallet, 'completeMint').mockResolvedValue([]);
    await wallet.mintProofsBolt11(1, 'q1');
    expect(check).toHaveBeenCalledWith('q1');
    expect(prepare.mock.calls[0][2]).toBe(full);
  });

  test('prepareBatchMint refuses an unlocked quote on a v3 keyset before any request', async () => {
    // Every quote in a v3 batch is a signing input; the mint must reject an unlocked one (NUT-29).
    const wallet = withV3Keyset();
    const locked = {
      quote: 'a',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      unit: 'sat',
      amount: 1,
      pubkey: '02'.padEnd(66, 'c'),
    };
    const unlocked = {
      quote: 'b',
      amount_paid: Amount.from(0),
      amount_issued: Amount.from(0),
      unit: 'sat',
      amount: 1,
    };
    const entries = [
      { amount: 1, quote: locked },
      { amount: 1, quote: unlocked },
    ] as never;
    await expect(
      wallet.prepareBatchMint('bolt11', entries, { privkey: '11'.repeat(32) }),
    ).rejects.toThrow(/quote #2 is unlocked/);
    await expect(wallet.prepareBatchMint('bolt11', [entries[1]] as never)).rejects.toThrow(
      /quote #1 is unlocked/,
    );
  });
});

