describe('Clear Authentication', () => {
  test('handleClearAuth calls ensureCAT (not getCAT) and sends Clear-auth header', async () => {
    const mintInfo = {
      name: 'Testnut mint',
      pubkey: '02abc',
      version: 'Nutshell/x',
      contact: [],
      time: 0,
      nuts: {
        21: {
          openid_discovery: 'https://auth.example.com/.well-known/openid-configuration',
          client_id: 'cashu-client',
          protected_endpoints: [{ method: 'POST', path: '/v1/swap' }],
        },
      },
    };
    server.use(http.get(mintUrl + '/v1/info', () => HttpResponse.json(mintInfo)));

    let receivedClearAuth: string | null = null;
    server.use(
      http.post(mintUrl + '/v1/swap', async ({ request }) => {
        receivedClearAuth = request.headers.get('clear-auth');
        return HttpResponse.json({ signatures: [] });
      }),
    );
    const freshToken = 'refreshed-cat-token';
    const mockAuthProvider: AuthProvider = {
      getBlindAuthToken: vi.fn().mockResolvedValue(''),
      getCAT: vi.fn().mockReturnValue('expired-cat-token'),
      setCAT: vi.fn(),
      ensureCAT: vi.fn().mockResolvedValue(freshToken),
    };
    const mintClient = new Mint(mintUrl, { authProvider: mockAuthProvider });
    await mintClient.swap({ inputs: [], outputs: [] });

    // ensureCAT must be called — not getCAT — so refresh logic can run
    expect(mockAuthProvider.ensureCAT).toHaveBeenCalled();
    expect(mockAuthProvider.getCAT).not.toHaveBeenCalled();

    // The refreshed token must appear in the Clear-auth header
    expect(receivedClearAuth).toBe(freshToken);
  });
});

describe('Auth header redirect handling', () => {
  const protectedSwapInfo = {
    name: 'Testnut mint',
    pubkey: '02abc',
    version: 'Nutshell/x',
    contact: [],
    time: 0,
    nuts: {
      21: {
        openid_discovery: 'https://auth.example.com/.well-known/openid-configuration',
        client_id: 'cashu-client',
        protected_endpoints: [{ method: 'POST', path: '/v1/swap' }],
      },
      22: {
        bat_max_mint: 100,
        protected_endpoints: [{ method: 'POST', path: '/v1/swap' }],
      },
    },
  };

  function mockAuthProvider(): AuthProvider {
    return {
      getBlindAuthToken: vi.fn().mockResolvedValue('bat-token'),
      getCAT: vi.fn().mockReturnValue('cat-token'),
      setCAT: vi.fn(),
      ensureCAT: vi.fn().mockResolvedValue('cat-token'),
    };
  }

  test('requests carrying a token or a body refuse redirects; bodiless ones are unchanged', async () => {
    server.use(http.get(mintUrl + '/v1/info', () => HttpResponse.json(protectedSwapInfo)));

    const authedSpy = vi.fn((args: { endpoint: string }) =>
      Promise.resolve(args.endpoint.includes('/v1/info') ? protectedSwapInfo : { signatures: [] }),
    );
    const authedMint = new Mint(mintUrl, { authProvider: mockAuthProvider() });
    await authedMint.swap({ inputs: [], outputs: [] }, authedSpy as unknown as RequestFn);
    const authedArgs = authedSpy.mock.calls.find((c) => c[0].endpoint.includes('/v1/swap'))![0];
    expect(authedArgs).toMatchObject({ redirect: 'error' });

    // No auth token, but the body carries proofs.
    const plainSpy = vi.fn().mockResolvedValue({ signatures: [] });
    const plainMint = new Mint(mintUrl);
    await plainMint.swap({ inputs: [], outputs: [] }, plainSpy);
    expect(plainSpy.mock.calls[0][0]).toMatchObject({ redirect: 'error' });

    const getSpy = vi
      .fn()
      .mockResolvedValue({ quote: 'q', request: 'lnbc', unit: 'sat', amount: 1, state: 'UNPAID' });
    await plainMint.checkMintQuote('bolt11', 'q', {
      customRequest: getSpy as unknown as RequestFn,
    });
    expect(getSpy.mock.calls[0][0]).not.toHaveProperty('redirect');
  });
});

