import { Server } from 'mock-socket';
import { test, describe, expect } from 'vitest';

import {
  Wallet,
  MeltQuoteState,
  MintQuoteState,
  type MeltQuoteBolt11Response,
  type MintQuoteBolt11Response,
} from '../../src';

import { mint, useTestServer } from './_setup';

useTestServer();

describe('WebSocket Updates', () => {
  test('mint update', async () => {
    const fakeUrl = 'ws://localhost:3338/v1/ws';
    const server = new Server(fakeUrl, { mock: false });
    server.on('connection', (socket) => {
      socket.on('message', (m) => {
        console.log(m);
        try {
          const parsed = JSON.parse(m.toString());
          if (parsed.method === 'subscribe') {
            const message = `{"jsonrpc": "2.0", "result": {"status": "OK", "subId": "${parsed.params.subId}"}, "id": ${parsed.id}}`;
            socket.send(message);
            setTimeout(() => {
              const message = `{"jsonrpc": "2.0", "method": "subscribe", "params": {"subId": "${parsed.params.subId}", "payload": {"quote": "123", "request": "456", "state": "PAID", "paid": true, "expiry": 123}}}`;
              socket.send(message);
            }, 500);
          }
        } catch {
          console.log('Server parsing failed...');
        }
      });
    });
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    const state = await new Promise((res, rej) => {
      const callback = (p: MintQuoteBolt11Response) => {
        if (p.state === MintQuoteState.PAID) {
          res(p);
        }
      };
      wallet.on
        .mintQuoteUpdates(['123'], callback, () => {
          rej(new Error('mint quote subscription error'));
        })
        .catch(rej);
    });
    expect(state).toMatchObject({ quote: '123' });
    mint.disconnectWebSocket();
    server.close();
  });
  test('melt update', async () => {
    const fakeUrl = 'ws://localhost:3338/v1/ws';
    const server = new Server(fakeUrl, { mock: false });
    server.on('connection', (socket) => {
      socket.on('message', (m) => {
        console.log(m);
        try {
          const parsed = JSON.parse(m.toString());
          if (parsed.method === 'subscribe') {
            const message = `{"jsonrpc": "2.0", "result": {"status": "OK", "subId": "${parsed.params.subId}"}, "id": ${parsed.id}}`;
            socket.send(message);
            setTimeout(() => {
              const message = `{"jsonrpc": "2.0", "method": "subscribe", "params": {"subId": "${parsed.params.subId}", "payload": {"quote": "123", "request": "456", "state": "PAID", "paid": true, "expiry": 123}}}`;
              socket.send(message);
            }, 500);
          }
        } catch {
          console.log('Server parsing failed...');
        }
      });
    });
    const wallet = new Wallet(mint);
    await wallet.loadMint();

    const state = await new Promise((res, rej) => {
      const callback = (p: MeltQuoteBolt11Response) => {
        console.log(p);
        if (p.state === MeltQuoteState.PAID) {
          res(p);
        }
      };
      wallet.on
        .meltQuoteUpdates(['123'], callback, (e) => {
          console.log(e);
          rej(new Error('melt quote subscription error'));
        })
        .catch(rej);
    });
    expect(state).toMatchObject({ quote: '123' });
    server.close();
  });
});

test/utils/bytes.test.ts.source:
import { numberToVarBytesBE } from '@noble/curves/utils.js';
import { utf8ToBytes } from '@noble/hashes/utils.js';
import { describe, expect, test } from 'vitest';

import {
  bytesToUtf8,
  compareBytes,
  decodeUtf8Document,
  decodeUtf8Field,
  minimalBytesBE,
} from '../../src/utils/bytes';

describe('bytesToUtf8', () => {
  test('round-trips through utf8ToBytes, multi-byte included', () => {
    for (const s of ['', 'sat', 'ünïcode ✓', '🥜']) {
      expect(bytesToUtf8(utf8ToBytes(s))).toBe(s);
    }
  });
});

describe('decodeUtf8Field', () => {
  test('keeps a leading BOM as content instead of stripping it', () => {
    // ef bb bf is the UTF-8 BOM, followed by 'a'.
    const bytes = Uint8Array.of(0xef, 0xbb, 0xbf, 0x61);
    expect(decodeUtf8Field(bytes)).toBe('﻿a');
  });

  test('rejects a byte sequence that is not valid UTF-8', () => {
    expect(() => decodeUtf8Field(Uint8Array.of(0xff))).toThrow();
  });
});

describe('decodeUtf8Document', () => {
  test('strips a leading BOM instead of keeping it as content', () => {
    // ef bb bf is the UTF-8 BOM, followed by '{"a":1}'.
    const bytes = Uint8Array.of(0xef, 0xbb, 0xbf, ...new TextEncoder().encode('{"a":1}'));
    expect(decodeUtf8Document(bytes)).toBe('{"a":1}');
  });

  test('rejects a byte sequence that is not valid UTF-8', () => {
    expect(() => decodeUtf8Document(Uint8Array.of(0xff))).toThrow();
  });
});

describe('compareBytes', () => {
  test('orders by first differing byte, unsigned', () => {
    expect(compareBytes(Uint8Array.of(1), Uint8Array.of(2))).toBeLessThan(0);
    expect(compareBytes(Uint8Array.of(2), Uint8Array.of(1))).toBeGreaterThan(0);
    // 0x80 is negative as a signed byte; it must still sort above 0x01.
    expect(compareBytes(Uint8Array.of(0x80), Uint8Array.of(0x01))).toBeGreaterThan(0);
    expect(compareBytes(Uint8Array.of(1, 2), Uint8Array.of(1, 2))).toBe(0);
  });

  test('a prefix sorts before what extends it', () => {
    expect(compareBytes(Uint8Array.of(1), Uint8Array.of(1, 0))).toBeLessThan(0);
    expect(compareBytes(new Uint8Array(0), Uint8Array.of(0))).toBeLessThan(0);
  });

  test('sorts an array into canonical order', () => {
    const sorted = [Uint8Array.of(2), Uint8Array.of(1, 9), Uint8Array.of(1)].sort(compareBytes);
    expect(sorted).toEqual([Uint8Array.of(1), Uint8Array.of(1, 9), Uint8Array.of(2)]);
  });
});

describe('minimalBytesBE', () => {
  test('encodes zero as no bytes, unlike numberToVarBytesBE', () => {
    expect(minimalBytesBE(0n)).toEqual(new Uint8Array(0));
    expect(numberToVarBytesBE(0n)).toEqual(Uint8Array.of(0));
  });

  test('drops leading zero bytes', () => {
    expect(minimalBytesBE(1n)).toEqual(Uint8Array.of(1));
    expect(minimalBytesBE(255n)).toEqual(Uint8Array.of(0xff));
    expect(minimalBytesBE(256n)).toEqual(Uint8Array.of(0x01, 0x00));
    expect(minimalBytesBE(0x0100n ** 4n)).toEqual(Uint8Array.of(1, 0, 0, 0, 0)); // 2^32
  });

  test('refuses a negative value', () => {
    expect(() => minimalBytesBE(-1n)).toThrow(RangeError);
  });

  test('encodes the largest amount but refuses anything above it', () => {
    expect(minimalBytesBE(2n ** 64n - 1n)).toEqual(new Uint8Array(8).fill(0xff));
    expect(() => minimalBytesBE(2n ** 64n)).toThrow(RangeError);
  });
});

test/crypto/NUT13-p2pk.test.ts.source:
import { hexToBytes } from '@noble/hashes/utils.js';
import { describe, expect, test } from 'vitest';

import { type Bip32KeyPurpose, createKeyPairDeriver, deriveKeyPair } from '../../src/crypto';

// BIP39 seed (no passphrase) for the mnemonic in the NUT-11 / NUT-20 test vectors:
// "half depart obvious quality work element tank gorilla view sugar picture humble"
const SEED = hexToBytes(
  'dd44ee516b0647e80b488e8dcc56d736a148f15276bef588b37057476d4b2b25' +
    '780d3688a32b37353d6995997842c0fd8b412475c891c16310471fbc86dcbda8',
);

// Expected compressed (02/03-prefixed) public keys from the PR test vectors.
const VECTORS: Record<Bip32KeyPurpose, string[]> = {
  P2PK: [
    '021693d45f4fdf610ae641fedb0944fb460fbb8264f21c19d2626c3da755fcbbcb',
    '0395461ab678058c0ed6aa39f38dda490eaa163e9ad27070b23ec3d06b41e07535',
    '02a05e4e593a633e9b4405f01c9632c8afde24cb613017a1aee56fd76291ad26d1',
    '033addea25c3873b93d67d536c61c9d9c993f6efd8b9dfa657951b66b5001e51dd',
    '03c964bdf42fc82b6c574615746eeca37527a24f1fdfc1b34a732c53843b5744a5',
  ],
  QuoteLock: [
    '03062837166e56114b59a4d1fd3a5a812bf7aadc1dde758428cf943d80acd41539',
    '02b47d9d41725f5ce6f08c874835cef25376cb1e95f6cb073fef52ca8fd986cf15',
    '029acbd3a46fd75bc05ba0226d0b4d909b2fb6e96c80544a094a1a3567737e44d3',
    '0373e4a42fbe0a4e18aadb57cf500b655f2446b4071ee579121d2ed8905bcc49c2',
    '02b8709bfce17c10f1864f5218844533ae60930d52089669b317d8b5f474eec071',
  ],
};

describe('deterministic P2PK / quote-lock key derivation (NUT-11, NUT-20)', () => {
  test.each(['P2PK', 'QuoteLock'] as const)(
    '%s matches spec test vectors for counters 0-4',
    (purpose) => {
      const expected = VECTORS[purpose];
      const derive = createKeyPairDeriver(SEED, purpose);
      for (let counter = 0; counter < expected.length; counter++) {
        const pair = deriveKeyPair(SEED, purpose, counter);
        expect(pair.privkey).toHaveLength(64); // 32 bytes, hex
        expect(pair.pubkey).toBe(expected[counter]);
        // cached factory must agree with the one-shot keypair
        expect(derive(counter)).toEqual(pair);
      }
    },
  );

  test('P2PK and QuoteLock purposes diverge for the same seed/counter', () => {
    expect(deriveKeyPair(SEED, 'P2PK', 0).pubkey).not.toBe(
      deriveKeyPair(SEED, 'QuoteLock', 0).pubkey,
    );
  });

  // deriveChild would silently harden indices >= 2^31, breaking xpub watch-only derivation
  test.each([0x80000000, -1, 1.5, Number.NaN])('rejects invalid counter %s', (counter) => {
    expect(() => deriveKeyPair(SEED, 'P2PK', counter)).toThrow('non-hardened');
  });

  test('accepts the maximum non-hardened counter', () => {
    expect(deriveKeyPair(SEED, 'P2PK', 0x7fffffff).pubkey).toMatch(/^0[23][0-9a-f]{64}$/);
  });
});

test/utils/bolt11.test.ts.source:
import { describe, it, expect } from 'vitest';

import { bolt11AmountMsat } from '../../src/utils';

// The 2,000 sat fixture invoice from test/wallet/_setup (not imported: _setup pulls in msw/node,
// which does not load in the browser projects).
const invoice =
  '';

describe('bolt11AmountMsat', () => {
  it('reads the fixture invoice amount (20u = 2,000 sat)', () => {
    expect(bolt11AmountMsat(invoice)).toBe(2_000_000n);
  });

  it.each([
    ['lnbc20u1pfake', 2_000_000n], // micro-bitcoin
    ['lnbc1m1pfake', 100_000_000n], // milli-bitcoin, amount digit before the separator
    ['lnbc1500n1pfake', 150_000n], // nano-bitcoin
    ['lnbc2500p1pfake', 250n], // pico-bitcoin
    ['lnbc21pfake', 200_000_000_000n], // whole bitcoin, no multiplier
    ['lntbs10u1pfake', 1_000_000n], // signet prefix
    ['lnbcrt500n1pfake', 50_000n], // regtest prefix
    ['LNBC20U1PFAKE', 2_000_000n], // uppercase form
  ])('parses %s', (pr, msat) => {
    expect(bolt11AmountMsat(pr)).toBe(msat);
  });

  it('returns null for an amountless invoice', () => {
    expect(bolt11AmountMsat('lnbc1pfake')).toBeNull();
  });

  it.each([
    ['lnbc2501p1pfake'], // pico amount not a multiple of 10 (sub-msat)
    ['lnbc0500u1pfake'], // leading zero
    ['lnbc01pfake'], // zero amount
    ['lnbc20u'], // no separator
    ['notaninvoice'],
    [''],
  ])('throws on %s', (pr) => {
    expect(() => bolt11AmountMsat(pr)).toThrow();
  });

  it('throws on non-string input', () => {
    expect(() => bolt11AmountMsat(null as unknown as string)).toThrow();
  });

  it('rejects an amount digit run far longer than any real invoice needs', () => {
    const invoice = `lnbc${'9'.repeat(100_000)}1pfake`;
    expect(() => bolt11AmountMsat(invoice)).toThrow('Invalid BOLT11 invoice');
  });

  it('bounds the prefix at exactly 100 characters', () => {
    // An all-letter prefix parses as amountless once it clears the length check.
    expect(bolt11AmountMsat(`ln${'x'.repeat(98)}1pfake`)).toBeNull();
    expect(() => bolt11AmountMsat(`ln${'x'.repeat(99)}1pfake`)).toThrow('Invalid BOLT11 invoice');
  });
});

test/crypto/bls_random_scalar.test.ts.source:
import { numberToBytesBE } from '@noble/curves/utils.js';
import { afterEach, describe, expect, test, vi } from 'vitest';

import { BLS_FR_ORDER, blindMessageBls } from '../../src/crypto';

// randomScalar() (module-private in curve_bls.ts) feeds the no-r path of blindMessageBls — the
// production random-output path for v3 BLS keysets. It must rejection-sample uniformly in
// [1, BLS_FR_ORDER), like deriveBatchWeights. Fr.fromBytes mod-reduces (BLS_FR_ORDER ~ 0.45·2^256),
// which biases scalars small; this guards against a regression back to that.
const { randomBytesMock } = vi.hoisted(() => ({ randomBytesMock: vi.fn() }));

vi.mock('@noble/hashes/utils.js', async (importActual) => {
  // eslint-disable-next-line @typescript-eslint/consistent-type-imports -- vitest importActual generic
  const actual = await importActual<typeof import('@noble/hashes/utils.js')>();
  return { ...actual, randomBytes: randomBytesMock };
});

describe('randomScalar uniform rejection sampling (no-r blinding path)', () => {
  afterEach(() => randomBytesMock.mockReset());

  test('discards an out-of-range draw instead of mod-reducing it', () => {
    const secret = new TextEncoder().encode('unlinkability');
    // 1st draw >= BLS_FR_ORDER: rejection sampling must discard it. 2nd draw in range: accepted.
    randomBytesMock
      .mockReturnValueOnce(numberToBytesBE(BLS_FR_ORDER + 7n, 32))
      .mockReturnValueOnce(numberToBytesBE(11n, 32));

    const { r } = blindMessageBls(secret);

    // Rejection sampling keeps the 2nd draw = 11. Mod-reduction would consume only the 1st draw:
    // (BLS_FR_ORDER + 7) mod BLS_FR_ORDER = 7 — never 11.
    expect(r).toBe(11n);
  });

  test('rejects a draw of exactly BLS_FR_ORDER (>= boundary, not >)', () => {
    const secret = new TextEncoder().encode('unlinkability');
    // A draw equal to the order must be rejected: as a scalar it is ≡ 0 and out of Fr*. A `>` (rather
    // than `>=`) bound would wrongly accept it, so the 2nd in-range draw must be the one returned.
    randomBytesMock
      .mockReturnValueOnce(numberToBytesBE(BLS_FR_ORDER, 32))
      .mockReturnValueOnce(numberToBytesBE(11n, 32));

    const { r } = blindMessageBls(secret);

    expect(r).toBe(11n);
  });
});

test/wallet/wallet-assertAmount.test.ts.source:
import { test, describe, expect } from 'vitest';

import { Wallet } from '../../src';
import { MINTCACHE } from '../consts';

const mintUrl = 'http://localhost:3338';
const wallet = new Wallet(mintUrl) as any;
wallet.loadMintFromCache(MINTCACHE.mintInfo, MINTCACHE.keychainCache);

describe('parseAmount tests', () => {
  test('allows valid integers', () => {
    expect(() => wallet.parseAmount(2561, 'test')).not.toThrow();
    expect(() => wallet.parseAmount(2561n, 'test')).not.toThrow();
    expect(() => wallet.parseAmount('2561', 'test')).not.toThrow();
    expect(() => wallet.parseAmount(Number.MAX_SAFE_INTEGER, 'test')).not.toThrow(); // exact boundary (2^53 - 1)
  });

  test('rejects non-integer numbers', () => {
    expect(() => wallet.parseAmount(512.0019, 'test')).toThrow('Invalid number amount: 512.0019');
    expect(() => wallet.parseAmount(NaN, 'test')).toThrow('Invalid number amount: NaN');
    expect(() => wallet.parseAmount(Infinity, 'test')).toThrow('Invalid number amount: Infinity');
    expect(() => wallet.parseAmount(-Infinity, 'test')).toThrow('Invalid number amount: -Infinity');
  });

  test('rejects zero', () => {
    expect(() => wallet.parseAmount(0, 'test')).toThrow('Amount must be positive: 0');
    expect(() => wallet.parseAmount(0n, 'test')).toThrow('Amount must be positive: 0');
    expect(() => wallet.parseAmount('0', 'test')).toThrow('Amount must be positive: 0');
  });

  test('rejects unsupported types', () => {
    expect(() => wallet.parseAmount(true, 'test')).toThrow('Unsupported amount input type');
    expect(() => wallet.parseAmount(false, 'test')).toThrow('Unsupported amount input type');
    expect(() => wallet.parseAmount({}, 'test')).toThrow('Unsupported amount input type');
    expect(() => wallet.parseAmount(null, 'test')).toThrow('Unsupported amount input type');
    expect(() => wallet.parseAmount(undefined as unknown, 'test')).toThrow(
      'Unsupported amount input type',
    );
  });

  test('rejects unsafe integer', () => {
    expect(() => wallet.parseAmount(9007199254740992, 'test')).toThrow('Unsafe integer amount'); // 2^53
    expect(() => wallet.parseAmount(Math.pow(2, 53), 'test')).toThrow('Unsafe integer amount');
  });
});

